def pipe_log(*args):
    """Log to stdout so it appears in OWUI's backend logs."""
    print(f"[openclaw-pipe] {' '.join(str(a) for a in args)}", flush=True)

logging.basicConfig(level=logging.INFO, stream=sys.stdout)
logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Background tasks
# ---------------------------------------------------------------------------

# The event loop keeps only a weak reference to a task, so a fire-and-forget
# asyncio.create_task() can be garbage-collected before it finishes and its
# work silently never happens. Background work goes through spawn_background,
# which holds the reference until the task is done.
_BACKGROUND_TASKS: set = set()


def spawn_background(coro):
    task = asyncio.create_task(coro)
    _BACKGROUND_TASKS.add(task)
    task.add_done_callback(_BACKGROUND_TASKS.discard)
    return task


# --- identity --------------------------------------------------------------

# ---------------------------------------------------------------------------
# Device Identity helpers
# ---------------------------------------------------------------------------

def _generate_device_identity():
    """Generate a fresh Ed25519 key pair and return a dict with id, publicKey,
    and privateKey (PEM)."""
    pk = ed25519.Ed25519PrivateKey.generate()
    pub = pk.public_key()
    raw = pub.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw
    )
    pub_b64 = base64.urlsafe_b64encode(raw).decode().rstrip("=")
    did = hashlib.sha256(raw).hexdigest()
    pem = pk.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    ).decode()
    return dict(id=did, publicKey=pub_b64, privateKey=pem)


def _sign_challenge(ident, nonce, ts, token_str="", scopes=None):
    """Sign the WebSocket challenge using the device identity. The Gateway
    checks the scope list in the signed payload against the scopes requested."""
    parts = [
        "v2", ident["id"], "webchat", "cli", "operator",
        ",".join(GATEWAY_SCOPES if scopes is None else scopes), str(ts), token_str, nonce
    ]
    pk = serialization.load_pem_private_key(
        ident["privateKey"].encode(), password=None, backend=default_backend()
    )
    sig = pk.sign(("|".join(parts)).encode())
    return dict(
        id=ident["id"],
        publicKey=ident["publicKey"],
        signature=base64.urlsafe_b64encode(sig).decode().rstrip("="),
        signedAt=ts,
        nonce=nonce
    )


def _parse_device_identity(raw):
    """Parse DEVICE_IDENTITY JSON, handling unescaped newlines in PEM keys."""
    if not raw:
        return None
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        pass
    try:
        def _fix_pem(m):
            return m.group(1) + m.group(2).replace("\n", "").replace("\r", "") + m.group(3)
        fixed = re.sub(
            r'("privateKey":\s*")(.*?)("[, \\}])',
            _fix_pem, raw, flags=re.DOTALL
        )
        return json.loads(fixed)
    except Exception:
        return None


# --- state -----------------------------------------------------------------


def _state_dir(path=None):
    """Return the persistent bridge state directory, creating it if possible."""
    root = path or os.environ.get("OPENCLAW_BRIDGE_STATE_DIR") or "/data/openclaw-bridge"
    try:
        os.makedirs(root, mode=0o700, exist_ok=True)
        return root
    except Exception as ex:
        fallback = "/tmp/openclaw-bridge"
        os.makedirs(fallback, mode=0o700, exist_ok=True)
        pipe_log(f"STATE_DIR unavailable ({root}: {ex}); using {fallback}")
        return fallback


def _read_json_file(path):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return None
    except Exception as ex:
        pipe_log(f"Failed reading {path}: {ex}")
        return None


def _write_json_file(path, data):
    try:
        tmp = f"{path}.tmp"
        with open(tmp, "w") as f:
            json.dump(data, f, separators=(",", ":"))
        os.chmod(tmp, 0o600)
        os.replace(tmp, path)
        return True
    except Exception as ex:
        pipe_log(f"Failed writing {path}: {ex}")
        return False


# --- turns -----------------------------------------------------------------

# ---------------------------------------------------------------------------
# Turn identity (ELI-100, DESIGN-agent-turns.md 2.2)
# ---------------------------------------------------------------------------
# Every run on an Open WebUI session key renders as one assistant message, and
# which message is decided from the run id alone: any connection, deploy or
# restarted process gets the same answer without shared memory.
#
#   msg-<chat>-<M>-<suffix>   a pipe-started run: its message is M, the reply
#                             Open WebUI created for it (the user turn), or
#                             the reply a resume / ask-user answer continues
#   owui-action-<...>         the Status Action's own runs (/compact): none
#   anything else             an agent turn: uuid5(TURN_NS, "<key>:<run>")

TURN_NS = uuid.UUID("6f1c3e2a-9d4b-4c6e-8a1f-0e0a1b100100")
ACTION_RUN_PREFIX = "owui-action-"
_UUID_RE = r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"
_PIPE_RUN_RE = re.compile(rf"^msg-(?P<chat>{_UUID_RE})-(?P<message>{_UUID_RE})-(?P<rest>.+)$")


def pipe_run_id(chat_id: str, message_id: str, kind: str | None = None) -> str:
    """The run id for a pipe-started run that writes into Open WebUI message
    `message_id`: `msg-<chat>-<M>-<t>` for the reply itself, and
    `msg-<chat>-<M>-<kind>-<t>` for a run continuing it (`input`, `resume`).
    The trailing send time is what `_run_id_sent_at` reads."""
    return f"msg-{chat_id}-{message_id}-{kind + '-' if kind else ''}{time.time()}"


def parse_pipe_run_id(run_id: str) -> dict | None:
    """{chat, message, kind} of a pipe-started run id, else None. `kind` is
    `reply` for the reply's own run, or the continuation kind."""
    m = _PIPE_RUN_RE.match(run_id or "")
    if not m:
        return None
    head = m.group("rest").split("-", 1)[0]
    kind = head if head in ("input", "resume") else "reply"
    return {"chat": m.group("chat"), "message": m.group("message"), "kind": kind}


def parse_announce_run_id(run_id: str) -> dict | None:
    """{child_session, child_run} of a sub-agent announce run, else None.

    The Gateway runs a child's completion in the parent session with run id
    `announce:` + `v1:<childSessionKey>:<childRunId>` (announce-idempotency-
    D7LnUTJR.mjs:4-10), suffixed `:wake` or `:retry-<n>` on redelivery. A
    `announce:requester-settle:...` run wakes a yielded parent for a batch
    of children and names no single child."""
    if not (run_id or "").startswith("announce:v1:"):
        return None
    rest = re.sub(r":(?:wake|retry-\d+)$", "", run_id[len("announce:v1:"):])
    child_session, _, child_run = rest.rpartition(":")
    if not child_session.startswith("agent:") or not child_run:
        return None
    return {"child_session": child_session, "child_run": child_run}


def turn_message_id(session_key: str, run_id: str, chat_id: str | None = None) -> str | None:
    """The Open WebUI message run `run_id` on `session_key` renders into, or
    None when it renders nothing (the Status Action's own runs). A pipe run
    id naming another chat than `chat_id` is treated as an agent turn: the
    message id is only trusted inside the chat it was minted for."""
    if not run_id or run_id.startswith(ACTION_RUN_PREFIX):
        return None
    parsed = parse_pipe_run_id(run_id)
    if parsed and (chat_id is None or parsed["chat"] == chat_id):
        return parsed["message"]
    return str(uuid.uuid5(TURN_NS, f"{session_key}:{run_id}"))


# ---------------------------------------------------------------------------
# Claim: one message per run, anchored at the tail (DESIGN 2.3)
# ---------------------------------------------------------------------------
# The claim lives in Open WebUI's DB under the chat's row lock, not in a
# process map, so an old deploy's connection, a new one and a restarted
# process all agree: whoever inserts M first owns it, and two different runs
# that start together chain off the tail each reads under the lock.

_TURN_WRITERS_ATTR = "_openclaw_turn_writers"


def _live_turn_writers() -> set:
    """Writer ids of the connections alive in this Open WebUI process. Kept on
    `open_webui.socket.main` so every load of this Function (a redeploy keeps
    the old module objects alive until they are reaped) shares one set."""
    mod = sys.modules.get("open_webui.socket.main")
    if mod is None:
        return set()
    writers = getattr(mod, _TURN_WRITERS_ATTR, None)
    if writers is None:
        writers = set()
        setattr(mod, _TURN_WRITERS_ATTR, writers)
    return writers


def _register_turn_writer(writer_id: str) -> None:
    _live_turn_writers().add(writer_id)


def _retire_turn_writer(writer_id: str) -> None:
    _live_turn_writers().discard(writer_id)


# Writer ids name their process, so another Open WebUI worker's writer can
# be judged (review 2af1 R8): `<host>/<boot>/<pid>.<start>:<uuid>`, with the
# kernel's boot id and the process start time guarding against a reused pid.
# A writer of this process is alive while its connection is (the set above);
# one of another process on this host while that process runs. A writer of
# another host or boot, or an older pipe's `<pid>:<uuid>`, is judged gone, as
# before: a takeover across hosts needs a shared lease, which a single-host
# Open WebUI does not.
_WRITER_ID_RE = re.compile(r"^(?P<host>[^/]*)/(?P<boot>[^/]*)/(?P<pid>\d+)\.(?P<start>\d+):")


def _proc_start(pid: int) -> str | None:
    """Start time of process `pid` (/proc/<pid>/stat field 22), None if gone."""
    try:
        with open(f"/proc/{pid}/stat") as f:
            return f.read().rsplit(")", 1)[1].split()[19]
    except (OSError, IndexError):
        return None


def _boot_id() -> str:
    try:
        with open("/proc/sys/kernel/random/boot_id") as f:
            return f.read().strip()[:8]
    except OSError:
        return ""


def turn_writer_id() -> str:
    import socket
    pid = os.getpid()
    return f"{socket.gethostname()}/{_boot_id()}/{pid}.{_proc_start(pid) or 0}:{uuid.uuid4()}"


def _turn_writer_alive(writer: str | None) -> bool:
    if not writer:
        return False
    if writer in _live_turn_writers():
        return True
    m = _WRITER_ID_RE.match(writer)
    if not m or int(m.group("pid")) == os.getpid():
        return False
    import socket
    if (m.group("host"), m.group("boot")) != (socket.gethostname(), _boot_id()):
        return False
    return _proc_start(int(m.group("pid"))) == m.group("start")


def _writer_may_take_over(existing: dict) -> bool:
    """A message another writer recorded can be taken only when that writer
    is gone (its connection retired or its process exited) and the message
    is unfinished. A message with no recorded writer is Open WebUI's own stub
    for a user turn; only its own inline request hands it over
    (`takeover=True`, DESIGN 2.6)."""
    writer = (existing.get("meta") or {}).get("openclaw_writer")
    return bool(writer) and existing.get("done") is False and not _turn_writer_alive(writer)


async def _claim_turn_message(chat_id: str, user_id: str, message_id: str, run_id: str,
                              writer_id: str, takeover: bool = False) -> dict:
    """Claim message `message_id` for run `run_id` in chat `chat_id`.

    Under the chat's row lock (`Chats._chat_transaction`): if the message
    exists, it is someone's already, unless `takeover` (a pipe run taking its
    own stub, DESIGN 2.6) or its recorded writer is gone. Another live
    writer's message is never taken. Otherwise it
    is inserted under the deepest leaf, which becomes its parent, and
    `currentId` moves to it. The `chat_message` row is mirrored as
    `insert_chat_turn` does.

    Returns {claimed, how: new|takeover|taken, message_id, parent, messages}:
    `messages` holds the changed nodes, for the `chat:messages` introduce."""
    from open_webui.models.chats import Chats
    from open_webui.models.chat_messages import ChatMessages
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        data = chat.chat or {}
        history = data.get("history") or {"messages": {}, "currentId": None}
        msgs = history.setdefault("messages", {})
        existing = msgs.get(message_id)
        if existing is not None:
            holder = (existing.get("meta") or {}).get("openclaw_writer")
            held = bool(holder) and holder != writer_id and _turn_writer_alive(holder)
            if held or not (takeover or _writer_may_take_over(existing)):
                return {"claimed": False, "how": "taken", "message_id": message_id,
                        "parent": existing.get("parentId"), "messages": {}}
            meta = {**(existing.get("meta") or {}), "openclaw_run": run_id,
                    "openclaw_writer": writer_id}
            msgs[message_id] = {**existing, "meta": meta}
            changed = {message_id: msgs[message_id]}
            how, parent = "takeover", existing.get("parentId")
        else:
            parent = _deepest_leaf_id(msgs, history.get("currentId"))
            leaf = msgs.get(parent) or {}
            model = leaf.get("model") or next(iter(data.get("models") or []), None)
            msgs[message_id] = {
                "id": message_id, "parentId": parent, "childrenIds": [], "role": "assistant",
                "content": "", "output": [], "done": False, "model": model,
                "modelName": leaf.get("modelName") or model, "timestamp": int(time.time()),
                "meta": {"openclaw_run": run_id, "openclaw_writer": writer_id},
            }
            changed = {message_id: msgs[message_id]}
            if parent:
                msgs[parent] = {**leaf, "childrenIds": [*(leaf.get("childrenIds") or []), message_id]}
                changed[parent] = msgs[parent]
            history["currentId"] = message_id
            chat.current_message_id = message_id
            how = "new"
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        chat.updated_at = int(time.time())
        for mid, m in changed.items():
            await ChatMessages.upsert_message(mid, chat_id, user_id, m, db=db)
        return {"claimed": True, "how": how, "message_id": message_id, "parent": parent,
                "messages": changed}


# ---------------------------------------------------------------------------
# Owner rule: who continues an interrupted run (DESIGN 2.7)
# ---------------------------------------------------------------------------
# Read from the run's PERSISTED session row: the settled push after its
# terminal (hasActiveRun false), or the first sessions.list after hello-ok.
# The Gateway recovers only rows still `running`; the pipe resumes only rows
# already terminal with an outside kill, so one run never gets two
# continuations.

MAX_TURN_RESUMES = 3
# The child's exit reaches the row only as this text (no structured field;
# dist cli-transport line pinned in test_fixture_openclaw_exit_errors.json,
# re-checked against the installed dist by ExitTextFixtureTest): SIGTERM
# (143) and SIGKILL / OOM (137) by exit code, or a raw signal.
_EXTERNAL_KILL_RE = re.compile(r"process exited with (?:code (?:143|137)\b|signal SIG[A-Z]+)")


def turn_owner(row: dict, stop_notice_before: bool = False) -> str:
    """`gateway`, `pipe` or `none` for an interrupted run's settled row.

    `stop_notice_before`: a `shutdown` event without `restartExpectedMs`
    reached this connection before the run's terminal (a stop-mode abort,
    which the Gateway never recovers)."""
    status = (row or {}).get("status")
    if status == "running":
        return "gateway"
    if status == "failed" and _EXTERNAL_KILL_RE.search(str(row.get("lastRunError") or "")):
        return "pipe"
    if status == "killed" and stop_notice_before:
        return "pipe"
    return "none"


def next_continuation(row: dict, stop_notice_before: bool, resumes_so_far: int) -> str:
    """What the writer of M does when its run settles: `gateway` (keep M open
    for the recovery run), `wait` (another run holds the session: send
    nothing, decide again on its settle), `resume` (send
    msg-<chat>-<M>-resume-<t>), or `finalize`. A resume sent into a busy
    session is queued as a follow-up, and after a restart recovery that
    follow-up fails (M3-crash 04351f67), so a session with an active run
    never gets one. The budget is counted on M, so a resume that is cut the
    same way again (an OOM loop) ends after MAX_TURN_RESUMES."""
    owner = turn_owner(row, stop_notice_before)
    if owner == "gateway":
        return "gateway"
    if (row or {}).get("hasActiveRun"):
        return "wait"
    if owner == "pipe" and resumes_so_far < MAX_TURN_RESUMES:
        return "resume"
    return "finalize"


# ---------------------------------------------------------------------------
# Rule E and the active run, from the transcript (DESIGN 2.1, case 5)
# ---------------------------------------------------------------------------

RECOVERY_SOURCE_TOOL = "main_session_restart_recovery"


def _history_user_turns(messages: list) -> list:
    """[(run_id, provenance sourceTool)] of the admitted user turns, in order."""
    out = []
    for m in messages or []:
        run = _history_user_run_id(m)
        if run:
            out.append((run, (m.get("provenance") or {}).get("sourceTool")))
    return out


def recovery_source_run(messages: list, run_id: str) -> str | None:
    """Rule E: for a restart-recovery run (its `<id>:user` turn carries the
    `main_session_restart_recovery` provenance, dist
    main-session-restart-recovery-CPJjd8da.mjs:441, 452-456), the run it
    recovers: the newest non-recovery admitted turn before it, which is what
    the Gateway's restartRecoveryDeliverySourceRunId names
    (chat-send-handler-kZQfUabO.mjs:635-636, agent-command-C9QUtzmi.mjs:1019).
    None for any other run."""
    turns = _history_user_turns(messages)
    for i, (run, tool) in enumerate(turns):
        if run == run_id:
            if tool != RECOVERY_SOURCE_TOOL:
                return None
            return next((r for r, t in reversed(turns[:i]) if t != RECOVERY_SOURCE_TOOL), None)
    return None


def run_message_id(session_key: str, chat_id: str, run_id: str, messages: list | None = None) -> str | None:
    """The message run `run_id` writes into: its source run's for a restart
    recovery (rule E), else its own (turn_message_id)."""
    source = recovery_source_run(messages, run_id) if messages else None
    return turn_message_id(session_key, source or run_id, chat_id)


# ---------------------------------------------------------------------------
# Cron wakes: one run id for every wake into a session (ELI-103)
# ---------------------------------------------------------------------------
# The cron executor runs a session wake with runId = the session's sessionId
# (run-executor.runtime-ro-4Z0fM.mjs:499), so the id names no single wake.
# What does: the wake's own admitted user turn, `<logicalTurnId>:user` with the
# prompt `[cron:<jobId> <name>] ...` (isolated-agent-C_VaOV3U.mjs:1066) and no
# provenance. On claude-cli it is committed before the CLI starts, so before
# the wake's first event (cli-runner-9MSP9PU4.mjs:1370 awaits it ahead of
# runCliRecovery). The next wake's turn is committed only once this wake's
# execution has ended (session work admission). So the wake's turn is the
# newest one committed at or before the event's `ts`. The run's closing
# message is keyed `cli-assistant:<sessionId>` and deduplicated by that key
# (session-accessor-CX17Bx59.mjs:3343-3347), so only the first wake into a
# session ever gets one: never end or rebuild a wake from it.

_CRON_PROMPT_RE = re.compile(r"^\[cron:(?P<job>[^\s\]]+)[\s\]]")


def wake_turns(messages: list) -> list:
    """[{key, at, job}] of the cron wake user turns, in transcript order: `key`
    is the turn id (its `:user` key without the suffix), `at` its commit time
    (`recordTimestampMs`), `job` the cron job id from its prompt."""
    out = []
    for m in messages or []:
        key = _history_user_run_id(m)
        if not key or parse_pipe_run_id(key) or m.get("provenance"):
            continue
        hit = _CRON_PROMPT_RE.match(((_history_item(m) or {}).get("text") or "").lstrip())
        if not hit:
            continue
        meta = m.get("__openclaw") if isinstance(m.get("__openclaw"), dict) else {}
        at = meta.get("recordTimestampMs") or m.get("timestamp")
        out.append({"key": key, "at": at if isinstance(at, (int, float)) else None,
                    "job": hit.group("job")})
    return out


def wake_turn_at(messages: list, at_ms: float, bound=frozenset()) -> dict | None:
    """The wake whose event was emitted at `at_ms`: the newest wake turn
    committed at or before it that no earlier wake on this session took
    (`bound`). None while it is not committed yet (the embedded runtime writes
    the user turn without awaiting it, embedded-agent-DNQn_PMM.mjs:5891): the
    caller tries again on the wake's next event."""
    for turn in reversed(wake_turns(messages)):
        if turn["at"] is not None and turn["at"] <= at_ms:
            return None if turn["key"] in bound else turn
    return None


def wake_span(messages: list, start_ms: float, end_ms: float) -> list:
    """A wake's assistant messages: runs on one session are serialized, and
    claude-cli imports its transcript stamped with the CLI's own times, so
    everything the wake wrote lies between its turn's commit and its terminal.
    A user turn queued meanwhile is committed inside that window too; it is
    not the wake's and is left out."""
    out = []
    for m in messages or []:
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        ts = m.get("timestamp")
        if isinstance(ts, (int, float)) and start_ms <= ts <= end_ms:
            out.append(m)
    return out


# --- thinking --------------------------------------------------------------
# Shared by BOTH the Thinking filter and the Pipe: the filter offers the levels
# and the pipe enforces them against the live session ladder, so the ranks and
# the clamping rule have to be one implementation, not two that agree today.
#
# Deliberately has no imports, no classes, and no module-level names beyond the
# five below. It is concatenated into the Pipe artifact, where every name in it
# lands in the same flat namespace as every other fragment: a helper named like
# one of the pipe's own (a `_state_dir`, say) would silently shadow it
# depending on fragment order. Filter-only helpers live in `thinking_filter`
# for exactly that reason.

# ---------------------------------------------------------------------------
# Levels
# ---------------------------------------------------------------------------

# Ranks mirror the gateway's own table (off is genuinely a level, not an
# absence). Used to order the dropdown and to clamp downward, never upward:
# asking for less thinking than requested is a safe degradation, asking for
# more is a surprise on someone's bill.
LEVEL_RANKS = {
    "off": 0,
    "minimal": 10,
    "low": 20,
    "medium": 30,
    "adaptive": 30,
    "high": 40,
    "xhigh": 60,
    "max": 70,
    "ultra": 80,
}

# The sentinel meaning "do not send the field at all". Distinct from "off",
# which is an explicit instruction to not think. "default" leaves the agent's
# own configured level alone; "off" overrides it.
UNSET = "default"

# Used until the pipe has run once and written a real ladder cache. Every
# provider observed supports at least these, so nothing here can be a lie.
FALLBACK_LEVELS = ["off", "minimal", "low", "medium", "high"]

LADDER_CACHE_NAME = "thinking-ladders.json"

# The Gateway's rejection lists LABELS, not ids, and for most profiles the two
# are identical (`label: id`). The one divergence is the binary profile, which
# labels `low` as "on". Mapping it back is the difference between learning a
# model's real two-level ladder and learning a one-level lie.
LEVEL_LABEL_ALIASES = {"on": "low"}

# The exact anchors of the Gateway's hard validation error, e.g.:
#   Thinking level "high" is not supported for claude-cli/claude-opus-5. Use one of: off.
# All three must be present and in order. That is deliberately at least as
# narrow as matching the whole sentence: it can never fire on genuine assistant
# text that happens to discuss thinking levels.
_REJECT_HEAD = 'Thinking level "'
_REJECT_MID = '" is not supported for '
_REJECT_TAIL = ". Use one of: "


def parse_thinking_rejection(text):
    """Read the Gateway's own rejection as an authoritative per-model ladder.

    This exists because `sessions.describe` cannot be trusted for this. Describe
    builds its ladder with no model catalog in scope, so `resolveThinkingProfile`
    never sees the catalog's `reasoning: false` and falls through to the generic
    base profile -- it reported all 8 levels for `claude-cli/claude-opus-5`,
    whose real ladder is `["off"]`. The send path resolves the same question
    WITH the catalog and rejects. So the rejection is the only place the truth
    is stated, and throwing it away is what made this misfire once per turn
    forever instead of once per model.

    Returns None when `text` is not that rejection. Otherwise a dict:
    `{"level": requested, "model": "provider/model", "levels": [ids]}`.
    `levels` may be empty if every listed label is unrecognised -- the caller
    still learns which model rejected which level, so it must check for None
    rather than for falsiness.

    Pure string parsing on purpose: this fragment is shared with the Thinking
    filter, which imports nothing (not even `re`) so that a filter running on
    every message can never fail on an import it did not need.
    """
    if not text:
        return None
    head = text.find(_REJECT_HEAD)
    if head < 0:
        return None
    level_start = head + len(_REJECT_HEAD)
    mid = text.find(_REJECT_MID, level_start)
    if mid < 0:
        return None
    tail = text.find(_REJECT_TAIL, mid)
    if tail < 0:
        return None

    level = text[level_start:mid].strip().lower()
    model = text[mid + len(_REJECT_MID):tail].strip()
    if not level or not model or " " in model:
        # A model ref never contains a space. Anything that does means the
        # anchors matched something that merely reads like the rejection.
        return None

    listed = text[tail + len(_REJECT_TAIL):]
    stop = listed.find(".")
    if stop >= 0:
        listed = listed[:stop]
    levels = []
    for token in listed.split(","):
        name = token.strip().lower()
        name = LEVEL_LABEL_ALIASES.get(name, name)
        if name in LEVEL_RANKS and name not in levels:
            levels.append(name)
    levels.sort(key=lambda lv: LEVEL_RANKS[lv])
    return {"level": level, "model": model, "levels": levels}


def clamp_to_ladder(level, ladder):
    """Fit a requested level to what a model actually supports.

    Returns (resolved_level, note). `note` is None when the request went
    through untouched, otherwise a short human sentence explaining what
    changed, which the caller is expected to show rather than swallow.

    Clamping is always downward to the nearest supported rank. If the model
    supports nothing at or below the request (a ladder of only higher levels,
    which no observed provider has, but which costs nothing to handle), the
    lowest supported level is used.
    """
    if not level or level == UNSET:
        return None, None
    if not ladder:
        # No ladder known: pass the request through and let the gateway rule on
        # it. Silently dropping a level the user explicitly picked is worse.
        return level, None
    if level in ladder:
        return level, None

    want = LEVEL_RANKS.get(level)
    if want is None:
        return None, f"Unknown thinking level {level!r}, ignoring it."

    ranked_ladder = [lv for lv in ladder if lv in LEVEL_RANKS]
    if not ranked_ladder:
        return None, "This model reported no recognized thinking levels; ignoring the selection."

    at_or_below = [lv for lv in ranked_ladder if LEVEL_RANKS[lv] <= want]
    if at_or_below:
        best = max(at_or_below, key=lambda lv: LEVEL_RANKS[lv])
    else:
        best = min(ranked_ladder, key=lambda lv: LEVEL_RANKS[lv])
    return best, (
        f"This model does not support thinking level {level!r}, "
        f"using {best!r} instead."
    )


# --- media -----------------------------------------------------------------


# ---------------------------------------------------------------------------
# File Server (media delivery)
# ---------------------------------------------------------------------------

MEDIA_DIR = "/tmp/openclaw-pipe-media"
MEDIA_BASE_URL = "http://localhost:18791"

_file_server_started = False

_MEDIA_TRIGGER = "MEDIA:"
_MEDIA_FNAME_RE = re.compile(r"\.[A-Za-z0-9]{1,8}$")


def _looks_like_media_filename(fname: str) -> bool:
    """Return True only if fname plausibly names a real file (has an
    extension). Without this, ordinary prose that happens to use "MEDIA:"
    as a documentation term (e.g. "the MEDIA: fix is proven") gets its next
    word treated as a filename and mangled into a broken image link --
    confirmed live 2026-07-10 when explaining this very feature corrupted
    "the MEDIA: fix" into `![fix](.../fix)`.
    """
    return bool(_MEDIA_FNAME_RE.search(fname))


def _advance_media_buffer(pending: str, delta: str) -> tuple[str, str]:
    """Feed a new assistant-delta chunk into the MEDIA: buffering state.

    Returns (text_to_yield_now, new_pending), mirroring
    `_advance_input_prompt_buffer`. A real streaming provider can deliver
    "MEDIA:filename.png" split across multiple deltas at any point,
    including mid-filename or mid-prefix -- resolving `_resolve_media`
    eagerly against a single truncated delta either drops the directive
    entirely (if "MEDIA:" itself is split, so neither chunk contains the
    full prefix) or resolves it against a truncated filename (confirmed
    live 2026-07-10: sending several images in one turn hit both failure
    modes in the same message). Hold back from the first "MEDIA:" (or a
    prefix of it that could still complete) until a whitespace char
    confirms the filename is done.
    """
    candidate = pending + delta
    idx = candidate.find(_MEDIA_TRIGGER)
    if idx == -1:
        for i in range(min(len(_MEDIA_TRIGGER) - 1, len(candidate)), 0, -1):
            if candidate.endswith(_MEDIA_TRIGGER[:i]):
                return candidate[:-i], candidate[-i:]
        return candidate, ""
    after = candidate[idx + len(_MEDIA_TRIGGER):]
    if not re.search(r"\s", after):
        return candidate[:idx], candidate[idx:]
    return candidate, ""


def _take_media_fname(after_prefix: str) -> tuple[str, str]:
    """Split the text after a "MEDIA:" prefix into (filename, rest).

    A filename ends at whitespace OR at the next "MEDIA:" directive. Splitting
    on whitespace alone glued "X.pngMEDIA:X.png" into one bogus filename, and
    the reply persisted as `![X.pngMEDIA:X.png](.../X.pngMEDIA:X.png)`, a link
    that 404s (ELI-76). A copy of the same directive glued on with no separator
    is dropped: nothing emits that on purpose, it is a re-delivered tail.
    """
    token = after_prefix.split()[0] if after_prefix else ""
    fname = token.split(_MEDIA_TRIGGER, 1)[0]
    rest = after_prefix[len(fname):]
    glued = _MEDIA_TRIGGER + fname
    while fname and rest.startswith(glued):
        after = rest[len(glued):]
        if after and not after[0].isspace() and not after.startswith(_MEDIA_TRIGGER):
            break  # a different, longer filename that merely starts the same
        rest = after
    return fname, rest


def _resolve_media(text, base_url=None):
    """Convert every MEDIA:filename directive in text to embedded media.

    A single reply can legitimately carry several images (confirmed live
    2026-07-10 sending a 4-screenshot bug repro) -- this must loop over every
    occurrence, not just the first, or later directives in the same chunk
    silently pass through as literal "MEDIA:filename" text.
    """
    if base_url is None:
        base_url = MEDIA_BASE_URL
    prefix = "MEDIA:"
    if prefix not in text:
        return text, False
    handled = False
    out = ""
    remaining = text
    while prefix in remaining:
        idx = remaining.index(prefix)
        before = remaining[:idx]
        after_prefix = remaining[idx + len(prefix):].strip()
        fname, rest = _take_media_fname(after_prefix)
        if not fname:
            break
        if not _looks_like_media_filename(fname):
            # Not a real directive -- e.g. prose using "MEDIA:" as a term,
            # not a file reference. Leave this occurrence as literal text
            # and keep scanning past it for any genuine directive later on.
            out += before + prefix
            remaining = remaining[idx + len(prefix):]
            continue
        # Prefer HTTPS URL over base64 data URI (base64 breaks OWUI streaming parser).
        url = f"{base_url.rstrip('/')}/{fname}"
        rest = rest.strip()
        out += before + f"![{fname}]({url})"
        handled = True
        if rest:
            out += "\n"
        remaining = rest
    out += remaining
    return (out, True) if handled else (text, False)


def _extract_request_bearer(__request__):
    """Return a Bearer token from the current OWUI request, when available."""
    if not __request__:
        return None
    headers = getattr(__request__, "headers", None)
    if not headers:
        return None
    auth = headers.get("authorization") or headers.get("Authorization")
    if auth and auth.lower().startswith("bearer "):
        return auth.split(" ", 1)[1].strip()
    return None


def _multipart_body(field_name, file_path, filename, mime):
    boundary = "----openclawowui" + uuid.uuid4().hex
    with open(file_path, "rb") as f:
        raw = f.read()
    head = (
        f"--{boundary}\r\n"
        f'Content-Disposition: form-data; name="{field_name}"; '
        f'filename="{filename}"\r\n'
        f"Content-Type: {mime}\r\n\r\n"
    ).encode()
    tail = f"\r\n--{boundary}--\r\n".encode()
    return boundary, head + raw + tail


def _upload_owui_file(file_path, base_url, token):
    """Upload one file to OWUI Files API and return the file object."""
    if not token:
        raise RuntimeError("missing OWUI bearer token")
    filename = os.path.basename(file_path)
    mime = mimetypes.guess_type(filename)[0] or "application/octet-stream"
    boundary, body = _multipart_body("file", file_path, filename, mime)
    req = urllib.request.Request(
        f"{base_url.rstrip('/')}/api/v1/files/?process=false",
        data=body,
        headers={
            "Authorization": f"Bearer {token}",
            "Accept": "application/json",
            "Content-Type": f"multipart/form-data; boundary={boundary}",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode("utf-8", "replace"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", "replace")[:300]
        raise RuntimeError(f"OWUI file upload failed: {exc.code} {detail}") from exc


async def _resolve_media_via_owui(
    text,
    *,
    base_url,
    token,
    __event_emitter__,
):
    """Upload every MEDIA: file in text to OWUI, in order, and attach each to
    the current message.

    A single reply can legitimately carry several images (confirmed live
    2026-07-10 sending a 4-screenshot bug repro) -- this must loop over every
    occurrence, not just the first, or later directives in the same chunk
    silently pass through as literal "MEDIA:filename" text. If any single
    directive can't be resolved this way (file missing locally, bad name),
    bail out entirely with handled=False so the caller's fallback
    (`_resolve_media`) handles ALL directives uniformly via the external
    URL instead of leaving a mix of native-upload and unresolved directives
    in one message.
    """
    prefix = "MEDIA:"
    if prefix not in text:
        return text, False

    out = ""
    remaining = text
    uploaded_any = False
    while prefix in remaining:
        idx = remaining.index(prefix)
        before = remaining[:idx]
        after_prefix = remaining[idx + len(prefix):].strip()
        fname, rest = _take_media_fname(after_prefix)
        if not fname or not _looks_like_media_filename(fname):
            # Not a real directive -- e.g. prose using "MEDIA:" as a term,
            # not a file reference. Leave this occurrence as literal text
            # and keep scanning past it for any genuine directive later on.
            out += before + prefix
            remaining = remaining[idx + len(prefix):]
            continue
        if ".." in fname or "/" in fname:
            return text, False
        fpath = os.path.join(MEDIA_DIR, fname)
        if not os.path.isfile(fpath):
            return text, False

        # _upload_owui_file uses blocking urllib -- must run off the event loop.
        # This call goes to OWUI's own API (often 127.0.0.1:8080, i.e. OWUI
        # calling itself) from *inside* the async handler for the very request
        # that's driving this pipe run. Calling it directly would block the
        # single asyncio event loop thread, and OWUI can't service its own
        # incoming HTTP request while its own loop is blocked waiting on it --
        # a guaranteed self-deadlock that only resolves via timeout. Running it
        # in a thread lets the event loop keep serving requests concurrently.
        file_obj = await asyncio.to_thread(_upload_owui_file, fpath, base_url, token)
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "files",
                    "data": {"files": [file_obj]},
                }
            )

        file_id = file_obj.get("id")
        mime = file_obj.get("meta", {}).get("content_type") or mimetypes.guess_type(fname)[0] or ""
        content_url = f"/api/v1/files/{file_id}/content" if file_id else ""
        if content_url and mime.startswith("image/"):
            replacement = f"![{fname}]({content_url})"
        elif content_url:
            replacement = f"[{fname}]({content_url})"
        else:
            replacement = f"`{fname}`"

        rest = rest.strip()
        out += before + replacement
        uploaded_any = True
        if rest:
            out += "\n"
        remaining = rest

    out += remaining
    return (out, True) if uploaded_any else (text, False)


async def _resolve_media_text(text, *, valves, __request__=None, __event_emitter__=None):
    """Resolve a MEDIA: directive, preferring the native OWUI Files API upload
    and falling back to the external file-server URL. Shared by the main
    per-delta resolution site and the end-of-stream final-flush site so both
    stay in sync (see `_advance_media_buffer` for why callers must only pass
    in text whose MEDIA:filename is already known-complete).
    """
    handled = False
    resolved = text
    if valves.USE_OWUI_FILES:
        token = _extract_request_bearer(__request__) or valves.OWUI_API_KEY
        try:
            resolved, handled = await _resolve_media_via_owui(
                text,
                base_url=valves.OWUI_BASE_URL,
                token=token,
                __event_emitter__=__event_emitter__,
            )
        except Exception as ex:
            pipe_log(f"  OWUI file upload failed; falling back: {ex}")
    if not handled:
        resolved, handled = _resolve_media(text, base_url=valves.FILE_SERVER_BASE_URL)
    return resolved, handled


# Anchor for finding a file server left behind by a *previous* deploy of this
# same function (same class of issue as P33/P36/gateway._reap_stale_gateway_
# connection: OWUI's function loader execs each redeploy into a brand-new
# module object with no teardown hook on the old one, so a module-level
# _file_server_started flag alone just resets and a second HTTPServer tries
# to bind the same port -- silently failing since the old one is still
# listening, per _start_file_server's `except OSError: pass`). Stashing the
# server object on `open_webui.socket.main` -- OWUI's own stable module,
# never reloaded by our function -- lets the next deploy find and shut down
# the previous one first, so redeploys self-heal without a container
# restart. Falls back to a no-op when not running inside OWUI (unit tests).
_STALE_FILE_SERVER_ATTR = "_openclaw_file_server_v1"


def _reap_stale_file_server() -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    stale = getattr(_owui_socket_main, _STALE_FILE_SERVER_ATTR, None)
    if stale is None:
        return
    try:
        stale.shutdown()
        stale.server_close()
        pipe_log("  reaped stale file server from a previous deploy")
    except Exception as ex:
        pipe_log(f"  failed to reap stale file server (non-fatal): {ex}")


def _remember_file_server(server) -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    setattr(_owui_socket_main, _STALE_FILE_SERVER_ATTR, server)


def _start_file_server(port=18791):
    """Start a minimal HTTP server for media files. Starts once per process."""
    global _file_server_started
    if _file_server_started:
        return
    _reap_stale_file_server()
    directory = "/tmp/openclaw-pipe-media"
    os.makedirs(directory, exist_ok=True)
    Path(directory, "health").write_text("ok")

    class _Handler(SimpleHTTPRequestHandler):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, directory=directory, **kwargs)

        def end_headers(self):
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Cache-Control", "no-cache")
            super().end_headers()

        def _handle_upload(self):
            length = int(self.headers.get("Content-Length", 0))
            if length == 0:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"empty")
                return
            body = self.rfile.read(length)
            path = self.path.strip("/").split("?")[0]
            if not path or ".." in path or "/" in path:
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b"bad path")
                return
            dest = os.path.join(directory, os.path.basename(path))
            with open(dest, "wb") as f:
                f.write(body)
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(f"ok:{path}".encode())

        def do_PUT(self):
            self._handle_upload()

        def do_POST(self):
            self._handle_upload()


    try:
        server = HTTPServer(("0.0.0.0", port), _Handler)
        _remember_file_server(server)
        threading.Thread(target=server.serve_forever, daemon=True).start()
        _file_server_started = True
    except OSError:
        pass


# --- emit ------------------------------------------------------------------


async def _emit_status(__event_emitter__, description, *, done=False):
    """Send an OWUI status event when the current pipe call supports events."""
    if not __event_emitter__:
        return
    await __event_emitter__(
        {"type": "status", "data": {"description": description, "done": done}}
    )


def _fmt_tokens(n) -> str:
    """Compact token count: 115212 -> '115k', 1000000 -> '1.0m'."""
    try:
        n = int(n)
    except (TypeError, ValueError):
        return "?"
    if n >= 1_000_000:
        return f"{n / 1_000_000:.1f}m"
    if n >= 1_000:
        return f"{n // 1_000}k"
    return str(n)


def _format_goal_line(goal: dict) -> str:
    """Mirror the TUI footer's goal phrasing (see docs/tools/goal.md)."""
    status = goal.get("status")
    tokens_used = goal.get("tokensUsed")
    budget = goal.get("tokenBudget")
    used_fmt = _fmt_tokens(tokens_used) if tokens_used is not None else "?"
    if status == "active":
        if budget:
            return f"🎯 Pursuing goal ({used_fmt}/{_fmt_tokens(budget)})"
        objective = (goal.get("objective") or "").strip()
        if len(objective) > 40:
            objective = objective[:39] + "…"
        return f"🎯 Pursuing goal: {objective}" if objective else "🎯 Pursuing goal"
    if status == "paused":
        return "🎯 Goal paused (/goal resume)"
    if status == "blocked":
        return "🎯 Goal blocked (/goal resume)"
    if status == "usage_limited":
        return "🎯 Goal hit usage limits (/goal resume)"
    if status == "budget_limited":
        return f"🎯 Goal unmet ({used_fmt}/{_fmt_tokens(budget)})"
    if status == "complete":
        return f"🎯 Goal achieved ({used_fmt})"
    return ""


def _window_bit(w: dict) -> str | None:
    used = w.get("usedPercent")
    if used is None:
        return None
    return f"{w.get('label')} {round(100 - used)}% left"


def _relative_time(reset_at_ms) -> str | None:
    """Compact relative countdown: '22m', '4h07m', '3d07h'. None if unknown/past."""
    if not reset_at_ms:
        return None
    delta_s = int((reset_at_ms - time.time() * 1000) / 1000)
    if delta_s <= 0:
        return None
    days, rem = divmod(delta_s, 86400)
    hours, rem = divmod(rem, 3600)
    minutes = rem // 60
    if days:
        return f"{days}d{hours:02d}h"
    if hours:
        return f"{hours}h{minutes:02d}m"
    return f"{minutes}m"


def _window_reset_line(w: dict) -> str | None:
    """Full detail line for one rate-limit window, only when it has a known
    reset time -- e.g. '⏱ 5h 18% left (resets in 22m)'. Skipped for windows
    without a `resetAt` (e.g. Gemini's Pro/Flash aren't time-windows), since
    there'd be nothing new to say beyond what the thin combined line already
    shows.
    """
    bit = _window_bit(w)
    rel = _relative_time(w.get("resetAt"))
    if not bit or not rel:
        return None
    return f"⏱ {bit} (resets in {rel})"


async def _build_usage_status_lines(conn, session_key, timeout: float = 5) -> list[str]:
    """Best-effort final status lines: context window fill (combined with the
    provider's primary/nearest-term rate-limit window on the same line, kept
    deliberately thin -- no reset time), one full detail line per rate-limit
    window that has a known reset time (e.g. both '5h' and 'Week' for
    Anthropic/OpenAI), and the active session goal (if any) on its own line.
    Returned as separate short lines (rather than one combined line) because
    OWUI's status UI hard-clamps every line to a single row (`line-clamp-1`,
    no way to disable per-event) -- one line per fact keeps each row inside
    that clamp instead of getting cut off mid-number.

    OWUI shows only the *last* emitted status line by default (the rest
    only appear once the user expands that message's status history), so
    the thin context+primary-window line is placed last on purpose. Goal and
    the per-window reset-time detail lines still show up immediately on
    expand.

    Both RPCs are read-only and already used elsewhere by the pipe
    (`sessions.describe`) or are simple/cheap (`usage.status`); any failure
    here must not affect the actual reply, so every error is swallowed and
    just omits that line. They're fetched concurrently (not one after the
    other) so this adds at most one round trip's worth of latency, not two,
    to the moment the status line settles after the reply text is done.
    """
    describe_task = asyncio.ensure_future(
        conn.send_request("sessions.describe", dict(key=session_key), timeout=timeout)
    )
    usage_task = asyncio.ensure_future(conn.send_request("usage.status", {}, timeout=timeout))

    context_bit = None
    goal_line = None
    provider = None
    try:
        desc = await describe_task
        session_row = (desc or {}).get("session") or {}
        provider = session_row.get("modelProvider")
        context_tokens = session_row.get("contextTokens")
        total_tokens = session_row.get("totalTokens")
        if context_tokens and total_tokens is not None:
            pct = round(total_tokens / context_tokens * 100, 1)
            context_bit = f"🧠 {_fmt_tokens(total_tokens)}/{_fmt_tokens(context_tokens)} ({pct:g}%)"
        goal = session_row.get("goal")
        if goal:
            goal_line = _format_goal_line(goal) or None
    except Exception:
        pass

    primary_bit = None
    reset_lines = []
    try:
        usage = await usage_task
        if provider:
            for p in (usage or {}).get("providers", []):
                if p.get("provider") != provider:
                    continue
                windows = p.get("windows") or []
                bits = [b for b in (_window_bit(w) for w in windows) if b]
                if bits:
                    primary_bit = f"⏱ {bits[0]}"
                elif p.get("summary"):
                    primary_bit = f"⏱ {p['summary']}"
                # A full "(resets in ...)" line per window that actually has
                # a known reset time -- including the same window already
                # folded into `primary_bit`, since that one stays thin (no
                # reset time) on purpose.
                reset_lines = [
                    line for line in (_window_reset_line(w) for w in windows) if line
                ]
                break
    except Exception:
        pass

    context_and_primary = " · ".join(bit for bit in (context_bit, primary_bit) if bit) or None

    return [line for line in (goal_line, *reset_lines, context_and_primary) if line]


async def _emit_message_snapshot(__event_emitter__, content):
    """Persist the in-flight assistant message content for OWUI reloads.

    Pipe yielded content is still the final source of truth, but OWUI only saves
    that content when the pipe completes. A short-name `replace` event updates
    the message content in the DB while the run is still active, so navigating
    away and back can rehydrate the partial response.
    """
    if not __event_emitter__ or not content:
        return
    await __event_emitter__(
        {"type": "replace", "data": {"content": content}}
    )


# --- composer --------------------------------------------------------------

# ---------------------------------------------------------------------------
# Composer "Status" button (experiment).
#
# Open WebUI (0.12) has no hook for adding a button to the composer row:
# filter chips there only toggle a filter or open its valves. So the button is
# installed by an `execute` event, the same unsandboxed in-page JS channel the
# Status dialog already uses. Chat.svelte runs an `execute` event only when
# its chat_id is the chat the tab shows AND its message_id is already in that
# tab's history; anything else is silently dropped. The snippet:
#
#   * is idempotent: it records itself on `window.__openclawComposerBtn` with a
#     version, so a repeat delivery only refreshes its config, and a newer
#     version tears the old one down before installing itself;
#   * keeps the button present with one MutationObserver (debounced), across
#     re-renders and chat switches (OWUI is a SPA, the composer is rebuilt
#     freely), and gives up for good if it ever has to re-insert the button
#     in a tight loop;
#   * shows the button only on `/c/<id>` pages whose chat model is one of this
#     Pipe's models (one chat fetch per chat, cached for the page lifetime),
#     and removes it everywhere else;
#   * places it right after the "OpenClaw Thinking" filter chip, or at the end
#     of the composer's chip group when that chip is off; when neither anchor
#     exists it shows nothing;
#   * on click POSTs to the Status Action with the same body shape the dialog's
#     own Compact button uses, so the existing Action flow opens the real
#     dialog;
#   * never throws into the page: errors become one console warning each and,
#     for a failed click, a small toast.
#
# It is delivered three ways, all cheap and all idempotent:
#   (a) the Status Action emits it after every status run (one spark click
#       installs it);
#   (b) the Pipe emits it at the start of each turn;
#   (c) the Pipe's composer watcher pushes it to one socket as soon as that
#       socket opens a chat on one of this Pipe's models (Open WebUI 0.12
#       records each socket's open chat in SESSION_POOL[sid]["chat_ids"]).
#
# (a) and (b) target whatever message the emitter is bound to. (c) targets the
# chat's latest *user* message on purpose: OWUI's event handler writes back a
# shallow copy of the targeted message after running the code, and a user
# message is the one kind that never streams, so the push can never clobber a
# reply that is streaming into the same tab.
# ---------------------------------------------------------------------------

_COMPOSER_BUTTON_VERSION = "2"

# The Status Action's function id (install_action.py's FUNCTION_ID; the
# dialog's own JS calls the same fixed id) and the Pipe's default function id.
# A Pipe installed under another id still works: it adds its own id (from the
# module name OWUI gives it) and the prefix of every model it serves.
_COMPOSER_ACTION_ID = "openclaw_status_action"
_COMPOSER_DEFAULT_MODEL_PREFIX = "openclaw_gateway."

# Name of the Thinking filter's chip (install_filter.py registers the filter
# under this name, and OWUI renders it as the chip icon's alt text). The button
# goes right after that chip when it is on screen.
_COMPOSER_THINKING_CHIP_LABEL = "OpenClaw Thinking"

_COMPOSER_BUTTON_JS_TEMPLATE = r"""
(function () {
  const CFG = __OPENCLAW_COMPOSER_CONFIG__;
  const KEY = '__openclawComposerBtn';
  try {
    const prev = window[KEY];
    if (prev && prev.version === CFG.version) {
      if (typeof prev.configure === 'function') prev.configure(CFG);
      return;
    }
    if (prev && typeof prev.teardown === 'function') {
      try { prev.teardown(); } catch (e) { /* the old copy is going away anyway */ }
    }
  } catch (e) {
    console.warn('[openclaw-composer] guard failed', e);
    return;
  }

  const BTN_ID = 'openclaw-composer-status-button';
  // A chat that is not OpenClaw is looked at again after this long (its model
  // can be switched); an OpenClaw chat stays OpenClaw for the page lifetime.
  const NEGATIVE_TTL_MS = 600000;
  // Re-inserting the button more often than this means something keeps
  // removing it (a layout this snippet does not understand): give up.
  const LOOP_LIMIT = 20;
  const LOOP_WINDOW_MS = 10000;
  const SPARK_PATH = 'M9.813 15.904 9 18.75l-.813-2.846a4.5 4.5 0 0 0-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 0 0 3.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 0 0 3.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 0 0-3.09 3.09ZM18.259 8.715 18 9.75l-.259-1.035a3.375 3.375 0 0 0-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 0 0 2.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 0 0 2.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 0 0-2.456 2.456ZM16.894 20.567 16.5 21.75l-.394-1.183a2.25 2.25 0 0 0-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 0 0 1.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 0 0 1.423 1.423l1.183.394-1.183.394a2.25 2.25 0 0 0-1.423 1.423Z';

  const state = {
    prefixes: [],
    // Informational only: the Action does not use it for the status path.
    sessionId: null,
    cache: {},
    inflight: {},
    observer: null,
    timer: null,
    busy: false,
    inserts: [],
    warned: {},
    dead: false,
  };

  function warnOnce(tag, err) {
    if (state.warned[tag]) return;
    state.warned[tag] = true;
    try { console.warn('[openclaw-composer] ' + tag, err); } catch (e) { /* no console */ }
  }

  function configure(cfg) {
    (cfg.modelPrefixes || []).forEach(function (p) {
      if (typeof p === 'string' && p && state.prefixes.indexOf(p) === -1) state.prefixes.push(p);
    });
    if (cfg.sessionId) state.sessionId = cfg.sessionId;
    // A delivery names the chat it was sent for, and is only ever sent for
    // an OpenClaw chat, so that chat needs no lookup.
    if (typeof cfg.chatId === 'string' && cfg.chatId) {
      state.cache[cfg.chatId] = { ok: true, vouched: true, at: Date.now() };
    }
    schedule();
  }

  function token() {
    try { return localStorage.getItem('token') || ''; } catch (e) { return ''; }
  }

  function currentChatId() {
    const m = /^\/c\/([^\/?#]+)\/?$/.exec(location.pathname);
    if (!m) return null;
    const id = decodeURIComponent(m[1]);
    // Temporary chats are never saved, so there is nothing to look up.
    if (id.indexOf('local:') === 0) return null;
    return id;
  }

  function isOpenclawModel(id) {
    return typeof id === 'string' && state.prefixes.some(function (p) { return id.indexOf(p) === 0; });
  }

  function chatModel(chat) {
    const c = (chat && chat.chat) || {};
    const candidates = Array.isArray(c.models) ? c.models.slice() : [];
    const h = c.history || {};
    const cur = h.messages && h.currentId ? h.messages[h.currentId] : null;
    if (cur && cur.model) candidates.push(cur.model);
    for (let i = 0; i < candidates.length; i++) {
      if (isOpenclawModel(candidates[i])) return candidates[i];
    }
    return null;
  }

  // Latest user message on the current branch, else the current leaf. The
  // Action's dialog events target this id, and a user message never streams,
  // so a dialog opened mid-reply cannot race the reply's own updates.
  function targetMessageId(chat) {
    const h = ((chat && chat.chat) || {}).history || {};
    const msgs = h.messages || {};
    let id = h.currentId;
    for (let i = 0; id && i < 500; i++) {
      const m = msgs[id];
      if (!m) break;
      if (m.role === 'user') return id;
      id = m.parentId;
    }
    return h.currentId || null;
  }

  function fetchChat(chatId) {
    return fetch('/api/v1/chats/' + encodeURIComponent(chatId), {
      headers: { 'Authorization': 'Bearer ' + token() },
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  function classify(chatId) {
    if (state.inflight[chatId]) return;
    state.inflight[chatId] = true;
    fetchChat(chatId).then(function (chat) {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: !!chatModel(chat), at: Date.now() };
    }, function () {
      const prev = state.cache[chatId];
      if (prev && prev.vouched) return;
      state.cache[chatId] = { ok: false, at: Date.now() };
    }).then(function () {
      delete state.inflight[chatId];
      schedule();
    });
  }

  function toast(text) {
    try {
      const dark = document.documentElement.classList.contains('dark');
      const el = document.createElement('div');
      el.setAttribute('role', 'status');
      el.textContent = text;
      el.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);'
        + 'z-index:10001;max-width:min(420px,90vw);padding:10px 14px;border-radius:12px;'
        + 'font-size:13px;line-height:1.4;box-shadow:0 4px 16px rgba(0,0,0,0.18);';
      el.style.background = dark ? '#1f2937' : '#ffffff';
      el.style.color = dark ? '#f3f4f6' : '#111827';
      el.style.border = '1px solid ' + (dark ? '#374151' : '#e5e7eb');
      document.body.appendChild(el);
      setTimeout(function () { el.remove(); }, 4000);
    } catch (e) {
      warnOnce('toast failed', text);
    }
  }

  // The POST body the Status Action receives. Same shape as the dialog's own
  // Compact button, minus `mode`, so the Action takes its normal status path.
  function actionBody(chatId, chat) {
    let model = chatModel(chat);
    const c = (chat && chat.chat) || {};
    const entry = state.cache[chatId];
    if (!model && entry && entry.vouched && Array.isArray(c.models) && typeof c.models[0] === 'string') {
      // A workspace model built on an OpenClaw model: its id has none of the
      // Pipe's prefixes, but the Pipe itself vouched for this chat.
      model = c.models[0];
    }
    const messageId = targetMessageId(chat);
    if (!model || !messageId) return null;
    return {
      model: model,
      chat_id: chatId,
      id: messageId,
      session_id: state.sessionId || 'openclaw-composer',
    };
  }

  function openStatus(btn) {
    if (state.busy) return;
    const chatId = currentChatId();
    if (!chatId) return;
    state.busy = true;
    btn.style.opacity = '0.6';
    fetchChat(chatId).then(function (chat) {
      const body = actionBody(chatId, chat);
      if (!body) throw new Error('this chat has no OpenClaw message yet');
      return fetch('/api/chat/actions/' + CFG.actionId, {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + token(),
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
    }).then(function (r) {
      if (r && !r.ok) {
        return r.json().catch(function () { return {}; }).then(function (j) {
          throw new Error((j && j.detail) || ('HTTP ' + r.status));
        });
      }
    }).catch(function (err) {
      console.warn('[openclaw-composer] status failed', err);
      toast('OpenClaw status: ' + ((err && err.message) || err));
    }).then(function () {
      state.busy = false;
      btn.style.opacity = '';
    });
  }

  function makeButton() {
    const b = document.createElement('button');
    b.type = 'button';
    b.id = BTN_ID;
    b.title = 'OpenClaw status';
    b.setAttribute('aria-label', 'OpenClaw status');
    b.dataset.openclawVersion = CFG.version;
    b.className = 'p-[0.375rem] flex gap-1 items-center text-sm rounded-full '
      + 'transition-colors duration-300 focus:outline-hidden shrink-0 '
      + 'bg-transparent text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800';
    b.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" '
      + 'stroke-width="1.75" stroke="currentColor" aria-hidden="true" class="size-4">'
      + '<path stroke-linecap="round" stroke-linejoin="round" d="' + SPARK_PATH + '"/></svg>'
      + '<span class="pr-0.5">Status</span>';
    b.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      openStatus(b);
    });
    return b;
  }

  // {parent, after}: insert right after `after` inside `parent`, or at the end
  // of `parent` when `after` is null. null when no known anchor is on screen.
  function findSlot() {
    const integ = document.getElementById('integration-menu-button');
    const form = integ ? integ.closest('form') : null;
    if (!form) return null;
    const imgs = form.querySelectorAll('img[alt]');
    for (let i = 0; i < imgs.length; i++) {
      if (imgs[i].getAttribute('alt') !== CFG.thinkingChipLabel) continue;
      const chip = imgs[i].closest('button');
      const wrap = chip ? chip.parentElement : null;
      if (wrap && wrap.parentElement && form.contains(wrap.parentElement)) {
        return { parent: wrap.parentElement, after: wrap };
      }
    }
    // The chip is only rendered while the filter is on. Fall back to the end
    // of the chip group the composer always renders next to it.
    const row = integ.closest('div.justify-between');
    if (!row || !form.contains(row)) return null;
    const chips = row.querySelector(':scope > div.flex-1');
    const groups = chips ? chips.querySelectorAll(':scope > div.shrink-0') : [];
    if (groups.length) return { parent: groups[groups.length - 1], after: null };
    return null;
  }

  function removeAll() {
    const all = document.querySelectorAll('#' + BTN_ID);
    for (let i = 0; i < all.length; i++) all[i].remove();
  }

  function ensure() {
    if (state.dead) return;
    const chatId = currentChatId();
    let show = false;
    if (chatId) {
      const c = state.cache[chatId];
      if (!c || (!c.ok && Date.now() - c.at > NEGATIVE_TTL_MS)) classify(chatId);
      show = !!(c && c.ok);
    }
    const slot = show ? findSlot() : null;
    if (!slot) {
      removeAll();
      return;
    }
    const all = document.querySelectorAll('#' + BTN_ID);
    let btn = all.length ? all[0] : null;
    for (let i = 1; i < all.length; i++) all[i].remove();
    if (btn && btn.dataset.openclawVersion !== CFG.version) {
      btn.remove();
      btn = null;
    }
    const placed = btn && (slot.after
      ? slot.after.nextElementSibling === btn
      : slot.parent.lastElementChild === btn);
    if (placed) return;
    const now = Date.now();
    state.inserts = state.inserts.filter(function (t) { return now - t < LOOP_WINDOW_MS; });
    state.inserts.push(now);
    if (state.inserts.length > LOOP_LIMIT) {
      warnOnce('the composer keeps removing the button; giving up until reload', null);
      teardown();
      state.dead = true;
      return;
    }
    if (!btn) btn = makeButton();
    if (slot.after) slot.after.insertAdjacentElement('afterend', btn);
    else slot.parent.appendChild(btn);
  }

  function schedule() {
    if (state.timer || state.dead) return;
    state.timer = setTimeout(function () {
      state.timer = null;
      try { ensure(); } catch (e) { warnOnce('ensure failed', e); }
    }, 150);
  }

  function teardown() {
    if (state.observer) state.observer.disconnect();
    state.observer = null;
    if (state.timer) clearTimeout(state.timer);
    state.timer = null;
    window.removeEventListener('popstate', schedule);
    try { removeAll(); } catch (e) { /* page is going away */ }
  }

  try {
    window[KEY] = {
      version: CFG.version,
      configure: configure,
      teardown: teardown,
      ensure: ensure,
      // For live checks from the console; not used by the page.
      debug: function () {
        const chatId = currentChatId();
        return {
          version: CFG.version, chatId: chatId, prefixes: state.prefixes.slice(),
          cached: chatId ? state.cache[chatId] || null : null, dead: state.dead,
          slot: !!findSlot(), buttons: document.querySelectorAll('#' + BTN_ID).length,
          inserts: state.inserts.length,
        };
      },
      actionBody: actionBody,
    };
    state.observer = new MutationObserver(schedule);
    state.observer.observe(document.body, { childList: true, subtree: true });
    window.addEventListener('popstate', schedule);
    configure(CFG);
  } catch (e) {
    warnOnce('install failed', e);
  }
})();
"""


def _composer_own_function_id():
    """This artifact's Open WebUI function id, from the module name OWUI's
    loader gives it (`function_<id>_<32 hex>`, utils/plugin.py), or None
    outside Open WebUI."""
    m = re.match(r"^function_(.+)_[0-9a-f]{32}$", globals().get("__name__") or "")
    return m.group(1) if m else None


def _composer_model_prefixes(model_id=None, own_id=None) -> list:
    """The model-id prefixes the button treats as OpenClaw chats: the default
    Pipe id, the Pipe's own function id when known, and the function id of
    `model_id` (a model this Pipe actually served)."""
    prefixes = [_COMPOSER_DEFAULT_MODEL_PREFIX]
    extra = []
    if isinstance(own_id, str) and own_id:
        extra.append(own_id + ".")
    if isinstance(model_id, str) and "." in model_id:
        extra.append(model_id.split(".", 1)[0] + ".")
    for p in extra:
        if p not in prefixes:
            prefixes.append(p)
    return prefixes


def _render_composer_button_js(*, session_id=None, model_prefixes=None, chat_id=None) -> str:
    """The install snippet with its config embedded as one JSON literal (same
    no-interpolation rule as action.py's `_json_for_js`: `<` escaped so the
    payload can never close an enclosing script tag)."""
    config = {
        "version": _COMPOSER_BUTTON_VERSION,
        "actionId": _COMPOSER_ACTION_ID,
        "modelPrefixes": list(model_prefixes or [_COMPOSER_DEFAULT_MODEL_PREFIX]),
        "sessionId": session_id if isinstance(session_id, str) and session_id else None,
        "chatId": chat_id if isinstance(chat_id, str) and chat_id else None,
        "thinkingChipLabel": _COMPOSER_THINKING_CHIP_LABEL,
    }
    payload = json.dumps(config).replace("<", "\\u003c")
    return _COMPOSER_BUTTON_JS_TEMPLATE.replace("__OPENCLAW_COMPOSER_CONFIG__", payload)


async def _emit_composer_button(__event_emitter__, *, session_id=None, model_id=None,
                                chat_id=None, model_prefixes=None) -> bool:
    """Emit the install snippet through an OWUI event emitter. Best effort:
    returns False instead of raising, because a cosmetic button must never
    fail the turn or the Action that carries it."""
    if not __event_emitter__:
        return False
    try:
        code = _render_composer_button_js(
            session_id=session_id,
            model_prefixes=model_prefixes or _composer_model_prefixes(model_id),
            chat_id=chat_id,
        )
        await __event_emitter__({"type": "execute", "data": {"code": code}})
        return True
    except Exception as ex:
        pipe_log(f"[composer] could not emit the status button: {ex}")
        return False


def _composer_latest_user_message_id(history: dict):
    """Python twin of the snippet's targetMessageId(): the latest user message
    on the current branch, else the current leaf, else None."""
    if not isinstance(history, dict):
        return None
    messages = history.get("messages") or {}
    current = history.get("currentId")
    msg_id = current
    for _ in range(500):
        if not msg_id:
            break
        msg = messages.get(msg_id)
        if not isinstance(msg, dict):
            break
        if msg.get("role") == "user":
            return msg_id
        msg_id = msg.get("parentId")
    return current or None


def _composer_chat_is_openclaw(chat_data: dict, prefixes) -> bool:
    """Python twin of the snippet's chatModel(): any of the chat's models, or
    the current leaf's model, starts with one of `prefixes`."""
    if not isinstance(chat_data, dict):
        return False
    candidates = list(chat_data.get("models") or [])
    history = chat_data.get("history") or {}
    leaf = (history.get("messages") or {}).get(history.get("currentId")) or {}
    if isinstance(leaf, dict) and leaf.get("model"):
        candidates.append(leaf["model"])
    return any(
        isinstance(m, str) and any(m.startswith(p) for p in prefixes)
        for m in candidates
    )


# --- composer_watch --------------------------------------------------------
#
# Pipe only (the Action artifact does not include this fragment). Uses the
# snippet helpers from composer.py.


# ---------------------------------------------------------------------------
# (c) Composer watcher: push the snippet when a tab opens an OpenClaw chat.
#
# Open WebUI 0.12 tabs emit `events:chat` join/leave, and the server keeps the
# joined ids in SESSION_POOL[sid]["chat_ids"] (socket/main.py). There is no
# hook on the join itself, so this polls the pool. For each (sid, chat) pair,
# after a short settle delay, it loads the chat, checks that the socket's own
# user owns it and that it is on one of this Pipe's models, and sends the
# snippet to that one socket (`to=sid`, never the user room) targeting the
# chat's latest user message.
#
# It is sent with `sio.call`, not `emit`: Chat.svelte acks an `execute` event
# only after actually running it, and drops it (no ack) while the tab has not
# loaded that chat's history yet. No ack means a retry a few seconds later, up
# to _COMPOSER_WATCH_ATTEMPTS times. Leaving and re-joining a chat re-arms the
# pair. The watcher idles while this Pipe function is disabled and stops when
# it is deleted. Every failure is logged once and swallowed: on an Open WebUI
# without `chat_ids` the loop simply finds nothing.
# ---------------------------------------------------------------------------

_COMPOSER_WATCH_INTERVAL_S = 2.0
_COMPOSER_WATCH_SETTLE_S = 1.0
_COMPOSER_WATCH_ACK_TIMEOUT_S = 4.0
_COMPOSER_WATCH_RETRY_S = 3.0
_COMPOSER_WATCH_ATTEMPTS = 3
_COMPOSER_WATCH_LIVENESS_S = 30.0

# Stashed on `open_webui.socket.main` (OWUI's own stable module, see
# `_STALE_CONN_ATTR` in gateway.py for why) so a redeploy can cancel the
# previous deploy's watcher task instead of leaving two running.
_COMPOSER_WATCH_ATTR = "_openclaw_composer_watcher_v1"

_composer_watcher_task = None


class _ComposerWatcher:
    def __init__(self, valves_getter, prefixes_getter, function_id=None):
        self.valves_getter = valves_getter
        self.prefixes_getter = prefixes_getter
        self.function_id = function_id
        # (sid, chat_id) -> {"next": monotonic time, "attempts": int, "done": bool}
        self._pairs: dict = {}

    def enabled(self) -> bool:
        try:
            return bool(getattr(self.valves_getter(), "COMPOSER_STATUS_BUTTON", True))
        except Exception:
            return False

    @staticmethod
    def _session_pool_batches():
        import open_webui.socket.main as _owui_socket_main
        getter = getattr(_owui_socket_main, "get_session_pool_batches", None)
        if getter is not None:
            return getter()
        pool = getattr(_owui_socket_main, "SESSION_POOL", None) or {}
        return [list(pool.items())]

    @staticmethod
    async def _load_chat(chat_id):
        from open_webui.models.chats import Chats
        chat = Chats.get_chat_by_id(chat_id)
        if asyncio.iscoroutine(chat):
            chat = await chat
        return chat

    @staticmethod
    async def _call_sid(sid, payload) -> bool:
        """True when the tab acked, i.e. actually ran the snippet."""
        from open_webui.socket.main import sio
        try:
            await sio.call("events", payload, to=sid, timeout=_COMPOSER_WATCH_ACK_TIMEOUT_S)
            return True
        except Exception:
            return False

    async def function_state(self) -> str:
        """"active", "inactive", "gone" or "unknown" for this Pipe function."""
        if not self.function_id:
            return "unknown"
        try:
            from open_webui.models.functions import Functions
            fn = Functions.get_function_by_id(self.function_id)
            if asyncio.iscoroutine(fn):
                fn = await fn
        except Exception:
            return "unknown"
        if fn is None:
            return "gone"
        return "active" if getattr(fn, "is_active", True) else "inactive"

    async def tick(self, now=None):
        if not self.enabled():
            self._pairs.clear()
            return 0
        now = time.monotonic() if now is None else now
        live = set()
        due = []
        for batch in self._session_pool_batches():
            for sid, session in batch:
                if not isinstance(session, dict):
                    continue
                user_id = session.get("id")
                for chat_id in session.get("chat_ids") or []:
                    key = (sid, chat_id)
                    live.add(key)
                    st = self._pairs.get(key)
                    if st is None:
                        self._pairs[key] = {"next": now + _COMPOSER_WATCH_SETTLE_S,
                                            "attempts": 0, "done": False}
                        continue
                    if st["done"] or now < st["next"]:
                        continue
                    st["attempts"] += 1
                    due.append((key, user_id))
        for key in [k for k in self._pairs if k not in live]:
            del self._pairs[key]
        if not due:
            return 0

        results = await asyncio.gather(
            *(self._push(sid, chat_id, user_id) for (sid, chat_id), user_id in due),
            return_exceptions=True,
        )
        pushed = 0
        for ((sid, chat_id), _user_id), result in zip(due, results):
            st = self._pairs.get((sid, chat_id))
            if isinstance(result, BaseException):
                pipe_log(f"[composer] push to {str(sid)[:8]} failed: {result}")
                result = "retry"
            if result == "acked":
                pushed += 1
            if st is None:
                continue
            if result == "retry" and st["attempts"] < _COMPOSER_WATCH_ATTEMPTS:
                st["next"] = now + _COMPOSER_WATCH_RETRY_S
            else:
                st["done"] = True
        return pushed

    async def _push(self, sid, chat_id, user_id) -> str:
        """"acked" (the tab ran it), "skip" (not ours to push) or "retry"."""
        if not user_id:
            return "skip"
        chat = await self._load_chat(chat_id)
        if chat is None or getattr(chat, "user_id", None) != user_id:
            return "skip"
        data = getattr(chat, "chat", None) or {}
        prefixes = self.prefixes_getter()
        if not _composer_chat_is_openclaw(data, prefixes):
            return "skip"
        message_id = _composer_latest_user_message_id(data.get("history") or {})
        if not message_id:
            return "skip"
        # The Stop / Send now intent hook rides along: a tab that opens the
        # chat after a turn writer started must still answer its cancel query
        # (ELI-100 case 8). Wrapped so the hook's own `return` ends only it.
        code = ("(function () {" + _INTENT_HOOK_JS + "})();\n"
                + _render_composer_button_js(session_id=sid, model_prefixes=prefixes, chat_id=chat_id))
        acked = await self._call_sid(sid, {
            "chat_id": chat_id,
            "message_id": message_id,
            "data": {"type": "execute", "data": {"code": code}},
        })
        return "acked" if acked else "retry"

    async def run(self):
        last_error = None
        next_liveness = 0.0
        state = "unknown"
        while True:
            try:
                now = time.monotonic()
                if now >= next_liveness:
                    next_liveness = now + _COMPOSER_WATCH_LIVENESS_S
                    state = await self.function_state()
                    if state == "gone":
                        pipe_log("[composer] Pipe function deleted; watcher stops")
                        return
                if state != "inactive":
                    await self.tick()
                last_error = None
            except asyncio.CancelledError:
                raise
            except Exception as ex:
                # Logged once per distinct failure, not every interval.
                if str(ex) != last_error:
                    last_error = str(ex)
                    pipe_log(f"[composer] watcher tick failed: {ex}")
            await asyncio.sleep(_COMPOSER_WATCH_INTERVAL_S)


_composer_known_prefixes = [_COMPOSER_DEFAULT_MODEL_PREFIX]


def _composer_note_model(model_id=None) -> list:
    """Remember the Pipe's own function id and the prefix of a model it
    actually served, so the button also recognises chats when the Pipe is
    installed under a non-default id. Returns the known prefixes. Pipe only:
    in the Action artifact the module name is the Action's id."""
    for p in _composer_model_prefixes(model_id, own_id=_composer_own_function_id()):
        if p not in _composer_known_prefixes:
            _composer_known_prefixes.append(p)
    return list(_composer_known_prefixes)


def _ensure_composer_watcher(valves_getter):
    """Start the watcher once per deploy, inside Open WebUI only. Cancels a
    previous deploy's watcher found on the stable socket module. Returns the
    running task, or None when not inside OWUI, disabled, or on failure."""
    global _composer_watcher_task
    try:
        if not bool(getattr(valves_getter(), "COMPOSER_STATUS_BUTTON", True)):
            return None
        if _composer_watcher_task is not None and not _composer_watcher_task.done():
            return _composer_watcher_task
        try:
            import open_webui.socket.main as _owui_socket_main
        except Exception:
            return None
        _composer_note_model()
        stale = getattr(_owui_socket_main, _COMPOSER_WATCH_ATTR, None)
        if stale is not None and stale is not _composer_watcher_task:
            try:
                stale.cancel()
            except Exception:
                pass
        watcher = _ComposerWatcher(valves_getter, lambda: list(_composer_known_prefixes),
                                   function_id=_composer_own_function_id())
        _composer_watcher_task = asyncio.get_running_loop().create_task(watcher.run())
        setattr(_owui_socket_main, _COMPOSER_WATCH_ATTR, _composer_watcher_task)
        return _composer_watcher_task
    except Exception as ex:
        pipe_log(f"[composer] could not start the watcher: {ex}")
        return None


# --- askuser ---------------------------------------------------------------


_USER_INPUT_TRIGGER_PREFIXES = ("Codex needs input:", "OpenClaw needs input:")


def _is_user_input_prompt(text: str) -> bool:
    """Return True for OpenClaw/Codex blocking user-input prompts."""
    normalized = (text or "").lstrip()
    return any(normalized.startswith(p) for p in _USER_INPUT_TRIGGER_PREFIXES)


def _could_be_user_input_prefix(normalized_text: str) -> bool:
    """Return True while `normalized_text` (already left-stripped) is still
    ambiguous: either a strict prefix of one of the trigger phrases (so more
    streamed text could still complete it), or already a full match.

    Used to decide whether to keep withholding assistant-delta text instead
    of yielding it immediately -- real token-by-token streaming (e.g. Claude)
    delivers the trigger phrase a few characters at a time, so checking each
    raw delta in isolation (as `_is_user_input_prompt` does) never matches.
    Only once the buffered text diverges from every trigger prefix do we know
    for sure this message isn't a needs-input prompt.
    """
    if not normalized_text:
        return True
    return any(
        normalized_text.startswith(p) or p.startswith(normalized_text)
        for p in _USER_INPUT_TRIGGER_PREFIXES
    )


# CommonMark 4.5: a fence is 3+ backticks or tildes indented up to 3 spaces;
# a backtick fence's info string has no backtick; only a run of the same
# character, at least as long and followed by nothing but spaces, closes it.
_FENCE_OPEN_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
_FENCE_CLOSE_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})[ \t]*$")


def _fence_of(state) -> str:
    """A fence state as the open fence's run ("" when none). `True` is an
    open backtick fence of unknown length (older callers passed a bool)."""
    if state is True:
        return "```"
    return state or ""


def _fence_step(line: str, fence: str) -> str:
    """The fence state after `line` when `fence` was open before it."""
    if fence:
        m = _FENCE_CLOSE_RE.match(line)
        if m and m.group(1)[0] == fence[0] and len(m.group(1)) >= len(fence):
            return ""
        return fence
    m = _FENCE_OPEN_RE.match(line)
    if m and not (m.group(1)[0] == "`" and "`" in m.group(2)):
        return m.group(1)
    return ""


def _fence_open_after(text: str, in_fence=False) -> str:
    """The fenced code block open at the end of `text` (its fence run, "" when
    none), when `in_fence` was open where `text` starts. Truthy when open."""
    fence = _fence_of(in_fence)
    for line in (text or "").split("\n"):
        fence = _fence_step(line, fence)
    return fence


def _marker_line_index(text: str, in_fence=False):
    """Index of the first line that opens a needs-input block, else None.

    The marker only counts at the start of a line, but it does NOT have to be
    the start of the message: a reply usually explains itself first and asks at
    the end. The buffer used to look only at the text after the LAST newline,
    which is fine while tokens arrive one at a time, but wrong when a provider
    delivers the whole reply as ONE cumulative chunk. In that case the marker
    sat mid-string with its option lines after it, was never recognised, and
    leaked into the chat as raw text with no dialog (seen live 2026-08-01 on a
    claude-cli turn; token-streamed turns were unaffected, which is why this
    looked intermittent).

    A line inside a fenced code block is a quote, not a prompt (ELI-107: a
    report quoting the block in a fence was held as a live prompt and hung).
    `in_fence`: a fence is open where `text` starts.
    """
    start, fence = 0, _fence_of(in_fence)
    while True:
        nl = text.find("\n", start)
        line = text[start:] if nl == -1 else text[start:nl]
        before, fence = fence, _fence_step(line, fence)
        if not before and not fence and _is_user_input_prompt(line):
            return start
        if nl == -1:
            return None
        start = nl + 1


def _advance_input_prompt_buffer(pending: str, delta: str,
                                 in_fence=False) -> tuple[str, str]:
    """Feed a new assistant-delta chunk into the needs-input buffering state.

    Returns `(text_to_yield_now, new_pending)`. `pending` is text already
    withheld because it might still become a needs-input trigger.

    A trigger is only meaningful as the start of a line, so once the
    combined text (`pending + delta`) diverges from every trigger prefix,
    only the text after the LAST newline is worth re-examining as a fresh
    candidate -- a real streaming delta doesn't necessarily break exactly at
    a line boundary (e.g. a single chunk can contain the tail of one
    paragraph, the blank-line separator, *and* the start of the next one),
    so checking `delta.endswith("\\n")` at the yield site isn't enough on
    its own (P22 follow-up, 2026-07-08 -- caught live: a reply that talked
    normally first and only asked its question in the next paragraph never
    got buffered, because the newline landed mid-delta, not at its edge).

    `in_fence`: a fenced code block is open where `pending + delta` starts
    (the shown text left it open); nothing in a fence is held (ELI-107).
    """
    candidate = pending + delta
    if not in_fence and _could_be_user_input_prefix(candidate.lstrip()):
        return "", candidate
    # A complete marker may sit mid-candidate when the whole reply arrives at
    # once. Flush what precedes it and hold from the marker onward.
    marker_at = _marker_line_index(candidate, in_fence)
    if marker_at is not None:
        return candidate[:marker_at], candidate[marker_at:]
    idx = candidate.rfind("\n")
    if idx == -1:
        return candidate, ""
    before, after = candidate[: idx + 1], candidate[idx + 1 :]
    if after and not _fence_open_after(before, in_fence) and _could_be_user_input_prefix(after.lstrip()):
        return before, after
    return before + after, ""


def _strip_input_marker_line(text: str) -> str:
    """Remove a leading needs-input trigger line ("OpenClaw needs input:" /
    "Codex needs input:") from text about to be shown as visible content.

    A needs-input prompt is normally intercepted into a modal and never
    rendered raw. But the fallback paths -- a cancelled/dismissed modal, a run
    that ended before the modal could fire, or the item-event path which lacks
    the streaming buffer guard -- can still reach a raw ``yield`` with the marker
    intact, leaking the literal directive line into the chat. The marker is only
    ever meaningful as the FIRST line, so drop exactly that line and keep the
    rest (the actual question) as a readable fallback.
    """
    if not text:
        return text
    stripped = text.lstrip()
    lead_ws = text[: len(text) - len(stripped)]
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        if stripped.startswith(prefix):
            rest = stripped[len(prefix):]
            nl = rest.find("\n")
            rest = rest[nl + 1:] if nl != -1 else ""
            return lead_ws + rest.lstrip("\n")
    return text


def _strip_needs_input_lines(text: str) -> str:
    """Drop every needs-input directive line (and the blank lines after it)
    that is outside a fenced code block: the question it opens stays as
    readable text, a quoted block in a fence stays as written (ELI-107)."""
    if not text:
        return text
    out, fence, skip_blank = [], "", False
    for line in text.split("\n"):
        before, fence = fence, _fence_step(line, fence)
        if not before and not fence and _is_user_input_prompt(line):
            skip_blank = True
            continue
        if skip_blank and not line.strip():
            continue
        skip_blank = False
        out.append(line)
    return "\n".join(out)


def _truncate_at_repeated_marker(text: str) -> str:
    """Keep only the FIRST needs-input block.

    An agent that emits the marker block twice (seen live: the second copy glued
    straight onto the last option, "3. Park itOpenClaw needs input: ...") turned
    a 3-option question into a 6-button dialog, one of whose labels was the raw
    internal directive. The agent misbehaved, but the pipe owns what the user
    sees, so it should not render that. Everything from a second marker onward
    is a repeat, not part of the prompt.
    """
    if not text:
        return text
    first_end = -1
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        i = text.find(prefix)
        if i != -1 and (first_end == -1 or i + len(prefix) < first_end):
            first_end = i + len(prefix)
    if first_end == -1:
        return text
    nxt = -1
    for prefix in _USER_INPUT_TRIGGER_PREFIXES:
        i = text.find(prefix, first_end)
        if i != -1 and (nxt == -1 or i < nxt):
            nxt = i
    return text[:nxt].rstrip() if nxt != -1 else text


def _dedupe_options(options):
    """Drop repeated option labels, keeping first-seen order.

    Belt and braces behind _truncate_at_repeated_marker: a dialog that offers
    the same answer twice is always wrong, whatever produced it.
    """
    seen, out = set(), []
    for opt in options:
        key = opt.strip().lower()
        if key and key not in seen:
            seen.add(key)
            out.append(opt)
    return out


def _extract_numbered_options(prompt_text: str) -> list[tuple[str, str]]:
    """Return [(index_str, label), ...] for a numbered option list, in prompt
    order, or [] if there are none. Matches lines like "1. foo" / "2) bar"."""
    pattern = re.compile(r"(?m)^\s*(\d+)[.)]\s+(.+)$")
    return [(m.group(1), m.group(2).strip()) for m in pattern.finditer(prompt_text or "")]


def _build_choice_modal_js(
    title: str, message: str, options: list[str], multi: bool = False
) -> dict:
    """Turn a numbered-option prompt into a real {"type": "execute"} OWUI event
    payload: a clickable-button overlay that resolves to the chosen label(s).

    OWUI has no native "pick one of N buttons" widget (only free-text "input",
    yes/no "confirmation", and a "select" dropdown). The "execute" event type
    runs raw JS: OWUI does `new Function('return (async () => {'+code+'})()')()`
    and forwards whatever that async fn *returns* as the __event_call__ result.
    There is no resolve/reject in scope, so the code must end with
    `return await new Promise(...)` whose executor's `resolve` is what button
    clicks call -- a bare top-level resolve() is a silent ReferenceError
    swallowed by OWUI's try/catch (the modal then just hangs; confirmed live
    2026-07-10).

    Single-select (multi=False): clicking a button resolves immediately to
    {value: label}. Multi-select (multi=True): each option toggles a checkbox;
    a "Submit" button (disabled until >=1 is picked) resolves to
    {value: "label1, label2"} (click order), which _normalize_event_call_response
    passes through verbatim so the agent receives a comma-joined list. In both
    modes Escape / backdrop resolve to null (cancel) so the pipe falls back /
    keeps waiting like the other modals. Themed with OWUI's own --color-gray-*
    CSS vars so it matches light/dark, with a plain-color fallback if absent.
    """
    cfg_json = json.dumps(
        {"title": title, "message": message, "options": options, "multi": bool(multi)}
    )
    code = (
        "return await new Promise(function(resolve){\n"
        "  var cfg = JSON.parse(" + json.dumps(cfg_json) + ");\n"
        "  var done = false;\n"
        "  var selected = [];\n"
        "  function finish(v){ if(done) return; done = true;"
        " try{ document.body.removeChild(ov); }catch(e){}"
        " document.removeEventListener('keydown', onKey); resolve(v); }\n"
        "  var stale = document.querySelectorAll('[data-openclaw-choice]');\n"
        "  for(var si=0; si<stale.length; si++){"
        " try{ stale[si].parentNode.removeChild(stale[si]); }catch(e){} }\n"
        "  var ov = document.createElement('div');\n"
        "  ov.setAttribute('data-openclaw-choice','1');\n"
        "  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);"
        "z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:1rem;';\n"
        "  var box = document.createElement('div');\n"
        "  box.style.cssText = 'background:var(--color-gray-850,#1b1b1b);"
        "color:var(--color-gray-100,#ececec);border:1px solid var(--color-gray-700,#333);"
        "padding:1.25rem;border-radius:.75rem;max-width:min(28rem,92vw);width:100%;"
        "max-height:88vh;overflow-y:auto;overscroll-behavior:contain;"
        "box-shadow:0 10px 40px rgba(0,0,0,.5);font-family:inherit;';\n"
        "  if(cfg.title){ var h=document.createElement('div'); h.textContent=cfg.title;"
        " h.style.cssText='font-weight:600;font-size:1rem;margin-bottom:.35rem;'; box.appendChild(h); }\n"
        "  if(cfg.message){ var m=document.createElement('div'); m.textContent=cfg.message;"
        " m.style.cssText='opacity:.8;font-size:.9rem;margin-bottom:.9rem;white-space:pre-wrap;';"
        " box.appendChild(m); }\n"
        "  var sub;\n"
        "  cfg.options.forEach(function(label){\n"
        "    var b=document.createElement('button');\n"
        "    b.style.cssText='display:block;width:100%;text-align:left;margin:.35rem 0;"
        "padding:.6rem .75rem;border-radius:.5rem;border:1px solid var(--color-gray-700,#3a3a3a);"
        "background:var(--color-gray-800,#2a2a2a);color:inherit;font-size:.9rem;cursor:pointer;"
        "transition:background .12s;';\n"
        "    if(cfg.multi){\n"
        "      var mark=document.createElement('span');"
        " mark.textContent='\\u2610 '; mark.style.cssText='opacity:.85;';\n"
        "      var lab=document.createElement('span'); lab.textContent=label;\n"
        "      b.appendChild(mark); b.appendChild(lab);\n"
        "      b.onclick=function(){\n"
        "        var i=selected.indexOf(label);\n"
        "        if(i>=0){ selected.splice(i,1); mark.textContent='\\u2610 ';"
        " b.style.background='var(--color-gray-800,#2a2a2a)'; }\n"
        "        else { selected.push(label); mark.textContent='\\u2611 ';"
        " b.style.background='var(--color-gray-600,#4a4a4a)'; }\n"
        "        if(sub){ sub.disabled=selected.length===0;"
        " sub.style.opacity=selected.length?'1':'.5';"
        " sub.style.cursor=selected.length?'pointer':'not-allowed'; }\n"
        "      };\n"
        "    } else {\n"
        "      b.textContent=label;\n"
        "      b.onmouseenter=function(){ b.style.background='var(--color-gray-700,#3a3a3a)'; };\n"
        "      b.onmouseleave=function(){ b.style.background='var(--color-gray-800,#2a2a2a)'; };\n"
        "      b.onclick=function(){ finish({value: label}); };\n"
        "    }\n"
        "    box.appendChild(b);\n"
        "  });\n"
        "  if(cfg.multi){\n"
        "    sub=document.createElement('button'); sub.textContent='Submit';\n"
        "    sub.style.cssText='display:block;width:100%;margin:.75rem 0 0;"
        "padding:.6rem .75rem;border-radius:.5rem;border:none;"
        "position:sticky;bottom:0;box-shadow:0 -8px 12px var(--color-gray-850,#1b1b1b);"
        "background:var(--color-gray-100,#ececec);color:var(--color-gray-900,#111);"
        "font-weight:600;font-size:.9rem;cursor:not-allowed;opacity:.5;';\n"
        "    sub.disabled=true;\n"
        "    sub.onclick=function(){ if(!selected.length) return;"
        " finish({value: selected.join(', ')}); };\n"
        "    box.appendChild(sub);\n"
        "  }\n"
        "  var onKey=function(e){ if(e.key==='Escape'){ finish(null); } };\n"
        "  document.addEventListener('keydown', onKey);\n"
        "  ov.onclick=function(e){ if(e.target===ov){ finish(null); } };\n"
        "  ov.appendChild(box);\n"
        "  document.body.appendChild(ov);\n"
        "});\n"
    )
    return {"type": "execute", "data": {"code": code}}


def _modal_payload_from_user_input_prompt(prompt_text: str) -> tuple[dict, bool]:
    """Build an OWUI modal payload from OpenClaw's "needs input:" prompt text.

    Returns (payload_dict, is_confirmation) where is_confirmation is True
    if a yes/no confirmation modal was chosen instead of a free-text input.

    A non-secret prompt carrying >=2 numbered options becomes a "choice"
    payload (clickable buttons -- see _build_choice_modal_js), which the
    caller converts to an "execute" event just before firing it.
    """
    prompt_text = _truncate_at_repeated_marker(prompt_text or "")
    lines = [line.strip() for line in prompt_text.splitlines()]
    lines = [line for line in lines if line]
    if lines and lines[0].endswith("needs input:"):
        lines = lines[1:]

    title = "OpenClaw needs input"
    if lines and len(lines[0]) <= 80 and not re.match(r"^\d+\.", lines[0]):
        title = lines[0]
        lines = lines[1:]

    message = "\n".join(lines).strip() or "Please answer so the run can continue."

    text_lower = (prompt_text or "").lower()

    # Multi-select ("check all that apply"): a numbered-option prompt carrying
    # one of these markers renders checkboxes + a Submit button instead of
    # one-click-and-done buttons. The marker itself is stripped from the
    # displayed title/message so the user never sees the raw directive.
    multi_markers = (
        "(multiselect)", "(multi-select)", "(multi)", "[multiselect]", "[multi]",
        "select all that apply", "choose all that apply", "check all that apply",
        "בחר כמה", "בחירה מרובה", "אפשר לבחור כמה", "בחר את כל",
    )
    has_multi_marker = any(m in text_lower for m in multi_markers)
    if has_multi_marker:
        for mk in multi_markers:
            title = re.sub(re.escape(mk), "", title, flags=re.IGNORECASE).strip()
            message = re.sub(re.escape(mk), "", message, flags=re.IGNORECASE).strip()
        title = title or "OpenClaw needs input"
        message = message or "Please answer so the run can continue."

    # Detect password / secret input. Kept specific on purpose: a bare "key"
    # substring matches innocent words ("monkey", "which key order?"), so we
    # only trigger on unambiguous secret markers.
    is_secret = any(
        marker in text_lower
        for marker in ("secret", "password", "may show your reply", "api key", "token")
    )

    # Detect confirmation (yes/no) questions -- conservatively. Misclassifying a
    # free-text choice as a binary yes/no silently strips the real answer, so we
    # only pick confirmation when the prompt clearly reads as binary:
    #   * an explicit yes/no marker is present, OR
    #   * a strong confirm verb appears AND the prompt ends with "?".
    # An enumerated option list ("1. ... 2. ...") is a CHOICE, never yes/no.
    has_options = bool(re.search(r"(?m)^\s*\d+[.)]\s", prompt_text or ""))
    yn_markers = ("(y/n)", "[y/n]", "y/n?", "yes/no", "(yes/no)")
    confirm_verbs = (
        "confirm", "proceed", "overwrite", "are you sure", "do you want",
        "delete", "remove", "בטוח", "האם", "هل تريد",
    )
    has_yn_marker = any(m in text_lower for m in yn_markers)
    has_confirm_verb = any(w in text_lower for w in confirm_verbs)
    ends_question = message.rstrip().endswith("?") or title.rstrip().endswith("?")
    is_confirmation = (
        not is_secret
        and not has_options
        and (has_yn_marker or (has_confirm_verb and ends_question))
    )

    if is_confirmation:
        # Use yes/no confirmation dialog for quick binary choices
        data = {
            "title": title,
            "message": message,
        }
        return {"type": "confirmation", "data": data}, True

    # Real clickable options ("American style" multiple choice): a numbered
    # list that isn't a secret prompt and didn't get claimed by confirmation.
    options = _extract_numbered_options(prompt_text)
    if not is_secret and len(options) >= 2:
        data = {
            "title": title,
            "message": message,
            "options": _dedupe_options([label for _, label in options]),
            "multi": has_multi_marker,
        }
        return {"type": "choice", "data": data}, False

    # Default: free-text input
    data = {
        "title": title,
        "message": message,
        "placeholder": "Reply with a number or your answer",
    }
    if is_secret:
        data["type"] = "password"
    return {"type": "input", "data": data}, False


_OPTION_DESCRIPTION_SEPARATORS = (" - ", " – ", " — ")

# OWUI clamps a request:user_input event call to 60..240s and, when it times
# out, removes the card itself. We ask for the maximum and re-show the card
# after each timeout, so a question waits for as long as max_wait_s allows.
_NATIVE_CARD_TIMEOUT_MS = 240_000
# A card cancelled this fast was never seen: OWUI's frontend cancels
# request:user_input at once when the user is viewing another chat.
_NATIVE_CARD_UNSEEN_CANCEL_S = 1.5
# How long a question card waits for a tab to view the chat again (a reload)
# before the reply ends with the question as text (ELI-107 decision 2).
_NATIVE_CARD_TAB_GRACE_S = 60


def _owui_supports_native_ask_user() -> bool:
    """True when the running OWUI renders `request:user_input` as its native
    question card (the ask_user builtin, shipped in 0.11.1)."""
    try:
        from open_webui.env import VERSION
    except Exception:
        return False
    parts = re.findall(r"\d+", str(VERSION))[:3]
    if len(parts) < 3:
        return False
    return tuple(int(p) for p in parts) >= (0, 11, 1)


def _split_option_description(text: str) -> tuple[str, str]:
    """"Postgres - robust, needs a server" -> ("Postgres", "robust, needs a server")."""
    for sep in _OPTION_DESCRIPTION_SEPARATORS:
        label, found, description = text.partition(sep)
        if found and label.strip() and description.strip():
            return label.strip(), description.strip()
    return text.strip(), ""


def _parse_ask_user_json(prompt_text: str) -> list[dict] | None:
    """Questions from a JSON needs-input body, or None for the text form.

    The body after the marker line may be a JSON object (optionally in a code
    fence) shaped like OWUI's ask_user arguments:
    {"questions": [{"header": ..., "question": ..., "options": [...]}]}.
    Options are strings or {"label", "description"} objects.
    """
    body = _strip_input_marker_line(_truncate_at_repeated_marker(prompt_text or "")).strip()
    fence = re.match(r"^```[a-zA-Z]*\s*\n(.*?)\n?```\s*$", body, re.DOTALL)
    if fence:
        body = fence.group(1).strip()
    if not body.startswith("{"):
        return None
    try:
        parsed = json.loads(body)
    except ValueError:
        return None
    raw_questions = parsed.get("questions") if isinstance(parsed, dict) else None
    if not isinstance(raw_questions, list) or not raw_questions:
        return None

    allow_other = parsed.get("allow_other", True) is not False
    questions, seen_ids = [], set()
    for index, raw in enumerate(raw_questions):
        if not isinstance(raw, dict):
            continue
        text = str(raw.get("question") or "").strip()
        if not text:
            continue
        qid = str(raw.get("id") or "").strip()[:64] or f"q{index + 1}"
        while qid in seen_ids:
            qid = f"{qid}_{index + 1}"
        seen_ids.add(qid)
        options, seen_labels = [], set()
        for opt in raw.get("options") or []:
            if isinstance(opt, dict):
                label = str(opt.get("label") or "").strip()
                description = str(opt.get("description") or "").strip()
            else:
                label, description = _split_option_description(str(opt))
            if label and label.lower() not in seen_labels:
                seen_labels.add(label.lower())
                options.append({"label": label[:80], "description": description[:240]})
        questions.append({
            "id": qid,
            "header": str(raw.get("header") or "").strip()[:48] or f"Question {index + 1}",
            "question": text[:500],
            "options": options,
            # A question with no options is free text, so it must accept typing.
            "allow_other": not options or raw.get("allow_other", allow_other) is not False,
        })
    return questions or None


def _native_ask_user_payload(prompt_text: str) -> dict | None:
    """Build OWUI's native `request:user_input` question card for a prompt.

    Returns None for prompts the card cannot express, which keep the legacy
    modal: secrets (the card has no masked input) and multi-select (the card
    picks one option per question).
    """
    questions = _parse_ask_user_json(prompt_text)
    if questions is None:
        payload, is_confirmation = _modal_payload_from_user_input_prompt(prompt_text)
        data = payload["data"]
        if data.get("type") == "password" or data.get("multi"):
            return None
        question = {
            "id": "answer",
            "header": data["title"],
            "question": data["message"],
            "options": [],
            "allow_other": True,
        }
        if is_confirmation:
            question["options"] = [
                {"label": "Yes", "description": ""},
                {"label": "No", "description": ""},
            ]
            question["allow_other"] = False
        elif payload["type"] == "choice":
            for label in data["options"]:
                label, description = _split_option_description(label)
                question["options"].append({"label": label, "description": description})
            # The numbered list is already in `options`; showing it again in
            # the question text would list every choice twice.
            message = re.sub(r"(?m)^\s*\d+[.)]\s+.*$\n?", "", data["message"]).strip()
            question["question"] = message or data["title"]
        questions = [question]
    return {
        "type": "request:user_input",
        "data": {
            "questions": questions,
            "allow_other": True,
            "timeout_ms": _NATIVE_CARD_TIMEOUT_MS,
        },
    }


def _format_native_answers(questions: list[dict], answers: dict) -> str:
    """Turn the card's {question_id: answer} into the text sent to the agent.

    One question returns the bare answer (the label, or what was typed), the
    same contract the legacy modals had; a Yes/No confirmation returns
    "yes"/"no". Several questions return one "Header: answer" line each.
    """
    lines = []
    for question in questions:
        answer = answers.get(question["id"]) if isinstance(answers, dict) else None
        if not isinstance(answer, dict):
            continue
        if answer.get("type") == "other":
            text = str(answer.get("text") or "").strip()
        else:
            text = str(answer.get("label") or "").strip()
        labels = [o["label"] for o in question.get("options", [])]
        if labels == ["Yes", "No"] and text in labels:
            text = text.lower()
        if text:
            lines.append((question.get("header") or question["id"], text))
    if not lines:
        return ""
    if len(questions) == 1:
        return lines[0][1]
    return "\n".join(f"{header}: {text}" for header, text in lines)


def _user_has_live_session(owui_user_id: str, owui_chat_id: str | None = None) -> bool:
    """Whether the user has a connected Open WebUI socket now that a card
    for `owui_chat_id` could be shown on (`_live_session_id_for_user`)."""
    try:
        from open_webui.socket.main import SESSION_POOL
    except Exception:
        return False
    return bool(_live_session_id_for_user(owui_user_id, SESSION_POOL, owui_chat_id))


async def _call_native_card_on_live_session(
    owui_user_id: str, owui_chat_id: str | None, owui_message_id: str | None, payload: dict
):
    """Show the card on the user's current socket session, or return None when
    they have none. Mirrors OWUI's own get_event_call for request:user_input:
    a fresh interaction_id, the clamped timeout, and the closing
    request:interaction:done event that removes the card from the screen."""
    try:
        from open_webui.socket.main import sio, SESSION_POOL
    except Exception as ex:
        pipe_log(f"  native card retry unavailable (not running inside OWUI process?): {ex}")
        return None
    sid = _live_session_id_for_user(owui_user_id, SESSION_POOL, owui_chat_id)
    if not sid:
        return None
    pipe_log(f"  question card: showing it on session {sid[:8]}...")
    interaction_id = str(uuid.uuid4())
    data = {**payload["data"], "interaction_id": interaction_id}
    timeout_s = min(max(data.get("timeout_ms", 120_000) / 1000, 60), 240)
    try:
        return await sio.call(
            "events",
            {
                "chat_id": owui_chat_id,
                "message_id": owui_message_id,
                "data": {**payload, "data": data},
            },
            to=sid,
            timeout=timeout_s,
        )
    except Exception as ex:
        return {"error": f"Event call timed out: {ex!r}"}
    finally:
        try:
            await sio.emit(
                "events",
                {
                    "chat_id": owui_chat_id,
                    "message_id": owui_message_id,
                    "data": {
                        "type": "request:interaction:done",
                        "data": {"interaction_id": interaction_id},
                    },
                },
                to=sid,
            )
        except Exception:
            pass


async def _ask_user_native_card(
    __event_call__,
    payload: dict,
    *,
    owui_user_id: str | None,
    owui_chat_id: str | None,
    owui_message_id: str | None,
    max_wait_s: float,
    poll_interval_s: float,
    owui_session_id: str | None = None,
    __event_emitter__=None,
) -> str | None:
    """Ask through OWUI's native question card until answered or cancelled.

    The card is re-shown after each OWUI-side timeout while a tab views the
    chat, and on a new socket viewing it after a reload, all within
    max_wait_s. It is re-shown only if such a tab is back within
    _NATIVE_CARD_TAB_GRACE_S (60 s); a first call no tab of the chat can
    show ends at once. Those and an explicit Cancel return None: the reply
    then ends with the question as text (ELI-107 decision 2).
    `owui_session_id`: the socket the turn started on; once it is gone the
    card moves to the tab viewing the chat without waiting out OWUI's call.
    """
    questions = payload["data"]["questions"]
    card_timeout_s = payload["data"]["timeout_ms"] / 1000
    deadline = time.monotonic() + max_wait_s
    use_live_session = False
    waiting_shown = False
    no_viewer_since = None
    while True:
        started = time.monotonic()
        if use_live_session:
            response = await _call_native_card_on_live_session(
                owui_user_id, owui_chat_id, owui_message_id, payload
            )
        else:
            response = await _event_call_while_session_lives(
                __event_call__, payload, owui_session_id, card_timeout_s + 15, poll_interval_s
            )
        elapsed = time.monotonic() - started

        if isinstance(response, dict) and response.get("status") == "answered":
            return _format_native_answers(questions, response.get("answers") or {}) or None
        unseen = response is None or (isinstance(response, dict) and (
            "error" in response
            or elapsed < _NATIVE_CARD_UNSEEN_CANCEL_S
            or elapsed >= card_timeout_s - 5
        ))
        if not unseen:
            pipe_log("  native question card cancelled by the user")
            return None
        if isinstance(response, dict) and "disconnected" in str(response.get("error", "")):
            if not owui_user_id:
                return None
            if not use_live_session and not waiting_shown and not _user_has_live_session(
                    owui_user_id, owui_chat_id):
                # The very first call found no live tab for this turn (an API
                # caller, or a tab closed before the question) and no tab views
                # the chat: nobody can see the card, so the reply ends now with
                # the question as text rather than staying open for a
                # reconnect (ELI-107: an hour).
                pipe_log("  no live tab for this turn's question card; showing it as text")
                return None
            # OWUI's __event_call__ is bound to the session that started the
            # turn; once that socket is gone, reach the user's new one.
            use_live_session = True
        if use_live_session and response is None:
            # No tab views the chat now. A reload brings one back within
            # seconds; past the grace the reply ends with the question as
            # text, so the stream does not outlive its run waiting for the
            # user to come back (ELI-107 decision 2).
            no_viewer_since = no_viewer_since or time.monotonic()
            if time.monotonic() - no_viewer_since >= _NATIVE_CARD_TAB_GRACE_S:
                pipe_log(f"  no tab came back to this chat within {_NATIVE_CARD_TAB_GRACE_S:g}s; "
                         "showing the question as text")
                return None
        else:
            no_viewer_since = None
        if time.monotonic() + poll_interval_s >= deadline:
            pipe_log(f"  gave up on the native question card after {int(max_wait_s)}s")
            return None
        if not waiting_shown:
            waiting_shown = True
            await _emit_status(
                __event_emitter__,
                "Waiting for your reply -- the question is pending in this chat",
                done=False,
            )
        await asyncio.sleep(poll_interval_s)


def _ask_user_detail_block(prompt_text: str, answer: str) -> str:
    """Render an answered ask-user prompt as a native OWUI tool-call block.

    OWUI's frontend only special-cases a handful of `<details type="...">`
    values with a nice icon + collapsible UI (confirmed by grepping the
    compiled frontend bundle): "tool_calls", "reasoning", "code_interpreter".
    There's no dedicated type for Q&A, so we reuse "tool_calls" (labelled as
    an "Ask User" call) to get the same familiar rendering users already
    know from real tool calls, inserted inline at the point the question
    was asked/answered -- instead of showing nothing (previous behavior:
    the raw prompt text was fully suppressed once answered).
    """
    json_questions = _parse_ask_user_json(prompt_text)
    if json_questions:
        question_display = "\n\n".join(
            f"{q['header']}\n{q['question']}" for q in json_questions
        )
    else:
        payload, _ = _modal_payload_from_user_input_prompt(prompt_text)
        data = payload.get("data", {})
        title = data.get("title", "Question")
        message = data.get("message", "")
        question_display = f"{title}\n{message}".strip() if message else title
    args_str = json.dumps({"question": question_display})
    call_id = f"ask-user-{uuid.uuid4().hex[:12]}"
    return (
        '\n<details type="tool_calls" done="true" '
        f'id="{html.escape(call_id)}" '
        'name="Ask User" '
        f'arguments="{html.escape(args_str[:3000])}" '
        f'result="{html.escape(answer[:8000])}" '
        'meta="" files="[]" embeds="[]">'
        '\n<summary>❓ Ask User</summary>\n</details>\n'
    )


@dataclass
class UserInputResult:
    """Outcome of trying to answer a needs-input prompt via an OWUI modal.

    handled=False  -> not a prompt, user cancelled, or delivery failed;
                      the caller should show the text as a fallback.
    handled=True, new_run_id=None -> answer delivered, the run resumed in
                      place (steer); keep consuming the current run.
    handled=True, new_run_id="..." -> answer spawned a new run; the caller
                      should switch its consumer to that run.
    """

    handled: bool
    new_run_id: str | None = None
    prompt_text: str | None = None
    answer: str | None = None
    # The answer run's consumer queue, registered before its send (N6).
    queue: object = None


def _normalize_event_call_response(response) -> str:
    """Extract text from common OWUI __event_call__ return shapes.
    Returns empty string for errors, None, or unrecognized shapes.
    """
    if response is None:
        return ""
    # Confirmation modals resolve to a bare boolean: True=confirm, False=cancel.
    # (bool is a subclass of int, so this must be handled before dict/str.)
    if isinstance(response, bool):
        return "yes" if response else "no"
    if isinstance(response, str):
        return response.strip()
    if isinstance(response, dict):
        # Error responses
        if "error" in response:
            return ""
        for key in ("value", "text", "content", "message", "response"):
            value = response.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        # Confirm type with options
        value = response.get("option")
        if isinstance(value, str) and value.strip():
            return value.strip()
        if response.get("confirmed") is True:
            return "yes"
        if response.get("confirmed") is False:
            return "no"
    return ""


def _live_session_id_for_user(user_id: str, session_pool, chat_id: str | None = None) -> str | None:
    """Find a currently-connected OWUI session_id belonging to user_id.

    session_pool is OWUI's own SESSION_POOL dict (sid -> user dict with an
    'id' field), imported live from the running process -- see
    _retry_modal_on_reconnect for why this only works inside OWUI itself.

    With `chat_id`, only a socket viewing that chat: OWUI 0.12 records the
    chats a socket has joined (`chat_ids`, events:chat join/leave). The
    user's first socket can be another tab or another client, where the card
    never shows (ELI-58 live repro). The newest such socket is the tab the
    user opened last; with none, None, so the card waits for the user to
    open the chat. An OWUI that records no `chat_ids` gets any socket.
    """
    mine = [(sid, s) for sid, s in list(session_pool.items()) if s and s.get("id") == user_id]
    if chat_id and any("chat_ids" in s for _sid, s in mine):
        viewing = [sid for sid, s in mine if chat_id in (s.get("chat_ids") or [])]
        return viewing[-1] if viewing else None
    return mine[0][0] if mine else None


async def _event_call_while_session_lives(__event_call__, payload: dict, session_id: str | None,
                                          timeout_s: float, poll_interval_s: float):
    """`__event_call__(payload)`, given up once the socket it is bound to
    leaves OWUI's SESSION_POOL (the tab was reloaded or closed): OWUI answers
    a call on a gone socket only at its own timeout, up to 240 s, and the
    card can be shown on the user's new socket only after that (ELI-58 live
    repro). Answers as OWUI does for a gone socket."""
    call = asyncio.ensure_future(asyncio.wait_for(__event_call__(payload), timeout=timeout_s))
    try:
        from open_webui.socket.main import SESSION_POOL
    except Exception:
        SESSION_POOL = None
    if not session_id or SESSION_POOL is None:
        return await call
    while True:
        done, _ = await asyncio.wait({call}, timeout=poll_interval_s)
        if done:
            return call.result()
        if session_id not in SESSION_POOL:
            call.cancel()
            pipe_log(f"  question card: session {session_id[:8]}... is gone; showing it on the user's tab")
            return {"error": "Client session disconnected."}


async def _retry_modal_on_reconnect(
    owui_user_id: str,
    owui_chat_id: str | None,
    owui_message_id: str | None,
    payload: dict,
    *,
    max_wait_s: float,
    poll_interval_s: float,
    event_timeout_s: float = 300,
) -> str | None:
    """Wait for owui_user_id to reconnect, then re-fire the modal directly.

    OWUI's own __event_call__ closure is bound to the session_id that was
    live when the original request started; once that session disconnects
    there is no way to retarget it. But OWUI imposes no execution timeout on
    a running pipe (confirmed in docs.openwebui.com's Events page,
    "Persistence & Browser Disconnection" section: the background task
    keeps running after tab close, only killed by returning/raising, manual
    /api/tasks/stop, or a server restart) -- and our pipe module runs inside
    the very same process as the OWUI backend, so we can import its live
    `sio` AsyncServer and SESSION_POOL dict directly and poll for a new
    session_id to appear for this user, then call sio.call() against it
    ourselves, bypassing the stale closure entirely.

    A re-fired modal is an `execute`/`input`/`confirmation` event whose
    `sio.call` only resolves once the user actually interacts with it, so the
    call must be given a real human-interaction budget: OWUI's own live caller
    uses WEBSOCKET_EVENT_CALLER_TIMEOUT (default 300s), and using a short 30s
    here was the bug that made a reconnect modal pop but then silently vanish
    if it wasn't clicked within 30s (and `seen_sids` then blocked it from ever
    re-firing). We now (a) give each fire `event_timeout_s`, and (b) re-fire
    when the user reconnects on a *fresh* session, or when a previous fire
    timed out with no interaction (they were away) -- so the question keeps
    coming back until it's answered. An explicit dismiss (Escape/backdrop,
    which resolves without an error) is respected: we stop re-popping that
    same live session and wait for a genuinely new reconnect.
    """
    try:
        from open_webui.socket.main import sio, SESSION_POOL
    except Exception as ex:
        pipe_log(f"  reconnect retry unavailable (not running inside OWUI process?): {ex}")
        return None

    deadline = time.monotonic() + max_wait_s
    # sid we've already delivered to and that dismissed (or is still showing)
    # the modal without answering -- don't spam it; wait for a fresh reconnect.
    dismissed_sid: str | None = None
    while time.monotonic() < deadline:
        await asyncio.sleep(poll_interval_s)
        sid = _live_session_id_for_user(owui_user_id, SESSION_POOL, owui_chat_id)
        if not sid:
            # Fully disconnected again; a later reconnect (even reusing this
            # sid) should re-fire.
            dismissed_sid = None
            continue
        if sid == dismissed_sid:
            continue
        pipe_log(f"  {owui_user_id[:8]}... reconnected (sid {sid[:8]}...); retrying modal")
        try:
            response = await asyncio.wait_for(
                sio.call(
                    "events",
                    {
                        "chat_id": owui_chat_id,
                        "message_id": owui_message_id,
                        "data": payload,
                    },
                    to=sid,
                    timeout=event_timeout_s,
                ),
                timeout=event_timeout_s + 5,
            )
        except Exception as ex:
            # Timed out with no interaction (tab open but idle, or the message
            # is no longer rendered so the client never acked). They were away;
            # loop and re-fire to this same session on the next poll.
            pipe_log(f"  retry event_call timed out/failed for sid {sid[:8]}...: {ex!r}")
            dismissed_sid = None
            continue
        answer = _normalize_event_call_response(response)
        if answer:
            return answer
        # Reconnected and the modal was shown but explicitly dismissed
        # (Escape/backdrop) or came back empty. Respect it: stop re-popping
        # this live session; only a fresh reconnect re-asks.
        pipe_log(f"  reconnect modal dismissed without an answer (sid {sid[:8]}...); waiting for a new reconnect")
        dismissed_sid = sid
    pipe_log(f"  gave up waiting for {owui_user_id[:8]}... to reconnect after {int(max_wait_s)}s")
    return None


async def _ask_user_input_modal(
    __event_call__,
    prompt_text: str,
    *,
    timeout_s: float = 60,
    owui_user_id: str | None = None,
    owui_chat_id: str | None = None,
    owui_message_id: str | None = None,
    max_wait_s: float = 3600,
    poll_interval_s: float = 5,
    owui_session_id: str | None = None,
    __event_emitter__=None,
) -> str | None:
    """Ask the user through OWUI's modal input API when available.

    If the live call fails (user not connected right now) and owui_user_id
    is given, keep the pipe's own background task alive and poll for the
    user to reconnect (up to max_wait_s total), retrying the modal against
    their fresh session -- see _retry_modal_on_reconnect. Without
    owui_user_id, behaves exactly as before: a single attempt, exceptions
    (including TimeoutError) propagate to the caller.
    """
    if not __event_call__ or not _is_user_input_prompt(prompt_text):
        return None
    native_payload = (
        _native_ask_user_payload(prompt_text) if _owui_supports_native_ask_user() else None
    )
    if native_payload is not None:
        return await _ask_user_native_card(
            __event_call__,
            native_payload,
            owui_user_id=owui_user_id,
            owui_chat_id=owui_chat_id,
            owui_message_id=owui_message_id,
            max_wait_s=max_wait_s,
            poll_interval_s=poll_interval_s,
            owui_session_id=owui_session_id,
            __event_emitter__=__event_emitter__,
        )
    payload, _ = _modal_payload_from_user_input_prompt(prompt_text)
    # A clickable-choice prompt is delivered as an "execute" event that renders
    # its own button overlay; convert here so both the live call and the
    # reconnect-retry path fire the same ready-to-run payload.
    if payload.get("type") == "choice":
        d = payload["data"]
        payload = _build_choice_modal_js(
            d["title"], d["message"], d["options"], d.get("multi", False)
        )

    try:
        response = await asyncio.wait_for(
            __event_call__(payload),
            timeout=timeout_s,
        )
        answer = _normalize_event_call_response(response)
        if answer:
            return answer
    except asyncio.TimeoutError:
        if not owui_user_id:
            raise

    if not owui_user_id:
        return None

    pipe_log(
        f"  modal not answered live; polling for {owui_user_id[:8]}... "
        f"to reconnect (up to {int(max_wait_s)}s)"
    )
    await _emit_status(
        __event_emitter__,
        "Waiting for your reply -- question is pending, reconnect anytime",
        done=False,
    )
    return await _retry_modal_on_reconnect(
        owui_user_id,
        owui_chat_id,
        owui_message_id,
        payload,
        max_wait_s=max_wait_s,
        poll_interval_s=poll_interval_s,
    )


# --- gateway ---------------------------------------------------------------
GATEWAY_SCOPES = ["operator.admin", "operator.read", "operator.write"]
# A connection for users not in OWNER_USERS. Without operator.admin the
# Gateway does not record its turns as the owner's, and the agent withholds
# owner-only tools from them. read: history, sessions, models, usage and the
# event subscriptions. write: send, abort and the model override.
RESTRICTED_SCOPES = ["operator.read", "operator.write"]


def _parse_owner_users(raw: str) -> frozenset:
    """OWNER_USERS as a set of lowercase user ids and emails."""
    return frozenset(p.strip().lower() for p in (raw or "").split(",") if p.strip())


def _is_owner_user(owners: frozenset, user_id, email) -> bool:
    """An empty list makes everyone an owner (the behaviour before the valve)."""
    if not owners:
        return True
    return any(v and str(v).strip().lower() in owners for v in (user_id, email))


# The requests that start, steer or end a run. The Gateway records a turn as
# the owner's when the connection that sends it holds operator.admin, so these
# go out only through `_run_request`, which picks the connection.
RUN_SEND, RUN_ABORT, RUN_PATCH = "chat.send", "chat.abort", "sessions.patch"
# chat.send fields the Gateway accepts only from an operator.admin connection
# ("system provenance fields require admin scope"). A send over the restricted
# connection leaves them out, so a non-owner turn carries no conversation
# metadata block.
ADMIN_ONLY_SEND_FIELDS = (
    "systemInputProvenance",
    "systemProvenanceReceipt",
    "suppressCommandInterpretation",
    "originatingChannel",
    "originatingTo",
    "originatingAccountId",
    "originatingThreadId",
)
_OWUI_KEY_USER = re.compile(r"^agent:[^:]+:openwebui-([0-9a-fA-F-]{36})-")


# ---------------------------------------------------------------------------
# Custom exceptions
# ---------------------------------------------------------------------------

class GatewayError(Exception):
    """Raised when the Gateway WebSocket handshake fails."""
    pass


# How long to wait for the Gateway's TCP/WS accept before giving up. Mirrors
# websockets' own open_timeout default; kept explicit so the bound is visible
# and tunable in one place rather than inherited silently.
_GATEWAY_CONNECT_TIMEOUT_S = 10.0

# Largest Gateway frame the socket accepts. websockets defaults to 1 MiB and
# answers a bigger frame by closing the WHOLE connection (1009, "message too
# big"), dropping every session's events: a 952-message `chat.history` is
# 3.1 MB, and one large tool result in an agent or `session.message` event is
# enough (measured 2026-10-12, repro_ws_max_size.py). Bounded, not None, so a
# runaway frame still can't take the Open WebUI process's memory with it.
GATEWAY_WS_MAX_SIZE = 64 * 1024 * 1024


def _explain_connect_rejection(message: str, *, device_id: str | None = None) -> str:
    """Turn the Gateway's terse connect rejection into something actionable.

    Device approval is a mandatory step of every first install, not an
    exceptional case, yet the raw response is just "pairing required" -- and the
    command that fixes it appears nowhere in the product, only in the README.
    The device id the operator has to match is already in hand here.
    """
    lowered = message.lower()
    if "pairing" in lowered or "not approved" in lowered:
        ident = f"\n\nThis device's id is `{device_id}`." if device_id else ""
        return (
            "This Open WebUI instance is not an approved device on the OpenClaw "
            "Gateway yet.\n\nOn the Gateway host, run:\n\n"
            "    openclaw devices list\n"
            "    openclaw devices approve <request-id>\n"
            f"{ident}\n\nThen send your message again."
        )
    if any(k in lowered for k in ("unauthor", "invalid token", "forbidden", "bad token")):
        return (
            f"The Gateway rejected the credentials ({message}). Check the "
            "GATEWAY_TOKEN valve in Open WebUI under Admin Panel > Functions > "
            "OpenClaw Gateway > valves; it must match `gateway.auth.token` in "
            "your OpenClaw config."
        )
    return message


def _parse_gateway_url(raw: str) -> tuple[str, int]:
    """Parse the GATEWAY_URL valve into (host, port).

    The valve wants a bare ``host:port`` -- but it renders as a text box that
    looks exactly like a URL field, so pasting ``http://host:18789`` is the
    single most likely new-user mistake. A naive ``rsplit(":", 1)`` handles that
    input catastrophically quietly:

      ``http://gw:18789``  -> host ``http://gw``  -> websockets parses the
                              hostname as literally ``http`` on port 80
      ``http://gw``        -> ``int("//gw")`` -> a raw ValueError that escapes
                              pipe()'s ``except GatewayError`` and surfaces as
                              an unattributed error naming no valve

    So: accept a scheme and strip it (being liberal costs three lines and kills
    the whole failure class), and raise a GatewayError naming the valve for
    anything still unparseable, so it lands in the one handler that prints
    nicely into the chat.
    """
    value = (raw or "").strip()
    if not value:
        raise GatewayError(
            "The GATEWAY_URL valve is empty. Set it to your OpenClaw Gateway "
            "as host:port, for example localhost:18789."
        )
    if "://" in value:
        scheme, _, value = value.partition("://")
        if scheme.lower() not in ("ws", "wss", "http", "https"):
            raise GatewayError(
                f"GATEWAY_URL has an unsupported scheme '{scheme}://'. Use a "
                "bare host:port, for example localhost:18789."
            )
    # Drop any path/query a pasted URL dragged along ("host:8443/" -> "host:8443").
    value = value.split("/", 1)[0].split("?", 1)[0]

    if value.startswith("["):
        # Bracketed IPv6, "[::1]:18789". Split on the closing bracket, not the
        # last colon, and keep the brackets -- websockets needs them in the URL.
        addr, sep, rest = value.partition("]")
        if not sep:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} is missing a closing ']' on the IPv6 "
                "address. Expected [address]:port, for example [::1]:18789."
            )
        inner = addr[1:]
        # Brackets mean IPv6 to every URL parser. If the contents are not an
        # IPv6 literal, websockets' urlsplit().hostname raises a bare ValueError
        # -- which is neither OSError nor WebSocketException, so it escapes the
        # connect handler AND pipe()'s except GatewayError. Reject it here.
        # This is reachable by following our own advice: the bare-IPv6 branch
        # below says "wrap it in brackets", and a user who wraps a *hostname*
        # lands exactly on this input.
        try:
            ipaddress.IPv6Address(inner)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has {inner!r} in brackets, but brackets "
                "are only for IPv6 literals. Use a plain host:port such as "
                f"{inner}:18789, or bracket an actual IPv6 address like "
                "[::1]:18789."
            )
        host = addr + "]"
        port_str = rest[1:] if rest.startswith(":") else (rest or "18789")
    elif value.count(":") > 1:
        # More than one colon and no brackets. If it parses as IPv6, say so;
        # otherwise it is something like "host:80:90" or a pasted URL with
        # userinfo, and calling that "an IPv6 address" would be wrong.
        try:
            ipaddress.IPv6Address(value)
        except ValueError:
            raise GatewayError(
                f"GATEWAY_URL {raw!r} has more than one ':' and is not an IPv6 "
                "address, so the port is ambiguous. Expected host:port, for "
                "example localhost:18789."
            )
        # A bare IPv6 literal. rpartition(":") would read "::1" as host ":" on
        # port 1 -- silently wrong on both counts, which is the whole failure
        # class this function exists to remove.
        raise GatewayError(
            f"GATEWAY_URL {raw!r} is an IPv6 address. Wrap it in brackets so "
            "the port is unambiguous, for example [::1]:18789."
        )
    else:
        host, sep, port_str = value.rpartition(":")
        if not sep:
            host, port_str = value, "18789"

    if not host or host == "[]":
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has no host. Expected host:port, "
            "for example localhost:18789."
        )
    if not (port_str.isascii() and port_str.isdigit()):
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has a non-numeric port {port_str!r}. "
            "Expected host:port, for example localhost:18789."
        )
    port = int(port_str)
    if not 1 <= port <= 65535:
        raise GatewayError(
            f"GATEWAY_URL {raw!r} has port {port}, which is outside 1-65535. "
            "The OpenClaw Gateway default is 18789."
        )
    return host, port


def _preview_recovery_text(preview: dict, session_key: str, user_text: str) -> str | None:
    """Return assistant text saved after this user message, if preview has it.

    Lossy: the Gateway clips every `sessions.preview` item server-side (800
    chars on 2026.9.x, 2000 before) whatever `maxChars` asks for. Only the
    fallback for when `_history_recovery_text` finds nothing (ELI-74).
    """
    previews = preview.get("previews")
    if not isinstance(previews, list):
        return None

    entry = None
    for candidate in previews:
        if isinstance(candidate, dict) and candidate.get("key") == session_key:
            entry = candidate
            break
    if not entry:
        return None

    return _recovery_text_from_items(entry.get("items"), user_text)


# Budget for reading back an interrupted turn's tail. `chat.history` honors
# maxChars per message (schema max 500000) up to a 128 KiB per-message byte
# cap; 50000 chars stays under that cap even for 2-byte scripts like Hebrew.
RECOVERY_HISTORY_LIMIT = 40
RECOVERY_HISTORY_MAX_CHARS = 50000


def _event_frame(payload: dict) -> dict:
    """A routed event payload as the receive loop hands frames to an inline
    reply, which reads `msg["payload"]`: a `chat` event has a state and no
    stream, anything else (including a rebuilt session.tool copy) is `agent`."""
    event = "chat" if "state" in payload and "stream" not in payload else "agent"
    return {"type": "event", "event": event, "payload": payload}


def _history_item(message) -> dict | None:
    """Flatten one `chat.history` message to the {role, text} shape of a
    `sessions.preview` item. Only `text` blocks count: tool calls, tool results
    and thinking blocks are not part of the visible answer."""
    if not isinstance(message, dict):
        return None
    content = message.get("content")
    if isinstance(content, str):
        text = content
    elif isinstance(content, list):
        text = "".join(
            str(block.get("text") or "")
            for block in content
            if isinstance(block, dict) and block.get("type") == "text"
        )
    else:
        text = str(message.get("text") or "")
    return {"role": message.get("role"), "text": text}


def _history_recovery_text(history: dict, user_text: str) -> str | None:
    """Return the full assistant text saved after this user message, read from
    a `chat.history` response.

    This replaces `sessions.preview` as the recovery source (ELI-74): the
    preview is clipped server-side, so a long reply recovered from it landed
    in OWUI cut mid-sentence with a trailing "...". `chat.history` returns the
    message whole.
    """
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    return _recovery_text_from_items([_history_item(m) for m in messages], user_text)


def _recovery_user_text_matches(item_text: str, user_text: str) -> bool:
    """True if a stored user message is the one this turn sent.

    The transcript can hold it verbatim or behind the Gateway's metadata
    envelope ("Conversation info (untrusted metadata): ...", then a blank
    line, then the text). `sessions.preview` strips that envelope;
    `chat.history` does not.
    """
    return item_text == user_text or item_text.endswith("\n" + user_text)


def _recovery_text_from_items(items, user_text: str) -> str | None:
    """The turn's final assistant text: the LAST non-empty assistant item after
    the last user item matching `user_text`, stopping at the next user message.

    Last, not first: a tool-using turn stores several assistant messages. On
    the claude-cli runtime the closing one repeats the whole turn's text
    (preambles included); on the embedded runtime it is the final answer. The
    first one is only the opening preamble ("I'll look at ..."), which is what
    recovery used to return.
    """
    if not isinstance(items, list):
        return None

    normalized_user_text = (user_text or "").strip()
    if not normalized_user_text:
        return None

    last_matching_user_index = None
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            continue
        if item.get("role") != "user":
            continue
        if _recovery_user_text_matches(
            str(item.get("text", "")).strip(), normalized_user_text
        ):
            last_matching_user_index = idx

    if last_matching_user_index is None:
        return None

    found = None
    for item in items[last_matching_user_index + 1:]:
        if not isinstance(item, dict):
            continue
        text = str(item.get("text", "")).strip()
        if item.get("role") == "user" and text:
            break  # the next turn; tool results are user items with no text
        if item.get("role") == "assistant" and text:
            found = text
    return found


async def _recover_turn_text(conn, session_key: str, user_text: str) -> str | None:
    """Read back the assistant text of a turn whose live stream was lost.

    `chat.history` first, because it returns the message whole. The old
    `sessions.preview`-only path persisted long replies clipped mid-sentence
    with a trailing "..." (ELI-74): the Gateway caps each preview item
    server-side, so no `maxChars` value fixes it. The preview stays as a
    fallback for a Gateway that refuses `chat.history`.
    """
    try:
        history = await conn.session_history(session_key)
        text = _history_recovery_text(history, user_text)
        if text:
            return text
        pipe_log("  history recovery found no reply; trying sessions.preview")
    except Exception as ex:
        pipe_log(f"  history recovery failed: {ex}; trying sessions.preview")
    try:
        preview = await conn.session_preview(session_key)
        return _preview_recovery_text(preview, session_key, user_text)
    except Exception as ex:
        pipe_log(f"  preview recovery failed: {ex}")
        return None


def _owui_session_key(agent_id: str, user_id: str, chat_id: str) -> str:
    return f"agent:{agent_id}:openwebui-{user_id}-{chat_id}"


def _session_thinking_ladder(desc: dict) -> list | None:
    """Pull the thinking levels a session's CURRENT model supports out of a
    `sessions.describe` response.

    `models.list` cannot answer this: it carries a `reasoning` boolean and
    nothing else. `agents.list` does carry a ladder, but the agent's PRIMARY
    model's, which is wrong the moment a session overrides the model. Only
    describe reflects what is actually resolved for this session right now.

    `thinkingLevels` is authoritative: the gateway defines it as the raw
    `{id, label}` objects (`resolveGatewaySessionThinkingProjectionInternal`
    -> `thinkingLevels: metadata.levels`), keyed by the canonical lowercase
    ids (`off`, `minimal`, ...) that LEVEL_RANKS and clamp_to_ladder match
    against. `thinkingOptions` is display-only -- the SAME gateway function
    derives it as `metadata.levels.map(level => level.label)`, i.e. human
    labels ("Off", "Extra High", ...), not ids. Matching a requested level
    against labels silently breaks clamping (nothing in LEVEL_RANKS looks
    like a label), so `thinkingOptions` must never be used for the ladder --
    checking it first, as this used to, let an unsupported level fall
    through the clamp and reach the gateway's own hard validation error
    (ELI-85 field mixup, caused a live chat to hard-fail on every turn).
    Kept only as a last-resort fallback in case a future gateway build ever
    stops emitting `thinkingLevels` -- an imperfect ladder beats none.

    Returns None (not []) when the field is absent, because "no ladder known"
    and "this model supports nothing" have to lead to different behaviour: the
    first passes the request through to the gateway, the second would clamp
    every request away.
    """
    row = (desc or {}).get("session") or {}
    levels = row.get("thinkingLevels")
    if isinstance(levels, list) and levels:
        out = [str(lv.get("id")) for lv in levels
               if isinstance(lv, dict) and lv.get("id")]
        if out:
            return out
    opts = row.get("thinkingOptions")
    if isinstance(opts, list) and opts:
        return [str(x).strip().lower() for x in opts]
    return None


def _session_model_key(row) -> str | None:
    """`provider/model` for a `sessions.describe` row, or None.

    Formatted to match the Gateway's own rejection text verbatim
    ("...is not supported for claude-cli/claude-opus-5.") so a ladder learned
    from a rejection and one observed from describe key the same entry.
    """
    row = row or {}
    provider = str(row.get("modelProvider") or "").strip()
    model = str(row.get("model") or "").strip()
    if not provider or not model:
        return None
    return f"{provider}/{model}"


def _ladder_cache_path(state_dir: str = "") -> str:
    return os.path.join(_state_dir(state_dir), LADDER_CACHE_NAME)


# Guards the ladder cache's read-merge-write sequence below. Pipe and Status
# Action requests can land in different threads of the same OWUI process, and
# without this a slower worker's read-merge-write can finish after a faster
# one's and silently drop the faster worker's update. A unique temp file (see
# _write_json_file) only makes each individual write atomic; it does nothing
# for two workers racing on the read-then-write in between.
_LADDER_CACHE_LOCK = threading.Lock()


def _record_thinking_ladder(levels, model_key=None, authoritative=False,
                             state_dir: str = "") -> None:
    """Fold a ladder we just saw into the cache, both as a union and per model.

    Two different consumers, two different needs, one file:

    * `levels` (union across every model seen) is what the Thinking filter
      offers, because Open WebUI builds a valve dropdown once from the class
      and cannot vary it per selected model.
    * `models[<provider/model>]` is what the SEND path clamps against, and it
      must be exact. Clamping against the union is what let `high` reach a
      model whose only level is `off`.

    `authoritative` marks a ladder the Gateway stated itself by rejecting a
    send. A merely observed one (from `sessions.describe`) must never overwrite
    it: describe resolves the ladder with no model catalog in scope and so
    reports the generic base profile for catalog-gated models. Trusting the
    weaker source second would undo the fix on the very next turn.

    Best-effort by design: a failed write costs a stale dropdown and one more
    rejected turn, and must never affect the message being sent.
    """
    known = [lv for lv in (levels or []) if lv in LEVEL_RANKS]
    path = _ladder_cache_path(state_dir)

    with _LADDER_CACHE_LOCK:
        current = _read_json_file(path) or {}

        have = current.get("levels")
        have = [x for x in have if x in LEVEL_RANKS] if isinstance(have, list) else []
        merged = sorted(set(have) | set(known), key=lambda lv: (LEVEL_RANKS[lv], lv))

        models = current.get("models")
        models = dict(models) if isinstance(models, dict) else {}
        model_changed = False
        if model_key:
            prior = models.get(model_key)
            prior = prior if isinstance(prior, dict) else {}
            if prior.get("source") == "gateway" and not authoritative:
                # Keep the stated truth; a describe-sourced ladder is not
                # evidence against it.
                pass
            else:
                entry = {
                    "levels": known,
                    "source": "gateway" if authoritative else "describe",
                    "updated": int(time.time()),
                }
                if (prior.get("levels") != entry["levels"]
                        or prior.get("source") != entry["source"]):
                    models[model_key] = entry
                    model_changed = True

        if merged == have and not model_changed:
            return
        payload = {"levels": merged, "updated": int(time.time())}
        if models:
            payload["models"] = models
        if not _write_json_file(path, payload):
            return
    if merged != have:
        pipe_log(f"thinking ladder cache updated: {merged}")
    if model_changed:
        pipe_log(
            f"thinking ladder for {model_key}: {known} "
            f"({'stated by gateway' if authoritative else 'observed'})"
        )


def _read_model_thinking_ladder(model_key, state_dir: str = ""):
    """The exact ladder for one model, or None if we have not learned it.

    None and [] mean different things here and the caller relies on it: None is
    "unknown, pass the request through", [] would be "supports nothing", which
    no model is. Entries that somehow persisted empty are treated as unknown.
    """
    if not model_key:
        return None
    cache = _read_json_file(_ladder_cache_path(state_dir)) or {}
    models = cache.get("models")
    if not isinstance(models, dict):
        return None
    entry = models.get(model_key)
    if not isinstance(entry, dict):
        return None
    levels = entry.get("levels")
    if not isinstance(levels, list):
        return None
    known = [lv for lv in levels if lv in LEVEL_RANKS]
    return known or None


def _owui_chat_send_params(
    session_key: str,
    message: str,
    idempotency_key: str,
    owui_chat_id: str | None,
    owui_user_id: str | None,
    attachments: list | None = None,
    thinking: str | None = None,
) -> dict:
    params = dict(
        sessionKey=session_key,
        message=message,
        idempotencyKey=idempotency_key,
    )
    if attachments:
        params["attachments"] = attachments
    # Only when actually chosen. chat.send reads an absent `thinking` as "use
    # whatever the agent is configured for", which is a different instruction
    # from any value we could send, "off" very much included.
    if thinking:
        params["thinking"] = thinking
    if owui_chat_id:
        metadata = {
            "chat_id": owui_chat_id,
            "source": "openwebui",
        }
        if owui_user_id and owui_user_id != "unknown":
            metadata["user_id"] = owui_user_id
        params["systemProvenanceReceipt"] = "\n".join([
            "Conversation info (untrusted metadata):",
            "```json",
            json.dumps(metadata, ensure_ascii=False, indent=2),
            "```",
        ])
    return params


def _resolved_model_key(patch_resp: dict) -> str | None:
    resolved = patch_resp.get("resolved", {})
    provider = resolved.get("modelProvider")
    model = resolved.get("model")
    if provider and model:
        return f"{provider}/{model}"
    return None


# Provider namespaces that name a *serving runtime* rather than the model's
# canonical API vendor. A model keyed under one of these (e.g.
# "claude-cli/claude-opus-5") resolves, on sessions.patch, to the model's
# canonical provider ("anthropic/claude-opus-5") -- the gateway always reports
# the vendor, not the runtime. Without treating these as equal, any model
# keyed by its runtime can never pass the post-patch equality check and the
# pipe wrongly aborts with "model override did not apply" (opus-5 was the only
# such model; the claude-cli/ key was chosen deliberately to avoid a separate
# compaction bug, so the fix belongs here, not in gateway config).
_RUNTIME_PROVIDER_NAMESPACES = {"claude-cli", "google-gemini-cli", "codex-cli"}


def _model_patch_matches(model_override: str | None, patch_resp: dict) -> bool:
    if model_override is None:
        return True
    if _resolved_model_key(patch_resp) == model_override:
        return True
    # Runtime-namespaced key (claude-cli/<id>) vs canonical vendor readback
    # (anthropic/<id>): same model, different provider label -- treat as applied.
    if "/" in model_override:
        want_provider, want_model = model_override.split("/", 1)
        got_model = patch_resp.get("resolved", {}).get("model")
        if want_provider in _RUNTIME_PROVIDER_NAMESPACES and want_model == got_model:
            return True
    return False


def _coerce_text(value) -> str:
    """Extract text from common stream payload shapes."""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        for key in ("delta", "text", "content", "message"):
            text = _coerce_text(value.get(key))
            if text:
                return text
        return ""
    if isinstance(value, list):
        parts = [_coerce_text(item) for item in value]
        return "".join(part for part in parts if part)
    return ""


def _content_has_image(raw_content) -> bool:
    """True if an OWUI message's `content` is a multimodal block list
    (P39) that includes at least one image_url block. `content` is a
    plain string for ordinary text-only messages -- only the list shape
    (sent when a user attaches an image) can carry one, so this returns
    False immediately for the common string case."""
    if not isinstance(raw_content, list):
        return False
    return any(
        isinstance(block, dict) and block.get("type") == "image_url"
        for block in raw_content
    )


_DATA_URL_RE = re.compile(r"^data:([^;,]*)(?:;[^,]*)?,(.*)$", re.DOTALL)


def _extract_image_attachments(raw_content) -> list:
    """Pull inline images out of an OWUI multimodal `content` block list
    (P39) and shape them for the gateway's `chat.send` `attachments` param:
    `{type, mimeType, fileName, content}` with `content` as base64.

    OWUI sends attached/pasted images as `image_url` blocks whose `url` is
    a `data:<mime>;base64,<data>` URI (confirmed via OWUI's own request
    shape, not just this bridge's tests) -- there is no plain-HTTP(S)
    `image_url` case to support here, so anything else is skipped rather
    than guessed at.
    """
    if not isinstance(raw_content, list):
        return []
    attachments = []
    for idx, block in enumerate(raw_content):
        if not (isinstance(block, dict) and block.get("type") == "image_url"):
            continue
        image_url = block.get("image_url")
        url = image_url.get("url") if isinstance(image_url, dict) else None
        if not isinstance(url, str):
            continue
        match = _DATA_URL_RE.match(url.strip())
        if not match or ";base64" not in url.split(",", 1)[0]:
            continue
        mime = match.group(1) or "image/png"
        ext = mimetypes.guess_extension(mime) or ".png"
        attachments.append({
            "type": "image",
            "mimeType": mime,
            "fileName": f"image-{idx + 1}{ext}",
            "content": match.group(2),
        })
    return attachments


def _item_assistant_text(data: dict) -> str:
    """Return visible assistant text carried by item/preamble events."""
    kind = str(data.get("kind", "")).strip().lower()
    if kind not in ("assistant", "message", "output", "preamble"):
        return ""
    for key in ("delta", "text", "content", "message"):
        text = _coerce_text(data.get(key)).strip()
        if text:
            return text
    return ""


# Queue item `_GatewayConnection._mark_event_gap` puts where events were lost.
_GAP_MARKER_TYPE = "_pipe_gap"
# Queue item `_GatewayConnection._note_gateway_boot` puts in every run queue
# when a reconnect lands on a new Gateway process: the run may be gone, and
# its owner (DESIGN 2.7) is decided from its row, not by the reply.
_RESTART_MARKER_TYPE = "_pipe_restart"
# Queue item carrying a session row to the inline replies of that session:
# `{"type", "row", "resync"}`. A run's own settle row (hasActiveRun false,
# lastRunId = the run) ends its reply even when its final event was lost;
# `resync` marks a row read after a reconnect or a frame gap, where an idle
# session means every admitted run is over; a `queued` row tells a reply
# waiting for its first event why (review 2af1 timers).
# `read_at` (time.monotonic) is when the row was read: a reply trusts an idle
# row only when it was read after its run was admitted (review 2af1 N4).
_ROW_MARKER_TYPE = "_pipe_row"
# Text on each side of a gap used to find where a repaired chunk goes.
_GAP_ANCHOR_CHARS = 120


def _align_whole_text(whole: str, received: str, gaps) -> tuple[str, list] | None:
    """Line up what a run actually sent (`whole`) with what reached us.

    `received` is the run's text as it arrived, `gaps` the offsets in it
    where a gap marker sat (events lost on a socket drop). Between gaps the
    received text is contiguous, so each piece is found in `whole` in order;
    whatever `whole` has between pieces is what was lost there. Returns
    (tail, missing): `tail` is what follows the last received piece (new
    text), `missing` a list of (offset in `received`, lost text). None when
    a piece is not in `whole`: then it is not the same text and nothing is
    repaired.
    """
    if not whole or not received:
        return None
    cuts = sorted({g for g in gaps or () if 0 <= g <= len(received)})
    bounds = [0, *cuts, len(received)]
    j = 0
    missing = []
    for a, b in zip(bounds, bounds[1:]):
        piece = received[a:b]
        if not piece:
            continue
        pos = whole.find(piece, j)
        if pos < 0:
            return None
        if pos > j:
            missing.append((a, whole[j:pos]))
        j = pos + len(piece)
    return whole[j:], missing


def _insert_at_anchor(text: str, chunk: str, before: str, after: str) -> str | None:
    """`text` with `chunk` put in front of `before`, or right after `after`."""
    if before:
        i = text.find(before)
        if i >= 0:
            return text[:i] + chunk + text[i:]
    if after:
        i = text.rfind(after)
        if i >= 0:
            i += len(after)
            return text[:i] + chunk + text[i:]
    return None


def _gap_repair_fields(message: dict, chunk: str, before: str, after: str) -> dict | None:
    """The DB fields that put `chunk` back into an OWUI message, or None.

    OWUI 0.12 renders and saves a reply from its `output` items (the content
    string is derived), so the chunk goes into the text part that holds the
    anchor; `content` is kept in step when present.
    """
    fields: dict = {}
    output = copy.deepcopy(message.get("output") or [])
    placed = False
    for item in output:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        for part in item.get("content") or []:
            if isinstance(part, dict) and part.get("type") == "output_text":
                new = _insert_at_anchor(part.get("text") or "", chunk, before, after)
                if new is not None:
                    part["text"] = new
                    placed = True
                    break
        if placed:
            break
    if placed:
        fields["output"] = output
    content = message.get("content")
    if isinstance(content, str) and content:
        new_content = _insert_at_anchor(content, chunk, before, after)
        if new_content is not None:
            fields["content"] = new_content
    if output and not placed:
        return None  # the screen renders `output`; a content-only fix would not show
    return fields or None


def _gap_repair_registry() -> dict:
    """Repairs waiting for a reply that is still streaming, by
    "<chat_id>:<message_id>". Shared across redeploys like the other
    bookkeeping, so a repair registered by one module instance is applied by
    the sink whichever instance is current."""
    state = _shared_gateway_state()
    if state is None:
        return _LOCAL_GAP_REPAIRS
    return state.setdefault("pending_gap_repairs", {})


_LOCAL_GAP_REPAIRS: dict = {}


async def _apply_gap_repair(conn, repair: dict) -> bool:
    """Put a lost chunk back into a reply OWUI has finished saving, in the DB
    and in every open tab (a `chat:completion` carrying only `output` replaces
    that one message's items, without a reload and without marking it done).
    """
    chat_id, message_id = repair["chat_id"], repair["message_id"]
    try:
        from open_webui.models.chats import Chats
    except Exception as ex:
        pipe_log(f"  gap repair unavailable (not inside OWUI process?): {ex}")
        return False
    try:
        async with conn._chat_write_lock(chat_id):
            chat = await Chats.get_chat_by_id(chat_id)
            messages = ((chat.chat.get("history") or {}).get("messages") or {}) if chat else {}
            message = messages.get(message_id)
            if not message:
                pipe_log(f"  gap repair: message {message_id[:8]}... not found; "
                         f"{len(repair['chunk'])} chars stay missing")
                return False
            fields = _gap_repair_fields(message, repair["chunk"],
                                        repair.get("before", ""), repair.get("after", ""))
            if not fields:
                pipe_log(f"  gap repair: no anchor in message {message_id[:8]}...; "
                         f"{len(repair['chunk'])} chars stay missing")
                return False
            await Chats.upsert_message_to_chat_by_id_and_message_id(chat_id, message_id, fields)
        live = {"output": fields["output"]} if "output" in fields else {"content": fields["content"]}
        await _relay_emit_event(repair["user_id"], chat_id, message_id,
                                {"type": "chat:completion", "data": live})
        pipe_log(f"  gap repair: put {len(repair['chunk'])} lost chars back into "
                 f"message {message_id[:8]}...")
        return True
    except Exception as ex:
        pipe_log(f"  gap repair failed: {ex}")
        return False


def _schedule_gap_repair(conn, repair: dict, *, streaming: bool) -> None:
    """Apply now, or once OWUI has saved the reply that is still streaming.

    A reply that stopped streaming is already saved: a finished one before
    `chat.finished`, a stopped one before OWUI's stop endpoint returns (it
    awaits the cancelled task), which is before the next reply could start.
    The one still streaming is saved from its `output` when the stream ends,
    which would overwrite a repair made now, so that repair waits for
    `chat.finished` (`_GapRepairSink`) or for the reply that adopts its run.
    """
    if not streaming:
        spawn_background(_apply_gap_repair(conn, repair))
        return
    key = f"{repair['chat_id']}:{repair['message_id']}"
    _gap_repair_registry().setdefault(key, []).append(repair)
    _ensure_gap_repair_sink()
    pipe_log(f"  gap repair for message {repair['message_id'][:8]}... waits for its final save")


def _take_gap_repairs(chat_id: str, message_id: str) -> list:
    return _gap_repair_registry().pop(f"{chat_id}:{message_id}", [])


async def _on_chat_finished(data: dict) -> None:
    repairs = _take_gap_repairs(str(data.get("chat_id")), str(data.get("message_id")))
    if not repairs:
        return
    conn = _gateway_connection
    if conn is None:
        return
    for repair in repairs:
        await _apply_gap_repair(conn, repair)


class _GapRepairSink:
    """OWUI event sink: `chat.finished` fires after the reply's final save
    (`publish_chat_finished_event`, after the upsert in middleware.py). It
    stays registered across redeploys, so it calls whichever handler the
    current module instance stored, never its own (stale) code."""

    openclaw_gap_repair_sink = True

    async def handle_event(self, app, event, request=None) -> None:
        if getattr(event, "event", None) != "chat.finished":
            return
        state = _shared_gateway_state() or {}
        handler = state.get("gap_repair_on_finished") or _on_chat_finished
        try:
            await handler(getattr(event, "data", None) or {})
        except Exception as ex:
            pipe_log(f"  gap repair sink failed: {ex}")


def _ensure_gap_repair_sink() -> None:
    try:
        import open_webui.events as owui_events
    except Exception:
        return
    state = _shared_gateway_state()
    if state is not None:
        state["gap_repair_on_finished"] = _on_chat_finished
    sinks = getattr(owui_events, "EVENT_SINKS", None)
    if isinstance(sinks, list) and not any(
        getattr(s, "openclaw_gap_repair_sink", False) for s in sinks
    ):
        sinks.append(_GapRepairSink())


# How much of the already-received text anchors a cumulative text that does not
# extend it by prefix. Long enough that a match means "this text contains what
# we have", never a coincidence of a short phrase ("OK.", "Done.").
_WHOLE_TEXT_ANCHOR_CHARS = 200
_MIN_WHOLE_TEXT_ANCHOR_CHARS = 64


def _item_delta_text(item_text: str, last_item_text: str, assistant_stream_text: str) -> str:
    """Compute the new text (if any) an `item` event adds beyond what's
    already been shown, either by a prior `item` event or by the regular
    `assistant` delta stream.

    Some item events of kind "message"/"output" echo the *complete* final
    assistant text (not just a genuine tool-preamble) -- without this check
    that full text gets yielded a second time on top of what the assistant
    stream already delivered, duplicating the whole final message.
    """
    baseline = last_item_text or assistant_stream_text
    if not baseline:
        return item_text
    if item_text == baseline:
        return ""
    if item_text.startswith(baseline):
        return item_text[len(baseline):]
    # Not a prefix extension. If the item still contains the tail of what was
    # already received, it is the cumulative text with something missing
    # from the middle or the start (events lost while the Gateway socket was
    # reconnecting): only what follows that tail is new. Returning the whole
    # item here posted a second full copy of a 4000-line reply (2026-10-12).
    # The missing piece is put back by the gap repair, not appended here.
    # Shorter anchors too: the hole may sit inside the longest one.
    for n in (_WHOLE_TEXT_ANCHOR_CHARS, 128, _MIN_WHOLE_TEXT_ANCHOR_CHARS):
        anchor = baseline[-n:]
        if len(anchor) < _MIN_WHOLE_TEXT_ANCHOR_CHARS:
            break
        pos = item_text.rfind(anchor)
        if pos >= 0:
            return item_text[pos + len(anchor):]
    return item_text


def _catch_all_delta(raw_text: str, received_text: str, visible_text: str) -> str:
    """New text carried by a cumulative catch-all assistant event.

    Some providers end a turn with an event that has no `delta` but a `text`
    field holding the WHOLE reply. It has to be diffed against what already
    arrived, or the entire message is treated as new.

    The diff is against `received_text`, everything the gateway sent us, and
    not only against what was shown. Those two differ: text held back by the
    ask-user buffer was received but never yielded. Diffing against shown text
    alone made the final catch-all look entirely new, so the whole needs-input
    block was appended to that buffer a second time and the dialog rendered the
    prompt twice with double the options (ELI-80). The visible-text pass stays
    as a second net for the drift case it was originally written for (P27).
    """
    if not raw_text:
        return ""
    delta = _item_delta_text(raw_text, "", received_text)
    return _suppress_already_shown(delta, visible_text)


def _suppress_already_shown(delta: str, visible_message_text: str) -> str:
    """Final safety net against re-yielding text that's already been shown.

    `_item_delta_text`'s dedup baseline (`assistant_stream_text` or
    `last_item_text`) is a separate accumulator from `visible_message_text`
    and can drift from it -- e.g. a provider's final catch-all event races
    an idle-timeout recovery cycle, or arrives after other text (tool
    blocks, recovered previews) has been recorded into
    `visible_message_text` without also updating `assistant_stream_text`.
    When that happens, `_item_delta_text`'s prefix check fails to match and
    it falls through to returning the *entire* cumulative text unchanged,
    which then gets appended a second time with no separator (P27,
    reproduced live 2026-07-10).

    `visible_message_text` is the true, complete record of everything
    already recorded for this turn, so checking whether `delta` is already
    its tail catches this regardless of which upstream baseline caused the
    false negative -- without touching the primary dedup logic (so a
    genuine partial catch-up, which is never already at the tail, still
    yields normally).
    """
    if delta and visible_message_text.endswith(delta):
        return ""
    return delta


def _attr(value: str) -> str:
    """Escape a string for use as an HTML attribute value in a tool card.

    `html.escape` alone is NOT enough here. OWUI's frontend parses these
    `<details>` attributes with a non-dotAll regex (`/(\\w+)="(.*?)"/g`, chunk
    `_UcCb4Vt.js`), so `.` never matches a newline: any attribute value
    containing a literal newline fails to match and is silently DROPPED -- the
    tool card then renders with INPUT and no OUTPUT at all, with no error.

    That was invisible for `arguments` (always `json.dumps`-ed, so its newlines
    are already the two-char `\\n` escape) but hit almost every multi-line tool
    `result`, which is passed through raw (2026-07-25).

    Encoding the newline as the numeric character reference `&#10;` keeps the
    attribute on one physical line for that regex while still decoding back to
    a real newline when the browser parses the attribute -- the same path that
    already turns `&quot;` into `"` in the rendered card.
    """
    return (
        html.escape(value)
        .replace("\r\n", "&#10;")
        .replace("\n", "&#10;")
        .replace("\r", "&#10;")
    )


def _tool_call_started_event(name: str, tool_call_id: str, args_str: str) -> dict:
    """Announce a tool call as a Responses-API output item (live spinner).

    Yielding a *dict* from the pipe is a supported protocol switch: OWUI
    serializes it verbatim as an SSE `data:` line (`functions.py::process_line`)
    instead of wrapping it in a chat chunk, and any event whose `type` starts
    with `response.` is folded into the backend's OWN output list by
    `handle_responses_streaming_event` (`middleware.py`).

    That matters because the backend's output list is what feeds the live
    `chat:completion` emissions, the final done event AND the DB write -- so a
    tool call announced this way is mutable, unlike yielded markdown, which is
    append-only for the rest of the turn (see the two-phase `<details>` attempt
    that this replaced). The frontend renders a `function_call` with no matching
    `function_call_output` as a spinner (`structuredOutput.ts::buildToolCallToken`).

    Ordering is by arrival, and `response.output_item.added` appends when it
    does not recognise the item, so these interleave correctly with ordinary
    streamed text -- no output_index bookkeeping needed on our side.

    The tool call id goes in `id`, and `call_id` is deliberately ABSENT. OWUI
    0.11.0 appended every added item unconditionally, so the obvious shape
    (`id="fc_<tid>"` + `call_id="<tid>"`) was safe. 0.11.1 rewrote that branch
    to dedup first:

        existing_index = next(idx for idx, existing in enumerate(new_output)
            if (item['id'] and existing['id'] == item['id'])
            or (item['call_id'] and existing['call_id'] == item['call_id']))
        if existing_index is not None: new_output[existing_index] = item

    -- so the `function_call_output` we send next, which must share the call
    id to pair, matched this item on `call_id` and REPLACED it. The card is
    built from the `function_call` item alone (`structuredOutput.ts`: `Ye()`
    reads `call_id ?? id` and looks the output up in a by-call_id map), so
    losing it means no card at all: no chevron, no Output, nothing. Every
    chat from the 0.11.1 upgrade onward persisted `fc=0 fco=N`.

    Carrying the id in `id` only keeps both items distinct for the dedup
    (`<tid>` vs `fco_<tid>`, and neither has a `call_id` the other shares)
    while every consumer that matters reads `call_id or id`:
    `structuredOutput.ts` for the card, `middleware.py`'s post-stream sweep
    for the "already has a result, don't execute it" guard, and
    `pause_for_tool_approval`, which even backfills `call_id` from `id`.
    """
    return {
        "type": "response.output_item.added",
        "item": {
            "type": "function_call",
            "id": tool_call_id,
            "name": name,
            "arguments": args_str[:3000],
            "status": "in_progress",
        },
    }


def _tool_call_result_event(tool_call_id: str, result_str: str) -> dict:
    """Complete a tool call announced by `_tool_call_started_event`.

    A `function_call_output` whose `call_id` matches the started item's id is
    what flips the card to done and reveals the Output section. If we never
    send one (run cancelled, pipe torn down), the backend still marks every
    leftover `in_progress` item completed before the final event, so a card
    can't be left spinning forever.

    This item keeps `call_id`; the started item does not carry one at all. See
    `_tool_call_started_event` for why that asymmetry is load-bearing on OWUI
    0.11.1+.
    """
    return {
        "type": "response.output_item.added",
        "item": {
            "type": "function_call_output",
            "id": f"fco_{tool_call_id}",
            "call_id": tool_call_id,
            "output": [{"type": "output_text", "text": result_str[:8000]}],
            "status": "completed",
        },
    }


TOOL_ERROR_MARK = "❌"


def _tool_call_error_relabel_event(name: str) -> dict:
    """Re-emit a failed call's `function_call` item with ❌ in its name.

    The card's collapsed row shows `attributes.name` and nothing else about
    outcome: its status icon is chosen by `isDone` alone, with no failure
    branch (`ToolCallDisplay.svelte:136`), so a red icon is unreachable
    without patching OWUI. The name is the only outcome-carrying field we
    control, and it renders through `Markdown`, so an emoji survives.

    `response.output_item.done` looks like the natural event for this, but in
    OWUI's `handle_responses_streaming_event` it is dead code: the broader
    `elif event_type.startswith('response.') and event_type.endswith('.done')`
    branch matches first and explicitly skips `output_item` ("handled
    specifically below" -- it isn't reachable). So we instead use that
    branch's own "Generic Field Done" arm, which for an unrecognized
    `response.<field>.done` event does `item[<field>] = data[<field>]` on
    `output[output_index]` (default: last item) and returns a non-None
    metadata dict, which is what actually triggers the broadcast. No
    `output_index` needed: the caller only uses this when the started item is
    still last, which is exactly when the default is correct.

    Unlike the old (dead) `output_item.done` shape, this mutates the existing
    item in place rather than replacing it wholesale, so `arguments`/`status`
    don't need to be repeated here -- they're already set on the item from the
    start event and survive untouched.
    """
    return {
        "type": "response.name.done",
        "name": f"{name} {TOOL_ERROR_MARK}",
    }


def _tool_error_banner(result_str: str) -> str:
    """Prefix a failed tool's Output with an explicit failure line.

    Used both as the fallback when the card label can't be safely relabeled
    (parallel calls) and alongside a relabel, so the reason is visible once
    the card is expanded rather than only implied by the ❌.
    """
    return f"{TOOL_ERROR_MARK} tool call failed\n\n{result_str}"


def _render_tool_result_block(name: str, tool_call_id: str, args_str: str,
                              result_str: str, meta) -> str:
    """Render a finished tool call as OWUI's collapsible `tool_calls` card.

    The markdown path, used when native tool items are off and by the shadow
    `_TurnRenderer` (which completes a run's OWUI message when the inline turn
    ended early, outside any live stream -- so it has no protocol channel and
    must bake the card into text).
    """
    return (
        '\n<details type="tool_calls" done="true" '
        f'id="{_attr(tool_call_id)}" '
        f'name="{_attr(name)}" '
        f'arguments="{_attr(args_str[:3000])}" '
        f'result="{_attr(result_str[:8000])}" '
        f'meta="{_attr(str(meta)[:500])}" '
        'files="[]" embeds="[]">'
        f'\n<summary>{html.escape(name)}</summary>\n</details>\n'
    )


class _TurnRenderer:
    """Reconstructs the visible assistant content of a run from its raw gateway
    event stream, mirroring the inline pipe loop's rendering.

    Purpose (2026-07-19; handover since ELI-100): when the inline pipe generator ends BEFORE a
    long run finishes (idle self-close, cancel, or a torn-down request), the
    tail used to survive only as a truncated, tool-block-less *detached*
    bubble read from a length-capped `sessions.preview`. This renderer instead
    accumulates the COMPLETE content (assistant text + every tool block, in
    order) straight from the same events the persistent connection already
    dispatches, so the run's ORIGINAL OWUI message can be finalized to exactly
    what a non-interrupted turn would have stored.

    Scope: assistant text deltas, item-carried text, and tool-result blocks.
    It holds the raw run text: the turn writer shows a resolved `MEDIA:` image
    and an answered ask-user card through the rewrites the inline reply
    recorded (`note_turn_rewrite`, review 2af1 R4).
    """

    def __init__(self):
        self.visible_text = ""
        # The same run the way OWUI 0.12 stores a streamed reply: `text` is the
        # message `content` (assistant text only) and `output` holds the
        # Responses-API items the cards are drawn from. The frontend renders
        # `output` whenever a message has one, so a tool block baked into
        # `content` as markdown is no card there (ELI-92).
        self.text = ""
        self.output: list[dict] = []
        self._assistant_stream_text = ""
        self._last_item_text = ""
        self._active_tool_args: dict[str, str] = {}
        self._tool_items: dict[str, dict] = {}
        self._tool_results: set[str] = set()
        # A new run continues the message (resume, recovery, answer run): its
        # first text gets the break the live stream puts between messages.
        # The Gateway inserts it only inside one run (graceful window
        # 2026-10-14: "...foreground.USER-DONE" across the resume).
        self.run_boundary = False

    def _add(self, chunk: str) -> None:
        if chunk:
            self.visible_text += chunk

    def _add_text(self, chunk: str) -> None:
        if not chunk:
            return
        if self.run_boundary:
            self.run_boundary = False
            chunk = _message_boundary_separator(self.text, chunk) + chunk
        self._add(chunk)
        self.text += chunk
        last = self.output[-1] if self.output else None
        if last is None or last.get("type") != "message":
            last = {
                "type": "message",
                "id": f"msg_{uuid.uuid4().hex[:24]}",
                "status": "in_progress",
                "role": "assistant",
                "content": [{"type": "output_text", "text": ""}],
            }
            self.output.append(last)
        last["content"][0]["text"] += chunk

    def _tool_item(self, name: str, tcid: str, args_str: str) -> dict:
        item = self._tool_items.get(tcid)
        if item is None:
            item = _tool_call_started_event(name, tcid, args_str)["item"]
            self._tool_items[tcid] = item
            self.output.append(item)
        return item

    def finished_output(self) -> list[dict]:
        """`output` as stored once the run is over: OWUI marks every item
        still in progress completed before its final write, and so do we."""
        out = copy.deepcopy(self.output)
        for item in out:
            if item.get("status") == "in_progress":
                item["status"] = "completed"
        return out

    def feed(self, payload: dict) -> None:
        data = payload.get("data", {}) or {}
        stream = payload.get("stream")
        name = data.get("name", "")
        phase = data.get("phase", "")

        if stream == "assistant":
            raw_delta = data.get("delta")
            if raw_delta:
                delta = raw_delta
            else:
                raw_text = data.get("text") or ""
                delta = (
                    _item_delta_text(raw_text, "", self._assistant_stream_text)
                    if raw_text else ""
                )
                delta = _suppress_already_shown(delta, self.visible_text)
            if delta:
                if (
                    "Sender (untrusted metadata)" in delta
                    or "UnTrustedMetadata" in delta
                ):
                    return
                self._assistant_stream_text += delta
                self._add_text(delta)

        if stream == "item":
            item_text = _item_assistant_text(data)
            if item_text:
                item_delta = _item_delta_text(
                    item_text, self._last_item_text, self._assistant_stream_text
                )
                self._last_item_text = item_text
                item_delta = _suppress_already_shown(item_delta, self.visible_text)
                self._add_text(item_delta)

        if stream == "tool":
            tcid = data.get("toolCallId", "")
            if phase == "start":
                if tcid:
                    args_str = json.dumps(data.get("args", {}))
                    self._active_tool_args[tcid] = args_str
                    self._tool_item(name, tcid, args_str)
            elif phase == "result":
                if tcid and tcid in self._tool_results:
                    return
                result = data.get("result", {})
                result_str = json.dumps(result) if not isinstance(result, str) else result
                args_str = self._active_tool_args.pop(tcid, None) or json.dumps(
                    data.get("args", {})
                )
                self._add(_render_tool_result_block(
                    name, tcid, args_str, result_str, data.get("meta", "")
                ))
                if tcid:
                    self._tool_results.add(tcid)
                    item = self._tool_item(name, tcid, args_str)
                    item["status"] = "completed"
                    if data.get("isError") is True:
                        item["name"] = f"{name} {TOOL_ERROR_MARK}"
                        result_str = _tool_error_banner(result_str)
                    self.output.append(_tool_call_result_event(tcid, result_str)["item"])


# ---------------------------------------------------------------------------
# Persistent Gateway Connection (singleton)
# ---------------------------------------------------------------------------

# Anchor for state that must be shared by *every* `_GatewayConnection` alive in
# this Python process -- not just the current module's singleton. OWUI's function
# loader execs each redeploy into a brand-new module object with no teardown hook
# on the old one, so a connection left running by a previous deploy (a "zombie")
# keeps its own event loop. With private bookkeeping it would not know that the
# live connection already showed a run, and wrote that turn into the chat a
# second time (P33, root-caused 2026-07-11). Stashing the bookkeeping on
# `open_webui.socket.main` (OWUI's own stable module, never reloaded by our
# function) makes all connections read and write the *same* dicts. Since
# ELI-100 a retired connection writes no turns at all (`_turn_route_event`).
_SHARED_STATE_ATTR = "_openclaw_gateway_shared_state_v1"


def _shared_gateway_state() -> dict | None:
    """Return the process-global bookkeeping dicts shared across all
    `_GatewayConnection` instances, or None when not running inside OWUI
    (e.g. unit tests), in which case callers keep instance-local state so
    each test connection stays isolated."""
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return None
    state = getattr(_owui_socket_main, _SHARED_STATE_ATTR, None)
    if state is None:
        state = {}
        setattr(_owui_socket_main, _SHARED_STATE_ATTR, state)
    # `setdefault` per key (not a one-shot dict literal on the `is None`
    # branch): this same dict persists across redeploys of the function
    # (stashed on OWUI's stable socket module), so a *new* key added in a
    # later version must be backfilled into the already-existing dict --
    # otherwise `__init__` does `_shared["new_key"]` and KeyErrors on the
    # first request after redeploy (chat_write_locks hit exactly this,
    # 2026-07-13).
    state.setdefault("delivered_live", {})
    state.setdefault("claimed_runs", {})
    state.setdefault("chat_write_locks", {})
    state.setdefault("turn_rewrites", {})
    return state


class _RunQueue(asyncio.Queue):
    """A run's event queue. Events wait for room (`await put`): a reply read
    slower than its run streams holds the receive loop back instead of losing
    text. Control markers (a gap, a restart, a session row) go in past the
    bound: they are few, a lost one can leave a reply that never ends, and
    the receive loop that puts them must never wait or raise (review 2af1 N5:
    QueueFull there killed the loop and every run on the connection hung)."""

    def put_control(self, item) -> None:
        bound, self._maxsize = self._maxsize, 0
        try:
            self.put_nowait(item)
        finally:
            self._maxsize = bound


# Open WebUI's uvicorn Server, kept while it serves (see `owui_shutting_down`).
_UVICORN_SERVER = None


def remember_owui_server() -> None:
    """Keep a reference to the uvicorn Server that runs Open WebUI.

    uvicorn installs `Server.handle_exit` as the SIGTERM/SIGINT handler while
    it serves, and that sets `should_exit` when a signal arrives. It restores
    the old handlers before asyncio cancels the tasks still running, which is
    when Open WebUI's reply tasks reach the pipe, so the Server is taken from
    the handler earlier: at import and at every request."""
    global _UVICORN_SERVER
    if _UVICORN_SERVER is not None:
        return
    try:
        server = getattr(signal.getsignal(signal.SIGTERM), "__self__", None)
    except (ValueError, TypeError):
        return
    if server is not None and hasattr(server, "should_exit"):
        _UVICORN_SERVER = server


def owui_shutting_down() -> bool:
    """True once Open WebUI's server got SIGTERM or SIGINT (`ha apps stop`,
    restart, update). Its shutdown cancels every open reply the way a Stop
    does, and no page is left to say which it was (ELI-94)."""
    remember_owui_server()
    return bool(getattr(_UVICORN_SERVER, "should_exit", False))


remember_owui_server()


@dataclass
class _Consumer:
    """An active run consumer -- its ``asyncio.Queue`` receives events."""
    session_key: str
    run_id: str
    queues: list[asyncio.Queue] = field(default_factory=list)


class _GatewayConnection:
    """Singleton persistent WebSocket connection to the Gateway.

    Maintains one WS connection, dispatches events to per-run queues, and
    auto-reconnects on disconnect with exponential backoff.
    """

    def __init__(self, valves_ref, writes_turns: bool = True, scopes: list | None = None,
                 identity_name: str = "identity", requests_only: bool = False):
        # Weak reference to Pipe valves (re-read on each call)
        self._valves = valves_ref
        # The scopes this connection requests and signs. A connection built with
        # RESTRICTED_SCOPES has its own device identity (`identity_name`) and
        # only sends requests (`requests_only`: no subscriptions, it renders
        # nothing); see `_run_request`.
        self.scopes = list(GATEWAY_SCOPES if scopes is None else scopes)
        self._identity_name = identity_name
        self.requests_only = requests_only
        self._ws: websockets.WebSocketClientProtocol | None = None
        self._event_loop_task: asyncio.Task | None = None
        self._init_lock = asyncio.Lock()

        # Identity
        self._ident: dict | None = None
        self._device_token: str | None = None

        # Request-response futures (keyed by request id)
        self._pending_reqs: dict[str, asyncio.Future] = {}

        # Run consumers (keyed by f"{session_key}:{run_id}")
        self._consumers: dict[str, _Consumer] = {}

        # Per-session locks serializing the queue-release -> chat.send -> run
        # registration critical section. Two concurrent messages that release
        # from the queue at the same instant would otherwise both send into the
        # same idle window; the gateway steer-merges the second into the first,
        # which then renders nothing ("no reply text"). Serializing the send so
        # the next waiter observes the just-started run (via sessions.list
        # hasActiveRun) closes that thundering-herd race. ELI-56.
        self._session_send_locks: dict[str, asyncio.Lock] = {}

        # Deferred aborts for cancelled turns, {session_key: {"run_id", "task"}}.
        # OWUI 0.12 has no "send while running" that keeps the running turn:
        # both its interrupt path and the queued message's "Send now" call
        # stopTasksByChatId and then submit the new message ~0.5-0.8s later
        # (measured live 2026-10-11). An immediate chat.abort on that cancel
        # kills the turn AND every subagent it spawned (the gateway's
        # chat.abort cascades through abortControlledSubagents). So the abort
        # waits a short grace window, and a new message for the same session
        # inside it claims the run instead of letting it die. A plain Stop
        # (no follow-up message) still aborts once the window passes.
        self._pending_cancel_aborts: dict[str, dict] = {}

        # ELI-59: last model applied per session, {session_key: (model, ts)}.
        # A burst of near-simultaneous messages on one session all issue the
        # SAME idempotent sessions.patch; under that contention the RPC can
        # transiently time out and that message's answer is replaced by a
        # "Model selection error". Caching the last applied value (with a
        # short TTL -- the session model can drift externally, e.g. /model in
        # the Control UI) lets same-model calls skip the RPC entirely, and the
        # per-session patch lock collapses a burst to ONE in-flight patch.
        # OWUI caveat: multiple worker processes each keep their own cache --
        # imperfect, but strictly fewer redundant patches than before.
        self._model_patch_cache: dict[str, tuple[str | None, float]] = {}
        self._model_patch_locks: dict[str, asyncio.Lock] = {}

        # Last thinking-clamp note shown per session, so a standing mismatch
        # between the picked level and the model's ladder is explained ONCE
        # instead of prefixing every single answer with the same italic line.
        self._thinking_note_shown: dict[str, str] = {}

        # Reconnect state
        self._reconnect_attempt = 0
        self._max_backoff = 30  # seconds
        # The Gateway sends a `tick` event every `policy.tickIntervalMs` of
        # hello-ok (30 s, server-maintenance-Wf2jQ0wx.mjs:156); its own client
        # drops a socket that sent no frame for twice that ("tick timeout",
        # client-CKDmO6tp.mjs:1447-1459). The event loop does the same.
        self._tick_interval_s = 30.0
        self._stopped = False
        # Set once a newer deploy of this function has taken over (see
        # `retire()`). A retired connection still serves runs it already
        # has consumers for, but never writes turns (`_turn_route_event`) and
        # never reconnects once those runs are gone.
        self._retired = False
        # ELI-100: this connection's identity as a turn writer. A message whose
        # recorded writer is gone (`_turn_writer_alive`: retired here, or its
        # worker process exited) can be taken over (DESIGN 2.3); retire()
        # removes it.
        self.writer_id = turn_writer_id()
        # The Status Action's own connection only makes RPCs: it never writes turns.
        self.writes_turns = writes_turns
        self._turn_pumps: dict = {}     # (session_key, run_id) -> _RunPump
        self._turn_writers: dict = {}   # (chat_id, message_id) -> _TurnWriter
        self._turn_skip_runs: dict = {}  # (session_key, run_id) of heartbeat runs
        # (session_key, run_id) -> events of an agent run not yet known to be
        # no heartbeat, and the runs known (review 2af1 R7, `_turn_kind_known`)
        self._turn_unkinded: dict = {}
        self._turn_kinded: dict = {}
        # (child session, child run) -> a sub-agent's result (review 2af1 R10)
        self._child_results: dict = {}
        # session_key -> run id of an inline reply with no Open WebUI message
        # waiting for its interrupted run's owner (review 2af1 R14)
        self._awaiting_owner: dict = {}
        self._session_ids: dict = {}     # session_key -> sessionId (a cron wake's run id)
        self._wake_turns_bound: dict = {}  # session_key -> wake turn keys given a message
        self._turn_resolve_lock = asyncio.Lock()
        self._frame_seq: int | None = None
        self._stop_notice_seen = False  # `shutdown` without restartExpectedMs on this socket
        self._shutdown_seen = False     # any `shutdown` on this socket
        # Bumped on every successful connect/reconnect. A consumer that
        # captures this before `chat.send` can later tell "the queue is quiet
        # because the agent is thinking" from "the queue is quiet because the
        # Gateway went away and came back, taking my run with it" -- the
        # Gateway only persists a turn once it COMPLETES, so a restart mid-run
        # destroys it silently and no terminal event is ever emitted.
        self.connection_epoch = 0
        # A reconnect is not a restart. `hello-ok.server.bootId` names the
        # Gateway process: same id after a reconnect = the same Gateway, its
        # runs are still going; a new id = it restarted and took them with it.
        # Treating every reconnect as a restart sent a bogus "gateway
        # restarted, resume" turn into live sessions and closed their OWUI
        # replies while the real run kept going (2026-10-12, a 1s WebSocket
        # drop under host memory pressure). `gateway_restarts` only counts
        # real restarts; consumers compare it, not `connection_epoch`.
        self.gateway_boot_id: str | None = None
        self.gateway_restarts = 0

        # Next request id
        self._next_req_id = 1

        # Counter for the event loop
        self._event_count = 0

        # Delivery bookkeeping. When running inside OWUI these dicts are the
        # *same objects* for every `_GatewayConnection` in the process (see
        # `_shared_gateway_state`), so a turn shown live by one connection is
        # seen as delivered by all of them (P33, 2026-07-11). Outside OWUI
        # (unit tests) each connection gets its own isolated dicts.
        _shared = _shared_gateway_state()

        # Runs the startup stub reconcile already finished, keyed by
        # "claim:<chat>:<stub>", so two connections never finalize one stub twice.
        self._claimed_runs: dict[str, bool] = (
            _shared["claimed_runs"] if _shared is not None else {}
        )

        # Records, by "session_key:run_id", every *final* event that was
        # actually dispatched to a live consumer queue (i.e. genuinely shown
        # to an open browser tab, which persists it itself via OWUI's normal
        # client-side flow). If the Gateway later re-emits a duplicate/retried
        # final event for that same run_id after the tab's request has
        # closed, this identity check catches it precisely -- unlike a
        # content-equality check, it can't false-positive just because two
        # unrelated turns happen to end with the same short text (e.g. "OK.",
        # "Done."), and unlike the debounce timer alone, it doesn't depend on
        # how long the session stays quiet afterward.
        # Events of a run continuing a message (an ask-user answer) that
        # arrived before its reply registered for it, while that reply still
        # streams the message: never a turn writer's (review 2af1 N6).
        self._held_for_live: dict[tuple[str, str], list] = {}
        self.unreachable_held_drains = 0
        self._delivered_live: dict[str, float] = (
            _shared["delivered_live"] if _shared is not None else {}
        )

        # Per-chat write locks for the read-modify-write paths that are not
        # turn writers (gap repair, stub reconcile). Shared across connections.
        # Keyed by chat_id.
        self._chat_write_locks: dict[str, asyncio.Lock] = (
            _shared["chat_write_locks"] if _shared is not None else {}
        )

        # Shadow bookkeeping. For a run that a live pipe() call is rendering
        # into a known OWUI message, `_run_targets[key]` holds that message's
        # (chat_id, message_id) and `_run_renderers[key]` a `_TurnRenderer`
        # accumulating the full content from this run's event stream -- so if
        # the inline turn ends before the run does (cancel, close, a torn-down
        # request), a turn writer continues the SAME message from it
        # (`_turn_route_event`, DESIGN 2.6). Instance-local
        # (not shared): only the singleton connection runs pipe() and dispatches
        # its own events; a zombie connection never registers a target.
        self._run_targets: dict[str, dict] = {}
        self._run_renderers: dict[str, "_TurnRenderer"] = {}
        # What the inline reply showed in place of raw run text, by
        # "chat_id:message_id": [(raw, shown)] for each resolved `MEDIA:`
        # directive and each ask-user prompt (its card, or its fallback text).
        # A turn writer that takes the message over repeats them (review 2af1
        # R4). Shared, so a successor deploy's writer has them too.
        self._turn_rewrites: dict[str, list] = (
            _shared["turn_rewrites"] if _shared is not None else {}
        )

        # Sessions whose transcript events (`session.tool`) this connection
        # asked for with `sessions.messages.subscribe`. A subscription ends
        # with the socket, so `_subscribe_all` renews every one after each
        # connect. Tool events for one call can arrive twice (as the run's
        # initiator AND as a subscriber); `_tool_events_seen` keeps the first.
        self._message_subscriptions: set[str] = set()
        # OWUI session key -> run ids active when this socket last subscribed
        # (ELI-100 DESIGN 2.1): runs that started before the subscription,
        # restart recovery above all, whose start push this socket never got.
        # An empty list means "active, ids not given": the Gateway omits
        # activeRunIds for claude-cli runs (session-active-runs-BURU1M8_.mjs:90).
        self.active_run_snapshot: dict[str, list[str]] = {}
        self._subscriptions_stale = False
        # One Event per session someone is waiting on, set by the next
        # `sessions.changed` that carries run state for it (ELI-88).
        self._session_change_waiters: dict[str, asyncio.Event] = {}
        self._tool_events_seen: dict[tuple, bool] = {}

    async def _subscribe_all(self) -> None:
        """Renew this socket's subscriptions: the session index
        (`sessions.changed`, which carries run start/settle), and transcript
        events for every OWUI session subscribed so far."""
        try:
            # List params make it one request: the Gateway registers this
            # socket for pushes, THEN lists (sessions-subscriptions:21-36), so a
            # run is in this snapshot or its start push comes after it.
            resp = await self.send_request("sessions.subscribe", {"activeOnly": True}, timeout=15)
        except Exception as ex:
            pipe_log(f"  sessions.subscribe failed: {ex}")
        else:
            self._note_active_snapshot(((resp or {}).get("list") or {}).get("sessions") or [])
            self._stop_notice_seen = False
            self._shutdown_seen = False
            spawn_background(_turn_after_hello(self))
        for key in list(self._message_subscriptions):
            await self._subscribe_messages(key)
        # A waiter that read run state before the subscription existed would
        # sleep through a settle it was never sent; make every waiter read
        # again now that settles are pushed.
        self._wake_session_waiters()

    def _note_active_snapshot(self, rows: list) -> None:
        """Keep the active runs of OWUI sessions from a subscribe snapshot."""
        snap = {}
        for row in rows:
            key = str(row.get("key") or "")
            runs = [r for r in (row.get("activeRunIds") or []) if r]
            if (runs or row.get("hasActiveRun")) and self.parse_owui_session_key(key):
                snap[key] = runs
        self.active_run_snapshot = snap
        if snap:
            pipe_log(f"  subscribe snapshot: {len(snap)} OWUI session(s) with an active run")

    async def _subscribe_messages(self, session_key: str) -> bool:
        try:
            await self.send_request(
                "sessions.messages.subscribe", {"key": session_key}, timeout=15
            )
            return True
        except Exception as ex:
            pipe_log(f"  sessions.messages.subscribe {session_key[-36:]} failed: {ex}")
            return False

    async def ensure_message_subscription(self, session_key: str) -> None:
        """Receive `session.tool` for `session_key` from now on. Tool events
        reach the connection that STARTED a run as `agent` events; everyone
        else, including this connection after a reconnect and for any run the
        Gateway starts itself (restart recovery, wakes, announces), gets them
        only as `session.tool` on a transcript subscription (ELI-92)."""
        if not session_key or session_key in self._message_subscriptions:
            return
        self._message_subscriptions.add(session_key)
        if not await self._subscribe_messages(session_key):
            self._message_subscriptions.discard(session_key)

    def _first_tool_event(self, payload: dict) -> bool:
        """False for a tool event this connection already dispatched: the
        same call's start/result can arrive both as the initiator's `agent`
        event and as a subscriber's `session.tool`."""
        data = payload.get("data") or {}
        tcid = data.get("toolCallId")
        phase = data.get("phase")
        if not tcid or phase not in ("start", "result"):
            return True
        key = (payload.get("sessionKey"), tcid, phase)
        if key in self._tool_events_seen:
            return False
        self._tool_events_seen[key] = True
        if len(self._tool_events_seen) > 4000:
            for stale in list(self._tool_events_seen)[:2000]:
                self._tool_events_seen.pop(stale, None)
        return True

    def session_change_event(self, session_key: str) -> asyncio.Event:
        """An Event set by the next pushed change to `session_key`'s run state
        (`sessions.changed` with `hasActiveRun`: run started, run settled).

        Take it BEFORE reading the state, then wait on it only if the read
        said busy: a change landing between the read and the wait has already
        set it, so no change can slip through and no polling is needed. A
        socket drop sets every waiter too (the change may be among the lost
        events), so a waiter always re-reads after a gap."""
        ev = self._session_change_waiters.get(session_key)
        if ev is None:
            ev = self._session_change_waiters[session_key] = asyncio.Event()
        return ev

    def _wake_session_waiters(self, session_key: str | None = None) -> None:
        keys = [session_key] if session_key else list(self._session_change_waiters)
        for key in keys:
            ev = self._session_change_waiters.pop(key, None)
            if ev is not None:
                ev.set()

    def _on_shutdown(self, payload: dict) -> None:
        """DESIGN 2.7 F4: the Gateway announces its close before it aborts any
        run. No restartExpectedMs = stop mode, whose aborted runs it never
        recovers; with it, restart mode, whose aborted rows stay `running`."""
        self._shutdown_seen = True
        if payload.get("restartExpectedMs") is None:
            self._stop_notice_seen = True

    def hand_over_run(self, session_key: str, run_id: str, *,
                      thinking: str | None = None, read_row: bool = False) -> bool:
        """An interrupted run's request ends without continuing it: the turn
        writer takes its message over (DESIGN 2.6) and the run's settled row
        decides who continues it (2.7), so a reply never resumes a run the
        Gateway recovers. `read_row`: the row is read now, for a handover
        that can come after the post-hello resync. False when there is no
        message to hand over."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets.get(key)
        parsed = self.parse_owui_session_key(session_key)
        if (target is None or not parsed or not self.writes_turns or self._retired
                or (session_key, run_id) in self._turn_pumps):
            return False
        pump = self._turn_pumps[(session_key, run_id)] = _RunPump()
        pump.handover = {"message_id": target["message_id"],
                         "renderer": self._run_renderers.get(key),
                         "thinking": thinking or target.get("thinking")}
        pump.stop_notice_before = self._stop_notice_seen
        self.unregister_run_target(session_key, run_id)
        spawn_background(_turn_pump_loop(self, session_key, run_id, parsed, pump))
        spawn_background(self.ensure_message_subscription(session_key))
        if read_row:
            spawn_background(_turn_resync(self, skip=set(self.active_run_snapshot)))
        pipe_log(f"  handed run {run_id[:24]}... over to the turn writer "
                 f"(message {target['message_id'][:8]}...)")
        return True

    def _on_sessions_changed(self, payload: dict) -> None:
        """A session row changed. Waiters on its run state re-read it, and an
        OWUI session whose run just started gets a transcript subscription
        before its first tool call (measured: run start is pushed ~3s ahead of
        the first `session.tool`)."""
        key = payload.get("sessionKey") or payload.get("key") or ""
        self.note_session_id(key, payload.get("sessionId"))
        if key and "hasActiveRun" in payload:
            self._wake_session_waiters(key)
            self.row_to_consumers(key, payload)
        if key and payload.get("hasActiveRun") is False:
            _turn_settled(self, key, payload)
        if (payload.get("hasActiveRun") and key
                and key not in self._message_subscriptions
                and self.parse_owui_session_key(key)):
            spawn_background(self.ensure_message_subscription(key))

    def row_to_consumers(self, session_key: str, row: dict, resync: bool = False,
                         read_at: float | None = None, outside_loop: bool = False) -> None:
        """Hand session row `row` to every inline reply of `session_key`.
        `read_at`: when the row was read, if not just now (a resync's read
        started before its reply came back). `outside_loop`: put by a task,
        not the receive loop, which may be waiting to put an earlier event
        into a full queue; the row waits its turn behind it (review 2af1
        N9), in a task per queue so one stalled reply holds up no other."""
        marker = {"type": _ROW_MARKER_TYPE, "row": row, "resync": resync,
                  "read_at": time.monotonic() if read_at is None else read_at}
        for key, consumer in list(self._consumers.items()):
            if key.startswith(f"{session_key}:"):
                for q in consumer.queues:
                    if outside_loop:
                        spawn_background(q.put(dict(marker)))
                    else:
                        q.put_control(dict(marker))

    async def push_row(self, session_key: str) -> None:
        """Read the session's row now and hand it to its inline replies."""
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  row read for {session_key[-12:]} failed: {ex!r}")
            return
        row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
        if row is not None:
            self.row_to_consumers(session_key, row, outside_loop=True)

    def stop_awaiting_owner(self, session_key: str, run_id: str) -> None:
        """The reply decided: the agent runs held for it go on (`_release_held`)."""
        if self._awaiting_owner.get(session_key) == run_id:
            del self._awaiting_owner[session_key]
            self._release_held(session_key)

    def note_session_id(self, session_key: str, session_id) -> None:
        if session_key and isinstance(session_id, str) and session_id:
            self._session_ids[session_key] = session_id

    async def session_id_for(self, session_key: str) -> str | None:
        """The session's sessionId, which is also the run id of every cron wake
        into it. Session rows and lifecycle / session.tool events carry it;
        assistant and chat events do not, so a wake whose first event is one
        of those reads the row."""
        known = self._session_ids.get(session_key)
        if known:
            return known
        try:
            lst = await self.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  sessionId read for {session_key[-12:]} failed: {ex!r}")
            return None
        for row in lst.get("sessions") or []:
            self.note_session_id(row.get("key") or "", row.get("sessionId"))
        return self._session_ids.get(session_key)

    def register_run_target(self, session_key: str, run_id: str,
                            chat_id: str | None, message_id: str | None,
                            thinking: str | None = None) -> None:
        """Remember that this run streams into OWUI message `message_id` in
        `chat_id`, and start a shadow `_TurnRenderer` for it. No-op without both
        ids (e.g. a chat with no stable message id yet). `thinking`: the
        turn's level, which a writer's resume keeps (review 2af1 R6)."""
        if not (chat_id and message_id and run_id):
            return
        key = f"{session_key}:{run_id}"
        self._run_targets[key] = {"chat_id": chat_id, "message_id": message_id,
                                  "thinking": thinking}
        self._run_renderers[key] = _TurnRenderer()
        # Bound memory: a run that never emits a terminal would otherwise leak
        # its target/renderer forever. Far above any real concurrency.
        if len(self._run_targets) > 100:
            for stale in list(self._run_targets)[:50]:
                self._run_targets.pop(stale, None)
                self._run_renderers.pop(stale, None)

    def unregister_run_target(self, session_key: str, run_id: str) -> None:
        key = f"{session_key}:{run_id}"
        self._run_targets.pop(key, None)
        self._run_renderers.pop(key, None)

    def continue_run_target(self, session_key: str, run_id: str, next_run_id: str,
                            shown: bool = True) -> None:
        """The inline reply moved from `run_id` to `next_run_id` (an ask-user
        answer run): the target and its shadow renderer follow it, so a
        handover of the answer run continues the same reply (review 2af1 R9;
        the writer finds the question run in the transcript as a pipe run of
        the same message). The question run was shown to its end: its late
        events open nothing. `shown=False` moves the target only: the answer
        is not sent yet (review 2af1 N6), or its send failed and the target
        moves back."""
        key = f"{session_key}:{run_id}"
        target = self._run_targets.pop(key, None)
        renderer = self._run_renderers.pop(key, None)
        if shown:
            self.mark_delivered_live(session_key, run_id)
        if target is None:
            return
        nkey = f"{session_key}:{next_run_id}"
        self._run_targets[nkey] = target
        self._run_renderers[nkey] = renderer if renderer is not None else _TurnRenderer()

    def note_turn_rewrite(self, chat_id: str | None, message_id: str | None,
                          raw: str, shown: str) -> None:
        """The inline reply showed `shown` where its run said `raw` (a resolved
        `MEDIA:` directive, an ask-user prompt's card). A writer that takes
        the message over shows the same (review 2af1 R4)."""
        if not (chat_id and message_id and raw) or raw == shown:
            return
        key = f"{chat_id}:{message_id}"
        rewrites = self._turn_rewrites.setdefault(key, [])
        if (raw, shown) not in rewrites:
            rewrites.append((raw, shown))
        if len(self._turn_rewrites) > 200:
            for stale in list(self._turn_rewrites)[:100]:
                self._turn_rewrites.pop(stale, None)

    def turn_rewrites(self, chat_id: str, message_id: str) -> list:
        return list(self._turn_rewrites.get(f"{chat_id}:{message_id}") or [])

    def _chat_write_lock(self, chat_id: str) -> asyncio.Lock:
        """Return the process-wide `asyncio.Lock` for serializing the
        read-modify-write paths into `chat_id` (gap repair, stub reconcile),
        creating it on first use."""
        lock = self._chat_write_locks.get(chat_id)
        if lock is None:
            lock = asyncio.Lock()
            self._chat_write_locks[chat_id] = lock
        return lock

    # ── Public API ──────────────────────────────────────────────────

    async def ensure_connected(self):
        """Ensure the WS connection is up; connect/reconnect if needed."""
        if self._ws and self._event_loop_task and not self._event_loop_task.done():
            return
        if self._retired and not self._consumers:
            # Reviving a retired connection is how orphans piled up: each one
            # kept writing every agent turn with its own (older) code.
            raise GatewayError(
                "gateway connection retired: a newer deploy of the pipe owns it now"
            )
        async with self._init_lock:
            if self._ws and self._event_loop_task and not self._event_loop_task.done():
                return
            self._stopped = False
            await self._connect_and_start()
            if not self._event_loop_task or self._event_loop_task.done():
                self._loop = asyncio.get_running_loop()
                self._event_loop_task = asyncio.create_task(self._event_loop())

    async def send_request(self, method: str, params: dict, timeout: float = 10) -> dict:
        """Send a request and wait for the response."""
        # `self._ws` is briefly None while the event loop is reconnecting
        # (see `_event_loop`/`_reconnect`). Without this guard the `.send`
        # below raises a bare `AttributeError: 'NoneType' object has no
        # attribute 'send'`, which surfaces to the user as a cryptic
        # "**Error sending message:** 'NoneType'...". A GatewayError with a
        # clear reason is caught by the same callers and reads sanely.
        if self._ws is None:
            raise GatewayError("gateway connection not ready (reconnecting)")
        req_id = str(self._next_req_id)
        self._next_req_id += 1
        fut = asyncio.get_running_loop().create_future()
        self._pending_reqs[req_id] = fut

        try:
            await self._ws.send(json.dumps(dict(
                type="req", id=req_id, method=method, params=params
            )))
            return await asyncio.wait_for(fut, timeout=timeout)
        finally:
            self._pending_reqs.pop(req_id, None)

    def session_send_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock serializing the queue-release -> chat.send -> run
        registration critical section (see `_session_send_locks`). Created
        lazily; asyncio.Lock is created on the running loop the first time it
        is awaited."""
        lock = self._session_send_locks.get(session_key)
        if lock is None:
            lock = asyncio.Lock()
            self._session_send_locks[session_key] = lock
        return lock

    MODEL_PATCH_CACHE_TTL_S = 60.0

    def model_patch_lock(self, session_key: str) -> asyncio.Lock:
        """Per-session lock so a burst of same-session messages issues one
        sessions.patch, not N concurrent ones (ELI-59). Lazily created, same
        pattern as session_send_lock."""
        lock = self._model_patch_locks.get(session_key)
        if lock is None:
            lock = asyncio.Lock()
            self._model_patch_locks[session_key] = lock
        return lock

    def model_patch_cached(self, session_key: str, model: str | None) -> bool:
        """True if `model` was successfully applied to this session within the
        cache TTL, so the idempotent sessions.patch can be skipped (ELI-59).
        The TTL bounds the wrong-model window if the session's model is changed
        externally (e.g. /model in the Control UI) between OWUI messages."""
        entry = self._model_patch_cache.get(session_key)
        if entry is None:
            return False
        cached_model, ts = entry
        return cached_model == model and (time.time() - ts) < self.MODEL_PATCH_CACHE_TTL_S

    def record_model_patched(self, session_key: str, model: str | None) -> None:
        """Record a successful sessions.patch for the cache (ELI-59)."""
        self._model_patch_cache[session_key] = (model, time.time())

    def should_announce_thinking_note(self, session_key: str, note: str) -> bool:
        """True the first time a given clamp note applies to a session.

        The level is picked in a filter dropdown and then stays picked, so a
        model that cannot honour it produces the identical note on every
        message. Told once it is useful; repeated above every answer it is
        noise the user has no way to dismiss, which is what it became in
        practice. Any CHANGE (different level, different model, a ladder
        learned from a rejection) is a new note and speaks up again.

        Per connection rather than persisted on purpose: after a redeploy or a
        reconnect the reminder is worth one repeat, and this must never be a
        file whose staleness could silence a genuinely new mismatch.
        """
        if not note:
            return False
        if self._thinking_note_shown.get(session_key) == note:
            return False
        self._thinking_note_shown[session_key] = note
        return True

    def invalidate_model_patch(self, session_key: str) -> None:
        """Drop the cached model for a session (ELI-59) -- called on patch
        failure so the next message retries the RPC from scratch."""
        self._model_patch_cache.pop(session_key, None)

    def register_consumer(self, session_key: str, run_id: str) -> asyncio.Queue:
        """Register an event consumer queue for a (session, run) pair.

        Returns a new queue attached to the consumer. Multiple queues per
        consumer are supported for broadcast (used by steering).
        """
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            consumer = _Consumer(session_key=session_key, run_id=run_id)
            self._consumers[key] = consumer
            pipe_log(f"  registered consumer: {key[:60]}...")
        q = _RunQueue(maxsize=500)
        consumer.queues.append(q)
        for ev in self._held_for_live.pop((session_key, run_id), []):
            q.put_nowait(_event_frame(ev))  # the run's first events, held for this reply (N6)
        return q

    def unregister_consumer(self, session_key: str, run_id: str, queue: asyncio.Queue | None = None):
        """Remove a consumer queue.

        If queue is given, only that queue is removed (broadcast mode).
        If queue is None, the entire consumer (all queues) is removed.
        """
        key = f"{session_key}:{run_id}"
        consumer = self._consumers.get(key)
        if consumer is None:
            return
        if queue:
            try:
                consumer.queues.remove(queue)
            except ValueError:
                pass
        if not consumer.queues or queue is None:
            del self._consumers[key]
            self._release_held(session_key)
        pipe_log(f"  unregistered consumer: {key[:60]}...")
        if self._retired and not self._consumers:
            pipe_log("  retired gateway connection: last run finished, closing")
            spawn_background(self.disconnect())

    def live_reply_owns(self, session_key: str, run_id: str) -> bool:
        """True when `run_id` continues a message (an ask-user answer, a
        resume) that a live inline reply of another run still streams: its
        events wait for that reply (`register_consumer`) instead of opening a
        second writer on the message (review 2af1 N6)."""
        parsed = parse_pipe_run_id(run_id)
        waiting = self._awaiting_owner.get(session_key)
        if waiting and parsed is None and run_id != waiting:
            # A reply with no message waits for its run's owner (R14): any
            # agent run here may be the Gateway's recovery of it. It waits
            # until the reply has read the transcript (rule E).
            return True
        if parsed is None or parsed["kind"] == "reply":
            return False
        for c in list(self._consumers.values()):
            other = parse_pipe_run_id(c.run_id) if c.session_key == session_key else None
            if (other and c.run_id != run_id and other["chat"] == parsed["chat"]
                    and other["message"] == parsed["message"]):
                return True
        return False

    def hold_for_live(self, session_key: str, run_id: str, payload: dict) -> None:
        held = self._held_for_live.setdefault((session_key, run_id), [])
        if len(held) < 500:
            held.append(payload)

    def _release_held(self, session_key: str) -> None:
        """A reply ended. The runs held for it stay held until they drain, in
        their order of arrival (review 2af1 N7, N8): into the run's own queue
        if a reply registers for it (`register_consumer`; the ask-user switch
        registers right after this release), before the run's next event
        (`_turn_route_now`), or here, in the background, for a run that sends
        no more."""
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            return  # no loop, no events to route (a sync teardown)
        for (sess, run) in list(self._held_for_live):
            if sess == session_key:
                async def drain(sess=sess, run=run):
                    self.drain_held(sess, run)
                spawn_background(drain())

    def drain_held(self, session_key: str, run_id: str) -> None:
        """Route the held events of a run no live reply owns any more, in
        order and synchronously: the router never awaits, so nothing routed
        for the run can come between them."""
        if self.live_reply_owns(session_key, run_id):
            return
        held = self._held_for_live.pop((session_key, run_id), None)
        if not held:
            return
        consumer = self._consumers.get(f"{session_key}:{run_id}")
        if consumer is not None:
            # Unreachable: `register_consumer` takes a run's held events
            # before its queue exists. Counted and logged so a path that
            # breaks this shows; the events still reach the reply.
            self.unreachable_held_drains += 1
            pipe_log(f"  ERROR unreachable: {len(held)} held event(s) for an already-registered "
                     f"consumer of {run_id[:24]}... (count {self.unreachable_held_drains})")
            for q in consumer.queues:
                for ev in held:
                    q.put_control(_event_frame(ev))
            return
        pipe_log(f"  {len(held)} held event(s) of {run_id[:24]}... released to the turn writer")
        for ev in held:
            _turn_route_now(self, ev)

    def mark_delivered_live(self, session_key: str, run_id: str):
        """Record that this run's final event was just dispatched to a live
        consumer queue -- i.e. genuinely shown to an open browser tab, which
        persists it itself via OWUI's own client-side flow. See
        `_delivered_live`'s docstring: a late event of such a run never
        reopens its message (`_turn_route_event`)."""
        key = f"{session_key}:{run_id}"
        self._delivered_live[key] = time.time()
        if len(self._delivered_live) > 500:
            oldest_first = sorted(self._delivered_live.items(), key=lambda kv: kv[1])
            for stale_key, _ in oldest_first[:250]:
                self._delivered_live.pop(stale_key, None)

    def was_delivered_live(self, session_key: str, run_id: str) -> bool:
        return f"{session_key}:{run_id}" in self._delivered_live

    def active_run_id_for_session(self, session_key: str) -> str | None:
        """Return the sole active run id for a session, if one is registered."""
        matches = [
            consumer.run_id for consumer in self._consumers.values()
            if consumer.session_key == session_key
        ]
        if len(matches) == 1:
            return matches[0]
        return None

    def parse_owui_session_key(self, session_key: str) -> tuple[str, str] | None:
        """Reverse `_owui_session_key`: extract (user_id, chat_id) from a
        session key this pipe built, e.g.
        "agent:main:openwebui-<user_id>-<chat_id>". Both ids are fixed-width
        36-char UUIDs, so a positional split resolves the ambiguity of a
        plain "-".split() (UUIDs themselves contain dashes). Returns None for
        session keys not owned by this pipe/agent (e.g. cross-channel bleed).
        """
        agent_id = getattr(self._valves(), "AGENT_ID", None)
        if not agent_id:
            return None
        prefix = f"agent:{agent_id}:openwebui-"
        if not session_key.startswith(prefix):
            return None
        after = session_key[len(prefix):]
        if len(after) < 73 or after[36] != "-":
            return None
        return after[0:36], after[37:73]

    def consumers_for_event(self, payload: dict) -> list[_Consumer]:
        """Return consumers that should receive a Gateway event payload."""
        evt_session = payload.get("sessionKey", "")
        evt_run_id = payload.get("runId", "")
        if evt_session and evt_run_id:
            consumer = self._consumers.get(f"{evt_session}:{evt_run_id}")
            return [consumer] if consumer else []
        if evt_session and not evt_run_id:
            matches = [
                consumer for consumer in self._consumers.values()
                if consumer.session_key == evt_session
            ]
            return matches if len(matches) == 1 else []
        return []

    async def session_preview(self, session_key: str, limit: int = 8,
                              max_chars: int = 4000) -> dict:
        """Fetch a bounded transcript preview. Every item comes back clipped
        server-side (see `_preview_recovery_text`), so do not use this where
        the whole message matters."""
        return await self.send_request(
            "sessions.preview",
            dict(keys=[session_key], limit=limit, maxChars=max_chars),
            timeout=10
        )

    async def session_history(self, session_key: str,
                              limit: int = RECOVERY_HISTORY_LIMIT,
                              max_chars: int = RECOVERY_HISTORY_MAX_CHARS,
                              timeout: float = 10) -> dict:
        """Fetch the session's recent messages unclipped, for timeout recovery."""
        return await self.send_request(
            "chat.history",
            dict(sessionKey=session_key, limit=limit, maxChars=max_chars),
            timeout=timeout
        )

    async def abort(self, session_key: str, run_id: str):
        """Send chat.abort for an active run."""
        try:
            await _run_request(self, RUN_ABORT, dict(sessionKey=session_key, runId=run_id),
                               wait=False)
            pipe_log(f"  sent chat.abort for run {run_id[:20]}...")
        except Exception as e:
            pipe_log(f"  abort send failed: {e}")

    async def _abort_cancelled_run(self, session_key: str, run_id: str,
                                   send_stop: bool) -> None:
        await self.abort(session_key, run_id)
        if send_stop:
            pipe_log("Generator cancelled -- sending /stop fallback")
            await self.send_stop(session_key)

    def park_cancelled_turn(self, session_key: str, run_id: str | None,
                            queue: asyncio.Queue | None, carried: list[str],
                            grace_s: float, send_stop: bool,
                            run_text: dict | None = None) -> None:
        """Hand a cancelled reply's unfinished business to the next message.

        OWUI cancels a response the same way for Stop and for Send now /
        interrupt (which then sends a new message): both call
        stopTasksByChatId, and the message queue lives only in the browser.
        So the cancelled turn is parked first and decided after:

        * `run_id` keeps running, and `queue` stays registered so every event
          the run emits (including ones queued but not yet shown) is buffered
          rather than dropped;
        * `carried` holds user messages the cancelled reply had accepted but
          not yet sent to the Gateway, oldest first;
        * `run_text` holds the run's text dedup baselines up to the cut
          ({"received", "stream", "item"}). The run's closing events repeat
          its WHOLE text; a claimer that starts from empty baselines takes all
          of it for new and appends the entire reply again (seen live
          2026-10-12: 2327..4000 followed by 1..4000).

        The caller then asks the browser which button was pressed and calls
        `settle_parked_turn`: Stop releases it now, Send now holds it for the
        follow-up message. `grace_s` is only the fallback for a client that
        cannot say (no page hook, API use). `claim_cancelled_turn` takes all
        of it over; if nothing claims it, the run is aborted, the queue
        released and the carried messages dropped (the user stopped them).

        Synchronous on purpose: it runs on the generator's cancel/close path,
        where an await can itself be interrupted, so nothing here may depend
        on one. The Gateway calls go to background tasks.

        Open WebUI shutting down cancels every open reply too, and that is no
        Stop: the run keeps going, nothing is aborted, and the next process's
        startup reconcile finishes the reply (ELI-90 if the run is still
        active, ELI-94 if it ended while Open WebUI was down).
        """
        if owui_shutting_down():
            if queue is not None:
                self.unregister_consumer(session_key, run_id, queue=queue)
            pipe_log(f"  Open WebUI is shutting down: run {str(run_id)[:20]}... keeps going "
                     f"({len(carried)} unsent message(s) dropped)")
            return
        previous = self._pending_cancel_aborts.pop(session_key, None)
        if previous is not None:
            if previous["task"] is not None:
                previous["task"].cancel()
            previous["resolved"].set()
            carried = list(previous["carried"]) + list(carried)
            if previous["queue"] is not None and previous["queue"] is not queue:
                self.unregister_consumer(
                    session_key, previous["run_id"], queue=previous["queue"])
            if previous["run_id"] and previous["run_id"] != run_id:
                spawn_background(self._abort_cancelled_run(
                    session_key, previous["run_id"], previous["send_stop"]))
        if run_id:
            # The cancelled message keeps what it showed (the caller's forced
            # snapshot). The run's tail belongs to whoever claims it: never
            # back-filled into the stopped message, never written as a turn of
            # its own.
            self.unregister_run_target(session_key, run_id)
            self.mark_delivered_live(session_key, run_id)

        entry = {"run_id": run_id, "queue": queue, "carried": list(carried),
                 "send_stop": send_stop, "task": None,
                 "resolved": asyncio.Event(), "run_text": run_text}

        def _release() -> None:
            if entry["queue"] is not None:
                self.unregister_consumer(session_key, run_id, queue=entry["queue"])
            if entry["carried"]:
                pipe_log(f"  stopped: dropping {len(entry['carried'])} unsent "
                         "message(s)")
            if run_id:
                spawn_background(
                    self._abort_cancelled_run(session_key, run_id, send_stop))

        entry["release"] = _release
        if grace_s <= 0:
            _release()
            return
        self._pending_cancel_aborts[session_key] = entry
        self._arm_parked_timer(session_key, entry, grace_s)

    def _arm_parked_timer(self, session_key: str, entry: dict,
                          wait_s: float) -> None:
        if entry["task"] is not None:
            entry["task"].cancel()

        async def _fire():
            await asyncio.sleep(wait_s)
            if self._pending_cancel_aborts.get(session_key) is not entry:
                return
            if entry.get("claiming"):
                # A follow-up message is already here, waiting for the page's
                # answer: only an explicit Stop may release the run now.
                return
            self._pending_cancel_aborts.pop(session_key, None)
            entry["resolved"].set()
            pipe_log(f"  no new message within {wait_s:g}s of the cancel: "
                     f"stopping run {str(entry['run_id'])[:20]}...")
            entry["release"]()

        entry["task"] = spawn_background(_fire())

    def settle_parked_turn(self, session_key: str, run_id: str | None,
                           intent: str | None, hold_s: float) -> None:
        """Apply what the browser said about the cancel of `run_id`.

        "stop": the user pressed Stop (or Escape), so stop now. "send_now":
        a follow-up message is on its way, so hold the run for it; `hold_s`
        only bounds a browser that dies before sending it. Anything else
        (no hook, no answer) keeps the fallback timer. No-op if the turn was
        already claimed or released.
        """
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None or entry["run_id"] != run_id:
            return
        if intent == "stop":
            self._pending_cancel_aborts.pop(session_key, None)
            if entry["task"] is not None:
                entry["task"].cancel()
            pipe_log(f"  cancel was a Stop: stopping run {str(run_id)[:20]}... now")
            entry["release"]()
        elif intent == "send_now":
            pipe_log(f"  cancel was a Send now: holding run {str(run_id)[:20]}... "
                     f"for the follow-up message (up to {hold_s:g}s)")
            self._arm_parked_timer(session_key, entry, hold_s)
        else:
            pipe_log("  cancel intent unknown (no page hook or no answer): "
                     "keeping the fallback window")
        entry["resolved"].set()

    async def claim_cancelled_turn(self, session_key: str,
                                   wait_s: float = 3.0) -> dict | None:
        """Take over the turn `park_cancelled_turn` parked, if any.

        Waits up to `wait_s` for `settle_parked_turn`, so a Stop whose answer
        is still on its way is honored: OWUI follows a Stop with the next
        queued message, which must start fresh rather than continue the run
        the user just stopped.

        Returns {"run_id", "queue", "carried"}; the caller now owns the run,
        its buffered queue and the carried messages.
        """
        entry = self._pending_cancel_aborts.get(session_key)
        if entry is None:
            return None
        if not entry["resolved"].is_set():
            entry["claiming"] = True
            try:
                await asyncio.wait_for(entry["resolved"].wait(), wait_s)
            except asyncio.TimeoutError:
                pass
        entry = self._pending_cancel_aborts.pop(session_key, None)
        if entry is None:
            return None
        if entry["task"] is not None:
            entry["task"].cancel()
        return {"run_id": entry["run_id"], "queue": entry["queue"],
                "carried": list(entry["carried"]),
                "run_text": entry.get("run_text")}

    def seed_run_renderer(self, session_key: str, run_id: str,
                          queue: asyncio.Queue,
                          run_text: dict | None = None) -> None:
        """Bring a freshly registered shadow renderer level with an adopted
        run: give it the run's dedup baselines (so the closing whole-text
        events are not appended again) and feed it the events still waiting
        in `queue`, which were dispatched before this reply registered its
        own target. Without this a handover to a turn writer would miss the
        buffered text and duplicate the rest."""
        renderer = self._run_renderers.get(f"{session_key}:{run_id}")
        if renderer is None:
            return
        if run_text:
            renderer._assistant_stream_text = run_text.get("received", "")
            renderer._last_item_text = run_text.get("item", "")
        for msg in list(getattr(queue, "_queue", ())):
            try:
                renderer.feed(msg.get("payload", {}))
            except Exception as ex:
                pipe_log(f"  shadow renderer seed failed: {ex}")

    async def send_stop(self, session_key: str):
        """Send the stronger /stop command for runtimes where chat.abort is incomplete."""
        try:
            resp = await _run_request(
                self, RUN_SEND,
                dict(
                    sessionKey=session_key,
                    message="/stop",
                    deliver=False,
                    idempotencyKey=f"stop-{uuid.uuid4()}",
                ),
                timeout=10,
            )
            pipe_log(f"  sent /stop fallback: {resp}")
        except asyncio.TimeoutError:
            pipe_log("  /stop fallback timed out")
        except Exception as e:
            pipe_log(f"  /stop fallback failed: {e}")

    async def retire(self):
        """Step down in favor of a newer deploy's connection.

        Runs that already have a consumer here keep being served until they
        unregister (cutting them would lose the reply); everything else stops
        now. Once the last consumer leaves, the connection closes itself and
        `ensure_connected` refuses to bring it back.
        """
        self._retired = True
        _retire_turn_writer(self.writer_id)
        for writer in list(self._turn_writers.values()):
            writer.release()
        for pump in list(self._turn_pumps.values()):
            pump.queue.put_nowait(("retired", None))
        if self._consumers:
            pipe_log(
                f"  retired gateway connection: serving {len(self._consumers)} "
                "in-flight run(s) before closing"
            )
            return
        await self.disconnect()

    async def disconnect(self):
        """Gracefully close the connection."""
        self._stopped = True
        if self._event_loop_task:
            self._event_loop_task.cancel()
            try:
                await self._event_loop_task
            except asyncio.CancelledError:
                pass
            self._event_loop_task = None
        if self._ws:
            try:
                await self._ws.close()
            except Exception:
                pass
            self._ws = None

    # ── Internal ────────────────────────────────────────────────────

    def _mark_event_gap(self) -> None:
        """Put a gap marker into every run queue, in stream order.

        The Gateway has no event replay (sequence numbers are per connection),
        so whatever it sent while this socket was down is gone. The marker
        sits exactly between the last event before the drop and the first one
        after, which is where the run's text has a hole; the consumer turns
        it into an offset and `_align_whole_text` puts the text back once the
        run's whole text is known.
        """
        n = 0
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _GAP_MARKER_TYPE})
                n += 1
        if n:
            pipe_log(f"  marked an event gap in {n} run queue(s)")
        self._wake_session_waiters()

    def _mark_gateway_restart(self) -> None:
        """Tell every live reply that its run's Gateway process is gone."""
        for consumer in list(self._consumers.values()):
            for q in consumer.queues:
                q.put_control({"type": _RESTART_MARKER_TYPE})

    def _note_gateway_boot(self, boot_id: str | None) -> None:
        """Count a Gateway restart only when its boot id changes."""
        first = self.connection_epoch <= 1
        if boot_id is None:
            # TEMPORARY fallback for a Gateway that sends no bootId (older
            # than 2026.9.x): a reconnect may be a restart, so count it as
            # one, which is the behaviour before boot ids existed.
            if not first:
                self.gateway_restarts += 1
                pipe_log("  reconnected; Gateway sent no bootId, treating it as a restart")
                self._mark_gateway_restart()
            return
        if self.gateway_boot_id is not None and boot_id != self.gateway_boot_id:
            self.gateway_restarts += 1
            pipe_log(f"  Gateway restarted (bootId {self.gateway_boot_id[:8]} -> {boot_id[:8]})")
            self._mark_gateway_restart()
        elif not first:
            pipe_log(f"  reconnected to the same Gateway (bootId {boot_id[:8]}); runs continue")
        self.gateway_boot_id = boot_id

    async def _connect_and_start(self):
        """Connect, handshake, and start the event loop task."""
        valves = self._valves()
        host, port = _parse_gateway_url(valves.GATEWAY_URL)
        token = valves.GATEWAY_TOKEN

        if not token:
            raise GatewayError(
                "The GATEWAY_TOKEN valve is empty. Set it in Open WebUI under "
                "Admin Panel > Functions > OpenClaw Gateway > valves. The value "
                "is `gateway.auth.token` in your OpenClaw config."
            )

        # Device identity
        self._ensure_identity(valves)

        # Connect
        pipe_log(f"Connecting to ws://{host}:{port}")
        # Bounded, and every failure converted to GatewayError. The conversion
        # is the load-bearing part: pipe() only has an `except GatewayError`
        # around this, so anything else escapes the generator and OWUI renders
        # it as an unattributed error naming no valve.
        #
        # websockets already defaults to open_timeout=10 and that covers the TCP
        # connect, so this wait_for is a belt-and-braces bound rather than the
        # only one -- keep _GATEWAY_CONNECT_TIMEOUT_S and that default in step
        # if you tune either.
        try:
            ws = await asyncio.wait_for(
                websockets.connect(f"ws://{host}:{port}", ping_interval=None,
                                   max_size=GATEWAY_WS_MAX_SIZE),
                timeout=_GATEWAY_CONNECT_TIMEOUT_S,
            )
        except asyncio.TimeoutError:
            raise GatewayError(
                f"No response from the OpenClaw Gateway at {host}:{port} within "
                f"{_GATEWAY_CONNECT_TIMEOUT_S:.0f}s. Check the GATEWAY_URL valve, "
                "and that the Open WebUI backend can reach that host (Open WebUI "
                "resolves it, not your browser)."
            )
        except (OSError, ValueError, websockets.exceptions.WebSocketException) as ex:
            # WebSocketException is NOT an OSError subclass, so catching OSError
            # alone still let InvalidStatus/InvalidHandshake escape -- which is
            # exactly what happens when something answers but isn't a Gateway
            # (a reverse proxy returning 502 on the upgrade, an HTTP server on
            # the port). That is a configuration mistake, and it belongs in the
            # chat naming the valve, not as an unattributed traceback.
            raise GatewayError(
                f"Could not connect to the OpenClaw Gateway at {host}:{port} "
                f"({type(ex).__name__}: {ex}). Is the Gateway running, and is "
                "the GATEWAY_URL valve pointing at it?"
            )

        # Handshake: receive challenge
        challenge = json.loads(await asyncio.wait_for(ws.recv(), 10))
        if challenge.get("event") != "connect.challenge":
            raise GatewayError("Bad handshake -- expected connect.challenge")

        c = challenge["payload"]
        signed = _sign_challenge(self._ident, c["nonce"], c["ts"], token_str=token,
                                 scopes=self.scopes)

        auth = dict(token=token)
        if self._device_token:
            auth["deviceToken"] = self._device_token

        await ws.send(json.dumps(dict(
            type="req", id="1", method="connect", params=dict(
                minProtocol=4, maxProtocol=4,
                client=dict(id="webchat", version="1",
                            platform="linux", mode="cli"),
                role="operator",
                scopes=self.scopes,
                auth=auth,
                device=signed,
                locale="en-US",
                userAgent="openclaw-owui-pipe/1.0",
                caps=["tool-events"]
            )
        )))

        resp = json.loads(await asyncio.wait_for(ws.recv(), 10))
        if not resp.get("ok"):
            raise GatewayError(
                _explain_connect_rejection(
                    str(resp.get("error", {}).get("message", "connect failed")),
                    device_id=(self._ident or {}).get("id"),
                )
            )

        # Capture device token for future reconnects
        hello_ok = resp.get("payload", {})
        if hello_ok.get("auth", {}).get("deviceToken"):
            self._device_token = hello_ok["auth"]["deviceToken"]
            self._save_device_token(valves)
            pipe_log(f"Device token captured: {self._device_token[:20]}...")

        self._ws = ws
        self._frame_seq = None  # frame seq counts per socket
        tick_ms = (hello_ok.get("policy") or {}).get("tickIntervalMs")
        if isinstance(tick_ms, (int, float)) and tick_ms > 0:
            self._tick_interval_s = tick_ms / 1000
        self._reconnect_attempt = 0
        self.connection_epoch += 1
        self._thinking_note_shown.clear()
        self._note_gateway_boot((hello_ok.get("server") or {}).get("bootId"))
        pipe_log(
            f"Connected to Gateway (persistent) [epoch {self.connection_epoch}]"
        )
        # Subscriptions belong to the socket. Their requests resolve on the
        # event loop, which is not reading yet here, so it renews them. A
        # requests-only connection has none: the main connection renders.
        self._subscriptions_stale = not self.requests_only
        # NOTE: does not start/spawn the event-loop task -- that happens
        # exactly once, in `ensure_connected`. This method is also called
        # from inside `_reconnect`, which runs from within the event-loop
        # task itself; spawning another task here would duplicate it.

    def _identity_path(self, valves):
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"{self._identity_name}.json")

    def _device_token_path(self, valves):
        suffix = self._identity_name[len("identity"):]
        return os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), f"device-token{suffix}.json")

    def _load_device_token(self, valves):
        if self._device_token:
            return
        data = _read_json_file(self._device_token_path(valves))
        if isinstance(data, dict) and data.get("deviceToken"):
            self._device_token = data["deviceToken"]
            pipe_log("Using persisted device token")

    def _save_device_token(self, valves):
        if not self._device_token:
            return
        _write_json_file(
            self._device_token_path(valves),
            {"deviceToken": self._device_token, "deviceId": self._ident.get("id")},
        )

    def _ensure_identity(self, valves):
        """Load or generate device identity from stable storage.

        Order matters for restart safety:
        1. state-dir identity file
        2. DEVICE_IDENTITY valve
        3. generate once and persist
        """
        if self._ident:
            return
        identity_path = self._identity_path(valves)
        ident = _read_json_file(identity_path)
        if ident and ident.get("id") and ident.get("privateKey"):
            self._ident = ident
            pipe_log(f"Using device identity from {identity_path}")
            self._load_device_token(valves)
            return

        # The DEVICE_IDENTITY valve names the main identity only; a restricted
        # connection always has its own.
        if self._identity_name == "identity" and getattr(valves, "DEVICE_IDENTITY", ""):
            ident = _parse_device_identity(valves.DEVICE_IDENTITY)
            if ident and ident.get("id") and ident.get("privateKey"):
                self._ident = ident
                _write_json_file(identity_path, ident)
                pipe_log("Using device identity from valve and persisted it to state dir")
                self._load_device_token(valves)
                return
            pipe_log("Failed to parse DEVICE_IDENTITY valve; generating new identity")

        self._ident = _generate_device_identity()
        _write_json_file(identity_path, self._ident)
        pipe_log(f"Generated new device identity and saved it to {identity_path}")
        if self._identity_name != "identity":
            return
        print(
            f"DEVICE_IDENTITY={json.dumps(self._ident, separators=(',',':'))}",
            flush=True
        )

    async def _event_loop(self):
        """Background task: reads WS messages and dispatches them.

        This is the ONLY task that ever calls `self._ws.recv()`. Reconnects
        happen in place (`self._ws = None`, then `_reconnect()` blocks until
        a new socket is ready) rather than by spawning a second event-loop
        task -- spawning a second task here previously caused a runaway
        reconnect storm: the old coroutine kept looping after `_reconnect()`
        returned, so two tasks raced on `self._ws.recv()`, each collision
        raised its own exception, and each of *those* spawned yet another
        task (2026-07-10 incident, see PLAN.md P36).
        """
        while not self._stopped:
            try:
                if self._ws is None:
                    await self._reconnect()
                    continue
                if self._subscriptions_stale:
                    self._subscriptions_stale = False
                    spawn_background(self._subscribe_all())
                msg = json.loads(await asyncio.wait_for(self._ws.recv(),
                                                        timeout=2 * self._tick_interval_s))

                # ── Dropped frames ──
                # Event frames carry a per-socket `seq`; the Gateway advances it
                # without sending when this client is slow and the event is
                # dropIfSlow (server-start-BB-IxTAg.mjs:3205-3207), and says so
                # nowhere else. A dropped frame may be a run's text (repaired
                # like a reconnect gap) or a settle push (open writers re-read
                # their session rows).
                _seq = msg.get("seq")
                if msg.get("type") == "event" and isinstance(_seq, int):
                    if self._frame_seq is not None and _seq != self._frame_seq + 1:
                        pipe_log(f"  frame seq gap: expected {self._frame_seq + 1}, got {_seq}")
                        self._mark_event_gap()
                        spawn_background(_turn_resync(self))
                    self._frame_seq = _seq

                # ── Request-response matching ──
                if msg.get("type") == "res":
                    req_id = msg.get("id")
                    fut = self._pending_reqs.get(req_id)
                    if fut and not fut.done():
                        if msg.get("ok") is False:
                            err = msg.get("error", {})
                            fut.set_exception(
                                GatewayError(
                                    err.get("message")
                                    or err.get("code")
                                    or "request failed"
                                )
                            )
                        else:
                            fut.set_result(msg.get("payload", {}))
                    continue

                # ── Tick keepalive (silently consume) ──
                if msg.get("event") == "tick" or msg.get("payload", {}).get("isHeartbeat"):
                    _note_heartbeat_run(self, msg.get("payload") or {})
                    continue

                # ── Event dispatch ──
                # On tool events (re-measured 2026-10-12, gateway 2026.9.x;
                # the 2026-07-30 ELI-26 measurement predates `session.tool`):
                #
                #   * The connection that STARTS a run gets its tool activity
                #     as `agent` events with payload.stream == "tool".
                #   * Any connection subscribed to the session with
                #     `sessions.messages.subscribe` gets the same payloads as
                #     `session.tool` events, whoever started the run (measured:
                #     observer got 3 start + 3 result, zero `agent` tool
                #     events). That covers this connection after a reconnect,
                #     and runs the Gateway starts itself (ELI-92).
                #
                # Both are folded into one path below, first copy wins.
                if msg.get("type") == "event" and msg.get("event") == "sessions.changed":
                    self._on_sessions_changed(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "shutdown":
                    self._on_shutdown(msg.get("payload") or {})
                    continue
                if msg.get("type") == "event" and msg.get("event") == "session.tool":
                    # Same payload as an `agent` tool event (stream "tool",
                    # data.phase/name/toolCallId/args/result), so it takes the
                    # same path: inline turn, shadow renderer, turn writer.
                    p = msg.get("payload") or {}
                    msg = {"type": "event", "event": "agent", "payload": {
                        k: p[k] for k in ("runId", "sessionKey", "sessionId", "stream",
                                          "data", "seq", "ts") if k in p}}
                if msg.get("type") != "event" or \
                   msg.get("event") not in ("agent", "chat"):
                    continue

                payload = msg.get("payload", {})
                if payload.get("stream") == "tool" and not self._first_tool_event(payload):
                    continue

                # ── Shadow render ──
                # Feed every event of a run we're tracking into its shadow
                # `_TurnRenderer`, whether or not a live consumer is still
                # attached: the inline turn can end at any point, and the turn
                # writer it hands over to starts from this content.
                _evt_sess = payload.get("sessionKey", "")
                _evt_run = payload.get("runId", "")
                if _evt_sess and _evt_run:
                    _renderer = self._run_renderers.get(f"{_evt_sess}:{_evt_run}")
                    if _renderer is not None:
                        try:
                            _renderer.feed(payload)
                        except Exception as ex:
                            pipe_log(f"  shadow renderer feed failed: {ex}")

                consumers = self.consumers_for_event(payload)

                # ── ELI-100: a run no live request consumes is a turn ──
                if not consumers and await _turn_route_event(self, payload):
                    continue

                if consumers:
                    self._event_count += 1
                    if not payload.get("runId"):
                        pipe_log("  dispatched session-only event to sole consumer")
                    if payload.get("state") == "final" and payload.get("sessionKey") and payload.get("runId"):
                        # Genuinely shown to a live tab, which persists it via
                        # OWUI's own client-side flow -- remember this so a
                        # later duplicate/retried final event for the same
                        # run_id never reopens its message (P33).
                        self.mark_delivered_live(payload["sessionKey"], payload["runId"])
                        # The inline turn is alive and took the final itself, so
                        # the parity shadow isn't needed for this run -- drop it.
                        self.unregister_run_target(payload["sessionKey"], payload["runId"])
                    for q in consumers[0].queues:
                        await q.put(msg)
                    continue

                if payload.get("sessionKey") and not payload.get("runId"):
                    pipe_log("  dropped ambiguous or unmatched session-only event")

                # If nothing matches at all, drop it.
                # This efficiently filters cross-session bleed (P16).

            except asyncio.TimeoutError:
                # Not even a tick for two intervals: the socket is dead without
                # having closed (half-open), so every run on it would wait
                # forever (review 2af1 R13). Tear it down and reconnect.
                pipe_log(f"  tick timeout: no frame for {2 * self._tick_interval_s:.0f}s, "
                         "reconnecting")
                transport = getattr(self._ws, "transport", None)
                if transport is not None:
                    transport.abort()
                self._ws = None
                self._mark_event_gap()
            except websockets.exceptions.ConnectionClosed as e:
                pipe_log(
                    "WS disconnected -- reconnecting... "
                    f"(code {getattr(e, 'code', None)}, reason {getattr(e, 'reason', '')!r})"
                )
                self._ws = None
                self._mark_event_gap()
            except asyncio.CancelledError:
                break
            except Exception as e:
                pipe_log(f"Event loop error: {e!r}")
                self._ws = None
                try:
                    self._mark_event_gap()
                except Exception as ex:  # the loop outlives any one failure
                    pipe_log(f"  event gap marking failed: {ex!r}")

    async def _reconnect(self):
        """Reconnect with exponential backoff.

        Blocks (looping in place, in the single `_event_loop` task) until a
        new connection is established or the connection is stopped. Must
        NEVER spawn a new `_event_loop` task -- see the docstring on
        `_event_loop` for why that caused a runaway task/connection storm.
        """
        while not self._stopped:
            self._reconnect_attempt += 1
            delay = min(2 ** (self._reconnect_attempt - 1), self._max_backoff)
            pipe_log(f"  reconnect in {delay}s (attempt {self._reconnect_attempt})")
            await asyncio.sleep(delay)
            if self._stopped:
                return
            try:
                await self._connect_and_start()
                return
            except Exception as e:
                pipe_log(f"  reconnect failed: {e}")
                self._ws = None
                # loop and try again


# Protocol sentinels (docs/tools/subagents.md:470-431) that mean "no
# user-visible content was produced" -- never real assistant text to show a
# human. An announce-follow-up run can legitimately finish with exactly one
# of these as its only "assistant text", and writing it into a chat leaks
# internal plumbing (P33, 2026-07-11: `ANNOUNCE_SKIP` landed as literal
# message text).
_SILENT_SENTINELS = {"ANNOUNCE_SKIP", "NO_REPLY", "no_reply"}


# How far back a reply looks for its run's own closing message when the
# stream lost text: later runs may already have ended after it.
RUN_TEXT_HISTORY_LIMIT = 60
# Messages to read when rebuilding a whole run from `chat.history`: each tool
# call is a message of its own (measured: 119 calls = 154 messages).
RUN_HISTORY_LIMIT = 600


def _history_text_for_run(history: dict, run_id: str) -> tuple[bool, str | None]:
    """The closing assistant text one specific run saved, found by its id.

    The Gateway stamps a run's closing assistant message with
    `idempotencyKey = "cli-assistant:<runId>"` (claude-cli runner), so the
    run's own reply is found by identity, not by position. Returns
    (found, text); text is None when the run ended silent.
    """
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return False, None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for message in reversed(messages):
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        meta = message.get("__openclaw")
        keys = {message.get("idempotencyKey"),
                meta.get("idempotencyKey") if isinstance(meta, dict) else None}
        if not keys & wanted:
            continue
        text = ((_history_item(message) or {}).get("text") or "").strip()
        if not text:
            fallback = message.get("openclawStreamFallback")
            if isinstance(fallback, dict):
                text = str(fallback.get("replacementText") or "").strip()
        return True, (text if text and text not in _SILENT_SENTINELS else None)
    return False, None


def _history_renderer(messages: list) -> "_TurnRenderer":
    """A `_TurnRenderer` fed one run's `chat.history` messages instead of its
    live events, so a run whose events were lost still ends as the same
    `text` + `output` items (ELI-88/90/92).

    claude-cli imports its transcript into the session as it goes: assistant
    messages whose blocks are `text`, `toolcall` {id, name, arguments} and
    `tool_result` {tool_use_id, content, is_error}, in order. The run's closing
    message (`cli-assistant:<runId>`) repeats all of its text, so it only
    counts when nothing in its own run carried text (a plain, tool-free
    reply, or imports that carry tool blocks only). It counts in place: an
    asked question's run closes before its answer run starts, and the
    question was lost when only the last closer was kept (ask-rebuild,
    2026-10-14, chat d0f0c6ff).

    Text after a tool call is joined to the text before it with the separator
    the Gateway's live stream inserts there (`sawToolUseSinceText`), so the
    rebuild equals what streamed (it streams as "\n\n<text>").
    Plain concatenation glued a preamble to the answer ("...one at a time.
    USER-DONE" with no break, restart window 2026-10-13)."""
    r = _TurnRenderer()
    run_text = False          # this run carried text before its closer
    tool_since_text = False   # the Gateway's `sawToolUseSinceText`
    for message in messages:
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
        keys = (str(message.get("idempotencyKey") or ""), str(meta.get("idempotencyKey") or ""))
        if any(k.startswith("cli-assistant:") for k in keys):
            text = ((_history_item(message) or {}).get("text") or "").strip()
            if not run_text and text and text not in _SILENT_SENTINELS:
                lead = _message_boundary_separator(r.text, text)
                tool_since_text = False
                r.feed({"stream": "assistant", "data": {"delta": lead + text}})
            run_text = False
            continue
        content = message.get("content")
        if isinstance(content, str):
            content = [{"type": "text", "text": content}]
        for block in content if isinstance(content, list) else []:
            if not isinstance(block, dict):
                continue
            kind = block.get("type")
            if kind == "text" and block.get("text"):
                lead = _message_boundary_separator(r.text, block["text"]) if tool_since_text else ""
                tool_since_text = False
                run_text = run_text or bool(block["text"].strip())
                r.feed({"stream": "assistant", "data": {"delta": lead + block["text"]}})
            elif kind == "toolcall" and block.get("id"):
                tool_since_text = True
                r.feed({"stream": "tool", "data": {
                    "phase": "start", "name": block.get("name", ""),
                    "toolCallId": block["id"], "args": block.get("arguments") or {}}})
            elif kind == "tool_result" and block.get("tool_use_id"):
                result = block.get("content")
                if isinstance(result, list):
                    result = "".join(str(b.get("text") or "") for b in result if isinstance(b, dict))
                r.feed({"stream": "tool", "data": {
                    "phase": "result", "name": block.get("name", ""),
                    "toolCallId": block["tool_use_id"], "result": result or "",
                    "isError": block.get("is_error") is True}})
    return r


def _message_boundary_separator(previous: str, nxt: str) -> str:
    """The newlines the Gateway inserts between two assistant messages of a
    claude-cli run (`missingMessageBoundarySeparator`,
    cli-live-session-registry-CS2DCATp.mjs:375 on 2026.9.3): enough for a
    blank line, counting the newlines both sides already have."""
    if not previous:
        return ""
    trailing = len(previous[-2:]) - len(previous[-2:].rstrip("\n"))
    leading = len(nxt[:2]) - len(nxt[:2].lstrip("\n"))
    return "\n" * max(0, 2 - trailing - leading)


def _is_closing_message(message) -> bool:
    """A run's closing assistant message (`cli-assistant:<runId>`)."""
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return False
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    return any(str(k or "").startswith("cli-assistant:")
               for k in (message.get("idempotencyKey"), meta.get("idempotencyKey")))


def _history_run_messages(history: dict, run_id: str) -> list | None:
    """One run's messages in `chat.history`: everything after the user
    message that started it, or after the previous run's closing message
    (a run with no user turn, e.g. a sub-agent announce), through its own
    closing message (`cli-assistant:<runId>`). None when the run has not
    closed yet."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list) or not run_id:
        return None
    wanted = {run_id, f"cli-assistant:{run_id}"}
    for end in range(len(messages) - 1, -1, -1):
        message = messages[end]
        if not isinstance(message, dict) or message.get("role") != "assistant":
            continue
        meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
        if not {message.get("idempotencyKey"), meta.get("idempotencyKey")} & wanted:
            continue
        start = end
        while start > 0 and (messages[start - 1] or {}).get("role") != "user" \
                and not _is_closing_message(messages[start - 1]):
            start -= 1
        return messages[start:end + 1]
    return None


def _deepest_leaf_id(messages: dict, start_id: str | None) -> str | None:
    """Walk down `childrenIds` from `start_id` to the deepest childless node.

    OWUI's `history.currentId` is only a *view* pointer: the frontend (or an
    interleaved live turn) can reset it back to an ancestor that already has
    children -- e.g. right after an agent turn was appended. Anchoring a
    new message directly on `currentId` in that state appends it as
    a *sibling* of the existing child, which OWUI renders as a 1/2·2/2 variant
    group instead of a linear message (observed 2026-07-13: a `Sub-agent
    finished` message and the next agent message both parented to the same
    node). Walking to the true leaf (following the most-recently-appended
    child at each branch) makes every turn writer chain off the real tail.
    Cycle-guarded and depth-capped for safety against malformed history.
    """
    node_id = start_id
    seen: set[str] = set()
    for _ in range(10_000):
        if not node_id or node_id in seen:
            break
        seen.add(node_id)
        node = messages.get(node_id) or {}
        children = node.get("childrenIds") or []
        if not children:
            break
        node_id = children[-1]
    return node_id


def _relay_output_events(sent: list[dict], current: list[dict]) -> list[dict]:
    """Responses stream events that take a tab's `message.output` from
    `sent` to `current`, in the shapes OWUI's `applyResponseStreamEvent`
    (structuredOutput.ts) folds: a new item is `output_item.added` with an
    explicit `output_index` (without one it is spliced in BEFORE the last
    item), grown message text is an `output_text.delta` on the item's id
    (which also extends `message.content`), and any other change to an
    existing item is `output_item.done`, which replaces it."""
    events: list[dict] = []
    for i, item in enumerate(current):
        old = sent[i] if i < len(sent) else None
        is_message = item.get("type") == "message"
        text = (item.get("content") or [{}])[0].get("text", "") if is_message else ""
        if old is None:
            added = copy.deepcopy(item)
            if is_message:
                added["content"] = [{"type": "output_text", "text": ""}]
            events.append({"type": "response.output_item.added",
                           "output_index": i, "item": added})
            if text:
                events.append({"type": "response.output_text.delta", "item_id": item["id"],
                               "output_index": i, "content_index": 0, "delta": text})
            continue
        if is_message and old.get("id") == item.get("id"):
            old_text = (old.get("content") or [{}])[0].get("text", "")
            if text != old_text and text.startswith(old_text):
                events.append({"type": "response.output_text.delta", "item_id": item["id"],
                               "output_index": i, "content_index": 0,
                               "delta": text[len(old_text):]})
                continue
        if item != old:
            events.append({"type": "response.output_item.done",
                           "output_index": i, "item": copy.deepcopy(item)})
    return events


def _relay_content_is_showable(text: str) -> bool:
    """True once the accumulated visible content is safe to surface as a real
    bubble: non-empty, not a silent sentinel, and not still a prefix that could
    grow into a sentinel-only run. Delaying introduce until this holds means a
    sentinel-only wake (`NO_REPLY`/`ANNOUNCE_SKIP`) never flashes an empty
    bubble -- the same suppression the post-hoc path gets from
    `_last_assistant_text_from_preview`, applied to a stream we watch grow.
    """
    t = text.strip()
    if not t or t in _SILENT_SENTINELS:
        return False
    if any(s.startswith(t) for s in _SILENT_SENTINELS):
        return False
    return True


async def _relay_emit_event(user_id: str, chat_id: str, message_id: str | None,
                            data: dict) -> bool:
    """Fire one OWUI socket `events` envelope to the user room (same transport
    as `_emit_live_bootstrap_reload`). Returns False on any failure so callers
    can log context; a failed emit never raises into the event loop."""
    if not message_id:
        return False
    try:
        from open_webui.socket.main import sio
    except Exception as ex:
        pipe_log(f"  socket emit unavailable (not inside OWUI process?): {ex}")
        return False
    try:
        await sio.emit(
            "events",
            {"chat_id": chat_id, "message_id": message_id, "data": data},
            room=f"user:{user_id}",
        )
        return True
    except Exception as ex:
        pipe_log(f"  socket emit failed: {ex}")
        return False


# ── Orphaned reply stubs (ELI-90) ──
# Open WebUI writes a reply's assistant message (`done: False`) before the
# pipe sends anything, and only the request that streams the reply ever sets
# `done: True`. When Open WebUI restarts mid-turn (three OOM kills on
# 2026-10-12 16:21-16:25 UTC), that request is gone: the run finishes in the
# Gateway, but the chat keeps an empty bubble that looks like it is still
# running, forever. On the first load after the restart these stubs are
# matched to their runs in the Gateway transcript and finished from it.

ORPHAN_STUB_NOTE = (
    "*This reply was cut off before it finished (Open WebUI restarted or "
    "lost the run), and no reply for it could be recovered from OpenClaw. "
    "Send the message again if you still need an answer.*"
)
ORPHAN_STUB_SILENT_NOTE = "*The run for this message stopped without leaving a reply in the transcript.*"


def _history_user_run_id(message) -> str | None:
    """The run a transcript user message started: the Gateway keys the user
    message a `chat.send` adds as `<runId>:user` (the run id is the send's
    idempotencyKey). None for any other message, including the copy the
    runtime imports next to it."""
    if not isinstance(message, dict) or message.get("role") != "user":
        return None
    meta = message.get("__openclaw") if isinstance(message.get("__openclaw"), dict) else {}
    key = str(message.get("idempotencyKey") or meta.get("idempotencyKey") or "")
    return key[:-len(":user")] if key.endswith(":user") and len(key) > 5 else None


def _run_id_sent_at(run_id: str) -> float | None:
    """The send time the pipe writes at the end of its run ids
    (`msg-<chat>-[<message>-]<time.time()>`)."""
    try:
        return float(run_id.rsplit("-", 1)[1]) if run_id.startswith("msg-") else None
    except (IndexError, ValueError):
        return None


def _stub_turn(history: dict, stub_id: str, user_text: str,
               stub_ts: float | None = None) -> dict | None:
    """The transcript turn an OWUI reply stub was waiting for:
    {"run_id", "messages", "closed", "by"}, or None when the transcript has
    none.

    The pipe puts the OWUI message id into the run id (`msg-<chat>-<message>-
    <time>`), so the turn is found by identity (`by` "id"). A run sent
    before that is found by its user text (`by` "text"): with `stub_ts` (the
    stub's creation time) the first matching run sent at or after it, since
    the pipe sends after Open WebUI creates the stub and the same short text
    ("works?") recurs; without it the newest match. `messages` runs to the
    run's closing message (`cli-assistant:<runId>`) or the next turn;
    `closed` says whether the run is over by the transcript alone."""
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    starts = [i for i, m in enumerate(messages) if _history_user_run_id(m)]
    pick, by = None, "id"
    if stub_id:
        by_id = [i for i in starts if f"-{stub_id}-" in _history_user_run_id(messages[i])]
        pick = by_id[-1] if by_id else None
    text = (user_text or "").strip()
    if pick is None and text:
        by, by_text = "text", [i for i in starts if _recovery_user_text_matches(
            ((_history_item(messages[i]) or {}).get("text") or "").strip(), text)]
        if stub_ts is not None:
            # 2s of slack: Open WebUI stamps whole seconds.
            by_text = [i for i in by_text
                       if (_run_id_sent_at(_history_user_run_id(messages[i])) or 0) >= stub_ts - 2]
            pick = by_text[0] if by_text else None
        else:
            pick = by_text[-1] if by_text else None
    if pick is None:
        return None
    run_id = _history_user_run_id(messages[pick])
    end = next((i for i in starts if i > pick), len(messages))
    turn = messages[pick + 1:end]
    closing = f"cli-assistant:{run_id}"
    for j, m in enumerate(turn):
        meta = m.get("__openclaw") if isinstance(m, dict) and isinstance(m.get("__openclaw"), dict) else {}
        if isinstance(m, dict) and closing in (m.get("idempotencyKey"), meta.get("idempotencyKey")):
            return {"run_id": run_id, "messages": turn[:j + 1], "closed": True, "by": by}
    return {"run_id": run_id, "messages": turn, "closed": end < len(messages), "by": by}


def _owui_message_ts(message: dict) -> float | None:
    ts = message.get("timestamp")
    if isinstance(ts, (int, float)) and ts > 0:
        return ts / 1000 if ts > 1e11 else float(ts)  # ms or s
    return None


async def _owui_chat_has_live_task(chat_id: str) -> bool:
    """True while Open WebUI runs a task for `chat_id` (a reply being
    generated by this process). Answers True when it cannot tell, so a
    reply that is still streaming is never overwritten."""
    try:
        from open_webui.main import app
        from open_webui.tasks import list_task_ids_by_item_id
        return bool(await list_task_ids_by_item_id(getattr(app.state, "redis", None), chat_id))
    except Exception as ex:
        pipe_log(f"  orphan stub: cannot read Open WebUI tasks ({ex}); leaving chat {chat_id[:8]}... alone")
        return True


async def _session_list_active(conn: "_GatewayConnection", session_key: str) -> bool | None:
    """`sessions.list` `hasActiveRun` for one session (counts a sub-agent
    yield gap as active, unlike `sessions.describe`). False when the Gateway
    lists no such session, None when it can't be asked."""
    try:
        lst = await conn.send_request("sessions.list", {}, timeout=15)
    except Exception as ex:
        pipe_log(f"  sessions.list for {session_key[-36:][:8]}... failed: {ex}")
        return None
    row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
    return bool(row and row.get("hasActiveRun"))


# A long session's whole transcript (952 messages for 0abe9bde) takes the
# Gateway well over the default 10s RPC bound to serialize.
ORPHAN_HISTORY_TIMEOUT_S = 60


async def _reconcile_stub(conn: "_GatewayConnection", agent_id: str,
                          chat_id: str, stub_id: str, *, wait: bool = True) -> str:
    """Finish one orphaned reply stub from its run in the transcript. A run
    still going is waited for on the pushed settle (`sessions.changed`), not
    on a timer, or with `wait=False` reported as "wait"; a stub a live turn
    writer takes over meanwhile is the writer's (DESIGN 2.6). Returns
    "done", "wait" or "skip"."""
    from open_webui.models.chats import Chats
    waiting = False
    while True:
        chat = await Chats.get_chat_by_id(chat_id)
        msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
        stub = msgs.get(stub_id) or {}
        if stub.get("role") != "assistant" or stub.get("done") is not False:
            return "skip"  # gone or finished meanwhile
        writer = (stub.get("meta") or {}).get("openclaw_writer")
        if writer:
            # A turn writer's message: its own writer finishes it, or, once
            # that writer is gone (a retired deploy, a dead process), this
            # connection adopts it. Another request's task in the chat is no
            # reason to leave it.
            if _turn_writer_alive(writer):
                return "skip"
            return await _adopt_turn_message(
                conn, chat_id=chat_id, user_id=chat.user_id, message_id=stub_id,
                session_key=_owui_session_key(agent_id, chat.user_id, chat_id),
                meta=stub.get("meta") or {})
        if await _owui_chat_has_live_task(chat_id):
            return "skip"  # a live request owns it
        session_key = _owui_session_key(agent_id, chat.user_id, chat_id)
        changed = conn.session_change_event(session_key)
        try:
            hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT,
                                              timeout=ORPHAN_HISTORY_TIMEOUT_S)
        except Exception as ex:
            pipe_log(f"  orphan stub {stub_id[:8]}...: chat.history failed: {ex!r}")
            return "skip"
        parent = msgs.get(stub.get("parentId")) or {}
        user_text = _coerce_text(parent.get("content")) if parent.get("role") == "user" else ""
        turn = _stub_turn(hist, stub_id, user_text, _owui_message_ts(stub))
        if turn is None or turn["closed"]:
            break  # no run to wait for, or it is over
        active = await _session_list_active(conn, session_key)
        if active is None:
            return "skip"
        if not active:
            break
        if not wait:
            return "wait"
        if not waiting:
            waiting = True
            pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: "
                     "its run is still going; finishing it when the run settles")
        await changed.wait()

    run_id = (turn or {}).get("run_id")
    # What the stub already shows is never replaced on a guess: a stub with
    # content (older pipes streamed into it, a writer persisted into it) is
    # rebuilt only from a run matched by identity, else just closed.
    has_content = bool(_coerce_text(stub.get("content")).strip() or stub.get("output"))
    fields: dict = {"done": True}
    output: list | None = None
    text = ""
    if turn and (turn["by"] == "id" or not has_content):
        rendered = _history_renderer(turn["messages"])
        if not rendered.text.strip() and not rendered.output and not has_content:
            rendered._add_text(ORPHAN_STUB_SILENT_NOTE)
        if rendered.output:
            output = rendered.finished_output()
            text = rendered.text.strip()
            fields.update(content=text, output=output)
    elif not has_content:
        rendered = _TurnRenderer()
        rendered._add_text(ORPHAN_STUB_NOTE)
        output, text = rendered.finished_output(), rendered.text
        fields.update(content=text, output=output)
    async with conn._chat_write_lock(chat_id):
        chat = await Chats.get_chat_by_id(chat_id)
        msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
        current = msgs.get(stub_id) or {}
        if current.get("done") is not False:
            return "skip"
        if _turn_writer_alive((current.get("meta") or {}).get("openclaw_writer")):
            return "skip"  # a turn writer took it over (DESIGN 2.6) and finishes it
        claim = f"{session_key}:{run_id}" if run_id else None
        if claim:
            if claim in conn._claimed_runs:
                return "skip"  # another connection finished this run's stub
            conn._claimed_runs[claim] = True
        # Open WebUI answers None, logging nothing, when the write fails (its
        # transaction raised and was rolled back).
        if await Chats.upsert_message_to_chat_by_id_and_message_id(
                chat_id, stub_id, fields) is None:
            if claim:
                conn._claimed_runs.pop(claim, None)
            pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: "
                     "Open WebUI did not save the write (ELI-90)")
            return "skip"
        if run_id:
            conn.mark_delivered_live(session_key, run_id)
    if output is not None:
        await _relay_emit_event(chat.user_id, chat_id, stub_id,
                                {"type": "chat:completion", "data": {"output": output}})
    await _relay_emit_event(chat.user_id, chat_id, stub_id,
                            {"type": "chat:active", "data": {"active": False}})
    cards = sum(1 for i in output or [] if i.get("type") == "function_call")
    if output is None:
        how = "closed, content kept"
    elif run_id:
        how = f"filled from run {run_id[:48]} by {turn['by']}"
    else:
        how = "no run in the transcript, note written"
    pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: {how} "
             f"({len(text)} chars, {cards} tool card(s)) (ELI-90)")
    return "done"


async def _orphan_stub_ids(prefixes: list[str]) -> list[tuple[str, str]]:
    """(chat_id, message_id) of every unfinished assistant message a model of
    this pipe wrote. Open WebUI keeps a row per message in `chat_message`
    whose id is `<chat_id>-<message_id>`."""
    from sqlalchemy import or_, select
    from open_webui.internal.db import get_async_db_context
    from open_webui.models.chat_messages import ChatMessage
    async with get_async_db_context() as db:
        rows = (await db.execute(
            select(ChatMessage.chat_id, ChatMessage.id)
            .where(ChatMessage.role == "assistant")
            .where(ChatMessage.done.is_(False))
            .where(or_(*[ChatMessage.model_id.startswith(p) for p in prefixes]))
        )).all()
    out = []
    for chat_id, composite in rows:
        prefix = f"{chat_id}-"
        out.append((chat_id, composite[len(prefix):] if composite.startswith(prefix) else composite))
    return out


_orphan_reconcile_task: "asyncio.Task | None" = None


async def _reconcile_orphan_stubs(valves_getter) -> None:
    try:
        conn = await _get_gateway_connection(valves_getter)
        agent_id = getattr(valves_getter(), "AGENT_ID", "") or "main"
        stubs = await _orphan_stub_ids(
            _composer_model_prefixes(own_id=_composer_own_function_id()))
    except Exception as ex:
        pipe_log(f"  orphan stub reconcile could not start: {ex}")
        return
    if stubs:
        pipe_log(f"  orphan stub reconcile: {len(stubs)} unfinished OpenClaw "
                 "repl(y/ies) in Open WebUI")
    # One at a time: Open WebUI's SQLite rejected most of 45 concurrent chat
    # writes (2026-10-12). Only a stub whose run is still going gets its own
    # task, to wait for that run's settle.
    counts: dict = {}
    for chat_id, stub_id in stubs:
        status = await _reconcile_stub_logged(conn, agent_id, chat_id, stub_id, wait=False)
        counts[status] = counts.get(status, 0) + 1
        if status == "wait":
            spawn_background(_reconcile_stub_logged(conn, agent_id, chat_id, stub_id))
    if stubs:
        pipe_log(f"  orphan stub reconcile: {counts}")
    try:
        await _reconcile_ended_while_down(conn, agent_id)
    except Exception as ex:
        pipe_log(f"  ended-while-down reconcile failed: {ex!r}")


def _history_closed_runs(messages: list) -> list:
    """[(run_id, closing timestamp ms)] of the runs `chat.history` shows as
    closed: a claude-cli run by its `cli-assistant:<runId>` message, an
    embedded run by an assistant message keyed with the run id itself."""
    started = {run for run, _tool in _history_user_turns(messages)}
    out = []
    for m in messages or []:
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        meta = m.get("__openclaw") if isinstance(m.get("__openclaw"), dict) else {}
        for k in (m.get("idempotencyKey"), meta.get("idempotencyKey")):
            k = str(k or "")
            run = k[len("cli-assistant:"):] if k.startswith("cli-assistant:") else (k if k in started else "")
            if run and isinstance(m.get("timestamp"), (int, float)):
                out.append((run, m["timestamp"]))
                break
    return out


def _settled_run_span(history: dict, run_id: str) -> list | None:
    """The messages of a run the session row reports settled (no active run,
    `lastRunId`): its span up to its closer or the next admitted turn, else,
    as the newest turn, everything after its user turn."""
    span = _history_span_messages(history, run_id)
    if span is not None:
        return span
    messages = (history or {}).get("messages")
    for i, m in enumerate(messages if isinstance(messages, list) else []):
        if _history_user_run_id(m) == run_id:
            return messages[i + 1:]
    return None


async def _reconcile_ended_while_down(conn: "_GatewayConnection", agent_id: str) -> None:
    """ELI-94, DESIGN-agent-turns.md case 4. A graceful Open WebUI stop saves
    the reply it cancels `done: true` with what it had; the run goes on and
    closes while Open WebUI is down, so no event reaches this process and
    the ELI-90 pass (done:false only) skips it. Two recorded timestamps say
    which chats missed something: the session row's `updatedAt` (bumped when
    a run ends) newer than the chat's `updated_at`. In those, a run that
    closed in a later second than the chat's last write is rebuilt from the
    transcript into its message (identity rule, rule E for recoveries)."""
    from open_webui.models.chats import Chats
    lst = await conn.send_request("sessions.list", {}, timeout=15)
    prefix = f"agent:{agent_id}:openwebui-"
    fixed = 0
    for row in lst.get("sessions") or []:
        key = row.get("key") or ""
        if not key.startswith(prefix) or row.get("hasActiveRun"):
            continue  # not ours, or a run still going: the handover (2.6) owns it
        after = key[len(prefix):]
        if len(after) != 73 or after[36] != "-":
            continue
        user_id, chat_id = after[:36], after[37:]
        updated = row.get("updatedAt")
        if not isinstance(updated, (int, float)):
            continue
        chat = await Chats.get_chat_by_id(chat_id)
        if chat is None or chat.user_id != user_id:
            continue
        written = int(getattr(chat, "updated_at", 0) or 0)
        if int(updated // 1000) <= written:
            continue
        fixed += await _reconcile_chat_ended_runs(conn, key, chat_id, written,
                                                  session_id=row.get("sessionId"),
                                                  last_run=row.get("lastRunId"), settled_ms=updated)
    if fixed:
        pipe_log(f"  ended-while-down reconcile: completed {fixed} repl(y/ies) (ELI-94)")


async def _reconcile_chat_ended_runs(conn: "_GatewayConnection", session_key: str,
                                     chat_id: str, written: int, *,
                                     session_id: str | None, last_run: str | None = None,
                                     settled_ms: float | None = None) -> int:
    """Rebuild every finished reply in `chat_id` whose run closed after the
    chat was last written (`written`, whole seconds) and that holds less than
    the transcript. A run closed by its transcript closer, or the session
    row's `lastRunId`, settled at the row's `updatedAt` (`settled_ms`; the
    embedded runtime writes no closer). Returns how many were written."""
    from open_webui.models.chats import Chats
    if await _owui_chat_has_live_task(chat_id):
        return 0  # a reply is streaming: its own request finishes it
    hist = await conn.session_history(session_key, limit=RUN_HISTORY_LIMIT,
                                      timeout=ORPHAN_HISTORY_TIMEOUT_S)
    messages = (hist or {}).get("messages") or []
    closed = _history_closed_runs(messages)
    if last_run and settled_ms and last_run not in {r for r, _ms in closed}:
        closed.append((last_run, settled_ms))
    targets: dict = {}
    for run, closed_ms in closed:
        # A wake's closer is keyed by the sessionId and deduplicated (ELI-103).
        if run == session_id or int(closed_ms // 1000) <= written:
            continue
        mid = run_message_id(session_key, chat_id, run, messages)
        if mid:
            targets.setdefault(mid, run)
    fixed = 0
    for mid, run in targets.items():
        runs = [r for r, _tool in _history_user_turns(messages)
                if r != session_id and run_message_id(session_key, chat_id, r, messages) == mid]
        if run not in runs:
            runs.append(run)
        spans = [_settled_run_span(hist, r) if r == last_run else _history_span_messages(hist, r)
                 for r in runs]
        if any(s is None for s in spans):
            continue  # a run written into it has not closed
        rendered = _history_renderer([m for s in spans for m in s])
        output, text = await _transcript_view(
            conn, session_key=session_key, chat_id=chat_id,
            user_id=session_key.rsplit("openwebui-", 1)[-1][:36], message_id=mid,
            runs=runs, messages=messages, rendered=rendered)
        if not output:
            continue
        async with conn._chat_write_lock(chat_id):
            chat = await Chats.get_chat_by_id(chat_id)
            msgs = ((chat.chat or {}).get("history") or {}).get("messages") or {} if chat else {}
            current = msgs.get(mid) or {}
            if current.get("role") != "assistant" or current.get("done") is not True:
                continue  # missing, or still generating: the ELI-90 pass owns done:false
            held_cards = sum(1 for i in current.get("output") or [] if i.get("type") == "function_call")
            cards = sum(1 for i in output if i.get("type") == "function_call")
            held_text = _coerce_text(current.get("content")).strip()
            if cards < held_cards or (cards == held_cards and len(text) <= len(held_text)):
                continue  # holds as much as the transcript: never rewritten
            if await Chats.upsert_message_to_chat_by_id_and_message_id(
                    chat_id, mid, {"content": text, "output": output, "done": True}) is None:
                pipe_log(f"  ended-while-down {mid[:8]}... in chat {chat_id[:8]}...: "
                         "Open WebUI did not save the write (ELI-94)")
                continue
            conn.mark_delivered_live(session_key, run)
        await _relay_emit_event(chat.user_id, chat_id, mid,
                                {"type": "chat:completion", "data": {"output": output}})
        pipe_log(f"  ended-while-down {mid[:8]}... in chat {chat_id[:8]}...: completed from "
                 f"{len(runs)} run(s) ({len(text)} chars, {cards} tool card(s), "
                 f"held {held_cards}) (ELI-94)")
        fixed += 1
    return fixed


async def _reconcile_stub_logged(conn, agent_id, chat_id, stub_id, *, wait=True) -> str:
    try:
        return await _reconcile_stub(conn, agent_id, chat_id, stub_id, wait=wait)
    except Exception as ex:
        pipe_log(f"  orphan stub {stub_id[:8]}... in chat {chat_id[:8]}...: reconcile failed: {ex!r}")
        return "failed"


def _ensure_orphan_reconcile(valves_getter) -> None:
    """Once per load of this Function inside Open WebUI (a restart reloads
    it; so does a deploy, which is harmless: a reply still streaming has a
    live task and is skipped)."""
    global _orphan_reconcile_task
    if _orphan_reconcile_task is not None:
        return
    try:
        import open_webui.models.chat_messages  # noqa: F401  (inside Open WebUI only)
    except Exception:
        return
    _orphan_reconcile_task = spawn_background(_reconcile_orphan_stubs(valves_getter))


# Read-only shim (ELI-100): bridge versions before ELI-100 embedded this in
# the message they wrote for a finished sub-agent task, invisible in rendered
# markdown (an HTML comment) but still present in the raw `content` OWUI
# hands the Action endpoint on click, so old messages keep opening -- the
# one piece of information a toolbar button click doesn't otherwise carry
# (OWUI sends chat_id/message_id/model/content, never a custom taskId).
# `_run_subagent_detail`-style consumers parse it back out with
# `_SUBAGENT_TASK_ID_MARKER_RE` to open straight into that task's drawer
# instead of the general status dialog.
_SUBAGENT_TASK_ID_MARKER_RE = re.compile(r"<!--\s*openclaw:taskId=([^\s>]+?)\s*-->")


# Module-level singleton
_gateway_connection: _GatewayConnection | None = None
_gateway_init_lock = asyncio.Lock()

# Anchor for finding a connection left behind by a *previous* deploy of this
# same function (P33/P36: OWUI's function loader (open_webui/utils/plugin.py)
# execs each redeploy into a brand-new module object with no teardown hook on
# the old one -- a module-level singleton alone resets every deploy and orphans
# the old module's WS/event-loop task forever). Stashing it as an attribute on
# `open_webui.socket.main` -- OWUI's own stable module, never reloaded by our
# function -- lets the next deploy find and `disconnect()` the previous one
# before opening a new connection, so redeploys self-heal without a container
# restart. Falls back to a no-op when not running inside OWUI (e.g. unit tests).
_STALE_CONN_ATTR = "_openclaw_gateway_connection_v1"


def _function_module_prefix(module_name: str) -> str:
    """`function_<id>_<hex>` -> `function_<id>`. OWUI 0.12 names every load of
    a Function this way (utils/plugin.py `load_function_module_by_id`), so the
    prefix tells "an older load of this same Function" apart from the Status
    Action, whose connection must be left alone."""
    head, sep, tail = module_name.rpartition("_")
    if sep and len(tail) == 32 and all(c in "0123456789abcdef" for c in tail):
        return head
    return module_name


def _orphaned_gateway_connections(current) -> list:
    """Live `_GatewayConnection`s created by OLDER loads of this Function.

    The single stashed attribute only ever named the previous deploy's
    connection; one that an in-flight run revived after being reaped dropped
    out of it and lived on. Scanning the heap is the only handle on those.
    """
    import gc
    prefix = _function_module_prefix(__name__)
    if not prefix.startswith("function_"):
        return []
    found = []
    for obj in gc.get_objects():
        cls = type(obj)
        if cls.__name__ != "_GatewayConnection" or obj is current:
            continue
        mod = getattr(cls, "__module__", "") or ""
        if mod == __name__ or _function_module_prefix(mod) != prefix:
            continue
        found.append(obj)
    return found


async def _retire_stale_connection(stale) -> None:
    retire = getattr(stale, "retire", None)
    if retire is not None:
        await asyncio.wait_for(retire(), timeout=5)
        return
    # Built before `retire()` existed: its own ensure_connected would revive
    # it, so pin both entry points shut on the instance before closing it.
    async def _refuse(*_a, **_k):
        raise GatewayError("gateway connection retired by a newer deploy")
    stale._stopped = True
    stale.ensure_connected = _refuse
    stale._connect_and_start = _refuse
    await asyncio.wait_for(stale.disconnect(), timeout=5)


async def _reap_stale_gateway_connection() -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    stale_conns = []
    stale = getattr(_owui_socket_main, _STALE_CONN_ATTR, None)
    if stale is not None and stale is not _gateway_connection:
        stale_conns.append(stale)
    try:
        for obj in _orphaned_gateway_connections(_gateway_connection):
            if not any(obj is s for s in stale_conns):
                stale_conns.append(obj)
    except Exception as ex:
        pipe_log(f"  orphan scan failed (non-fatal): {ex}")
    for conn in stale_conns:
        try:
            await _retire_stale_connection(conn)
            pipe_log(
                "  reaped stale gateway connection from a previous deploy "
                f"({type(conn).__module__})"
            )
        except Exception as ex:
            pipe_log(f"  failed to reap stale gateway connection (non-fatal): {ex}")


def _remember_gateway_connection(conn: _GatewayConnection) -> None:
    try:
        import open_webui.socket.main as _owui_socket_main
    except Exception:
        return
    setattr(_owui_socket_main, _STALE_CONN_ATTR, conn)


async def _get_gateway_connection(valves_getter) -> _GatewayConnection:
    """Get or create the singleton Gateway connection."""
    global _gateway_connection
    if _gateway_connection is not None:
        await _gateway_connection.ensure_connected()
        return _gateway_connection
    async with _gateway_init_lock:
        if _gateway_connection is not None:
            await _gateway_connection.ensure_connected()
            return _gateway_connection
        await _reap_stale_gateway_connection()
        conn = _GatewayConnection(valves_getter)
        await conn.ensure_connected()
        _gateway_connection = conn
        _remember_gateway_connection(conn)
        return conn


# ---------------------------------------------------------------------------
# Owner users (OWNER_USERS valve)
# ---------------------------------------------------------------------------
# The main connection holds operator.admin, so every turn it sends is the
# owner's and gets owner-only tools. For a chat whose user is not in
# OWNER_USERS, every request that starts, steers or ends a run goes over a
# second connection with RESTRICTED_SCOPES and its own device identity. Reading
# and rendering stay on the main connection: they do not make a turn the
# owner's, and the main connection remains the only one that writes into Open
# WebUI (ELI-100).

_restricted_connection: "_GatewayConnection | None" = None
_restricted_init_lock = asyncio.Lock()


async def _get_restricted_connection(valves_getter) -> "_GatewayConnection":
    """The connection for non-owner users' run requests: read + write scopes,
    identity `identity-restricted.json`, requests only."""
    global _restricted_connection
    async with _restricted_init_lock:
        if _restricted_connection is None:
            conn = _GatewayConnection(valves_getter, writes_turns=False, scopes=RESTRICTED_SCOPES,
                                      identity_name="identity-restricted", requests_only=True)
            await conn.ensure_connected()
            _restricted_connection = conn
            return conn
    await _restricted_connection.ensure_connected()
    return _restricted_connection


async def _owui_call(fn, *args):
    out = fn(*args)
    return await out if asyncio.iscoroutine(out) else out


async def _owner_users_setting(conn) -> "str | None":
    """OWNER_USERS as configured, or None when it cannot be read. The Pipe's
    connection carries the Pipe's valves; the Status Action's own connection
    does not, so the setting is read from the Pipe function's saved valves."""
    valves_getter = getattr(conn, "_valves", None)
    raw = getattr(valves_getter() if callable(valves_getter) else None, "OWNER_USERS", None)
    if isinstance(raw, str):
        return raw
    try:
        from open_webui.models.functions import Functions
    except ImportError:
        return ""  # not inside Open WebUI: there is no valve to set
    try:
        found = ""
        for fn in await _owui_call(Functions.get_functions_by_type, "pipe") or []:
            saved = await _owui_call(Functions.get_function_valves_by_id, fn.id) or {}
            if isinstance(saved, dict) and saved.get("OWNER_USERS"):
                found = ",".join(x for x in (found, saved["OWNER_USERS"]) if x)
        return found
    except Exception as ex:
        pipe_log(f"  owner users: could not read the Pipe's valves ({ex!r}); treating as not owner")
        return None


async def _user_email(user_id: str) -> "str | None":
    try:
        from open_webui.models.users import Users
        user = await _owui_call(Users.get_user_by_id, user_id)
        return getattr(user, "email", None) if user else None
    except Exception:
        return None


async def _sender_is_owner(conn, session_key: str) -> bool:
    """Whether a run request for `session_key` may go out as the owner's. An
    empty OWNER_USERS keeps the old behaviour (everyone is). Otherwise the
    chat's user (from the session key, with that user's email) must be on the
    list; anything that cannot be decided is not the owner's."""
    raw = await _owner_users_setting(conn)
    if raw is None:
        return False
    owners = _parse_owner_users(raw)
    if not owners:
        return True
    m = _OWUI_KEY_USER.match(session_key or "")
    if not m:
        return False
    user_id = m.group(1)
    if user_id.lower() in owners:
        return True
    return _is_owner_user(owners, user_id, await _user_email(user_id))


async def _run_request(conn, method: str, params: dict, *, timeout: float = 10,
                       owner: "bool | None" = None, wait: bool = True):
    """Send a request that starts, steers or ends a run (`RUN_SEND`,
    `RUN_ABORT`, `RUN_PATCH`) on the connection the chat's owner status calls
    for: `conn` for an owner, the restricted connection otherwise. `owner`
    overrides the decision from the session key (a title run, whose session
    is not the chat's). `wait=False` sends without waiting for the answer."""
    if owner is None:
        owner = await _sender_is_owner(conn, params.get("sessionKey") or params.get("key") or "")
    target = conn if owner else await _get_restricted_connection(conn._valves)
    if not owner and method == RUN_SEND:
        dropped = [f for f in ADMIN_ONLY_SEND_FIELDS if f in params]
        if dropped:
            params = {k: v for k, v in params.items() if k not in dropped}
            pipe_log(f"  non-owner chat.send: left out admin-only fields {dropped}")
    if not wait:
        await target._ws.send(json.dumps(dict(type="req", id="abort" if method == RUN_ABORT
                                              else f"run-{uuid.uuid4().hex[:8]}",
                                              method=method, params=params)))
        return None
    return await target.send_request(method, params, timeout=timeout)


# --- writer ----------------------------------------------------------------

# ---------------------------------------------------------------------------
# The turn writer (ELI-100, DESIGN-agent-turns.md 2.3-2.5)
# ---------------------------------------------------------------------------
# One writer per run this connection renders outside a live `pipe()` request:
# agent turns (cron wake, sessions_send, sub-agent announce, restart recovery)
# and user turns whose request ended before the run. It owns exactly one
# message, the one turn identity names, and registers itself with Open
# WebUI's task registry so the page treats the chat as generating and its
# Stop button reaches it.


async def _set_turn_meta(chat_id: str, message_id: str, meta: dict) -> bool:
    """Merge `meta` into message `message_id` under the chat's row lock."""
    from open_webui.models.chats import Chats
    from sqlalchemy.orm.attributes import flag_modified

    async with Chats._chat_transaction(chat_id) as (db, chat):
        data = chat.chat or {}
        history = data.get("history") or {}
        msg = (history.get("messages") or {}).get(message_id)
        if msg is None:
            return False
        msg["meta"] = {**(msg.get("meta") or {}), **meta}
        chat.chat = {**data, "history": history}
        flag_modified(chat, "chat")
        return True


async def _introduce_turn_message(chat_id: str, user_id: str, messages: dict, current_id: str) -> None:
    """Show a newly claimed message in every open tab of the chat without a
    reload: the shared `chat:messages` event to room `chat:<id>`, which the
    page merges and moves its view to (Open WebUI emits the same for its own
    turns; measured live as M1)."""
    from open_webui.socket.main import sio

    await sio.emit("events", {
        "chat_id": chat_id, "message_id": current_id, "user_id": user_id, "shared": True,
        "data": {"type": "chat:messages", "data": {"messages": messages, "currentId": current_id}},
    }, room=f"chat:{chat_id}")


def _owui_redis():
    """Open WebUI's redis client, or None in a single-process install
    (`create_task` handles both)."""
    app = getattr(sys.modules.get("open_webui.main"), "app", None)
    return getattr(getattr(app, "state", None), "redis", None)


TURN_CUT_OFF_NOTE = ("_(This reply was cut off: the run was interrupted again after "
                     f"{MAX_TURN_RESUMES} attempts to continue it.)_")


def _run_prompt_text(span: list | None) -> str:
    """The needs-input prompt a run's text ends with, as the renderer shows
    it (`_prompt_tail`); "" when there is none."""
    return _prompt_tail(_last_item_text(_history_renderer(span))) if span else ""


def _last_item_text(renderer: "_TurnRenderer") -> str:
    """The text of the run's last message item, the only one a closing
    question can be in; fences never span items (review 2af1 F4). "" when
    the run ended on a tool call."""
    last = renderer.output[-1] if renderer.output else None
    if last is None or last.get("type") != "message":
        return ""
    return ((last.get("content") or [{}])[0].get("text")) or ""


def _prompt_tail(text: str, start: int = 0) -> str:
    """`text` from its last needs-input trigger line at or after `start` on,
    the prompt the inline reply would ask; "" when there is none. A trigger
    line in a code fence is a quote (ELI-107). Always "" in the Status
    Action's build."""
    find = globals().get("_marker_line_index")
    fenced = globals().get("_fence_open_after")
    if not (text and find and fenced):
        return ""
    last = None
    while True:
        at = find(text[start:], fenced(text[:start]))
        if at is None:
            break
        last = start + at
        start = text.find("\n", last) + 1
        if not start:
            break
    return text[last:] if last is not None else ""


RESUME_DIRECTIVE_PREFIX = "[system] Your previous "


# A request longer than this is quoted as its head and tail (review 2af1 F2).
RESUME_REQUEST_MAX = 6000
RESUME_REQUEST_HEAD = 2000
# OpenClaw's inbound metadata blocks a stored user turn can start with
# ("Conversation info (untrusted metadata):" and a fenced JSON body).
_INBOUND_META_RE = re.compile(
    r"\A\s*[A-Z][^\n]{0,80}\(untrusted metadata\):[ \t]*\n```[^\n]*\n.*?\n```[ \t]*(?:\n+|\Z)", re.S)


def _strip_inbound_meta(text: str) -> str:
    """`text` without the metadata blocks in front of it (review 2af1 F5)."""
    while True:
        m = _INBOUND_META_RE.match(text or "")
        if not m:
            return text
        text = text[m.end():]


def _quote_block(text: str) -> str:
    """`text` between two delimiter lines that occur in it as no line: a run
    of dashes longer than any dash-only line of its own (review 2af1 F2b)."""
    dashes = [len(x.strip()) for x in text.split("\n") if x.strip() and set(x.strip()) == {"-"}]
    delim = "-" * max([3] + [n + 1 for n in dashes])
    return f"{delim}\n{text}\n{delim}"


def _clip_middle(text: str, limit: int = RESUME_REQUEST_MAX, head: int = RESUME_REQUEST_HEAD) -> str:
    """`text` within `limit` characters: its head and tail, the question a
    long request usually ends with included, and a line for what is left
    out (review 2af1 F2)."""
    if len(text) <= limit:
        return text
    tail = limit - head
    return f"{text[:head]}\n[... {len(text) - limit} characters omitted ...]\n{text[-tail:]}"


def _resume_directive(shown: str | None, request: str | None = None,
                      attachments: int = 0) -> str:
    """The message a resume sends: continue from what the user already sees.

    A resume follows an outside kill (the owner rule), which also kills any
    tool call still running. Its result then reads like the command failing
    (`Exit code 137`), and a resume that does not say why stopped there and
    asked the user what to do (M3 window, 2026-10-13: 4 of 4).

    `request`: the user's message the run was answering. The killed run's
    claude-cli session is not continued: the resume runs in a new one that
    holds only this message (M3 window run 2, 2026-10-14: "I don't have the
    rest of your sequence"), so the request travels in it. `attachments`:
    how many images or files it carried, which do not travel (F3)."""
    cause = (
        "The Gateway restarted or your process was killed from outside while you "
        "were working. A tool call that was still running was killed by that, so "
        "its result (such as exit code 137 or 143) says nothing about the command "
        "itself: rerun it if the request still needs it.")
    request = (request or "").strip()
    if request:
        cause += (" The request you were answering, which this session may no longer "
                  f"hold, was:\n\n{_quote_block(_clip_middle(request))}\n")
    if attachments:
        cause += (f" The request also carried {attachments} attachment"
                  f"{'s' if attachments > 1 else ''} (an image or a file) that this session "
                  "cannot see; if the request needs it, ask the user to send it again.")
    shown = (shown or "").strip()
    if shown:
        return (
            f"[system] Your previous reply was cut off partway through. {cause} The "
            "user can already see the following partial text, and it cannot be edited "
            f"or retracted:\n\n{_quote_block(shown[-1500:])}\n\n"
            "Continue that reply seamlessly from exactly where it stops and finish the "
            "request. Do not repeat any of it, do not restart the answer, and do not "
            "mention the interruption.")
    return (
        f"[system] Your previous run was cut off before you produced any output. {cause} "
        "Answer the most recent message now and finish the request. Do not mention "
        "the interruption.")


def _is_sentinel_message_item(item: dict) -> bool:
    if item.get("type") != "message":
        return False
    text = "".join(c.get("text", "") for c in item.get("content") or [])
    return text.strip() in _SILENT_SENTINELS


def _turn_note_item(note: str) -> dict:
    return {"type": "message", "id": f"msg_note_{uuid.uuid4().hex[:12]}", "status": "completed",
            "role": "assistant", "content": [{"type": "output_text", "text": note}]}


def _output_item_boundary(sent: list, current: list) -> bool:
    """True when `current` has a new item, or an item other than a growing
    message text changed (a tool result, a finished card)."""
    if len(current) != len(sent):
        return True
    for i, (old, new) in enumerate(zip(sent, current)):
        if old == new:
            continue
        growing_text = (i == len(current) - 1 and new.get("type") == "message"
                        and old.get("id") == new.get("id"))
        if not growing_text:
            return True
    return False


# Open WebUI cancels a response identically for Stop and for Send now (both
# call stopTasksByChatId; the message queue exists only in the browser), so
# the backend can never tell them apart. The page can: this hook, installed
# once per page through an `execute` event, records per chat which one the
# user pressed. Labels are OWUI's English strings (they are localized, so a
# non-English UI falls back to the timer); Escape is OWUI's Stop shortcut,
# and Enter in the composer while a response runs is an interrupt when the
# message queue is off (with it on, a later Stop or Send now click
# overwrites it).
_INTENT_HOOK_JS = r"""
if (!window.__ocIntentHook) {
  window.__ocIntentHook = true;
  window.__ocIntents = {};
  const chat = () => (location.pathname.match(/\/c\/([^/?#]+)/) || [])[1] || null;
  const mark = (kind) => { const c = chat(); if (c) window.__ocIntents[c] = { kind, t: Date.now() }; };
  // The Stop button's aria-label is translated; its icon is not (R15).
  const STOP_ICON = 'M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75';
  const isStop = (b) => b.getAttribute('aria-label') === 'Stop' || b.id === 'stop-response-button'
    || [...b.querySelectorAll('svg path')].some((p) => (p.getAttribute('d') || '').startsWith(STOP_ICON));
  const running = () => [...document.querySelectorAll('button')].some(isStop);
  document.addEventListener('click', (e) => {
    const b = e.target && e.target.closest ? e.target.closest('button') : null;
    if (!b) return;
    // Send now needs no mark: an unknown intent already keeps writing.
    if (b.getAttribute('aria-label') === 'Send now') mark('send_now');
    else if (isStop(b)) mark('stop');
  }, true);
  document.addEventListener('keydown', (e) => {
    if (!running()) return;
    if (e.key === 'Escape') { mark('stop'); return; }
    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && e.target && e.target.closest
        && e.target.closest('#chat-input')) mark('send_now');
  }, true);
}
return true;
"""


def _intent_query_js(chat_id: str) -> str:
    """Read and clear what the page recorded for `chat_id` (see
    `_INTENT_HOOK_JS`). "none" means the hook is there but saw no click, so
    the cancel came from elsewhere; null means no hook at all."""
    return (
        "const c = " + json.dumps(chat_id) + ";"
        "const all = window.__ocIntents;"
        "if (!all) return null;"
        "const i = all[c]; delete all[c];"
        "return (i && Date.now() - i.t < 60000) ? i.kind : 'none';"
    )


# The page's answer to an intent query is an RPC reply; this bounds a tab that
# never answers (it is not a wait for anything to happen).
_INTENT_QUERY_TIMEOUT_S = 3.0


def _intent_answer(resp) -> str | None:
    if isinstance(resp, str):
        return resp.strip() or None
    if isinstance(resp, dict) and "error" not in resp:
        for key in ("value", "result", "text"):
            if isinstance(resp.get(key), str):
                return resp[key].strip() or None
    return None


async def _page_cancel_intent(user_id: str, chat_id: str, message_id: str) -> str | None:
    """Which button cancelled the writer's task: "stop", "send_now", or None
    (no tab of this user shows the chat, no hook, or no click recorded). Asks
    every tab showing the chat (OWUI's SESSION_POOL[sid]["chat_ids"]); a
    Stop anywhere wins."""
    try:
        from open_webui.socket import main as socket_main
    except Exception:
        return None
    pool = getattr(socket_main, "SESSION_POOL", None) or {}
    sids = [sid for sid, sess in list(pool.items())
            if isinstance(sess, dict) and sess.get("id") == user_id
            and chat_id in (sess.get("chat_ids") or [])]
    answers = set()
    for sid in sids:
        try:
            resp = await socket_main.sio.call("events", {
                "chat_id": chat_id, "message_id": message_id,
                "data": {"type": "execute", "data": {"code": _intent_query_js(chat_id)}},
            }, to=sid, timeout=_INTENT_QUERY_TIMEOUT_S)
        except Exception as ex:
            pipe_log(f"  turn writer: intent query to {sid[:8]}... failed: {ex!r}")
            continue
        answers.add(_intent_answer(resp))
    for kind in ("stop", "send_now"):
        if kind in answers:
            return kind
    return None


class _TurnWriter:
    """Writes run `run_id` into message `message_id` of chat `chat_id`."""

    def __init__(self, conn: "_GatewayConnection", *, session_key: str, chat_id: str,
                 user_id: str, run_id: str, message_id: str | None,
                 takeover: bool = False, renderer: "_TurnRenderer | None" = None,
                 thinking: str | None = None, wake: dict | None = None):
        self.conn = conn
        self.session_key, self.chat_id, self.user_id = session_key, chat_id, user_id
        self.run_id, self.message_id = run_id, message_id
        # A pipe run's message already exists (Open WebUI's stub): the writer
        # takes it over instead of inserting one (DESIGN 2.6).
        self.takeover = takeover
        self.renderer = renderer if renderer is not None else _TurnRenderer()
        # A user turn's level (ELI-85): its resume continues the same reply.
        self.thinking = thinking
        # A cron wake (ELI-103): {key, at, job} of its turn, and `end` once its
        # terminal arrived. Its transcript span is a time window, not a run id.
        self.wake = wake
        self.opened = False
        self.task_id: str | None = None
        self.parent_id: str | None = None
        # every run written into M, in transcript order (_adopt_recoveries_from)
        self.runs = [run_id]
        # Where each run's streamed part starts in the renderer, in adoption
        # order: (run, output index, text length). See `_from_transcript`.
        self.run_marks: list = [(run_id, 0, 0)]
        self.resumes = 0                # resume budget, counted on M (MAX_TURN_RESUMES)
        self.pending_resume = False     # a resume the Gateway refused; sent on the next hello-ok
        self.request: str | None = None  # the user's message M answers, quoted by a resume
        self.request_attachments = 0    # its images or files, which a resume cannot carry
        self.awaiting_row = False       # kept open for a Gateway recovery (R2)
        self.closed = False             # nothing more to write (ended, or M is someone else's)
        self.sent_output: list = []     # the `output` open tabs hold
        self._media_failed: set = set()  # MEDIA directives that did not resolve
        self._emit = None
        self._done = asyncio.Event()
        # Two pumps feed one writer when a recovery continues M; only one may
        # claim it.
        self._open_lock = asyncio.Lock()

    async def open(self, takeover: bool = False) -> bool:
        """Claim the message, introduce it to open tabs and register the
        writer's task. False when there is nothing to open (a run that renders
        nothing) or another live writer holds the message."""
        async with self._open_lock:
            return await self._open(takeover)

    async def _open(self, takeover: bool) -> bool:
        if self.opened:
            return True
        if not self.message_id:
            return False
        _register_turn_writer(self.conn.writer_id)
        claim = await _claim_turn_message(self.chat_id, self.user_id, self.message_id,
                                          self.run_id, self.conn.writer_id, takeover=takeover)
        if not claim["claimed"]:
            pipe_log(f"  turn writer: message {self.message_id[:8]}... is held by another writer")
            return False
        self.parent_id = claim["parent"]
        if claim["how"] == "new":
            await _introduce_turn_message(self.chat_id, self.user_id, claim["messages"],
                                          self.message_id)
        from open_webui.tasks import create_task

        self.task_id, _ = await create_task(_owui_redis(), self._hold(), id=self.chat_id)
        meta = {"task_id": self.task_id}
        if self.wake is not None:
            # What a successor needs to adopt this message (ELI-103 step 4).
            meta["openclaw_wake"] = {k: self.wake.get(k) for k in ("key", "at", "job")}
        await _set_turn_meta(self.chat_id, self.message_id, meta)
        self.opened = True
        try:
            # Case 8: lets a cancel of this task ask the page whether it was
            # Stop or Send now. Idempotent in the page.
            await (await self._emitter())({"type": "execute", "data": {"code": _INTENT_HOOK_JS}})
        except Exception as ex:
            pipe_log(f"  turn writer: intent hook install failed: {ex!r}")
        pipe_log(f"  turn writer: opened {self.message_id[:8]}... ({claim['how']}) for run "
                 f"{self.run_id[:24]}... in chat {self.chat_id[:8]}...")
        return True

    def _showable(self) -> bool:
        """Condition B: a tool call start, or text that is not a silent
        sentinel or a prefix of one. Whichever comes first."""
        if any(i.get("type") == "function_call" for i in self.renderer.output):
            return True
        return _relay_content_is_showable(self.renderer.visible_text or "")

    async def feed(self, payload: dict | None) -> None:
        """One event of the run: grow the renderer, open the message on the
        first showable item, then stream what changed. None streams what the
        renderer already holds (a handover's shadow renderer)."""
        if self.closed:
            return
        try:
            if payload is not None:
                self.renderer.feed(payload)
        except Exception as ex:
            pipe_log(f"  turn writer: renderer feed failed: {ex}")
        if not self.opened:
            if not self._showable():
                return
            if not await self.open(takeover=self.takeover):
                self.closed = True
                return
        await self._stream()

    async def _emitter(self):
        if self._emit is None:
            from open_webui.socket.main import get_event_emitter

            # update_db=False: the writer owns this message's DB writes.
            self._emit = await get_event_emitter(
                {"chat_id": self.chat_id, "message_id": self.message_id,
                 "user_id": self.user_id}, update_db=False)
        return self._emit

    async def _stream(self) -> None:
        """Emit the output change as Responses events (Open WebUI forwards a
        throttled shared copy to the chat room), keep the response stream
        current for a tab that opens the chat mid-turn, and write the DB on
        item boundaries (a new item, a tool result), not per text delta."""
        output, text = await self._view(final=False)
        emit = await self._emitter()
        for ev in _relay_output_events(self.sent_output, output):
            await emit({"type": "response:completion", "data": ev})
        boundary = _output_item_boundary(self.sent_output, output)
        self.sent_output = copy.deepcopy(output)
        from open_webui.tasks import save_response_stream

        await save_response_stream(_owui_redis(), self.task_id, self.chat_id, self.message_id,
                                   text, self.sent_output)
        if boundary:
            await self._persist(done=False, output=output, text=text)

    def _rewrite(self, text: str) -> str:
        for raw, shown in self.conn.turn_rewrites(self.chat_id, self.message_id or ""):
            if raw in text:
                text = text.replace(raw, shown)
        # A prompt nobody answered here shows as the inline reply's fallback
        # does: without its internal directive line (the writer side of
        # ELI-58), a quote in a code fence kept (ELI-107). Absent in the
        # Status Action's build.
        strip = globals().get("_strip_needs_input_lines")
        return strip(text) if strip else text

    def _note_transcript_answers(self, messages: list) -> None:
        """An answered ask-user prompt is a card, rebuilt from the transcript
        when the inline reply's own rewrite is gone (an Open WebUI restart,
        a known gap of PR #20): the prompt ends the text of the run before
        the answer run, and the answer is the answer run's own user turn. A
        rewrite the reply recorded is kept as it was. Absent in the Status
        Action's build, which writes no turns."""
        block = globals().get("_ask_user_detail_block")
        if block is None or not self.message_id:
            return
        recorded = {raw for raw, _ in self.conn.turn_rewrites(self.chat_id, self.message_id)}
        hist, prev = {"messages": messages}, None
        for run, _tool in _history_user_turns(messages):
            if run_message_id(self.session_key, self.chat_id, run, messages) != self.message_id:
                continue
            parsed = parse_pipe_run_id(run)
            if prev is not None and parsed and parsed["kind"] == "input":
                prompt = _run_prompt_text(_history_span_messages(hist, prev))
                answer = next((((_history_item(m) or {}).get("text") or "").strip() for m in messages
                               if _history_user_run_id(m) == run), "")
                if prompt and answer and prompt not in recorded:
                    self.conn.note_turn_rewrite(self.chat_id, self.message_id, prompt,
                                                block(prompt, answer))
            prev = run

    async def _view(self, *, final: bool) -> tuple[list, str]:
        """(output, text) of M as the inline reply shows a run (review 2af1
        R4): the rewrites it recorded (an image for a `MEDIA:` directive, a
        card for an answered ask-user prompt) applied to the renderer, a
        directive that first came after the handover resolved here, and,
        while the run streams, a directive whose filename is still arriving
        held back, as the inline reply holds it."""
        await self._resolve_media(self._rewrite(self.renderer.text), final)
        output = self.renderer.finished_output() if final else copy.deepcopy(self.renderer.output)
        hold = None if final else globals().get("_advance_media_buffer")

        def show(text: str, tail: bool) -> str:
            text = self._rewrite(text)
            return hold("", text)[0] if hold and tail else text
        for n, item in enumerate(output):
            if item.get("type") == "message" and item.get("content"):
                part = item["content"][0]
                part["text"] = show(part.get("text") or "", n == len(output) - 1)
        return output, show(self.renderer.text, True)

    async def _resolve_media(self, text: str, final: bool) -> None:
        """Upload each complete `MEDIA:` directive the inline reply never saw,
        once, the way it does (`_resolve_media_text`: Open WebUI's files, else
        the file server), and record the result as a rewrite. Absent in the
        Status Action's build, which writes no turns."""
        resolve = globals().get("_resolve_media_text")
        if resolve is None or "MEDIA:" not in text:
            return
        for directive in _media_directives(text, final):
            if directive in self._media_failed:
                continue
            try:
                shown, handled = await resolve(directive, valves=self.conn._valves(),
                                               __event_emitter__=await self._emitter())
            except Exception as ex:
                pipe_log(f"  turn writer: {directive[:60]} did not resolve: {ex!r}")
                shown, handled = directive, False
            if handled and shown != directive:
                self.conn.note_turn_rewrite(self.chat_id, self.message_id, directive, shown)
            else:
                self._media_failed.add(directive)

    async def _persist(self, *, done: bool, output: list | None = None,
                       text: str | None = None) -> None:
        from open_webui.models.chats import Chats

        try:
            await Chats.upsert_message_to_chat_by_id_and_message_id(
                self.chat_id, self.message_id,
                {"content": self.renderer.text if text is None else text,
                 "output": output if output is not None else copy.deepcopy(self.renderer.output),
                 "done": done})
        except Exception as ex:
            pipe_log(f"  turn writer: persist failed: {ex}")

    def adopt(self, run_id: str) -> None:
        """A run that continues M (a pipe resume, or a restart recovery that
        rule E maps here) is written into the same message."""
        if run_id not in self.runs:
            self.runs.append(run_id)
            self.run_marks.append((run_id, len(self.renderer.output), len(self.renderer.text)))
            self.renderer.run_boundary = True
        self.run_id = run_id

    def _adopt_recoveries_from(self, messages: list) -> None:
        """Runs written into M whose events never reached this writer: restart
        recoveries that rule E maps to M (they ran while the socket was down,
        case 4), and pipe runs naming M, such as the question run an ask-user
        answer run continues after an Open WebUI restart left no target
        (review 2af1 R9). M's runs are put in transcript order."""
        order = []
        for run, tool in _history_user_turns(messages):
            if run in self.runs or (
                    (tool == RECOVERY_SOURCE_TOOL or parse_pipe_run_id(run) is not None)
                    and run_message_id(self.session_key, self.chat_id, run, messages) == self.message_id):
                order.append(run)
        self.runs = [*order, *(r for r in self.runs if r not in order)]

    async def end(self, row: dict, stop_notice_before: bool = False) -> None:
        """The current run settled; `row` is its settled session row (DESIGN
        2.5, 2.7). Keep M open for a recovery or a busy session, resume an
        outside kill, or finalize."""
        if self.closed:
            return
        decision = next_continuation(row, stop_notice_before, self.resumes)
        if decision in ("gateway", "wait"):
            # The pump stays (R2): the recovery run takes M over (rule E), or a
            # later row leaves `running`. A recovery the Gateway gives up on
            # tombstones the row to failed (main-session-restart-recovery-
            # CPJjd8da.mjs:1150), which is that row.
            self.awaiting_row = True
            pipe_log(f"  turn writer: {self.message_id and self.message_id[:8]}... stays open "
                     f"({decision}) after run {self.run_id[:24]}...")
            return
        self.awaiting_row = False
        if decision == "resume":
            self.resumes += 1
            self.pending_resume = True
            await self._send_resume()
            return
        note = None
        if turn_owner(row, stop_notice_before) == "pipe":
            note = TURN_CUT_OFF_NOTE
        elif (row or {}).get("status") in ("failed", "timeout") and row.get("lastRunError"):
            note = f"**Error:** {row['lastRunError']}"
        if note is None and await self._ask_question():
            return
        await self.finalize(note)

    async def _ask_question(self) -> bool:
        """A run that ends with a question asks it as the inline reply does:
        Open WebUI's question card on the tab viewing the chat (ELI-107
        decision 1, option 1). One card call, bounded by its own timeout, so
        M waits for no tab. The answer is sent as an `input` run that this
        writer adopts, and the question shows as its Ask User card. False
        when nothing was sent: no question, no tab on the chat, a cancel, a
        timeout, or a refused send; M then ends with the question as text.
        Absent in the Status Action's build, which writes no turns."""
        g = globals()
        names = ("_call_native_card_on_live_session", "_native_ask_user_payload",
                 "_owui_supports_native_ask_user", "_format_native_answers",
                 "_ask_user_detail_block", "_is_user_input_prompt")
        if self.closed or not self.opened or not all(n in g for n in names):
            return False
        # Only a question in the run's last message item (fences are per
        # item), after the last one already answered in M: the text of an
        # answer run follows its question's raw text.
        text = _last_item_text(self.renderer)
        start = 0
        for raw, _ in self.conn.turn_rewrites(self.chat_id, self.message_id):
            at = text.rfind(raw)
            if at >= 0:
                start = max(start, at + len(raw))
        prompt = _prompt_tail(text, start)
        if not prompt or not g["_is_user_input_prompt"](prompt):
            return False
        payload = g["_native_ask_user_payload"](prompt) if g["_owui_supports_native_ask_user"]() else None
        if payload is None:
            return False
        try:
            response = await g["_call_native_card_on_live_session"](
                self.user_id, self.chat_id, self.message_id, payload)
        except Exception as ex:
            pipe_log(f"  turn writer: question card failed: {ex!r}")
            return False
        if response is None:
            pipe_log(f"  turn writer: no tab views chat {self.chat_id[:8]}...; the question stays text")
            return False
        if self.closed or not (isinstance(response, dict) and response.get("status") == "answered"):
            return False
        answer = g["_format_native_answers"](payload["data"]["questions"], response.get("answers") or {})
        if not answer:
            return False
        key = pipe_run_id(self.chat_id, self.message_id, "input")
        try:
            resp = await self.conn.send_request("chat.send", _owui_chat_send_params(
                session_key=self.session_key, message=answer, idempotency_key=key,
                owui_chat_id=self.chat_id, owui_user_id=self.user_id,
                thinking=self.thinking), timeout=30)
        except Exception as ex:
            pipe_log(f"  turn writer: sending the answer failed ({ex}); the question stays text")
            return False
        self.conn.note_turn_rewrite(self.chat_id, self.message_id, prompt,
                                    g["_ask_user_detail_block"](prompt, answer))
        self.adopt(resp.get("runId") or key)
        pipe_log(f"  turn writer: answer sent for {self.message_id[:8]}... as {self.run_id[:32]}...")
        await self._stream()
        return True

    async def on_hello(self) -> None:
        """A new socket: send a resume the closing Gateway refused."""
        if self.pending_resume and not self.closed:
            await self._send_resume()

    async def _run_request(self) -> tuple[str | None, int]:
        """(text, attachments) of the user's message M answers: the user turn
        of the first run written into M, in transcript order, that is not
        itself a resume. Every run naming M counts, so M's own first run (a
        pipe run or an agent turn) is found even when this writer was made
        for a later run of M, a redeploy's or an Open WebUI restart's (review
        2af1 F1). (None, 0) when the transcript cannot be read (the resume
        then goes without it)."""
        try:
            hist = await self.conn.session_history(self.session_key, limit=RUN_HISTORY_LIMIT)
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for the resume failed: {ex!r}")
            return None, 0
        messages = (hist or {}).get("messages") or []
        for m in messages:
            run = _history_user_run_id(m)
            if not run or not (run in self.runs or run_message_id(
                    self.session_key, self.chat_id, run, messages) == self.message_id):
                continue
            # The user's answer to M's question and a resume are no request
            # (review 2af1 N2): only M's reply run or an agent turn is.
            if (parse_pipe_run_id(run) or {}).get("kind") in ("input", "resume"):
                continue
            content = m.get("content")
            blocks = content if isinstance(content, list) else []
            text = content if isinstance(content, str) else "".join(
                str(b.get("text") or "") for b in blocks
                if isinstance(b, dict) and b.get("type") == "text")
            text = _strip_inbound_meta(text)
            # Content blocks, or (how the Gateway stores an Open WebUI image
            # turn) string content with the images in `__openclaw.media` (N1).
            media = (m.get("__openclaw") or {}).get("media")
            attachments = max(sum(1 for b in blocks if isinstance(b, dict) and b.get("type") != "text"),
                              len(media) if isinstance(media, list) else 0)
            if text.lstrip().startswith(RESUME_DIRECTIVE_PREFIX):
                continue
            if text.strip() or attachments:
                return text, attachments
        return None, 0

    async def _send_resume(self) -> None:
        if not self.request and not self.request_attachments:
            self.request, self.request_attachments = await self._run_request()
        directive = _resume_directive(self.renderer.visible_text, self.request,
                                      self.request_attachments)
        key = pipe_run_id(self.chat_id, self.message_id, "resume")
        try:
            resp = await _run_request(self.conn, RUN_SEND, _owui_chat_send_params(
                session_key=self.session_key, message=directive, idempotency_key=key,
                owui_chat_id=self.chat_id, owui_user_id=self.user_id,
                thinking=self.thinking), timeout=30)
        except Exception as ex:
            pipe_log(f"  turn writer: resume refused ({ex}); sending it on the next hello")
            return
        self.pending_resume = False
        self.adopt(resp.get("runId") or key)
        pipe_log(f"  turn writer: resumed {self.message_id[:8]}... as {self.run_id[:32]}... "
                 f"({self.resumes}/{MAX_TURN_RESUMES})")

    async def finalize(self, note: str | None = None) -> None:
        """Write M's last state, `done: true`: from the transcript when every
        run written into M has closed there, else what streamed. A silent
        sentinel is never written; a sentinel-only run that showed tool cards
        keeps them (condition B)."""
        if self.closed:
            return
        self.closed = True
        try:
            try:
                hist = await self.conn.session_history(self.session_key, limit=RUN_HISTORY_LIMIT)
            except Exception as ex:
                hist = None
                pipe_log(f"  turn writer: chat.history failed at the end: {ex!r}")
            if self.wake is not None:
                self._rebuild_wake(hist)
            else:
                if hist:
                    self._adopt_recoveries_from(hist.get("messages") or [])
                if hist:
                    self._note_transcript_answers(hist.get("messages") or [])
                rebuilt = self._from_transcript(hist) if hist else None
                if rebuilt is not None:
                    self.renderer = rebuilt
                if not (self._showable() or note):
                    await self._show_silent_announce(hist)
            if not self.opened:
                if not (self._showable() or note) or not await self.open(takeover=self.takeover):
                    return
            output, text = await self._view(final=True)
            output = [i for i in output if not _is_sentinel_message_item(i)]
            text = text.strip()
            if text in _SILENT_SENTINELS:
                text = ""
            if note:
                text = f"{text}\n\n{note}" if text else note
                output.append(_turn_note_item(note))
            await self._persist(done=True, output=output, text=text)
            emit = await self._emitter()
            await emit({"type": "chat:completion", "data": {"done": True, "content": text,
                                                             "output": output}})
            await emit({"type": "chat:active", "data": {"active": False}})
            tools = sum(1 for i in output if i.get("type") == "function_call")
            pipe_log(f"  turn writer: finalized {self.message_id[:8]}... ({len(text)} chars, "
                     f"{tools} tool card(s), {len(self.runs)} run(s))")
        finally:
            self._done.set()

    async def _show_silent_announce(self, hist: dict | None) -> None:
        """A sub-agent's completion the parent answered with silence (NO_REPLY)
        still shows the child's result, as one card (review 2af1 R10): its
        label from the parent's spawn call, its result from the child's own
        transcript, or what was kept of it before a `cleanup: "delete"` (its
        chat final, or the transcript read as the announce run started).
        Nothing when the child's result cannot be had."""
        child = next(filter(None, (parse_announce_run_id(r) for r in self.runs)), None)
        if child is None:
            return
        result = await _child_result(self.conn, child)
        if not result:
            return
        label = None
        for m in (hist or {}).get("messages") or []:
            blocks = m.get("content") if isinstance(m.get("content"), list) else []
            calls = {b.get("id"): b for b in blocks if isinstance(b, dict) and b.get("type") == "toolcall"}
            for b in blocks:
                if (isinstance(b, dict) and b.get("type") == "tool_result"
                        and child["child_session"] in json.dumps(b.get("content"))
                        and b.get("tool_use_id") in calls):
                    args = calls[b["tool_use_id"]].get("arguments") or {}
                    label = args.get("label") or args.get("task")
        tcid = f"subagent-{child['child_run']}"
        args_str = json.dumps({"label": label or child["child_session"]})
        call = _tool_call_started_event("Sub-agent", tcid, args_str)["item"]
        call["status"] = "completed"
        self.renderer = _TurnRenderer()
        self.renderer.output = [call, _tool_call_result_event(tcid, result)["item"]]

    def release(self) -> None:
        """This writer's connection was retired by a newer deploy: end the Open
        WebUI task now and write nothing more. A task left registered keeps the
        chat "generating" and makes orphan repair skip the chat (live 2026-10-13,
        task 03904655 of retired 62b9927 held efe80f6a). M stays unfinished
        with this writer recorded, which no longer counts as live, so the
        successor adopts it (`_adopt_turn_message`) and finishes it once its
        run is over."""
        if self.closed:
            return
        self.closed = True
        self._done.set()

    def _rebuild_wake(self, hist: dict | None) -> None:
        """Repair lost events from the wake's window of the transcript. A wake
        has no closing message to prove its span complete (only the first wake
        into a session gets one), so the transcript replaces what streamed only
        when it holds at least as much: it never takes content away."""
        if not hist or self.wake.get("at") is None or self.wake.get("end") is None:
            return
        rebuilt = _history_renderer(wake_span(hist.get("messages"), self.wake["at"],
                                              self.wake["end"]))
        # Every card that streamed must be in it: the transcript may lack a
        # wake's tool calls entirely (gate 2026-10-13: no import of the wake's
        # CLI session with a user turn queued behind it), and an item count
        # takes a text item for a card.
        if (self._holds_streamed_calls(rebuilt, "wake's")
                and len(rebuilt.output) >= len(self.renderer.output)
                and len(rebuilt.text) >= len(self.renderer.text) and rebuilt.output):
            self.renderer = rebuilt

    def _from_transcript(self, hist: dict) -> "_TurnRenderer | None":
        """M rebuilt from the transcript wherever the transcript holds it.

        A run counts as covered when its span holds every call it streamed.
        A killed or aborted claude-cli run is never covered: its calls and
        text are never imported (graceful window 2026-10-14; run 64028b9f).
        The transcript is used from the first run k after which every run is
        covered; what streamed before run k's start is kept as it was, and
        the rebuild follows it with the live stream's break. So a resume
        after a killed run keeps the killed run's preamble and card, and a
        recovery the writer joined late still gets its start back (crash
        window 2026-10-14: its first text and card ran before the pipe was
        back). None (keep what streamed) while a run has not closed, or when
        the transcript covers nothing."""
        spans = [_history_span_messages(hist, r) for r in self.runs]
        if any(s is None for s in spans):
            return None
        out, text = self.renderer.output, self.renderer.text
        starts = {run: (o, t) for run, o, t in self.run_marks}
        order = sorted(self.run_marks, key=lambda m: m[1])

        def streamed(run):
            if run not in starts:
                return []
            o = starts[run][0]
            end = min((m[1] for m in order if m[1] > o), default=len(out))
            owner = [m for m in order if m[1] == o][-1][0]   # adopted last at this point
            return out[o:end] if owner == run else []

        def covered(run, span):
            rebuilt = _history_renderer(span)
            calls = {i.get("id") for i in rebuilt.output if i.get("type") == "function_call"}
            seg = streamed(run)
            return ({i.get("id") for i in seg if i.get("type") == "function_call"} <= calls
                    and (bool(rebuilt.output) or not seg))
        k = len(self.runs)
        while k > 0 and covered(self.runs[k - 1], spans[k - 1]):
            k -= 1
        if k == len(self.runs):
            pipe_log(f"  turn writer: the transcript covers none of {self.message_id[:8]}...'s "
                     f"{len(self.runs)} run(s); keeping what streamed")
            return None
        rest = _history_renderer([m for s in spans[k:] for m in s])
        if not rest.output:
            return None
        cut = min((starts[r] for r in self.runs[k:] if r in starts), default=(len(out), len(text)))
        if k == 0 or cut == (0, 0):
            return rest
        prefix_out, prefix_text = copy.deepcopy(out[:cut[0]]), text[:cut[1]]
        rest_out = rest.finished_output()
        sep = _message_boundary_separator(prefix_text, rest.text) \
            if prefix_text.strip() and rest.text else ""
        if sep:
            first = next(i for i in rest_out if i.get("type") == "message")
            first["content"][0]["text"] = sep + first["content"][0]["text"]
        composed = _TurnRenderer()
        composed.output = prefix_out + rest_out
        composed.text = composed.visible_text = prefix_text + sep + rest.text
        pipe_log(f"  turn writer: {self.message_id[:8]}... keeps {len(prefix_out)} streamed item(s) of "
                 f"{k} run(s) the transcript lacks, then {len(self.runs) - k} run(s) from it")
        return composed

    def _holds_streamed_calls(self, rebuilt, whose: str) -> bool:
        """Whether a transcript rebuild holds every tool call that streamed
        into M. A transcript can lack them all: a wake's CLI session not yet
        imported (gate 2026-10-13), or an aborted claude-cli run, whose tool
        calls are never imported (run 64028b9f, 2026-10-14)."""
        streamed = {o.get("id") for o in self.renderer.output if o.get("type") == "function_call"}
        missing = streamed - {o.get("id") for o in rebuilt.output if o.get("type") == "function_call"}
        if missing:
            pipe_log(f"  turn writer: the transcript lacks {len(missing)} of the {whose} "
                     f"{len(streamed)} streamed call(s); keeping what streamed")
        return not missing

    async def _stopped(self) -> None:
        """Open WebUI cancelled the writer's task. Stop and Send now both do
        that (DESIGN case 8), so the page is asked which: Stop aborts the run
        and finalizes what M has; Send now or no answer keeps writing M to the
        run's end, and the queued message runs after it (case 7)."""
        intent = await _page_cancel_intent(self.user_id, self.chat_id, self.message_id)
        pipe_log(f"  turn writer: task of {self.message_id[:8]}... cancelled, page intent "
                 f"{intent or 'unknown'}")
        if intent != "stop" or self.closed:
            return
        try:
            await _run_request(
                self.conn, RUN_ABORT, {"sessionKey": self.session_key, "runId": self.run_id}, timeout=15)
        except Exception as ex:
            pipe_log(f"  turn writer: chat.abort failed: {ex}")
        await self.finalize()

    async def _hold(self) -> None:
        """The Open WebUI task: alive exactly while this writer owns the run.
        Cancelled by the page's Stop (POST /api/tasks/chat/<id>/stop)."""
        try:
            await self._done.wait()
        except asyncio.CancelledError:
            if not self.closed:
                spawn_background(self._stopped())
            raise


# ---------------------------------------------------------------------------
# Routing: which writer gets a run's events (DESIGN 2.1, 2.2)
# ---------------------------------------------------------------------------
# The socket's receive loop also reads RPC replies, so it must never await an
# RPC itself. Each routed run gets a queue and a pump task: the pump resolves
# the run's message (rule E reads the transcript once for a non-pipe run) and
# then feeds the run's events and its settle in order.


def _media_directives(text: str, final: bool) -> list[str]:
    """Each complete `MEDIA:<file>` directive in `text`, as written, by the
    inline reply's grammar (`_take_media_fname`). The last one is complete
    once something follows its filename, or when the run is over."""
    take, looks = globals().get("_take_media_fname"), globals().get("_looks_like_media_filename")
    out, i = [], 0
    while take and looks:
        idx = text.find("MEDIA:", i)
        if idx < 0:
            break
        after = text[idx + len("MEDIA:"):]
        stripped = after.strip()
        fname, rest = take(stripped)
        end = idx + len("MEDIA:") + (len(after) - len(after.lstrip())) + len(stripped) - len(rest)
        if fname and looks(fname) and (final or end < len(text)) and text[idx:end] not in out:
            out.append(text[idx:end])
        i = idx + len("MEDIA:")
    return out


async def _transcript_view(conn: "_GatewayConnection", *, session_key: str, chat_id: str,
                           user_id: str, message_id: str, runs: list, messages: list,
                           rendered: "_TurnRenderer") -> tuple[list, str]:
    """(output, text) of M rebuilt from the transcript as the writer finalizes
    it (`_TurnWriter._view`): an answered ask-user prompt as its card, one
    nobody answered without its directive line, a `MEDIA:` directive as its
    image. `content` is that text, so it always agrees with the items. The
    ELI-94 reconcile wrote the bare rebuild and dropped an answered card
    (ask-rebuild, 2026-10-14, chat d0f0c6ff)."""
    view = _TurnWriter(conn, session_key=session_key, chat_id=chat_id, user_id=user_id,
                       run_id=runs[-1], message_id=message_id, renderer=rendered)
    view.runs = list(runs)
    view._note_transcript_answers(messages)
    output, text = await view._view(final=True)
    output = [i for i in output if not _is_sentinel_message_item(i)]
    text = text.strip()
    return output, "" if text in _SILENT_SENTINELS else text


def _history_span_messages(history: dict, run_id: str) -> list | None:
    """One run's messages in `chat.history`, or None while it may still be
    writing. A closed run ends at its `cli-assistant:<runId>`; a run cut off
    with no closing turn (a crash, an outside kill) ends where the next
    admitted turn (a recovery, a resume) begins."""
    closed = _history_run_messages(history, run_id)
    if closed is not None:
        return closed
    messages = (history or {}).get("messages")
    if not isinstance(messages, list):
        return None
    starts = [i for i, m in enumerate(messages) if _history_user_run_id(m)]
    for n, i in enumerate(starts):
        if _history_user_run_id(messages[i]) == run_id and n + 1 < len(starts):
            return messages[i + 1:starts[n + 1]]
    return None


class _RunPump:
    def __init__(self):
        self.queue: asyncio.Queue = asyncio.Queue()
        self.writer: "_TurnWriter | None" = None
        self.handover: dict | None = None  # {message_id, renderer} of a request that ended early
        self.stop_notice_before = False
        self.wake = False               # a cron wake: runId is the sessionId (ELI-103)
        self.held: list = []            # a wake's events before its turn is known
        self.heartbeat = False          # a wake-id run the Gateway flagged isHeartbeat


async def _turn_route_event(conn: "_GatewayConnection", payload: dict) -> bool:
    return _turn_route_now(conn, payload)


def _turn_route_now(conn: "_GatewayConnection", payload: dict) -> bool:
    """Queue `payload` for its run's writer when the run is a turn this
    connection writes: an OWUI session key and no live request consuming it.
    A run whose request ended before it is handed over (DESIGN 2.6). True
    when handled here. Never awaits: held events drain through it in order
    (`drain_held`)."""
    sess, run = payload.get("sessionKey") or "", payload.get("runId") or ""
    if not (getattr(conn, "writes_turns", False) and sess and run) or conn._retired:
        return False
    conn.note_session_id(sess, payload.get("sessionId"))
    parsed = conn.parse_owui_session_key(sess)
    if not parsed:
        _note_child_result(conn, payload)
        return False
    if conn.consumers_for_event(payload):
        return False
    if run.startswith(ACTION_RUN_PREFIX):
        return True  # the Status Action's own runs render nothing
    if (sess, run) in conn._held_for_live:
        conn.drain_held(sess, run)  # the earlier ones first (review 2af1 N7)
    if conn.live_reply_owns(sess, run):
        conn.hold_for_live(sess, run, payload)
        return True
    _note_heartbeat_run(conn, payload)
    if (sess, run) in conn._turn_skip_runs:
        return True
    if conn.was_delivered_live(sess, run):
        # A request showed this run to the end, or a Stop / Send now closed
        # its message: a late event reopens nothing.
        return True
    if not _turn_kind_known(conn, sess, run, payload):
        return True
    return _turn_queue(conn, sess, run, parsed, payload)


def _turn_queue(conn: "_GatewayConnection", sess: str, run: str, parsed: tuple,
                payload: dict) -> bool:
    pump = conn._turn_pumps.get((sess, run))
    if pump is None:
        pump = conn._turn_pumps[(sess, run)] = _RunPump()
        target = conn._run_targets.get(f"{sess}:{run}")
        if target is not None:
            # DESIGN 2.6: the request streaming this run ended before it. The
            # writer continues in the same message from the shadow renderer,
            # which already holds this event.
            pump.handover = {"message_id": target["message_id"],
                             "renderer": conn._run_renderers.get(f"{sess}:{run}"),
                             "thinking": target.get("thinking")}
            conn.unregister_run_target(sess, run)
        spawn_background(_turn_pump_loop(conn, sess, run, parsed, pump))
        spawn_background(conn.ensure_message_subscription(sess))
        child = parse_announce_run_id(run)
        if child is not None:
            # Read before the Gateway deletes a `cleanup: "delete"` child,
            # which it does once this announcement is delivered.
            spawn_background(_child_result(conn, child))
        if target is not None:
            return True
    if payload.get("state") in ("final", "error", "aborted"):
        pump.stop_notice_before = conn._stop_notice_seen
    pump.queue.put_nowait(("event", payload))
    return True


def _note_child_result(conn: "_GatewayConnection", payload: dict) -> None:
    """Keep the result of a sub-agent an Open WebUI session spawned, from its
    own chat final (`spawnedBy` = the parent, server-chat-CbnqM5f6.mjs
    emitChatTerminal): a `cleanup: "delete"` child is gone by the time its
    announce run ends (subagent-announce-BIG31XbZ.mjs:413), and a silent
    announce shows this result (review 2af1 R10)."""
    if payload.get("state") != "final" or not conn.parse_owui_session_key(payload.get("spawnedBy") or ""):
        return
    text = (_history_item(payload.get("message")) or {}).get("text") or ""
    if text.strip():
        _keep_child_result(conn, payload["sessionKey"], payload["runId"], text.strip())


def _keep_child_result(conn: "_GatewayConnection", child_session: str, child_run: str,
                       text: str) -> None:
    conn._child_results[(child_session, child_run)] = text
    if len(conn._child_results) > 200:
        for stale in list(conn._child_results)[:100]:
            conn._child_results.pop(stale, None)


async def _child_result(conn: "_GatewayConnection", child: dict) -> str | None:
    """The result of the sub-agent run an announce run names: kept from its
    chat final, else read from its transcript (and kept), else None."""
    key = (child["child_session"], child["child_run"])
    if key in conn._child_results:
        return conn._child_results[key]
    try:
        child_hist = await conn.session_history(child["child_session"], limit=20)
    except Exception as ex:
        pipe_log(f"  turn writer: child transcript of {child['child_session'][-12:]} "
                 f"unreadable: {ex!r}")
        return None
    found, result = _history_text_for_run(child_hist, child["child_run"])
    if not (found and result):
        return None
    _keep_child_result(conn, *key, result)
    return result


def _note_heartbeat_run(conn: "_GatewayConnection", payload: dict) -> None:
    """Condition B: a heartbeat run never gets a message. Its agent events
    carry isHeartbeat (server-chat-CbnqM5f6.mjs:791, 823-826); its chat events
    and session.tool copies do not, so the run is remembered, and what it sent
    before its first flagged event is dropped (`_turn_kind_known`)."""
    sess, run = payload.get("sessionKey"), payload.get("runId")
    if payload.get("isHeartbeat") is not True or not (sess and run):
        return
    if run == conn._session_ids.get(sess):
        return  # a wake's id: never skip it for good (handled in _wake_step)
    held = conn._turn_unkinded.pop((sess, run), None)
    if held:
        pipe_log(f"  turn writer: heartbeat run {run[:24]}...: {len(held)} earlier event(s) not shown")
    conn._turn_skip_runs[(sess, run)] = True
    if len(conn._turn_skip_runs) > 500:
        for stale in list(conn._turn_skip_runs)[:250]:
            conn._turn_skip_runs.pop(stale, None)


# Bounds on runs held unclassified: a run is classified by its first agent
# event, so anything past these is a leak, not a wait.
_UNKINDED_RUNS_MAX = 64
_UNKINDED_EVENTS_MAX = 500


def _classifies(payload: dict) -> bool:
    """An event that tells a heartbeat run from any other: an agent event of
    its own (not a session.tool copy, which the receive loop rebuilds without
    the flag, and not a tool event, the stream those copies share), or the
    run's end, which comes after its flagged lifecycle end."""
    stream = payload.get("stream")
    return (bool(stream) and stream != "tool") or _is_terminal_event(payload)


def _turn_kind_known(conn: "_GatewayConnection", sess: str, run: str, payload: dict) -> bool:
    """Review 2af1 R7: an agent run's events may reach the writer only once the
    run is known not to be a heartbeat. Until then they are held in order;
    the run's first classifying event releases them ahead of itself, its
    first flagged one drops them (`_note_heartbeat_run`), and its session's
    settled row releases them too (`_turn_settled`). A pipe run (the pipe
    started it) and a cron wake (`_wake_step` judges it) need no wait."""
    if (sess, run) in conn._turn_kinded or parse_pipe_run_id(run) is not None \
            or run == conn._session_ids.get(sess):
        return True
    if not _classifies(payload):
        held = conn._turn_unkinded.setdefault((sess, run), [])
        if len(held) < _UNKINDED_EVENTS_MAX:
            held.append(payload)
        while len(conn._turn_unkinded) > _UNKINDED_RUNS_MAX:
            stale = next(iter(conn._turn_unkinded))
            pipe_log(f"  turn writer: run {stale[1][:24]}... never classified: released")
            _release_unkinded(conn, *stale)
        return False
    _release_unkinded(conn, sess, run)
    return True


def _release_unkinded(conn: "_GatewayConnection", sess: str, run: str) -> None:
    conn._turn_kinded[(sess, run)] = True
    if len(conn._turn_kinded) > 500:
        for stale in list(conn._turn_kinded)[:250]:
            conn._turn_kinded.pop(stale, None)
    for ev in conn._turn_unkinded.pop((sess, run), []):
        _turn_route_now(conn, ev)


def _turn_settled(conn: "_GatewayConnection", session_key: str, row: dict) -> None:
    """The session went idle: every run pumped on it has ended. Its settled
    row decides each writer's next step (DESIGN 2.5, 2.7). A run still held
    unclassified is no heartbeat (its flagged lifecycle end would have come
    first) and is released ahead of the row."""
    for (sess, run) in [k for k in conn._turn_unkinded if k[0] == session_key]:
        _release_unkinded(conn, sess, run)
    for (sess, _run), pump in list(conn._turn_pumps.items()):
        if sess == session_key:
            pump.queue.put_nowait(("settled", row))


async def _turn_writer_for(conn: "_GatewayConnection", sess: str, run: str,
                           user_id: str, chat_id: str) -> "_TurnWriter | None":
    # Two runs can name one message (a recovery and the run it recovers). The
    # one resolved second must find the first one's writer, not open its own,
    # so resolving and registering is one step per connection.
    async with conn._turn_resolve_lock:
        return await _turn_writer_for_locked(conn, sess, run, user_id, chat_id)


async def _turn_writer_for_locked(conn, sess, run, user_id, chat_id):
    messages = None
    if parse_pipe_run_id(run) is None:
        # Not a pipe run: a restart recovery writes into the message of the run
        # it recovers (rule E), which only the transcript names.
        try:
            messages = (await conn.session_history(sess, limit=50, max_chars=200)).get("messages")
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for rule E failed: {ex!r}")
    mid = run_message_id(sess, chat_id, run, messages)
    if mid is None:
        return None
    writer = conn._turn_writers.get((chat_id, mid))
    if writer is not None and not writer.closed:
        writer.adopt(run)
        return writer
    # A pipe run names Open WebUI's stub for its turn: after an Open WebUI
    # restart no request or target is left, and the writer takes the stub
    # over unless another live writer holds it.
    writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                         run_id=run, message_id=mid,
                         takeover=parse_pipe_run_id(run) is not None)
    conn._turn_writers[(chat_id, mid)] = writer
    return writer


async def _turn_pump_loop(conn: "_GatewayConnection", sess: str, run: str,
                          parsed: tuple, pump: _RunPump) -> None:
    user_id, chat_id = parsed
    try:
        handed = pump.handover
        if pump.writer is not None:
            pass  # adopted from a gone writer's message (_adopt_turn_message)
        elif handed is not None:
            pump.writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                                      run_id=run, message_id=handed["message_id"], takeover=True,
                                      renderer=handed["renderer"], thinking=handed.get("thinking"))
            conn._turn_writers[(chat_id, handed["message_id"])] = pump.writer
            await pump.writer.feed(None)
        elif re.fullmatch(_UUID_RE, run) and run == await conn.session_id_for(sess):
            pump.wake = True
        else:
            pump.writer = await _turn_writer_for(conn, sess, run, user_id, chat_id)
        while True:
            kind, item = await pump.queue.get()
            if kind == "retired":
                return
            if pump.wake:
                if await _wake_step(conn, sess, run, user_id, chat_id, pump, kind, item):
                    return
                continue
            writer = pump.writer
            if kind == "event":
                if writer is not None:
                    await writer.feed(item)
                continue
            # Only the pump of the writer's current run ends it: an interrupted
            # run's pump also gets the session's settle once its recovery has
            # taken M over, and the recovery's own pump may still hold events.
            if writer is not None and writer.run_id == run:
                await writer.end(item, stop_notice_before=pump.stop_notice_before)
                if writer.closed:
                    conn._turn_writers.pop((chat_id, writer.message_id), None)
                elif writer.awaiting_row and writer.run_id == run:
                    continue  # R2: the next row of the session decides again
            return
    except Exception as ex:
        pipe_log(f"  turn writer: pump for run {run[:24]}... failed: {ex!r}")
    finally:
        if conn._turn_pumps.get((sess, run)) is pump:
            conn._turn_pumps.pop((sess, run), None)


def _is_terminal_event(payload: dict) -> bool:
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    return payload.get("state") in ("final", "error", "aborted") or (
        payload.get("stream") == "lifecycle" and data.get("phase") in ("end", "error"))


def _event_ms(payload: dict) -> float:
    """When the Gateway emitted the event: agent events carry `ts`
    (agent-events enrichAgentEvent); a chat event has none, and the receive
    time on this host stands in (the Gateway runs on the same clock)."""
    ts = payload.get("ts")
    return float(ts) if isinstance(ts, (int, float)) else time.time() * 1000


# chat.history returns at most this many messages (CHAT_HISTORY_MAX_ENTRIES,
# chat-history-constants-C-H8nkgi.mjs:3).
CHAT_HISTORY_MAX = 1000


async def _wake_bind(conn: "_GatewayConnection", sess: str, run: str, user_id: str,
                     chat_id: str, pump: _RunPump, at_ms: float) -> tuple[str, float | None]:
    """Give the wake its message: the one its own admitted turn names.
    Returns ("bound", the job run's start), ("wait", None) while a cron job
    of this session runs but its turn is not readable yet (the embedded
    runtime commits it after the first events), or ("stray", None): nothing
    runs a wake into this session, so the event is not a wake's (review
    2af1 N2)."""
    try:
        jobs = (await conn.send_request("cron.list", {"includeDisabled": True}, timeout=15)).get("jobs")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.list for a wake failed: {ex!r}")
        return "wait", None
    starts = [(j.get("state") or {}).get("runningAtMs") for j in jobs or []
              if j.get("sessionTarget") == f"session:{sess}"]
    running_start = min((s for s in starts if isinstance(s, (int, float))), default=None)
    bound = conn._wake_turns_bound.setdefault(sess, set())
    # The turn is committed after its job started: read back until the window
    # holds a message older than that start (review 2af1: a fixed 50-message
    # window lost a wake that had written more before a reconnect).
    limit, turn = 50, None
    while True:
        try:
            messages = (await conn.session_history(sess, limit=limit, max_chars=200)).get("messages") or []
        except Exception as ex:
            pipe_log(f"  turn writer: chat.history for a wake failed: {ex!r}")
            return "wait", None
        turn = wake_turn_at(messages, at_ms, bound)
        oldest = min((m.get("timestamp") for m in messages
                      if isinstance(m.get("timestamp"), (int, float))), default=None)
        if (turn is not None or running_start is None or len(messages) < limit
                or limit >= CHAT_HISTORY_MAX or (oldest is not None and oldest < running_start)):
            break
        limit = min(limit * 4, CHAT_HISTORY_MAX)
    start = await _wake_job_start(conn, turn, at_ms, jobs) if turn is not None else None
    if start is None:
        return ("wait", None) if running_start is not None else ("stray", None)
    bound.add(turn["key"])
    mid = turn_message_id(sess, turn["key"], chat_id)
    pump.writer = _TurnWriter(conn, session_key=sess, chat_id=chat_id, user_id=user_id,
                              run_id=run, message_id=mid, wake=dict(turn))
    conn._turn_writers[(chat_id, mid)] = pump.writer
    pipe_log(f"  turn writer: wake turn {turn['key'][:8]}... (cron job {turn['job'][:8]}...) "
             f"is message {mid[:8]}...")
    return "bound", start


async def _wake_job_start(conn: "_GatewayConnection", turn: dict, at_ms: float,
                          jobs: list | None) -> float | None:
    """When the cron job run that wrote wake turn `turn` started, if the event
    at `at_ms` is that run's; else None. The job must be running since before
    the turn was written (`state.runningAtMs`), or have a finished run whose
    window holds both the turn and the event (`cron.runs`, kept after a
    one-shot job is deleted). Anything else that runs with runId = sessionId
    (a node agent command, a compaction) is not a wake and opens no message
    (live 2026-10-13: runningAtMs 1791863926518 precedes the turn's commit
    1791863928462). An RPC failure answers None: the events wait."""
    job, at = turn.get("job"), turn.get("at") or 0
    running = next(((j.get("state") or {}).get("runningAtMs") for j in jobs or []
                    if j.get("id") == job), None)
    if running and running <= at:
        return running
    run = await _wake_job_run(conn, job, at)
    if run is not None and at_ms <= (run.get("ts") or 0):
        return run.get("runAtMs") or 0
    return None


async def _wake_job_run(conn: "_GatewayConnection", job: str, turn_at: float) -> dict | None:
    """The finished `cron.runs` entry of `job` whose run wrote a turn at
    `turn_at`: started before it, finished after it."""
    try:
        runs = (await conn.send_request("cron.runs", {"id": job, "limit": 20}, timeout=15)).get("entries")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.runs for wake job {str(job)[:8]}... failed: {ex!r}")
        return None
    done = [e for e in runs or [] if e.get("action") == "finished"
            and (e.get("runAtMs") or 0) <= turn_at <= (e.get("ts") or 0)]
    return min(done, key=lambda e: e.get("ts") or 0, default=None)


async def _wake_step(conn: "_GatewayConnection", sess: str, run: str, user_id: str,
                     chat_id: str, pump: _RunPump, kind: str, item) -> bool:
    """One queue item of a cron wake. A session row never ends a wake: the
    row stays idle while it runs, and a row pushed for another run (a message
    queued behind it) says nothing about it. Its own terminal event does.
    True when the wake is over and the pump can go."""
    if kind == "settled":
        return False
    if kind == "event" and (pump.heartbeat or item.get("isHeartbeat") is True):
        # Condition B by the run's resolved identity, not by its id: the skip
        # table is keyed by run id, which a wake shares with every other wake
        # (ELI-103 f). Nothing more of this run is shown; its terminal frees
        # the id for the next wake.
        pump.heartbeat = True
        pump.held.clear()
        if pump.writer is not None and not pump.writer.opened:
            pump.writer.closed = True
        if _is_terminal_event(item):
            await _wake_finish(conn, sess, run, pump, _event_ms(item))
            return True
        return False
    if kind == "wake-ended":
        await _wake_finish(conn, sess, run, pump, item)
        return True
    if pump.writer is None:
        pump.held.append(item)
        state, start = await _wake_bind(conn, sess, run, user_id, chat_id, pump, _event_ms(item))
        if state == "stray":
            # Nothing runs a wake into this session: these events are no
            # wake's, and holding them would hand them to the next wake, which
            # reuses this run id (review 2af1 N2). The next event is judged anew.
            pipe_log(f"  turn writer: {len(pump.held)} sessionId event(s) on {sess[-12:]} with no "
                     "running cron wake: not shown")
            pump.held.clear()
            return True
        if pump.writer is not None:
            held, pump.held = pump.held, []
            for ev in held:
                if _event_ms(ev) >= start:  # older ones predate this wake's run
                    await pump.writer.feed(ev)
    else:
        await pump.writer.feed(item)
    if _is_terminal_event(item):
        await _wake_finish(conn, sess, run, pump, _event_ms(item))
        return True
    return False


async def _wake_finish(conn: "_GatewayConnection", sess: str, run: str, pump: _RunPump,
                       end_ms: float) -> None:
    writer = pump.writer
    if writer is None:
        if not pump.heartbeat:
            pipe_log(f"  turn writer: a sessionId run on {sess[-12:]} ended with no running "
                     f"cron wake turn; {len(pump.held)} event(s) not shown")
    else:
        if not writer.closed:  # a heartbeat that already showed something is finished too
            writer.wake["end"] = end_ms
            await writer.finalize()
        conn._turn_writers.pop((writer.chat_id, writer.message_id), None)
    # The next wake reuses this run id: nothing remembered for it may carry over.
    conn._turn_skip_runs.pop((sess, run), None)
    conn._delivered_live.pop(f"{sess}:{run}", None)


async def _wake_resync(conn: "_GatewayConnection") -> None:
    """After a reconnect: end the wakes whose terminal this socket missed. The
    row cannot say (it is idle during a wake); the cron job can: it carries
    `runningAtMs` while it runs and a one-shot job is deleted once it ran."""
    wakes = [(k, p) for k, p in conn._turn_pumps.items()
             if p.wake and p.writer is not None and p.writer.wake]
    if not wakes:
        return
    try:
        jobs = (await conn.send_request("cron.list", {"includeDisabled": True}, timeout=15)).get("jobs")
    except Exception as ex:
        pipe_log(f"  turn writer: cron.list after hello failed: {ex!r}")
        return
    running = {j.get("id") for j in jobs or [] if (j.get("state") or {}).get("runningAtMs")}
    for (_sess, _run), pump in wakes:
        wake = pump.writer.wake
        if wake["job"] not in running:
            # The wake ended at its job run's finish, not now: a run queued
            # behind it may have written since (review 2af1 N1). Unknown
            # (None): the transcript is not used, the message keeps what it
            # streamed.
            run = await _wake_job_run(conn, wake["job"], wake.get("at") or 0)
            pump.queue.put_nowait(("wake-ended", (run or {}).get("ts")))


async def _adopt_turn_message(conn: "_GatewayConnection", *, chat_id: str, user_id: str,
                              session_key: str, message_id: str, meta: dict) -> str:
    """Take over message `message_id`, which a turn writer of a retired or
    dead connection left unfinished. Its meta names the run (and a wake's
    turn). Later events of the run reach the pump made here; a run already
    over is finished now. Returns "adopted" or "skip"."""
    run = meta.get("openclaw_run")
    if not run or (session_key, run) in conn._turn_pumps or conn._retired:
        return "skip"
    pump = conn._turn_pumps[(session_key, run)] = _RunPump()
    wake = meta.get("openclaw_wake") if isinstance(meta.get("openclaw_wake"), dict) else None
    if wake and wake.get("key"):
        pump.wake = True
        conn._wake_turns_bound.setdefault(session_key, set()).add(wake["key"])
    pump.writer = _TurnWriter(conn, session_key=session_key, chat_id=chat_id, user_id=user_id,
                              run_id=run, message_id=message_id, takeover=True,
                              wake=dict(wake) if pump.wake else None)
    conn._turn_writers[(chat_id, message_id)] = pump.writer
    spawn_background(_turn_pump_loop(conn, session_key, run, (user_id, chat_id), pump))
    spawn_background(conn.ensure_message_subscription(session_key))
    pipe_log(f"  turn writer: adopted {message_id[:8]}... (run {run[:24]}...) from writer "
             f"{str(meta.get('openclaw_writer'))[:12]}...")
    if pump.wake:
        await _wake_resync(conn)
        return "adopted"
    try:
        lst = await conn.send_request("sessions.list", {"search": session_key[-36:], "limit": 10},
                                      timeout=15)
    except Exception as ex:
        pipe_log(f"  turn writer: row read for an adopted message failed: {ex!r}")
        return "adopted"
    row = next((r for r in (lst.get("sessions") or []) if r.get("key") == session_key), None)
    if row is not None and not row.get("hasActiveRun"):
        pump.queue.put_nowait(("settled", row))
    return "adopted"


async def _turn_after_hello(conn: "_GatewayConnection") -> None:
    """After a reconnect: send resumes the closing Gateway refused, and end
    the runs whose session is no longer active though no settle reached this
    socket (it was down). Sessions still active wait for their own settle."""
    for writer in list(conn._turn_writers.values()):
        if writer.pending_resume:
            await writer.on_hello()
    await _turn_resync(conn, skip=set(conn.active_run_snapshot))
    await _wake_resync(conn)


async def _turn_resync(conn: "_GatewayConnection", skip: set = frozenset()) -> None:
    """Read the row of every session with an open pump or an inline reply
    (except `skip`, known active) and end the ones that went idle while their
    settle was missed. Inline replies get the row busy or idle: one that lost
    its own final and settle in the gap looks for its closer even while a
    later run keeps the session busy (review 2af1 N3)."""
    idle = {sess for (sess, _run) in [*conn._turn_pumps, *conn._turn_unkinded] if sess not in skip}
    idle |= {c.session_key for c in list(conn._consumers.values()) if c.session_key not in skip}
    for sess in idle:
        read_at = time.monotonic()
        try:
            lst = await conn.send_request("sessions.list", {"search": sess[-36:], "limit": 10},
                                          timeout=15)
        except Exception as ex:
            pipe_log(f"  turn writer: row read after hello failed: {ex!r}")
            continue
        row = next((r for r in (lst.get("sessions") or []) if r.get("key") == sess), None)
        if row is None:
            continue
        if not row.get("hasActiveRun"):
            _turn_settled(conn, sess, row)
        conn.row_to_consumers(sess, row, resync=True, read_at=read_at, outside_loop=True)


# --- models ----------------------------------------------------------------


# ---------------------------------------------------------------------------
# Pipe class (Open WebUI entry point)
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# Dynamic model discovery helpers
# ---------------------------------------------------------------------------

_FALLBACK_MODELS = [
    {"key": "deepseek/deepseek-v4-flash", "name": "DeepSeek V4 Flash", "tags": ["configured", "alias:DeepSeek"]},
    {"key": "openai/gpt-5.5", "name": "gpt-5.5", "tags": ["configured"]},
    {"key": "anthropic/claude-opus-4-8", "name": "claude-opus-4-8", "tags": ["configured", "alias:opus"]},
    {"key": "anthropic/claude-sonnet-5", "name": "Claude Sonnet 5", "tags": ["configured", "alias:sonnet-5"]},
    {"key": "openrouter/z-ai/glm-5.2", "name": "GLM 5.2", "tags": ["configured", "alias:openrouter-glm-5.2"]},
]


def _friendly_name(model_entry: dict) -> str:
    """Return a human-friendly name for a model entry.

    Priority: model name field → alias tag → last segment of key.

    The catalog `name` is preferred because it carries the *version*
    ("Claude Opus 4.8"), while the alias is a deliberately short handle
    ("opus") that hides which version you're actually talking to -- the
    selector then shows two indistinguishable "Opus"/"Sonnet" entries as
    new versions land. Same complaint as upstream openclaw#111884.
    Alias remains the fallback for models the gateway returns unnamed.
    """
    name = model_entry.get("name", "")
    if name:
        return name
    tags = model_entry.get("tags", [])
    alias = next((t for t in tags if t.startswith("alias:")), None)
    if alias:
        alias_name = alias.split(":", 1)[1]
        return alias_name[0].upper() + alias_name[1:] if alias_name else alias_name
    return model_entry["key"].rsplit("/", 1)[-1]


def _provider_from_key(key: str) -> str:
    """Extract the provider/vendor from a model key like 'anthropic/claude-opus-4-8'."""
    return key.split("/", 1)[0] if "/" in key else ""


def _normalize_model_entry(raw: dict) -> dict:
    """Normalize a raw gateway `models.list` entry into the {key, name, tags}
    shape used elsewhere in this module (matches _FALLBACK_MODELS).

    The gateway's actual response shape is {id, name, provider, alias, ...} --
    there is no combined "key" or "tags" field, so this bridges the two.
    """
    provider = raw.get("provider", "")
    model_id = raw.get("id", "")
    key = f"{provider}/{model_id}" if provider and model_id else (model_id or provider)
    tags = ["configured"] if raw.get("available", True) else []
    alias = raw.get("alias")
    if alias:
        tags.append(f"alias:{alias}")
    return {"key": key, "name": raw.get("name", model_id), "tags": tags}


def _usable_models(raw_models: list[dict]) -> list[dict]:
    """Normalize `models.list` entries, dropping the ones the Gateway marks
    `available: false` (e.g. `unavailableReason: "missing-auth"`).

    An allowlisted model with no credentials still comes back from
    `models.list`. Listing it put a selector entry in OWUI that could only
    fail: `anthropic/claude-haiku-5-5` sat next to the working
    `claude-cli/claude-haiku-5-5`, and picking it 401'd with "No API key
    found for provider anthropic". Entries without the field count as usable.
    """
    return [
        _normalize_model_entry(m) for m in raw_models
        if m.get("available", True) is not False
    ]


# Wording that points at the agent/session rather than the model. Kept NARROW
# on purpose -- an earlier version also matched "not found", which misfiled
# "model 'x/y' not found" as an AGENT_ID problem. Do not re-broaden these; the
# tests in SessionPatchFailureAttributionTests assert both directions.
_AGENT_ERROR_HINTS = ("agent", "session")


def _explain_session_patch_failure(err, *, model_override, agent_id) -> str:
    """Describe a failed sessions.patch without misattributing the cause.

    The session key embeds AGENT_ID and this patch is the turn's first
    agent-scoped RPC, so a mistyped AGENT_ID surfaces here -- and used to be
    reported as "Model selection error", sending the user to fix
    DEFAULT_MODEL, which was never the problem.

    Classifying by substring is genuinely ambiguous, so the ordering matters and
    is deliberate:

    * "model" (or the model key) present -> a MODEL error. Checked FIRST and
      allowed to win outright, because gateway model errors routinely mention
      the agent too ("model x/y is not configured for this agent"), whereas an
      agent error rarely mentions a model. An earlier version of this matched
      "not found" as an agent hint, which misfiled "model 'x/y' not found" --
      the exact misattribution this function exists to prevent, just pointed
      the other way.
    * otherwise, agent/session wording -> an AGENT error.
    * otherwise -> say we don't know, and name both valves. Guessing wrong is
      worse than admitting ambiguity: it sends the user to edit a valve that
      was correct.
    """
    # Transient and transport failures are neither valve's fault, and the retry
    # comment in pipe() says they are the common ones under load. Classify by
    # TYPE first: substring matching cannot see them, and str(TimeoutError()) is
    # "", which rendered as a dangling colon followed by advice to edit two
    # valves that were both correct.
    if isinstance(err, (asyncio.TimeoutError, ConnectionError)):
        return (
            "**The Gateway did not respond in time while starting this "
            "conversation.** This is usually transient -- send the message "
            "again. If it keeps happening, check that the Gateway is healthy "
            "and reachable from Open WebUI."
        )

    detail = str(err).strip() or repr(err)
    low = detail.lower()
    wanted = model_override or "agent default"

    looks_like_model = "model" in low or (
        bool(model_override) and model_override.lower() in low
    )
    if looks_like_model:
        return f"**Model selection error:** could not apply `{wanted}`: {detail}"

    if any(h in low for h in _AGENT_ERROR_HINTS):
        return (
            f"**Could not start a session on agent `{agent_id}`:** {detail}\n\n"
            f"Check the `AGENT_ID` valve -- it must name an agent your OpenClaw "
            f"Gateway actually defines (`main` unless you configured others). "
            f"This surfaces here because applying the model is the first thing "
            f"the pipe asks the agent to do; the model (`{wanted}`) may be fine."
        )

    return (
        f"**Could not start this conversation's session:** {detail}\n\n"
        f"The pipe was applying model `{wanted}` on agent `{agent_id}`. Check "
        f"the `AGENT_ID` valve names an agent your Gateway defines, and that "
        f"the model is one it offers."
    )


MODELS_SOURCE_LIVE = "live"
MODELS_SOURCE_CACHE = "cache"
MODELS_SOURCE_FALLBACK = "fallback"

# Appended to selector entries built from _FALLBACK_MODELS. Display text only --
# the entry's `id` (the routing key) is untouched, so this cannot affect routing.
UNVERIFIED_MODEL_SUFFIX = " -- example, Gateway not reached"


async def _discover_models(valves) -> list[dict]:
    """Back-compat wrapper for callers that don't care where the list came from."""
    models, _source = await _discover_models_with_source(valves)
    return models


async def _discover_models_with_source(valves) -> tuple[list[dict], str]:
    """Discover models, and report where the list came from.

    Returns (models, source), source being "live", "cache" or "fallback".

    Callers need that distinction because the three are not interchangeable to
    a user. `pipes()` never initiates a connection -- it only reuses one that a
    previous chat established -- so on a fresh install the live branch is skipped
    and no cache exists yet, and the selector filled up with five hardcoded
    models bearing no relationship to the user's Gateway, rendered identically
    to genuinely discovered ones. Picking one the Gateway doesn't have then
    failed with a bare "Model selection error", with nothing to suggest the list
    itself had been fabricated.
    """
    # 1. Try live gateway (fast path only if already connected)
    global _gateway_connection
    conn = _gateway_connection
    if conn and conn._ws and conn._event_loop_task and not conn._event_loop_task.done():
        try:
            resp = await conn.send_request("models.list", {}, timeout=5)
            raw_models = resp.get("models", [])
            if raw_models:
                models = _usable_models(raw_models)
                _write_json_file(
                    os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), "models-cache.json"),
                    {"models": models, "cachedAt": time.time()}
                )
                return models, MODELS_SOURCE_LIVE
        except Exception as e:
            pipe_log(f"Live model discovery failed: {e}")

    # 2. Cache fallback
    cache = _read_json_file(os.path.join(_state_dir(getattr(valves, "STATE_DIR", "")), "models-cache.json"))
    if cache and cache.get("models"):
        pipe_log("Using cached model list")
        return cache["models"], MODELS_SOURCE_CACHE

    # 3. Hardcoded fallback
    pipe_log(
        "Using hardcoded fallback model list -- the Gateway has not been reached "
        "yet, so these are examples, not your Gateway's models. They are labelled "
        "as such in the model selector."
    )
    return _FALLBACK_MODELS, MODELS_SOURCE_FALLBACK


# --- pipe ------------------------------------------------------------------

# Session states that `sessions.describe` reports for a genuinely in-progress
# run. Blacklisting terminal states is unsafe: an idle session reports "idle"
# (and "done"), so a `not in (done, failed, cancelled)` test would treat every
# resting session as active and hang every message. Only these gate the queue.
_ACTIVE_RUN_STATES = ("active", "running", "streaming", "queued")


def _session_active_from_signals(describe_status, list_has_active_run) -> bool:
    """Decide whether a session has an in-progress run from the two gateway
    signals the pipe can observe over RPC (ELI-56).

    `sessions.describe` only exposes a persisted `status`, which flips to
    'done' the instant a turn calls `sessions_yield` to await a subagent -- even
    though the run is merely suspended and WILL resume, and the gateway still
    steer-merges any message sent into that window (→ a phantom "no reply
    text" bubble). `sessions.list` additionally exposes `hasActiveRun`, the
    authoritative live signal derived from the gateway's chatAbortControllers
    map + isEmbeddedAgentRunActive(sessionId); it stays true across the whole
    yield gap. So a session is "active" if EITHER describe says a run state OR
    list says a run is live.
    """
    if describe_status in _ACTIVE_RUN_STATES:
        return True
    return bool(list_has_active_run)


def _owui_owns_inflight_message() -> bool:
    """True when the running Open WebUI (0.12+) owns the in-flight assistant
    message, which makes the pipe's REST mid-run snapshot a no-op.

    Two 0.12 changes, measured live on 2026-10-11 against 0.12.0:
      * `Chats.update_chat_by_id` keeps the STORED copy of any assistant
        message whose stored or incoming `done` is False
        (`models/chats.py::update_chat_by_id`), so the snapshot's
        `history.messages[id]` patch is dropped. The live probe saw every
        snapshot POST return 200 while the DB row stayed at content=0 until
        `done`.
      * The streaming handler keeps in-progress content/output in
        `response_streams` (`middleware.py::save_current_response_stream`)
        and `GET /api/v1/chats/{id}` overlays it onto the message
        (`routers/chats.py::overlay_response_streams`). The same probe read
        the growing text back from that GET every poll, so a client that
        reloads mid-turn is rehydrated by OWUI itself.

    `insert_chat_turn` (the 0.12 server-side turn insertion that came with
    the `done` rule) is the feature marker. Outside OWUI, or on an older
    OWUI, this is False and the snapshot keeps running.
    """
    mod = sys.modules.get("open_webui.models.chats")
    if mod is None:
        try:
            import importlib
            mod = importlib.import_module("open_webui.models.chats")
        except Exception:
            return False
    chats = getattr(mod, "Chats", None)
    return callable(getattr(chats, "insert_chat_turn", None))


def _thinking_rejection_retry_body(body, recovered, resolved_thinking):
    """Decide whether a textless ("PHANTOM") turn's preview-recovered text is
    the Gateway's permanent-brick thinking-level rejection, and build the
    retry body if so (ELI-85 follow-up).

    `clamp_to_ladder` passes a requested level straight through whenever the
    model's real ladder is unknown -- and if the target model can't honour it,
    the Gateway hard-rejects the turn. That rejection never streams as a normal
    event (the run delivers a single contentless `final`), so it only surfaces
    via preview recovery at the caller's final fallback.

    Detection is `parse_thinking_rejection`, the same parser that extracts the
    ladder, so the thing that decides to retry and the thing that learns from
    the retry can never disagree about what a rejection is.

    Returns None when `recovered` isn't that rejection (nothing to retry).
    Otherwise returns a fresh dict body with `reasoning_effort` stripped, so
    resending it can no longer hit the same rejection -- which is also what
    makes recursing on this once safe: the retried call resolves
    `resolved_thinking` to None (`clamp_to_ladder` short-circuits on no
    requested level), so this can't match twice in a row.
    """
    if not recovered or resolved_thinking is None:
        return None
    if parse_thinking_rejection(recovered) is None:
        return None
    retry_body = dict(body)
    retry_body.pop("reasoning_effort", None)
    return retry_body


# A Send now's follow-up message is known to be coming; this only bounds a
# browser that dies between the cancel and the send.
_SEND_NOW_HOLD_S = 120.0


async def _current_load(pipe, request):
    """The Pipe of the load Open WebUI serves now, when `pipe` belongs to an
    older load of this Function; else None (ELI-102).

    A deploy execs the new content into a new module, and the first request
    there retires the old load's connection. A turn the old load admitted but
    had not yet connected (the dev build holds new turns while a deploy is
    pending, 24 min on 2026-10-13) then met the retired connection and was
    lost as "gateway connection retired". Open WebUI's own lookup
    (`get_function_module_by_id`, which also sets the valves) names the
    current load."""
    prefix = _function_module_prefix(__name__)
    if request is None or not prefix.startswith("function_"):
        return None
    try:
        from open_webui.functions import get_function_module_by_id

        current = await get_function_module_by_id(request, prefix[len("function_"):])
    except Exception as ex:
        pipe_log(f"  current load lookup failed, serving this turn here: {ex!r}")
        return None
    if current is None or current is pipe or type(current).__module__ == __name__:
        return None
    return current


async def _settle_cancel_intent(conn, session_key, run_id, chat_id, event_call):
    """Ask the page whether this cancel was Stop or Send now, and settle the
    parked turn accordingly (see `settle_parked_turn`)."""
    intent = None
    if event_call and chat_id:
        try:
            resp = await asyncio.wait_for(
                event_call({"type": "execute",
                            "data": {"code": _intent_query_js(chat_id)}}),
                timeout=_INTENT_QUERY_TIMEOUT_S,
            )
            intent = _normalize_event_call_response(resp) or None
        except (Exception, asyncio.CancelledError) as ex:
            pipe_log(f"  cancel intent query failed: {ex!r}")
    pipe_log(f"  cancel intent from the page: {intent or 'unknown'}")
    conn.settle_parked_turn(session_key, run_id, intent, hold_s=_SEND_NOW_HOLD_S)


async def _gateway_run_status(conn, session_key: str) -> str | None:
    """The Gateway's own run status (P26), for a reply that has been quiet.

    A quiet queue does not mean the run ended: it may be queued behind
    another run, in a long tool call, or in a sub-agent yield gap. Returns
    the `sessions.describe` status ("running", "done", "failed",
    "cancelled", ...), so callers can tell a user stop from a dead run. A
    terminal status is checked against `sessions.list` `hasActiveRun`, which
    counts a yield gap as active where describe already says "done"
    (ELI-56); then it is "running". None when the probe failed or the
    session is unknown."""
    try:
        desc = await conn.send_request("sessions.describe", dict(key=session_key), timeout=8)
    except Exception as ex:
        pipe_log(f"  initial describe probe failed: {ex}")
        return None
    session_row = desc.get("session")
    if session_row is None:
        return None
    status = session_row.get("status")
    if status in ("done", "failed", "cancelled") and await _session_list_active(conn, session_key):
        return "running"
    return status


@dataclass
class _TurnState:
    """What one reply still owes the user if it is cancelled or closed now.

    `unsent` are user messages it accepted but has not yet sent to the
    Gateway (its own, plus any carried over from a cancelled reply).
    `run_id` / `queue` are a run it is consuming, its own or one it adopted,
    and the consumer queue buffering that run's events. `parked` is set once
    the cancel was handed to `park_cancelled_turn`.
    """
    conn: object = None
    session_key: str | None = None
    chat_id: str | None = None
    unsent: list = field(default_factory=list)
    run_id: str | None = None
    queue: object = None
    run_text: dict | None = None
    parked: bool = False


class Pipe:
    """
    Open WebUI Pipe that routes messages through OpenClaw Gateway via
    a persistent WebSocket connection.

    Valves (configured in OWUI admin panel):
    - GATEWAY_URL: OpenClaw Gateway address (default "localhost:18789")
    - GATEWAY_TOKEN: Gateway API token (required)
    - DEVICE_IDENTITY: (optional) persisted device identity JSON
    - AGENT_ID: target agent (default "main")
    - ENABLE_FILE_SERVER: start media file server (default True)
    - USE_OWUI_FILES: upload MEDIA files into OWUI Files API (default True)
    - SEND_STOP_ON_CANCEL: send /stop after chat.abort when OWUI cancels
    - INTERRUPT_GRACE_SECONDS: how long a cancel waits for a follow-up message
      before aborting the run (default 3; 0 aborts immediately)
    """

    class Valves(BaseModel):
        GATEWAY_URL: str = Field(
            default="localhost:18789",
            description="Required. Your OpenClaw Gateway as host:port -- no "
                "http:// or ws:// prefix. Example: 192.168.1.10:18789. It must "
                "be reachable from the Open WebUI backend, which is not "
                "necessarily the same network as your browser."
        )
        GATEWAY_TOKEN: str = Field(
            default="",
            description="Required. The Gateway API token: the value of "
                "`gateway.auth.token` in your OpenClaw config. Ask whoever runs "
                "the Gateway if you don't manage it yourself."
        )
        DEVICE_IDENTITY: str = Field(
            default="",
            description="(Advanced -- normally leave empty.) Ed25519 device "
                "identity JSON. The pipe generates one on first connect and "
                "persists it in STATE_DIR. Set this only to import an "
                "already-approved identity, or to make the companion Status "
                "Action reuse this exact device instead of raising a second "
                "pairing request."
        )
        STATE_DIR: str = Field(
            default="/data/openclaw-bridge",
            description="Directory inside the Open WebUI container where the "
                "device identity and Gateway token are stored. Must survive "
                "restarts: if it is not writable the pipe silently falls back "
                "to /tmp, and you will be asked to approve the device again "
                "after every restart."
        )
        OWNER_USERS: str = Field(
            default="",
            description="Open WebUI user ids or emails, comma-separated, whose "
                "chats act with full owner rights on the Gateway. Leave empty "
                "and every user acts as the owner (the old behaviour). When set, "
                "everyone else talks to the Gateway over a separate connection "
                "with read and write access only, so the agent withholds "
                "owner-only tools (automations, outbound messaging, sessions "
                "admin, terminal) from their turns. Use it whenever someone "
                "other than the Gateway's owner can sign in to Open WebUI."
        )
        AGENT_ID: str = Field(
            default="main",
            description="Which OpenClaw agent handles these chats. Leave as "
                "'main' unless your Gateway defines additional named agents."
        )
        ENABLE_FILE_SERVER: bool = Field(
            default=True,
            description="Start a small HTTP server on port 18791 to serve "
                "agent-generated images and files. Only used as a fallback when "
                "USE_OWUI_FILES is off or an upload fails. Note it is "
                "unauthenticated -- leave off if port 18791 is exposed."
        )
        USE_OWUI_FILES: bool = Field(
            default=True,
            description="Recommended. Upload agent-generated images and files "
                "through Open WebUI's own Files API so they attach natively and "
                "work over HTTPS. Falls back to the file server if it fails."
        )
        SEND_STOP_ON_CANCEL: bool = Field(
            default=True,
            description="Recommended. When you press Stop, also send the agent "
                "a /stop, so a tool it is running is actually killed -- aborting "
                "the stream alone can leave the tool running."
        )
        INTERRUPT_GRACE_SECONDS: float = Field(
            default=10.0,
            description="Recommended: 10. Fallback only: the Pipe asks the "
                "page whether a cancel was Stop or Send now and acts on that "
                "at once; this window applies when the page cannot say (a "
                "non-English UI, API clients). Sending a message while the agent is "
                "working (Open WebUI's Send now, or sending with the message "
                "queue off) stops the current response. With this set, the "
                "agent's run is kept alive instead: the new reply first shows "
                "the rest of the running turn, then answers your message. A "
                "plain Stop with no new message still stops the run after this "
                "many seconds. 0 stops immediately, as before."
        )
        OWUI_BASE_URL: str = Field(
            default="http://127.0.0.1:8080",
            description="Open WebUI's own base URL, resolved by the Open WebUI "
                "backend itself and not by your browser. The default is correct "
                "for a standard single-container install; change it only if "
                "Open WebUI cannot reach itself at 127.0.0.1:8080."
        )
        OWUI_API_KEY: str = Field(
            default="",
            description="(Optional.) Only needed if media uploads fail with an "
                "auth error -- the pipe normally reuses your own login token."
        )
        FILE_SERVER_BASE_URL: str = Field(
            default="http://localhost:18791",
            description="Legacy fallback only: base URL of the built-in media file "
                "server, used when USE_OWUI_FILES is off or an upload fails. The "
                "browser resolves this URL, not OWUI, so the default only works when "
                "you browse OWUI from the same host. Point it at an address your "
                "browser can reach if you depend on this fallback."
        )
        DEFAULT_MODEL: str = Field(
            default="",
            description="Model used when you pick 'OpenClaw · Default'. Leave empty to "
                "use the agent's own configured model. The dropdown lists models "
                "discovered from your Gateway; before the first successful "
                "connection it shows a built-in example list that may not match "
                "your Gateway.",
            json_schema_extra={
                "input": {"type": "select", "options": "get_model_options"}
            }
        )
        MAX_MODELS: int = Field(
            default=30,
            description="Maximum number of models to show in the selector.",
            ge=1,
            le=100
        )
        AUTO_TITLE: bool = Field(
            default=True,
            description="Auto-generate a chat title after the first exchange (like native OWUI). "
                "Uses a fast model; best-effort, non-blocking."
        )
        COMPOSER_STATUS_BUTTON: bool = Field(
            default=True,
            description="Add an OpenClaw 'Status' button to the composer row of "
                "OpenClaw chats (it opens the same dialog as the Status Action's "
                "message button, so that Action must be installed). Installed "
                "into the page at the start of each turn and when a tab opens an "
                "OpenClaw chat. Turn off to stop delivering it; an already open "
                "tab keeps it until reload."
        )
        TITLE_GEN_AGENT_ID: str = Field(
            default="title-gen",
            description="Agent id used for background chat-title generation. It must "
                "exist on the Gateway (default 'title-gen'); if it does not, titles are "
                "silently skipped. Kept separate from AGENT_ID so title generation never "
                "queues behind your conversation."
        )

    # Set from the live valves so the DEFAULT_MODEL dropdown (a classmethod with
    # no access to self.valves) reads the same cache pipes() writes.
    _last_state_dir = ""

    def __init__(self):
        self.valves = self.Valves()
        self._active_tool_args: dict[str, str] = {}
        # Will be set per pipe() call
        self._current_session_key: str | None = None
        self._current_run_id: str | None = None
        self._connection: _GatewayConnection | None = None

    async def pipes(self):
        """Expose multiple OWUI model-selector entries from one pipe.
        
        Dynamically discovers models from the OpenClaw Gateway (or cache)
        and returns one entry per model plus a 'Default' entry.
        """
        type(self)._last_state_dir = getattr(self.valves, "STATE_DIR", "") or ""
        # Every page load lists models, so this is the earliest point the
        # composer watcher can start after an Open WebUI restart or redeploy.
        _ensure_composer_watcher(lambda: self.valves)
        # ...and the earliest point to finish replies a restart orphaned.
        _ensure_orphan_reconcile(lambda: self.valves)
        models, source = await _discover_models_with_source(self.valves)

        # Apply safety cap
        if len(models) > self.valves.MAX_MODELS:
            models = models[:self.valves.MAX_MODELS]

        # A hardcoded list is a guess, not a discovery. Say so in the only place
        # the user is looking -- the selector itself -- rather than letting five
        # invented models masquerade as their Gateway's. Suffixing the display
        # name is deliberate: `id` stays the untouched routing key.
        unverified = source == MODELS_SOURCE_FALLBACK
        entries = []
        for m in models:
            friendly = _friendly_name(m)
            provider = _provider_from_key(m["key"])
            name = f"{friendly} ({provider}) · OpenClaw"
            if unverified:
                name += UNVERIFIED_MODEL_SUFFIX
            entries.append({"id": m["key"], "name": name})

        # Always prepend Default at top. It is the one entry that always works
        # in this state: it clears the override and uses the agent's own model,
        # so it needs no Gateway round trip to be correct.
        #
        # If discovery ever comes back empty (fallback list included), say the
        # warning on Default instead of leaving a bare, unexplained selector.
        default_name = "OpenClaw · Default"
        if unverified and not entries:
            default_name += UNVERIFIED_MODEL_SUFFIX
        return [{"id": "default", "name": default_name}] + entries

    @classmethod
    def get_model_options(cls):
        """Return model options for the DEFAULT_MODEL valve dropdown.

        Reads synchronously from the model cache or fallback list.

        Uses the state dir the running Pipe last resolved (recorded in
        _last_state_dir) rather than _state_dir() with no argument. Being a
        classmethod there is no self.valves here, and the no-argument form
        resolves to OPENCLAW_BRIDGE_STATE_DIR or /data/openclaw-bridge -- so for
        anyone who set the STATE_DIR valve it read a path nothing ever writes,
        never found the cache, and therefore labelled every option
        "Gateway not reached" permanently, long after successful discovery.
        """
        cache = _read_json_file(
            os.path.join(_state_dir(cls._last_state_dir), "models-cache.json")
        )
        cached = cache.get("models") if cache else None
        models = cached or _FALLBACK_MODELS
        # Same honesty as pipes(): before the first successful connection this
        # dropdown is a built-in example list, not a reference of what the
        # Gateway actually offers.
        suffix = "" if cached else UNVERIFIED_MODEL_SUFFIX
        return [
            {
                "value": m["key"],
                "label": f"{_friendly_name(m)} ({_provider_from_key(m['key'])}){suffix}",
            }
            for m in models
        ]

    def _selected_preset(self, body):
        """Extract the model key from the OWUI model string."""
        model = str(body.get("model", ""))
        # Split on the FIRST dot only: the function id (e.g. "openclaw_gateway")
        # never contains a dot, but model keys can (e.g. "gemini-3.1-pro-preview").
        # rsplit would wrongly cut inside the version number.
        suffix = model.split(".", 1)[-1]
        if suffix == "default":
            return "default"
        return suffix  # raw model key

    def _model_override_for_preset(self, preset):
        """Return the model string to pass to sessions.patch."""
        if preset == "default":
            return self.valves.DEFAULT_MODEL.strip() or None
        return preset

    # ── Auto-title helpers ──────────────────────────────────────────

    async def _auto_title(self, body, conn, visible_message_text,
                          owui_origin_chat_id, bearer_token, session_key=""):
        """Generate a chat title and set it via OWUI's REST API.

        Fires after the SECOND successful exchange (first message + response),
        when OWUI's chat_id is stable. The first request uses a temporary ID.
        Best-effort, non-blocking -- failures are logged but never surfaced.
        """
        if not self.valves.AUTO_TITLE:
            return

        messages = body.get("messages", [])
        if not messages or not owui_origin_chat_id or not visible_message_text:
            return

        # Fire on the SECOND user message: one full exchange is now in history,
        # and the chat_id is stable (OWUI replaces the temp ID after exchange 1).
        user_msgs = [m for m in messages if m.get("role") == "user"]
        assistant_msgs = [m for m in messages if m.get("role") == "assistant"]
        if len(user_msgs) != 2 or len(assistant_msgs) != 1:
            return

        # Build title from the FIRST exchange, not the current message
        user_text = user_msgs[0].get("content", "")[:400]
        assistant_preview = assistant_msgs[0].get("content", "")[:400]

        pipe_log(f"Auto-title: generating title for chat {owui_origin_chat_id}")

        try:
            # The title run carries this chat's text, so it goes out with the
            # chat's owner status (OWNER_USERS), not the owner's.
            owner = await _sender_is_owner(conn, session_key)
            title = await self._generate_title_text(conn, user_text, assistant_preview, owner=owner)
            if not title:
                return
            await self._set_owui_chat_title(owui_origin_chat_id, title, bearer_token)
            pipe_log(f"Auto-title: set to '{title}'")
        except Exception as e:
            pipe_log(f"Auto-title: failed (non-fatal): {e}")

    async def _generate_title_text(self, conn, user_msg: str,
                                    assistant_msg: str, owner: bool = True) -> str | None:
        """Use a lightweight model call to generate a 3-5 word title + emoji.

        Sends a chat.send to a temp session and reads the run from its own
        signals: its assistant text up to its final event, or, when the final
        was lost, its settle row and the transcript (review 2af1 timers). The
        old 7 x 3 s `sessions.preview` poll dropped any title slower than that.

        Runs under TITLE_GEN_AGENT_ID (a separate configured agent from
        AGENT_ID), not the main conversation's agent. A bare/unprefixed
        sessionKey previously defaulted onto the SAME agent as the live
        conversation, so this background call shared its CLI process/queue
        lane and queued behind any heavy turn (2026-07-10 regression). A
        distinct agent id gets its own lane.
        """
        prompt = (
            "Create a concise title (3-5 words) with a relevant emoji "
            "for this conversation. Output ONLY the title, nothing else "
            "-- no quotes, no explanation.\n\n"
            f"User message: {user_msg}\n\n"
            f"Assistant response: {assistant_msg}"
        )

        agent_id = self.valves.TITLE_GEN_AGENT_ID.strip() or "title-gen"
        title_session = f"agent:{agent_id}:title-gen-{uuid.uuid4().hex[:12]}"
        run_id = f"title-{title_session}"
        # Listen before sending: a fast run can end before chat.send returns.
        queue = conn.register_consumer(title_session, run_id)
        try:
            try:
                resp = await _run_request(
                    conn, RUN_SEND,
                    dict(sessionKey=title_session, message=prompt, idempotencyKey=run_id),
                    timeout=15, owner=owner,
                )
            except Exception as e:
                pipe_log(f"Auto-title: chat.send failed: {e}")
                return None
            if resp.get("runId") and resp["runId"] != run_id:
                conn.unregister_consumer(title_session, run_id, queue=queue)
                run_id = resp["runId"]
                queue = conn.register_consumer(title_session, run_id)
            text = ""
            while True:
                msg = await queue.get()
                kind = msg.get("type")
                if kind == _RESTART_MARKER_TYPE:
                    pipe_log("Auto-title: Gateway restarted; no title")
                    return None
                if kind == _ROW_MARKER_TYPE:
                    row = msg.get("row") or {}
                    if row.get("hasActiveRun") is False and (
                            msg.get("resync") or row.get("lastRunId") == run_id):
                        hist = await conn.session_history(title_session, limit=10)
                        found, whole = _history_text_for_run(hist, run_id)
                        return self._clean_title_text(whole or text) if (found or text) else None
                    continue
                payload = msg.get("payload") or {}
                data = payload.get("data") or {}
                if payload.get("stream") == "assistant":
                    text += data.get("delta") or ""
                if payload.get("stream") == "lifecycle" and data.get("phase") == "error":
                    pipe_log(f"Auto-title: title run failed: {data.get('error')}")
                    return None
                if payload.get("state") in ("error", "aborted"):
                    return None
                if payload.get("state") == "final":
                    final = _coerce_text(payload.get("message")) if payload.get("message") else ""
                    return self._clean_title_text(final or text)
        finally:
            conn.unregister_consumer(title_session, run_id)

    @staticmethod
    def _clean_title_text(raw: str) -> str | None:
        """Clean up raw model output into a valid title."""
        title = raw.strip('\"\' \n\r')
        # Some models wrap in quotes or add explanatory text
        if "\n" in title:
            title = title.split("\n")[0].strip()
        if len(title) > 80:
            title = title[:77] + "..."
        return title if title else None

    async def _set_owui_chat_title(self, chat_id: str, title: str,
                                    bearer_token: str | None):
        """Set the chat title via OWUI's REST API (POST /api/v1/chats/{id})."""
        token = bearer_token or self.valves.OWUI_API_KEY
        if not token:
            pipe_log("Auto-title: no OWUI auth token available")
            return

        data = json.dumps({"chat": {"title": title}}).encode()
        req = urllib.request.Request(
            f"{self.valves.OWUI_BASE_URL.rstrip('/')}/api/v1/chats/{chat_id}",
            data=data,
            headers={
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        await asyncio.to_thread(urllib.request.urlopen, req, timeout=10)

    async def _rest_snapshot_message(self, chat_id: str, message_id: str,
                                      content: str, bearer_token: str | None):
        """Persist the in-flight assistant message via OWUI's REST API.

        Deliberately NOT the __event_emitter__ `replace` event, and
        deliberately NOT `POST /api/v1/chats/{id}/messages/{message_id}`
        either -- that dedicated endpoint calls an `event_emitter` with a
        `chat:message` socket event, which races the live HTTP delta stream
        exactly like `replace` does (P17/P19/P23/P25/P27, 6e5f372). This
        uses the same whole-chat update endpoint `_set_owui_chat_title`
        already calls mid-conversation (`POST /api/v1/chats/{id}` with no
        `message_id` in the path), which was confirmed by reading the live
        OWUI 0.11.0 source (`bridge-rehydration-rest-snapshot-verify`,
        2026-08-26) to never emit any Socket.IO frame -- it writes the DB
        row directly with nothing for the frontend's live-stream handlers
        to even receive.

        Read-modify-write is required because `chat.messages[]` (the flat,
        active-branch array) has no server-side merge -- sending it fully
        replaces the old array, per `routers/chats.py::update_chat_by_id`
        (`updated_chat = {**chat.chat, **form_data.chat}`). `chat.history
        .messages{}` (keyed by message id) merges whole-object-per-id
        server-side (`Chats.merge_history`), so only the one patched
        message needs to be sent there.

        Skipped on OWUI 0.12+ (`_owui_owns_inflight_message`): there the
        write is discarded for an unfinished message and OWUI serves the
        in-flight text to reloading clients on its own.
        """
        token = bearer_token or self.valves.OWUI_API_KEY
        if not token or not chat_id or not message_id:
            return
        if _owui_owns_inflight_message():
            return
        base = self.valves.OWUI_BASE_URL.rstrip('/')
        headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        }

        def _get_chat():
            req = urllib.request.Request(
                f"{base}/api/v1/chats/{chat_id}", headers=headers, method="GET",
            )
            with urllib.request.urlopen(req, timeout=10) as resp:
                return json.loads(resp.read().decode("utf-8", "replace"))

        try:
            current = await asyncio.to_thread(_get_chat)
        except Exception as ex:
            pipe_log(f"  rest_snapshot: GET failed: {ex}")
            return

        chat_obj = (current or {}).get("chat") or {}
        messages = chat_obj.get("messages")
        history_messages = ((chat_obj.get("history") or {}).get("messages")) or {}

        target = history_messages.get(message_id)
        if target is None and isinstance(messages, list):
            target = next(
                (m for m in messages if isinstance(m, dict) and m.get("id") == message_id),
                None,
            )
        if target is None:
            # Message doesn't exist yet on the OWUI side (e.g. very first
            # chunk of a brand-new chat, before OWUI's own request handler
            # has created the row) -- nothing to patch onto.
            return

        patched = dict(target)
        patched["content"] = content

        patch: dict = {"history": {"messages": {message_id: patched}}}
        if isinstance(messages, list):
            patched_messages = [
                (patched if isinstance(m, dict) and m.get("id") == message_id else m)
                for m in messages
            ]
            patch["messages"] = patched_messages

        data = json.dumps({"chat": patch}).encode()

        def _post_chat():
            req = urllib.request.Request(
                f"{base}/api/v1/chats/{chat_id}",
                data=data, headers=headers, method="POST",
            )
            urllib.request.urlopen(req, timeout=10)

        try:
            await asyncio.to_thread(_post_chat)
        except Exception as ex:
            pipe_log(f"  rest_snapshot: POST failed: {ex}")

    async def pipe(self, body, __event_emitter__, __event_call__=None,
                   __user__=None, __metadata__=None, __request__=None,
                   __task__=None, __task_body__=None):
        """Main pipe entry point -- called by Open WebUI for each user message.

        Thin wrapper around _pipe_impl so dev-only deploy-coordination hooks
        (ELI-24) can bracket every turn without re-indenting the whole body.
        """
        remember_owui_server()
        current = await _current_load(self, __request__)
        if current is not None:
            pipe_log("Turn admitted by a superseded load of this Function: the current "
                     f"load ({type(current).__module__}) serves it")
            async with contextlib.aclosing(current.pipe(
                body, __event_emitter__, __event_call__=__event_call__,
                __user__=__user__, __metadata__=__metadata__, __request__=__request__,
                __task__=__task__, __task_body__=__task_body__,
            )) as turn_gen:
                async for item in turn_gen:
                    yield item
            return
        try:
            # aclosing: when OWUI closes this generator, close the inner one
            # now rather than whenever it is garbage-collected, so its cancel
            # handling runs before the next message arrives.
            async with contextlib.aclosing(self._pipe_impl(
                body, __event_emitter__, __event_call__=__event_call__,
                __user__=__user__, __metadata__=__metadata__, __request__=__request__,
                __task__=__task__, __task_body__=__task_body__,
            )) as turn_gen:
                async for item in turn_gen:
                    yield item
        finally:
            pass

    async def _pipe_impl(self, body, __event_emitter__, __event_call__=None,
                   __user__=None, __metadata__=None, __request__=None,
                   __task__=None, __task_body__=None, _initial_visible_text="",
                   _send_texts=None):
        """One reply: runs `_pipe_turn`, and makes sure a cancel or close at
        ANY point hands what the reply still owes to the next message (see
        `park_cancelled_turn`) instead of dropping it.

        `_pipe_turn` parks for itself while it is streaming a run, where it
        also snapshots and shows "Stopped". This catches every other point:
        before the message is sent (model patch, queue wait, a yield outside
        the stream loop) and around the adopt / retry recursion. OWUI ends a
        reply either by cancelling its task (CancelledError at an await) or
        by closing the generator (GeneratorExit at a yield); both land here.

        `_send_texts` replaces this request's own text as what to send, for
        the recursions that send messages carried over from earlier replies.
        """
        turn = _TurnState()
        try:
            async with contextlib.aclosing(self._pipe_turn(
                body, __event_emitter__, __event_call__=__event_call__,
                __user__=__user__, __metadata__=__metadata__,
                __request__=__request__, __task__=__task__,
                __task_body__=__task_body__,
                _initial_visible_text=_initial_visible_text,
                _send_texts=_send_texts, turn=turn,
            )) as turn_gen:
                async for item in turn_gen:
                    yield item
        except (asyncio.CancelledError, GeneratorExit) as stop:
            if (not turn.parked and turn.conn is not None and turn.session_key
                    and (turn.unsent or turn.run_id)):
                turn.parked = True
                pipe_log(
                    f"Reply {type(stop).__name__} outside the stream loop: parking "
                    f"{len(turn.unsent)} unsent message(s), run "
                    f"{str(turn.run_id)[:20]}"
                )
                turn.conn.park_cancelled_turn(
                    turn.session_key, turn.run_id, turn.queue, turn.unsent,
                    float(getattr(self.valves, "INTERRUPT_GRACE_SECONDS", 0) or 0),
                    send_stop=self.valves.SEND_STOP_ON_CANCEL,
                    run_text=turn.run_text,
                )
                await _settle_cancel_intent(
                    turn.conn, turn.session_key, turn.run_id, turn.chat_id,
                    __event_call__)
            raise

    async def _pipe_turn(self, body, __event_emitter__, __event_call__=None,
                   __user__=None, __metadata__=None, __request__=None,
                   __task__=None, __task_body__=None, _initial_visible_text="",
                   _send_texts=None, turn=None):
        """Uses a shared persistent WS connection; no per-message reconnect,
        no global lock, and no 60s timeout.

        `_initial_visible_text` seeds the terminal snapshot for the
        thinking-rejection retry recursion below: the retry note belongs to
        the turn that's ending, not the one about to start, but this call's
        own `visible_message_text` is what the forced terminal `replace`
        snapshot persists -- a note recorded only on the caller's copy would
        show while streaming and vanish on reload.
        """
        if self.valves.ENABLE_FILE_SERVER:
            _start_file_server()
        preset = self._selected_preset(body)
        model_override = self._model_override_for_preset(preset)

        # Per-chat thinking level (ELI-85). `reasoning_effort` is the single
        # source of truth: Open WebUI's own Advanced Params control writes it,
        # and so does the companion Thinking filter's toggle. Reading the field
        # rather than a filter-specific one means either control works, and the
        # bridge keeps working for anyone who never installs the filter.
        # Absent means absent: no `thinking` is sent and the agent's configured
        # level applies. Validation against the model's real ladder happens
        # below, once describe has told us what this session resolves to.
        requested_thinking = body.get("reasoning_effort") or None
        if requested_thinking is not None:
            requested_thinking = str(requested_thinking).strip().lower() or None
        session_thinking_ladder = None
        session_model_key = None
        session_runtime = None

        # --- P15: Short-circuit OWUI background tasks ---
        # O10 addendum: image_prompt_generation and function_calling also get
        # skipped here -- both already have a documented, silent OWUI-side
        # fallback for an empty response (raw user message / "no tool
        # needed" respectively -- see PLAN.md O10), so skipping them costs
        # nothing and saves a full agent turn. moa_response_generation is
        # deliberately excluded -- it is a user-triggered "Merge Responses"
        # request whose only output path is the streamed content itself, so
        # a no-op here would show as a visibly empty result rather than a
        # graceful fallback.
        if __task__ and __task__ in (
            "title_generation",
            "tags_generation",
            "follow_up_generation",
            "emoji_generation",
            "autocomplete_generation",
            "query_generation",
            "image_prompt_generation",
            "function_calling",
        ):
            pipe_log(f"Skipping OWUI background task: {__task__}")
            return

        # --- Extract user message ---
        # OWUI sends `content` as a plain string for text-only messages, but
        # as a list of content blocks (`{"type": "text", ...}` /
        # `{"type": "image_url", ...}`) whenever the user attaches an image.
        # Coercing through _coerce_text (already used elsewhere for gateway
        # event payloads with the same block shape) extracts and joins any
        # text blocks and safely no-ops on plain strings.
        messages = body.get("messages", [])
        raw_content = messages[-1]["content"] if messages else ""
        text = _coerce_text(raw_content)
        has_image = _content_has_image(raw_content)
        image_attachments = _extract_image_attachments(raw_content) if has_image else []
        if not text and not image_attachments:
            if has_image:
                yield (
                    "**Couldn't read that image** -- only base64-embedded "
                    "images are supported right now. Please describe what's "
                    "in the image in words and send that instead."
                )
            else:
                yield "No message"
            return

        if has_image and not image_attachments:
            # An image block was present but couldn't be turned into an
            # attachment (e.g. not a base64 data URL) -- text still goes
            # through, but say so rather than silently dropping the image.
            yield (
                "_(Note: that image couldn't be relayed to the agent -- "
                "only the text below was sent.)_\n\n"
            )

        _ensure_orphan_reconcile(lambda: self.valves)
        await _emit_status(__event_emitter__, "Thinking...", done=False)
        if self.valves.COMPOSER_STATUS_BUTTON and not _initial_visible_text:
            # Cheap and idempotent: installs the composer Status button in the
            # tabs showing this chat (a no-op where it is already there). Once
            # per turn: the thinking-retry recursion skips it.
            _ensure_composer_watcher(lambda: self.valves)
            await _emit_composer_button(
                __event_emitter__,
                session_id=(__metadata__ or {}).get("session_id"),
                chat_id=(__metadata__ or {}).get("chat_id"),
                model_prefixes=_composer_note_model(body.get("model")),
            )
        pipe_log(f"Messages: {len(messages)}, last role: "
                 f"{messages[-1]['role'] if messages else 'NONE'}")

        # --- Get the persistent connection ---
        try:
            conn = await _get_gateway_connection(lambda: self.valves)
        except GatewayError as e:
            await _emit_status(__event_emitter__, "", done=True)
            yield f"**Gateway connection error:** {e}"
            return

        self._connection = conn

        # --- Derive stable session key ---
        if __metadata__:
            chat_id = (
                __metadata__.get("chat_id")
                or __metadata__.get("session_id")
                or __metadata__.get("conversation_id")
            )
            user_id = __metadata__.get("user_id", "unknown")
        else:
            chat_id = None
            user_id = "unknown"

        owui_origin_chat_id = chat_id
        owui_origin_user_id = user_id

        if not chat_id:
            chat_id = f"owui-{uuid.uuid4().hex[:12]}"
            pipe_log("WARNING: no chat_id in metadata, generated random:", chat_id)

        session_key = _owui_session_key(self.valves.AGENT_ID, user_id, chat_id)
        pipe_log(f"Session key: {session_key}")
        self._current_session_key = session_key

        # DIAG (2026-07-18, ELI-56): log the OWUI message_id + a short content
        # hash of the user text so a *re-fired / duplicate* completion for the
        # same message -- the suspected cause of the phantom "1-event, no-text"
        # turns (e.g. on a socket reconnect behind a reverse proxy) -- becomes
        # visible: two pipe() invocations with the SAME owui_msg_id / text_sha
        # close together is a smoking gun. Pure logging, no behavior change.
        _diag_md = __metadata__ or {}
        _diag_sha = hashlib.sha1(text.encode("utf-8", "replace")).hexdigest()[:8]
        self._diag_text_sha = _diag_sha
        pipe_log(
            f"  [diag] owui_msg_id={_diag_md.get('message_id')} "
            f"session_id={str(_diag_md.get('session_id'))[:12]} "
            f"text_sha={_diag_sha} text_preview={text[:48]!r}"
        )

        if turn is None:
            turn = _TurnState()
        turn.conn = conn
        turn.session_key = session_key
        turn.chat_id = owui_origin_chat_id
        turn.unsent = list(_send_texts) if _send_texts else [text]
        if owui_origin_chat_id and __event_emitter__:
            # Lets a later cancel ask the page whether it was Stop or Send
            # now. Idempotent in the page; fire-and-forget.
            try:
                await __event_emitter__(
                    {"type": "execute", "data": {"code": _INTENT_HOOK_JS}})
            except Exception as ex:
                pipe_log(f"  intent hook install failed: {ex!r}")
        # What actually went out in this turn's chat.send, for the
        # thinking-rejection retry to send again.
        sent_texts = list(turn.unsent)

        # A cancel of this session's previous response that arrived just
        # before this message is OWUI's "Send now" / interrupt, not a Stop:
        # take over what it left (see `park_cancelled_turn`): its run, still
        # running with its events buffered, and any message it had not sent
        # yet. Claimed this early because the model patch below can take
        # seconds and the grace window is short.
        adopted_run_id = None
        adopted_queue = None
        adopted_run_text = None
        claimed = await conn.claim_cancelled_turn(session_key)
        if claimed:
            if claimed["carried"]:
                turn.unsent = claimed["carried"] + turn.unsent
                pipe_log(
                    f"  carrying {len(claimed['carried'])} unsent message(s) "
                    "from the cancelled reply"
                )
            adopted_run_id = claimed["run_id"]
            adopted_queue = claimed["queue"]
            if adopted_run_id:
                adopted_run_text = claimed.get("run_text")
                turn.run_id = adopted_run_id
                turn.queue = adopted_queue
                turn.run_text = adopted_run_text
                pipe_log(
                    f"  new message right after a cancel: keeping run "
                    f"{adopted_run_id[:20]}... alive and continuing it in this "
                    "reply before sending the message"
                )

        # Apply the model with one retry. sessions.patch is idempotent (set the
        # session's model to a fixed value), and under a burst of near-
        # simultaneous messages the RPC can transiently time out or return a
        # racing/stale row (observed once at ~8 messages in 3s). A single retry
        # absorbs that blip instead of surfacing a scary "Model selection error"
        # to the user; a genuine misconfig still fails on the second attempt.
        # ELI-59 (fuller fix): the burst's patches are all redundant -- same
        # session, same model -- so (a) a per-session lock collapses them to one
        # in-flight RPC, and (b) a TTL cache of the last applied model lets the
        # waiters (and the next ~60s of same-model messages) skip the RPC
        # entirely. Failure invalidates the cache so nothing sticks.
        patch_err = None
        async with conn.model_patch_lock(session_key):
            if conn.model_patch_cached(session_key, model_override):
                pipe_log(
                    f"  model patch skipped (cached: "
                    f"{model_override or 'agent default'})"
                )
            else:
                for _patch_attempt in range(2):
                    try:
                        patch_resp = await _run_request(
                            conn, RUN_PATCH,
                            dict(key=session_key, model=model_override),
                            timeout=10
                        )
                        if not _model_patch_matches(model_override, patch_resp):
                            resolved_model = _resolved_model_key(patch_resp)
                            raise GatewayError(
                                "model override did not apply "
                                f"(wanted {model_override or 'agent default'}, "
                                f"got {resolved_model or 'agent default'})"
                            )
                        if model_override:
                            pipe_log(f"Applied model override: {model_override}")
                        else:
                            pipe_log("Cleared model override; using agent default")
                        conn.record_model_patched(session_key, model_override)
                        patch_err = None
                        break
                    except Exception as e:
                        patch_err = e
                        pipe_log(
                            f"  [diag] model patch attempt {_patch_attempt + 1} failed: "
                            f"{type(e).__name__}: {e!r}"
                        )
                        if _patch_attempt == 0:
                            await asyncio.sleep(0.5)
                if patch_err is not None:
                    conn.invalidate_model_patch(session_key)
        if patch_err is not None:
            await _emit_status(__event_emitter__, "", done=True)
            yield _explain_session_patch_failure(
                patch_err,
                model_override=model_override,
                agent_id=self.valves.AGENT_ID,
            )
            return

        # Tool cards for this session's runs whoever started them, including
        # this reply's own run after a reconnect (see `ensure_message_subscription`).
        await conn.ensure_message_subscription(session_key)

        # --- Concurrency: queue behind an active run, never steer-merge ---
        # A message that arrives while a run is active must become its OWN run,
        # not a steer-merge into the active run. Steer-merging (the gateway's
        # default when a run is active) returns a *phantom* runId that never
        # runs independently and emits no terminal -- the injected message just
        # merges into the active run -- so a bubble bound to it renders nothing
        # ("No visible response"). Instead we wait for the active run to reach a
        # definite terminal, then send this message as a fresh run with its own
        # runId + terminal. This matches OWUI's default "queue" UX and can never
        # strand the bubble. (This is a deterministic wait on the gateway's own
        # run status, not a heuristic timer.)
        # Whether the session already has an in-progress run must be decided
        # AUTHORITATIVELY by the gateway (sessions.describe), NOT by the
        # per-worker `active_run_id_for_session` registry: OWUI runs multiple
        # worker processes, so a run started while another worker handled the
        # previous turn is invisible to this worker's registry. That blind spot
        # let a concurrent message fall through to a fresh chat.send while the
        # gateway still had an active run -- the gateway steer-merged it and
        # returned a runId that instantly emits a single 'final' with no text,
        # so the bubble rendered nothing and the real answer leaked out as a
        # separate message. (Verified from live pipe logs 2026-07-18.)
        async def _list_has_active_run() -> bool | None:
            """Authoritative live run signal from sessions.list (hasActiveRun).
            Returns None if the probe fails or our session isn't in the list."""
            try:
                lst = await conn.send_request("sessions.list", dict(), timeout=8)
            except Exception as ex:
                pipe_log(f"  active-check sessions.list failed: {ex}")
                return None
            for s in (lst.get("sessions") or []):
                if s.get("key") == session_key:
                    return bool(s.get("hasActiveRun"))
            return None

        async def _session_run_active() -> bool:
            # Fast path: describe exposes a persisted `status`. When it names a
            # live run state we're done. But describe.status flips to 'done'
            # during a subagent-yield gap (the run is only suspended and will
            # resume -- ELI-56), so a non-active status is NOT conclusive:
            # confirm against sessions.list's authoritative hasActiveRun before
            # treating the session as free to send into.
            nonlocal session_thinking_ladder, session_model_key, session_runtime
            try:
                desc = await conn.send_request(
                    "sessions.describe", dict(key=session_key), timeout=8
                )
                row = desc.get("session") or {}
                status = row.get("status")
                session_runtime = (row.get("agentRuntime") or {}).get("id") or session_runtime
                # Harvest the thinking ladder from the describe we are already
                # making. This probe runs before every send, so the per-model
                # validation below costs no extra round trip, and piggybacking
                # rather than adding a describe of its own means the ladder can
                # never be fresher or staler than the run state it was read
                # alongside.
                #
                # Describe is a WEAK source and is treated as one. It resolves
                # the ladder with no model catalog in scope, so for a
                # catalog-gated model it reports the generic base profile
                # rather than the truth -- live, it advertised all 8 levels for
                # claude-cli/claude-opus-5, whose real ladder is ["off"]. Good
                # enough to seed the dropdown; not good enough to clamp a send
                # against once the Gateway itself has ruled.
                session_model_key = _session_model_key(row)
                ladder = _session_thinking_ladder(desc)
                if ladder:
                    session_thinking_ladder = ladder
                    _record_thinking_ladder(
                        ladder, model_key=session_model_key,
                        state_dir=getattr(self.valves, "STATE_DIR", ""))
                if row.get("activeRunId") or status in _ACTIVE_RUN_STATES:
                    return True
            except Exception as ex:
                # Describe failed: fall back to the list probe below, and if
                # that also fails, to the (per-worker, possibly-blind) registry.
                pipe_log(f"  active-check describe failed: {ex}")
                status = None
            list_active = await _list_has_active_run()
            if list_active is not None:
                active = _session_active_from_signals(status, list_active)
                if active and status not in _ACTIVE_RUN_STATES:
                    pipe_log(
                        f"  active-check: describe.status={status!r} but "
                        "list.hasActiveRun=True (subagent-yield gap; queueing)"
                    )
                return active
            return conn.active_run_id_for_session(session_key) is not None

        if (adopted_run_id and adopted_queue is None
                and not await _session_run_active()):
            # It finished during the cancel/re-send gap and nothing buffered
            # its events: nothing to continue. (With a parked queue the run's
            # tail and final are waiting in it, so it is always adopted.)
            pipe_log("  adopted run already ended; sending the message normally")
            adopted_run_id = None
            adopted_run_text = None
            turn.run_id = None
            turn.run_text = None
        if adopted_run_id:
            # Stream the rest of the adopted run into THIS reply. The message
            # itself is sent afterwards, as its own run, by the recursive call
            # at the end of this turn: sending it now would steer into the
            # live run, and the claude-cli runtime has no steering hook (the
            # gateway acks "started", then drops the message once the run
            # ends -- measured 2026-10-11).
            our_run_id = adopted_run_id
            self._current_run_id = our_run_id
            resolved_thinking = None
            pending_clamp_note = ""
            if adopted_queue is not None:
                queue = adopted_queue
            else:
                queue = conn.register_consumer(session_key, our_run_id)
            turn.queue = queue
            await _emit_status(
                __event_emitter__,
                "Continuing the current task; your message is next…",
                done=False,
            )
        else:
            # Serialize the queue-release -> chat.send -> run-registration critical
            # section per session. Two messages released from the queue at the same
            # instant would otherwise both send into the same idle window; the
            # gateway steer-merges the second into the first, which then renders
            # nothing ("no reply text"). Holding this lock only across the wait+send
            # (NOT the event loop below) means the next waiter re-checks AFTER our
            # run is registered and observes it active (sessions.list hasActiveRun),
            # so it waits its turn instead of racing us. Confirmed thundering-herd
            # phantom: two Captured runIds 10ms apart under a burst release (ELI-56).
            # NOTE: do NOT prepend a `/queue followup` directive here. On the
            # 2026.7.1 gateway that directive is NOT stripped from a device
            # chat.send -- it leaked verbatim into the delivered message.
            async with conn.session_send_lock(session_key):
                # Wait for the Gateway to push that the run settled
                # (`sessions.changed`, see `session_change_event`), re-reading
                # the authoritative state after each change. No poll, no
                # settle window and no ceiling (ELI-88): the old 30-minute
                # ceiling released a message into a run that was still going,
                # where the Gateway queued it and claude-cli dropped it. A
                # resume that starts right after a settle is caught after the
                # send instead (see `enqueued_not_started`). Stop cancels this
                # wait like any other.
                ever_active = False
                while True:
                    changed = conn.session_change_event(session_key)
                    if not await _session_run_active():
                        break
                    if not ever_active:
                        ever_active = True
                        pipe_log("Session has an active run (gateway-authoritative); "
                                 "queueing behind it")
                        await _emit_status(
                            __event_emitter__,
                            "Queued: waiting for the current run to finish…",
                            done=False,
                        )
                    await changed.wait()
                if ever_active:
                    pipe_log("  active run settled; sending queued message as its own run")

                # --- Send this message as its own fresh run (still holding the lock
                #     so the next waiter observes our run before deciding to send) ---
                # The OWUI message id in the run id ties the run to the reply
                # it streams into, so a reply orphaned by an Open WebUI restart
                # is matched to its run by identity (ELI-90, `_stub_turn`).
                reply_id = (__metadata__ or {}).get("message_id")
                idempotency_key = (pipe_run_id(chat_id, reply_id) if reply_id
                                   else f"msg-{chat_id}-{time.time()}")
                # Fit the requested level to what this session's model actually
                # supports. The dropdown is a union across models, so a level that
                # is real for one model can be unavailable here. Clamping is
                # downward only and always explained: silently answering at a level
                # other than the one asked for is worse than a short note, and
                # silently erroring out is worse still.
                #
                # A ladder the Gateway STATED (by rejecting a send) beats the one
                # describe reported, because describe answers this question without
                # a model catalog and overreports for catalog-gated models. This is
                # what makes the rejection cost one turn per model instead of one
                # turn every turn.
                #
                # Look up by `model_override` (the runtime-namespaced routing key,
                # e.g. "claude-cli/claude-opus-5") before `session_model_key` (the
                # vendor key describe resolves it to, e.g. "anthropic/claude-opus-5"
                # -- see `_RUNTIME_PROVIDER_NAMESPACES`). The Gateway's rejection
                # text names the model by its routing key, so that is where
                # `_record_thinking_ladder` files the authoritative entry; reading
                # back under the vendor key alone missed it every time and repeated
                # the same round-trip rejection (and its note) on every turn.
                _state_dir_valve = getattr(self.valves, "STATE_DIR", "")
                effective_ladder = (_read_model_thinking_ladder(model_override, _state_dir_valve)
                                    or _read_model_thinking_ladder(session_model_key, _state_dir_valve)
                                    or session_thinking_ladder)
                resolved_thinking, thinking_note = clamp_to_ladder(
                    requested_thinking, effective_ladder)
                # Held until `visible_message_text` exists below (it isn't defined
                # yet at this point in the turn) so the note that streams here also
                # ends up in the forced terminal snapshot -- otherwise it shows
                # while streaming and is gone after a reload.
                pending_clamp_note = ""
                if thinking_note:
                    pipe_log(f"thinking: {thinking_note}")
                    # Logged every time, shown once: the dropdown keeps the level
                    # selected, so an unchanged mismatch would otherwise stamp the
                    # same italic line above every answer in the chat.
                    if conn.should_announce_thinking_note(session_key, thinking_note):
                        pending_clamp_note = f"_{thinking_note}_\n\n"
                        yield pending_clamp_note
                # Listen before sending: the run's first events can arrive
                # before chat.send returns, and with no consumer they would go
                # to the turn writer, which takes this reply's message over
                # while the reply still streams (review 2af1 R12). The run id
                # is the idempotency key.
                queue = conn.register_consumer(session_key, idempotency_key)
                try:
                    send_resp = await _run_request(
                        conn, RUN_SEND,
                        _owui_chat_send_params(
                            session_key=session_key,
                            message="\n\n".join(t for t in turn.unsent if t),
                            idempotency_key=idempotency_key,
                            owui_chat_id=owui_origin_chat_id,
                            owui_user_id=owui_origin_user_id,
                            attachments=image_attachments,
                            thinking=resolved_thinking,
                        ),
                        timeout=30
                    )
                except asyncio.TimeoutError:
                    conn.unregister_consumer(session_key, idempotency_key, queue=queue)
                    await _emit_status(__event_emitter__, "", done=True)
                    yield "**Timeout:** Gateway did not respond to chat.send"
                    return
                except Exception as e:
                    conn.unregister_consumer(session_key, idempotency_key, queue=queue)
                    await _emit_status(__event_emitter__, "", done=True)
                    yield f"**Error sending message:** {e}"
                    return
                our_run_id = send_resp.get("runId") or idempotency_key
                self._current_run_id = our_run_id
                pipe_log(f"Captured runId: {our_run_id}")
                if our_run_id != idempotency_key:
                    conn.unregister_consumer(session_key, idempotency_key, queue=queue)
                    queue = conn.register_consumer(session_key, our_run_id)
                sent_texts = list(turn.unsent)
                turn.unsent = []
                turn.run_id = our_run_id
                turn.queue = queue
                turn.run_text = None
        # Tell the persistent connection which OWUI message this run streams
        # into, so a turn writer continues that message from a shadow renderer
        # if this inline turn ends before the run does (cancel, close, a
        # torn-down request). No-op without a stable message id. See
        # _turn_route_event (writer.py) and _TurnRenderer (gateway.py).
        owui_message_id = (__metadata__ or {}).get("message_id")
        conn.register_run_target(
            session_key, our_run_id, owui_origin_chat_id, owui_message_id,
            thinking=resolved_thinking,
        )
        # When the Gateway had admitted this reply's run (chat.send returned;
        # an adopted run already ran). An idle row read after it means the
        # run is over; one read before may show the previous run's settle
        # (review 2af1 N4).
        admitted_at = float("-inf") if adopted_run_id else time.monotonic()
        # A gap or a resync since: this run's own final and settle may be
        # lost, so another run's settle row may be the first sign it ended.
        signals_lost = False
        if adopted_run_id and adopted_queue is not None:
            conn.seed_run_renderer(session_key, our_run_id, queue,
                                   run_text=adopted_run_text)
        # Extracted once up front (not just at the terminal snapshot/auto-title
        # step further below) so the mid-run REST snapshot gate has a token to
        # use throughout the streaming loop, not only after it ends.
        bearer_token = _extract_request_bearer(__request__)

        # --- Consume events ---
        done = False
        event_count = 0
        text_yielded = False
        aborted = False
        first_event_arrived = False
        # The Gateway acks every chat.send with "started"; one that it queued
        # behind a run (or steered into one) instead gets a lone `chat` final
        # with no message as its first and only event.
        enqueued_not_started = False
        last_item_text = ""
        assistant_stream_text = ""
        # Everything the gateway has sent for this turn, including text the
        # ask-user buffer withheld. assistant_stream_text only tracks what was
        # FLUSHED, so it cannot be used to dedup a cumulative catch-all event
        # while a needs-input block is being held back (ELI-80).
        assistant_received_text = ""
        if adopted_run_text:
            # Continuing a run another reply started: its text baselines carry
            # over (see `park_cancelled_turn`), while what THIS reply shows,
            # `visible_message_text`, starts empty.
            assistant_received_text = adopted_run_text.get("received", "")
            assistant_stream_text = adopted_run_text.get("stream", "")
            last_item_text = adopted_run_text.get("item", "")
        # Offsets in `assistant_received_text` where events were lost (a
        # Gateway socket drop, see `_mark_event_gap`), and which OWUI reply
        # showed the run from which offset, so a lost chunk can be put back
        # into the reply it belongs to. Both are run-level and travel with an
        # adopted run.
        run_gaps: list[int] = list((adopted_run_text or {}).get("gaps", []))
        run_segments: list[dict] = list((adopted_run_text or {}).get("segments", []))
        if chat_id and owui_message_id:
            # The reply that showed the run until now has stopped streaming,
            # so OWUI has saved it; repairs that waited for it can go in.
            for seg in run_segments:
                for repair in _take_gap_repairs(chat_id, seg["message_id"]):
                    _schedule_gap_repair(conn, repair, streaming=False)
            run_segments.append({"message_id": owui_message_id,
                                 "start": len(assistant_received_text)})

        def reconcile_whole_text(whole: str) -> str | None:
            """After a gap, line the run's whole text up with what arrived
            and put each lost chunk back into the reply that showed it.
            Returns the text after the last received piece (the only new
            text), or None when there is no gap or `whole` does not line up
            (an item carrying one segment, not the whole run), which leaves
            the gaps pending for the next whole text."""
            if not run_gaps or not chat_id:
                return None
            aligned = _align_whole_text(whole, assistant_received_text, run_gaps)
            if aligned is None:
                return None
            tail, missing = aligned
            run_gaps.clear()
            for offset, chunk in missing:
                seg = next((sg for sg in reversed(run_segments) if sg["start"] <= offset),
                           run_segments[0] if run_segments else None)
                if seg is None:
                    continue
                nxt = next((sg["start"] for sg in run_segments if sg["start"] > seg["start"]),
                           len(assistant_received_text))
                repair = {
                    "user_id": owui_origin_user_id, "chat_id": chat_id,
                    "message_id": seg["message_id"], "chunk": chunk,
                    "before": assistant_received_text[offset:min(offset + _GAP_ANCHOR_CHARS, nxt)],
                    "after": assistant_received_text[max(seg["start"], offset - _GAP_ANCHOR_CHARS):offset],
                }
                pipe_log(f"  event gap: {len(chunk)} chars lost at offset {offset}; "
                         f"repairing message {seg['message_id'][:8]}...")
                _schedule_gap_repair(conn, repair,
                                     streaming=seg["message_id"] == owui_message_id)
            return tail
        visible_message_text = _initial_visible_text + pending_clamp_note
        had_tool_block = False
        # toolCallIds announced to OWUI as `function_call` items that have
        # not been completed by a matching result item yet. Anything left
        # here when the run ends would render as a spinner forever.
        pending_tool_calls: set[str] = set()
        # toolCallId of the `function_call` item yielded most recently, held
        # only while it is still the LAST item in OWUI's output list; anything
        # else we yield clears it. A failed call can only be relabeled (❌ in
        # the card name) while it is last, because the relabel event replaces
        # by index and we send none -- see `_tool_call_error_relabel_event`.
        relabelable_tool_call: str | None = None
        pending_prompt_text = ""
        pending_media_text = ""
        last_snapshot_text = ""
        last_snapshot_time = 0.0
        snapshot_interval_s = 1.0
        snapshot_min_delta_chars = 250
        # REST-API mid-run snapshot (bridge-rehydration-rest-snapshot-verify,
        # confirmed safe 2026-08-26): a parallel, throttled persistence path
        # for the plain assistant-text stream, which lost the `replace`-based
        # snapshot in 6e5f372 and cannot regain it that way -- see
        # REHYDRATION-PLAINTEXT-FIX-PROPOSAL.md for why every replace-based
        # variant of this (P17/P19/P23/P25/P27) is unsafe at any throttle.
        # This instead POSTs straight to the chat's DB row, which never
        # broadcasts to the live client, so it cannot race the delta stream.
        last_rest_snapshot_text = ""
        last_rest_snapshot_time = 0.0
        rest_snapshot_interval_s = 2.5
        rest_snapshot_task: asyncio.Task | None = None
        # OWUI 0.12+ discards this write and rehydrates reloads itself
        # (`_owui_owns_inflight_message`), so don't schedule it at all there.
        rest_snapshot_enabled = not _owui_owns_inflight_message()
        max_events_without_text = 5000
        queued_shown = False
        # An interrupted run is not continued here: its message goes to the
        # turn writer, whose settled row decides who continues it (DESIGN 2.7).
        handed_over = False
        # A reply with no Open WebUI message (an API request) has nothing to
        # hand over: it applies the owner rule itself, in its own stream
        # (review 2af1 R14). Set while it waits for the interrupted run's row.
        awaiting_owner = False
        owner_notice_before = False
        owner_resumes = 0
        owner_run = None

        def await_owner() -> None:
            nonlocal awaiting_owner, owner_notice_before, owner_run
            awaiting_owner, owner_notice_before = True, conn._stop_notice_seen
            owner_run = conn._awaiting_owner[session_key] = our_run_id
            pipe_log(f"  run {our_run_id[:24]}... interrupted, no message to hand over: "
                     "its row decides here")
            spawn_background(conn.push_row(session_key))

        async def owner_step(row: dict):
            """One row while the reply waits for its run's owner (DESIGN 2.7):
            ("switch", run, queue) to continue in the Gateway's recovery run
            or a resume sent here, ("end", note) to finish, None to wait."""
            nonlocal owner_resumes
            decision = next_continuation(row, owner_notice_before, owner_resumes)
            if decision == "gateway":
                # The Gateway recovers it as a run whose turn names this one
                # (rule E); until that turn is committed, the next row looks again.
                try:
                    messages = (await conn.session_history(session_key, limit=50,
                                                           max_chars=200)).get("messages") or []
                except Exception as ex:
                    pipe_log(f"  chat.history for the recovery failed: {ex!r}")
                    return None
                rec = next((r for r, _t in _history_user_turns(messages)
                            if recovery_source_run(messages, r) == our_run_id), None)
                if rec is None:
                    return None
                pipe_log(f"  following the Gateway's recovery run {rec[:24]}...")
                return ("switch", rec, conn.register_consumer(session_key, rec))
            if decision == "wait":
                return None
            if decision == "resume":
                key = f"msg-{chat_id}-resume-{time.time()}"
                resume_queue = conn.register_consumer(session_key, key)
                try:
                    resp = await _run_request(conn, RUN_SEND, _owui_chat_send_params(
                        session_key=session_key, message=_resume_directive(visible_message_text, text),
                        idempotency_key=key, owui_chat_id=owui_origin_chat_id,
                        owui_user_id=owui_origin_user_id, thinking=resolved_thinking), timeout=30)
                except Exception as ex:
                    # The Gateway is closing: its next hello reads the row again.
                    conn.unregister_consumer(session_key, key, queue=resume_queue)
                    pipe_log(f"  resume refused ({ex}); trying again on the next row")
                    return None
                owner_resumes += 1
                new_run = resp.get("runId") or key
                if new_run != key:
                    conn.unregister_consumer(session_key, key, queue=resume_queue)
                    resume_queue = conn.register_consumer(session_key, new_run)
                pipe_log(f"  resumed as {new_run[:32]}... ({owner_resumes}/{MAX_TURN_RESUMES})")
                return ("switch", new_run, resume_queue)
            if turn_owner(row, owner_notice_before) == "pipe":
                return ("end", TURN_CUT_OFF_NOTE)
            if (row or {}).get("status") in ("failed", "timeout") and row.get("lastRunError"):
                return ("end", f"**Error:** {row['lastRunError']}")
            return ("end", None)

        async def recover_from_transcript() -> str | None:
            """The run's text read back: by its run id, else by its user text,
            which only a run seen here may use. With nothing of it seen, the
            session's last reply may be another run's (review 2af1 N4)."""
            try:
                hist = await conn.session_history(session_key, limit=RUN_TEXT_HISTORY_LIMIT)
                found, whole = _history_text_for_run(hist, our_run_id)
                if found and whole:
                    return whole
            except Exception as ex:
                pipe_log(f"  recovery by run id: chat.history failed: {ex!r}")
            if not first_event_arrived:
                pipe_log("  recovery: nothing of this run seen, no text by its id")
                return None
            return await _recover_turn_text(conn, session_key, text)

        async def settled_tail(row: dict, closer_only: bool = False) -> str | None:
            """What this reply still owes once its run settled with no final
            event here: the run's text after what arrived (its closing message
            in the transcript), or, for a run that showed nothing, why.
            `closer_only`: the session is busy, maybe with a later run, so
            only this run's own closer says it ended; None without one."""
            try:
                hist = await conn.session_history(session_key, limit=RUN_TEXT_HISTORY_LIMIT)
            except Exception as ex:
                pipe_log(f"  settled run: chat.history failed: {ex!r}")
                hist = None
            found, whole = _history_text_for_run(hist, our_run_id) if hist else (False, None)
            if found and whole:
                gap_tail = reconcile_whole_text(whole)
                if gap_tail is not None:
                    return gap_tail
                if whole.startswith(assistant_received_text):
                    return whole[len(assistant_received_text):]
                return "" if text_yielded else whole
            if closer_only:
                return "" if found else None
            if text_yielded:
                return ""
            status = row.get("status")
            if status in ("cancelled", "killed"):
                return "**Stopped.**"
            if status in ("failed", "timeout"):
                err = row.get("lastRunError")
                return f"**Error:** {err}" if err else "**Failed:** the run did not complete."
            return await recover_from_transcript() or ""

        def record_visible_chunk(chunk: str):
            nonlocal visible_message_text, relabelable_tool_call
            if chunk:
                visible_message_text += chunk
                # Text either extends OWUI's last output item or appends a new
                # `message` one (`middleware.py:4452`); either way the
                # `function_call` we were holding is no longer last, so an
                # index-less relabel would now overwrite this text instead.
                relabelable_tool_call = None

        async def maybe_emit_snapshot(*, force: bool = False):
            nonlocal last_snapshot_text, last_snapshot_time
            # ELI-82 instrumentation. A forced snapshot is the pipe's last
            # chance to persist trailing text, and it used to be completely
            # silent: on the 2026-08-01 incident the final 3417-char block
            # vanished and there was no way to tell whether this ever ran, let
            # alone with what. Only `force` calls are logged, so the mid-stream
            # cadence stays quiet. Log-only, no behaviour change.
            if force:
                pipe_log(
                    f"  snapshot(force): visible={len(visible_message_text)} "
                    f"last={len(last_snapshot_text)} "
                    f"delta={len(visible_message_text) - len(last_snapshot_text)}"
                )
            if not visible_message_text or visible_message_text == last_snapshot_text:
                if force:
                    pipe_log(
                        "  snapshot(force): SKIPPED "
                        + ("visible_message_text empty" if not visible_message_text
                           else "identical to last snapshot")
                    )
                return
            now = time.time()
            if (
                not force
                and last_snapshot_text
                and now - last_snapshot_time < snapshot_interval_s
                and len(visible_message_text) - len(last_snapshot_text) < snapshot_min_delta_chars
            ):
                return
            await _emit_message_snapshot(__event_emitter__, visible_message_text)
            last_snapshot_text = visible_message_text
            last_snapshot_time = now
            if force:
                pipe_log(f"  snapshot(force): EMITTED {len(visible_message_text)} chars")

        def maybe_start_rest_snapshot():
            """Throttled gate for the REST-API mid-run snapshot.

            Fire-and-forget (background task): a GET+POST round trip inline
            in the streaming path would stall the live delta yield every
            time the throttle opens. Guarded so at most one is in flight at
            once, and stops firing once the turn hits terminal flush (`done`
            True) -- matching this project's established convention
            (19e9fd7/2092e19) of never doing anything new right at the
            natural end of a message, even though this path is confirmed
            safe from the replace-vs-delta race that motivated that
            convention (bridge-rehydration-rest-snapshot-verify, 2026-08-26).
            """
            nonlocal last_rest_snapshot_text, last_rest_snapshot_time, rest_snapshot_task
            if done or not owui_message_id or not rest_snapshot_enabled:
                return
            if not visible_message_text or visible_message_text == last_rest_snapshot_text:
                return
            now = time.time()
            if (
                last_rest_snapshot_text
                and now - last_rest_snapshot_time < rest_snapshot_interval_s
            ):
                return
            if rest_snapshot_task is not None and not rest_snapshot_task.done():
                return
            snapshot_text = visible_message_text
            last_rest_snapshot_text = snapshot_text
            last_rest_snapshot_time = now
            rest_snapshot_task = asyncio.create_task(
                self._rest_snapshot_message(
                    owui_origin_chat_id, owui_message_id, snapshot_text, bearer_token,
                )
            )

        async def maybe_answer_user_input(prompt_text: str) -> UserInputResult:
            """Ask the user via an OWUI modal and deliver their answer.

            See UserInputResult for the meaning of the return value. Crucially,
            a delivered answer that steers the *same* run (no new runId) still
            returns handled=True, so the caller suppresses the raw prompt text
            instead of leaking it into the chat.
            """
            if not _is_user_input_prompt(prompt_text):
                return UserInputResult(False, None)
            reconnect_user_id = (
                owui_origin_user_id
                if owui_origin_user_id and owui_origin_user_id != "unknown"
                else None
            )
            try:
                answer = await _ask_user_input_modal(
                    __event_call__,
                    prompt_text,
                    owui_user_id=reconnect_user_id,
                    owui_chat_id=owui_origin_chat_id,
                    owui_message_id=(__metadata__ or {}).get("message_id"),
                    owui_session_id=(__metadata__ or {}).get("session_id"),
                    __event_emitter__=__event_emitter__,
                )
            except Exception as ex:
                pipe_log(f"  user input modal failed; falling back to chat prompt: {ex}")
                answer = None
            if answer is None:
                pipe_log("  user input modal cancelled or empty answer")
                return UserInputResult(False, None)
            pipe_log("  user input answered via OWUI modal")
            await _emit_status(__event_emitter__, "Sending answer...", done=False)
            # The answer continues this reply: its run id names it (ELI-100 2.2).
            idempotency_key = (pipe_run_id(chat_id, owui_message_id, "input") if owui_message_id
                               else f"user-input-{chat_id}-{time.time()}")
            # Listen before sending, as for the first send (R12): the answer
            # run's first events can arrive before chat.send returns, and with
            # no consumer and no target they would open a second writer on
            # this reply's message (review 2af1 N6).
            answer_queue = conn.register_consumer(session_key, idempotency_key)
            conn.continue_run_target(session_key, our_run_id, idempotency_key, shown=False)

            def unlisten():
                conn.unregister_consumer(session_key, idempotency_key, queue=answer_queue)
                conn.continue_run_target(session_key, idempotency_key, our_run_id, shown=False)
            try:
                send_resp = await _run_request(
                    conn, RUN_SEND,
                    _owui_chat_send_params(
                        session_key=session_key,
                        message=answer,
                        idempotency_key=idempotency_key,
                        owui_chat_id=owui_origin_chat_id,
                        owui_user_id=owui_origin_user_id,
                    ),
                    timeout=30,
                )
            except Exception as ex:
                # Delivery failed: report not-handled so the caller falls back
                # to showing the prompt text (better than a silent stall).
                pipe_log(f"  sending answer back failed: {ex}")
                unlisten()
                return UserInputResult(False, None)
            new_run_id = send_resp.get("runId") or None
            if new_run_id != idempotency_key:
                unlisten()  # steered into the live run, or renamed: as before
                answer_queue = None
            else:
                nonlocal admitted_at, signals_lost
                admitted_at, signals_lost = time.monotonic(), False
            await _emit_status(__event_emitter__, "Answer sent; continuing...", done=False)
            if new_run_id:
                pipe_log(f"  answer sent, new runId: {new_run_id[:20]}...")
            else:
                pipe_log("  answer sent, steering into active run (no new runId)")
            return UserInputResult(True, new_run_id, prompt_text=prompt_text, answer=answer,
                                   queue=answer_queue)

        def switch_to_answer_run(answer_res: UserInputResult) -> None:
            """The reply continues in the answer run (R9). Its target moved
            before the send when its consumer was registered then (N6); the
            question run was shown to its end either way."""
            if answer_res.queue is not None:
                conn.mark_delivered_live(session_key, our_run_id)
            else:
                conn.continue_run_target(session_key, our_run_id, answer_res.new_run_id)

        adopt_new_run = True
        try:
            while adopt_new_run:
                adopt_new_run = False
                # A new run's text is a new message item (review 2af1 F4).
                fence_item_start = len(assistant_stream_text)
                try:
                    while not done:
                        # No silence timer: a quiet queue is a long tool call or
                        # model thinking as often as a dead run. The run's own
                        # signals end the reply: its terminal event, its settle
                        # row (below), a Gateway restart (handed over).
                        msg = await queue.get()

                        if msg.get("type") == _ROW_MARKER_TYPE and awaiting_owner:
                            step = await owner_step(msg.get("row") or {})
                            if step is None:
                                continue
                            if step[0] == "end":
                                if step[1]:
                                    note = f"\n\n{step[1]}" if visible_message_text.strip() else step[1]
                                    record_visible_chunk(note)
                                    yield note
                                    text_yielded = True
                                done = True
                            else:
                                # The reply continues in the run that continues
                                # this one: its events (held until now) and its end.
                                _kind, new_run, new_queue = step
                                conn.unregister_consumer(session_key, our_run_id, queue=queue)
                                queue, our_run_id = new_queue, new_run
                                self._current_run_id = our_run_id
                                turn.run_id, turn.queue = our_run_id, queue
                                admitted_at, signals_lost = time.monotonic(), False
                            awaiting_owner = False
                            conn.stop_awaiting_owner(session_key, owner_run)
                            continue

                        if msg.get("type") == _ROW_MARKER_TYPE:
                            row = msg.get("row") or {}
                            if row.get("status") == "queued" and not first_event_arrived \
                                    and not queued_shown:
                                queued_shown = True
                                await _emit_status(
                                    __event_emitter__,
                                    "Waiting -- your message is queued behind an "
                                    "active response...",
                                    done=False,
                                )
                            # Read after this run was admitted, an idle session
                            # means it is over, whichever run settled last. That
                            # is the end signal once its own may have been lost
                            # in a gap (review 2af1 N3). A row read before the
                            # admission shows nothing about it (N4).
                            admitted = msg.get("read_at", time.monotonic()) >= admitted_at
                            if admitted and msg.get("resync"):
                                signals_lost = True
                            tail = None
                            if row.get("hasActiveRun") is False and (
                                    row.get("lastRunId") == our_run_id
                                    or (admitted and signals_lost)):
                                # The run settled while its terminal event never
                                # reached this reply (dropped frame, socket gap).
                                # Its transcript has what was lost.
                                pipe_log(f"  run settled (row status {row.get('status')}, "
                                         f"last run {str(row.get('lastRunId'))[:24]}) without its final")
                                tail = await settled_tail(row)
                            elif row.get("hasActiveRun") and msg.get("resync") and admitted:
                                # After a gap the session is busy, maybe with a
                                # later run: this run's closer says it ended.
                                tail = await settled_tail(row, closer_only=True)
                                if tail is not None:
                                    pipe_log("  run closed in the transcript during a gap")
                            if tail is not None:
                                if tail:
                                    record_visible_chunk(tail)
                                    yield tail
                                    text_yielded = True
                                    await maybe_emit_snapshot(force=True)
                                done = True
                            continue

                        if msg.get("type") == _RESTART_MARKER_TYPE:
                            # A new Gateway process: the run may be recovered
                            # by it (a crash leaves its row `running`) or need
                            # a resume. Its row decides, in the turn writer.
                            if conn.hand_over_run(session_key, our_run_id,
                                                  thinking=resolved_thinking, read_row=True):
                                handed_over = done = True
                            elif awaiting_owner:
                                spawn_background(conn.push_row(session_key))
                            elif not owui_message_id:
                                await_owner()
                            else:
                                pipe_log("  Gateway restarted; no message to hand over, waiting")
                            continue

                        if msg.get("type") == _GAP_MARKER_TYPE:
                            signals_lost = True
                            run_gaps.append(len(assistant_received_text))
                            pipe_log(f"  event gap at offset {len(assistant_received_text)} "
                                     "(Gateway socket dropped)")
                            continue

                        event_count += 1
                        first_event_arrived = True
                        payload = msg.get("payload", {})
                        stream = payload.get("stream")
                        data = payload.get("data", {})
                        name = data.get("name", "")
                        phase = data.get("phase", "")
                        state = payload.get("state", "")
                        if (event_count == 1 and state == "final" and msg.get("event") == "chat"
                                and not payload.get("message")):
                            enqueued_not_started = True

                        # --- P16: Double-check session/run match ---
                        evt_session = payload.get("sessionKey", "")
                        evt_run_id = payload.get("runId", "")
                        if evt_session and evt_session != session_key:
                            pipe_log(f"  queue delivered wrong session: {evt_session[:40]}...")
                            continue
                        if evt_run_id and evt_run_id != our_run_id:
                            pipe_log(f"  queue delivered wrong run: {evt_run_id[:20]}...")
                            continue

                        # --- Completion signals (multiple sources) ---
                        err = (str(data.get("error", "unknown"))
                               if stream == "lifecycle" and phase == "error" else "")
                        aborted_run = state == "aborted" or data.get("aborted") is True
                        # DESIGN 2.7: an outside kill of the CLI, or an abort
                        # after a shutdown notice, may be continued by the
                        # Gateway (a `running` row) or by a resume. The reply
                        # decides neither: the turn writer takes the message
                        # and the settled row picks the owner. Without a
                        # message to hand over, it ends here like any error.
                        if _EXTERNAL_KILL_RE.search(err) or (aborted_run and conn._shutdown_seen):
                            if conn.hand_over_run(session_key, our_run_id, thinking=resolved_thinking):
                                handed_over = done = True
                                continue
                            if not owui_message_id:
                                await_owner()
                                continue
                        if stream == "lifecycle" and phase == "end":
                            done = True
                            pipe_log("  lifecycle end -> done")
                        elif err:
                            yield f"\n\n**Error:** {err}"
                            done = True
                            pipe_log("  lifecycle error -> done")
                        if state in ("final", "cancelled", "error", "aborted") or aborted_run:
                            done = True
                            pipe_log(f"  payload state='{state}' aborted={aborted_run} -> done")

                        # --- Assistant text stream ---
                        if stream == "assistant":
                            raw_delta = data.get("delta")
                            if raw_delta:
                                delta = raw_delta
                                assistant_received_text += raw_delta
                            else:
                                # Some providers (observed with claude-cli-backed
                                # Opus/Sonnet overrides) send a final catch-all event
                                # with no `delta` but a `text` field holding the full
                                # cumulative reply rather than a fresh chunk. Treating
                                # it as always-new re-sent the whole message a second
                                # time. Diff it against what's already been streamed,
                                # same as the item-event dedup below.
                                raw_text = data.get("text") or ""
                                gap_tail = reconcile_whole_text(raw_text) if raw_text else None
                                before = _item_delta_text(
                                    raw_text, "", assistant_received_text
                                ) if raw_text else ""
                                delta = (
                                    _suppress_already_shown(gap_tail, visible_message_text)
                                    if gap_tail is not None
                                    else _catch_all_delta(
                                        raw_text, assistant_received_text, visible_message_text
                                    )
                                )
                                if before and not delta:
                                    pipe_log(
                                        "  suppressed duplicate catch-all assistant "
                                        f"text ({len(before)} chars already received)"
                                    )
                                assistant_received_text += delta
                            if delta:
                                # Filter Sender metadata
                                if (
                                    "Sender (untrusted metadata)" in delta
                                    or "UnTrustedMetadata" in delta
                                ):
                                    pipe_log("  filtered metadata block")
                                    continue
                                # Hold back text while it (or a fresh line within
                                # it) is still ambiguous whether it opens with a
                                # needs-input trigger phrase. Real token-by-token
                                # streaming delivers that phrase a few characters at
                                # a time, so checking each raw delta in isolation
                                # (as used to happen here) essentially never
                                # matches -- only the buffered, accumulated text can
                                # be checked reliably. Resolved once the run ends
                                # (see the `else:` clause below) or as soon as the
                                # buffered text diverges from every trigger.
                                # A fence the shown text of this message item left open
                                # makes a marker a quote (ELI-107); held text always
                                # starts outside one. A fence never spans items.
                                flush_text, pending_prompt_text = (
                                    _advance_input_prompt_buffer(
                                        pending_prompt_text, delta,
                                        _fence_open_after(assistant_stream_text[fence_item_start:]))
                                )
                                if not flush_text:
                                    continue
                                delta = flush_text

                                # Hold back a MEDIA: directive until its filename is
                                # confirmed complete (terminated by whitespace) -- a
                                # real streaming provider can split "MEDIA:filename.png"
                                # across multiple deltas at any point, including
                                # mid-filename or mid-prefix. See _advance_media_buffer.
                                delta, pending_media_text = _advance_media_buffer(
                                    pending_media_text, delta
                                )
                                if not delta:
                                    continue

                                text_yielded = True
                                # No snapshot here, regardless of whether tool blocks
                                # exist earlier in the message. A `replace` event sets
                                # the full message content; if it lands on (or near)
                                # the complete final text right before the generator
                                # naturally finishes, OWUI double-saves -- the
                                # `replace` writes it once, then the generator's own
                                # accumulated streamed yields write the same content
                                # again on top. This isn't only a risk for the literal
                                # last chunk: since these snapshots are throttled by
                                # time/char thresholds rather than tied to "a tool
                                # block was just added", they keep firing throughout
                                # any plain-text tail after a tool call and will
                                # eventually land close enough to the end to trigger
                                # the same duplicate. The one snapshot that's actually
                                # safe is the forced one taken right when a tool
                                # block itself is yielded (still partial content by
                                # definition, since the block was just added) -- see
                                # the `stream == "tool"` / phase == "result" handler.
                                # See P17 / P19 / P23 / P24 / ELI-9 for the history of
                                # this recurring bug.
                                # MEDIA: resolution
                                if "MEDIA:" in delta:
                                    resolved, handled = await _resolve_media_text(
                                        delta,
                                        valves=self.valves,
                                        __request__=__request__,
                                        __event_emitter__=__event_emitter__,
                                    )
                                    if handled:
                                        pipe_log("  resolved MEDIA: directive")
                                        # A writer that takes this reply over
                                        # shows the same image (review 2af1 R4).
                                        conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                               delta, resolved)
                                        record_visible_chunk(resolved)
                                        yield resolved
                                        await maybe_emit_snapshot()
                                        continue
                                assistant_stream_text += delta
                                record_visible_chunk(delta)
                                yield delta
                                # NOTE: do NOT emit a `replace` snapshot per text
                                # delta here. A mid-stream `replace` carrying the
                                # full accumulated text makes OWUI's own
                                # `_suppress_already_shown` treat the *continuing*
                                # delta stream as already-shown and suppress it --
                                # the visible stream freezes mid-message (regression
                                # 2026-07-18, exactly the P23/P25 hazard). Mid-run
                                # DB back-sync for this path goes through the REST
                                # snapshot gate instead (`maybe_start_rest_snapshot`,
                                # bridge-rehydration-rest-snapshot-verify), which
                                # writes the chat row directly and never broadcasts
                                # to the live client, so it cannot trigger that
                                # suppression.
                                maybe_start_rest_snapshot()

                        # --- Assistant text carried by item/preamble events ---
                        if stream == "item":
                            item_text = _item_assistant_text(data)
                            if item_text:
                                answer_res = await maybe_answer_user_input(item_text)
                                if answer_res.handled:
                                    detail_block = ""
                                    if answer_res.answer:
                                        detail_block = _ask_user_detail_block(
                                            answer_res.prompt_text or item_text, answer_res.answer
                                        )
                                        record_visible_chunk(detail_block)
                                        yield detail_block
                                        await maybe_emit_snapshot(force=True)
                                    conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                           answer_res.prompt_text or item_text,
                                                           detail_block)
                                    if answer_res.new_run_id and answer_res.new_run_id != our_run_id:
                                        pipe_log(f"  needs-input handled, switching to run {answer_res.new_run_id[:20]}...")
                                        # The answer run continues this reply (R9).
                                        switch_to_answer_run(answer_res)
                                        conn.unregister_consumer(session_key, our_run_id, queue=queue)
                                        queue = answer_res.queue or conn.register_consumer(
                                            session_key, answer_res.new_run_id)
                                        our_run_id = answer_res.new_run_id
                                    done = False
                                    last_item_text = item_text
                                    continue
                                gap_tail = reconcile_whole_text(item_text)
                                item_delta = gap_tail if gap_tail is not None else _item_delta_text(
                                    item_text, last_item_text, assistant_stream_text
                                )
                                last_item_text = item_text
                                # Same safety net as the assistant-stream catch-all
                                # above, and for the same reason: `last_item_text`/
                                # `assistant_stream_text` can drift from
                                # `visible_message_text`, and this call site has the
                                # exact same `_item_delta_text` fallback that
                                # re-yields the entire text when the prefix check
                                # fails (P27).
                                item_delta = _suppress_already_shown(item_delta, visible_message_text)
                                # Unlike the assistant-stream path, item events
                                # carry no `_advance_input_prompt_buffer` guard,
                                # so a needs-input prompt that arrives here (and
                                # wasn't handled into a modal above) would leak
                                # its raw "OpenClaw needs input:" marker line.
                                # Strip it defensively.
                                if _is_user_input_prompt(item_delta):
                                    stripped = _strip_input_marker_line(item_delta)
                                    conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                           item_delta, stripped)
                                    item_delta = stripped
                                if item_delta:
                                    text_yielded = True
                                    pipe_log("  yielded text from item event")
                                    record_visible_chunk(item_delta)
                                    yield item_delta

                        # --- Tool call events ---
                        if stream == "tool":
                            if phase == "start":
                                tool_call_id = data.get("toolCallId", "")
                                args = json.dumps(data.get("args", {}))
                                if tool_call_id:
                                    self._active_tool_args[tool_call_id] = args
                                pipe_log(f"  Tool start: {name}")
                                if tool_call_id:
                                    # Protocol switch, not text: this dict becomes a
                                    # `function_call` item in OWUI's own output list,
                                    # which renders as a live spinner until its
                                    # matching result item arrives. Deliberately NOT
                                    # recorded into `visible_message_text` -- it is
                                    # not part of the message text, and the snapshot
                                    # path must not duplicate it as markdown.
                                    pending_tool_calls.add(tool_call_id)
                                    yield _tool_call_started_event(name, tool_call_id, args)
                                    # Text after a tool call is a new message item.
                                    fence_item_start = len(assistant_stream_text)
                                    # Now the last item in OWUI's output list,
                                    # so a relabel on failure can target it
                                    # without an output_index. A second start
                                    # (parallel calls) displaces the first,
                                    # which then falls back to the banner.
                                    relabelable_tool_call = tool_call_id
                                await _emit_status(
                                    __event_emitter__,
                                    f"Running {name}...",
                                    done=False,
                                )

                            elif phase == "result":
                                result = data.get("result", {})
                                result_str = json.dumps(result) if not isinstance(result, str) else result
                                tool_call_id = data.get("toolCallId", "")
                                # The Gateway already tells us the outcome
                                # (`execute.runtime`'s emitCliToolResult); the
                                # card just never showed it.
                                is_error = data.get("isError") is True
                                stored_args = self._active_tool_args.pop(tool_call_id, None)
                                args_str = stored_args or json.dumps(data.get("args", {}))
                                if (
                                    adopted_run_id and tool_call_id
                                    and tool_call_id not in pending_tool_calls
                                ):
                                    # Started under the reply that was
                                    # interrupted, so this reply has no card
                                    # for the result to complete: open one.
                                    pending_tool_calls.add(tool_call_id)
                                    yield _tool_call_started_event(name, tool_call_id, args_str)
                                    relabelable_tool_call = tool_call_id
                                pipe_log(
                                    f"  Tool result: {name} ({len(result_str)} chars)"
                                    f"{' [error]' if is_error else ''}"
                                )
                                if is_error:
                                    # Log the gate decision, always. Without it a
                                    # skipped relabel is invisible, which is
                                    # indistinguishable from the error branch never
                                    # running at all. That ambiguity is exactly why
                                    # ELI-75 read as a missing feature for months
                                    # while the branch was in fact running and only
                                    # the relabel was being skipped.
                                    pipe_log(
                                        f"  relabel gate: call={tool_call_id!r} "
                                        f"held={relabelable_tool_call!r} "
                                        + ("FIRE" if tool_call_id
                                           and relabelable_tool_call == tool_call_id
                                           else "SKIP")
                                    )
                                    if tool_call_id and relabelable_tool_call == tool_call_id:
                                        # Mutates the started item's `name`
                                        # field in place via OWUI's generic
                                        # "<field>.done" handler: the
                                        # collapsed row becomes "View Result
                                        # from **<name> ❌**", and OWUI
                                        # persists it, so the mark survives a
                                        # reload.
                                        yield _tool_call_error_relabel_event(name)
                                    result_str = _tool_error_banner(result_str)
                                relabelable_tool_call = None
                                if tool_call_id:
                                    # Completes the item yielded at start: the shared
                                    # call_id is what flips that card to done and
                                    # reveals its Output. No snapshot needed -- the
                                    # backend folds this into the output list it
                                    # already persists and re-emits.
                                    pending_tool_calls.discard(tool_call_id)
                                    yield _tool_call_result_event(tool_call_id, result_str)
                                else:
                                    # No toolCallId means there is nothing to pair a
                                    # result item to, so fall back to the markdown
                                    # card -- the same one the shadow renderer emits.
                                    tool_block = _render_tool_result_block(
                                        name, tool_call_id, args_str, result_str,
                                        data.get("meta", ""),
                                    )
                                    had_tool_block = True
                                    record_visible_chunk(tool_block)
                                    yield tool_block
                                    await maybe_emit_snapshot(force=True)
                                await _emit_status(
                                    __event_emitter__,
                                    f"{name} done",
                                    done=True,
                                )

                        # --- Item events (progress) ---
                        if stream == "item":
                            pipe_log(f"  Item: kind={data.get('kind','')} "
                                     f"status={data.get('status','')} "
                                     f"title={str(data.get('title',''))[:50]}")

                        if not text_yielded and event_count >= max_events_without_text:
                            recovered = await recover_from_transcript()
                            if recovered:
                                pipe_log("  recovered assistant text after event cap")
                                text_yielded = True
                                record_visible_chunk(recovered)
                                yield recovered
                                await maybe_emit_snapshot(force=True)
                            else:
                                timeout_text = (
                                    "\n\n**Timeout:** The run emitted too many progress "
                                    "events without assistant text. The pipe kept the "
                                    "run from ending as `(no response)`, but the Gateway "
                                    "did not provide visible output."
                                )
                                record_visible_chunk(timeout_text)
                                yield timeout_text
                                await maybe_emit_snapshot(force=True)
                                text_yielded = True
                            done = True

                except (asyncio.CancelledError, GeneratorExit) as stop:
                    # OWUI ended this response: the Stop button, or Send now /
                    # interrupt, which stop it the same way and then send a
                    # new message. It arrives as a task cancel when we are
                    # awaiting, or as a generator close when we are suspended
                    # at a yield (OWUI busy with the last chunk), which is
                    # most of the time while text streams. Handling only the
                    # cancel left the close path with no abort, no handover
                    # and the reply's own unsent message lost (2026-10-11).
                    #
                    # Park first, synchronously: the run keeps going with its
                    # events buffered, and the next message takes it over
                    # (see `park_cancelled_turn`). The awaits after it may be
                    # interrupted themselves; nothing depends on them.
                    aborted = True
                    grace_s = float(getattr(self.valves, "INTERRUPT_GRACE_SECONDS", 0) or 0)
                    turn.parked = True
                    conn.park_cancelled_turn(
                        session_key, our_run_id, queue, turn.unsent, grace_s,
                        send_stop=self.valves.SEND_STOP_ON_CANCEL,
                        run_text={"received": assistant_received_text,
                                  "stream": assistant_stream_text,
                                  "item": last_item_text,
                                  "gaps": run_gaps,
                                  "segments": run_segments},
                    )
                    pipe_log(
                        f"Generator {type(stop).__name__}: run parked "
                        f"{grace_s:g}s with {len(turn.unsent)} unsent "
                        "message(s), in case a new message follows"
                        if grace_s > 0 else
                        f"Generator {type(stop).__name__}: sending chat.abort"
                    )
                    try:
                        await _settle_cancel_intent(
                            conn, session_key, our_run_id,
                            owui_origin_chat_id, __event_call__)
                        await maybe_emit_snapshot(force=True)
                        await _emit_status(__event_emitter__, "Stopped", done=True)
                    except (Exception, asyncio.CancelledError) as ex:
                        pipe_log(f"  stop snapshot/status skipped: {ex!r}")
                    raise

                else:
                    # Normal completion (no cancellation).
                    if pending_prompt_text:
                        # The buffered plain-text tail either fully resolved into a
                        # needs-input trigger (see `_could_be_user_input_prefix`
                        # above -- buffering only continues past the ambiguous
                        # prefix stage while it keeps matching) or the run ended
                        # mid-buffer without ever diverging. Either way, resolve it
                        # now that the full text is available. `maybe_answer_user_input`
                        # re-checks the trigger itself and returns False for a
                        # partial/non-match, in which case fall back to showing it
                        # as plain text so nothing is silently dropped.
                        answer_res = await maybe_answer_user_input(pending_prompt_text)
                        if answer_res.handled:
                            # Answer delivered. Re-enter the main loop (via the outer
                            # `while adopt_new_run`) to consume the follow-up -- whether
                            # the run resumed in place (steer) or a new run was spawned
                            # -- so the continuation reuses the same needs-input
                            # re-detection, dedup and snapshot handling as any other
                            # run instead of a separate, drift-prone copy of the loop.
                            text_yielded = True
                            detail_block = ""
                            if answer_res.answer:
                                detail_block = _ask_user_detail_block(
                                    answer_res.prompt_text or pending_prompt_text, answer_res.answer
                                )
                                record_visible_chunk(detail_block)
                                yield detail_block
                                await maybe_emit_snapshot(force=True)
                            conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                   pending_prompt_text, detail_block)
                            pending_prompt_text = ""
                            if answer_res.new_run_id and answer_res.new_run_id != our_run_id:
                                pipe_log(f"  continuing into new run: {answer_res.new_run_id[:20]}...")
                                # The answer run continues this reply (R9).
                                switch_to_answer_run(answer_res)
                                conn.unregister_consumer(session_key, our_run_id, queue=queue)
                                queue = answer_res.queue or conn.register_consumer(
                                    session_key, answer_res.new_run_id)
                                our_run_id = answer_res.new_run_id
                            else:
                                pipe_log("  continuing in the same run after modal answer")
                            done = False
                            adopt_new_run = True
                        else:
                            # Modal not handled (cancelled / dismissed / gave up
                            # on reconnect). Show the prompt as a fallback, but
                            # never leak the literal "OpenClaw needs input:"
                            # directive line as visible text.
                            fallback = _strip_input_marker_line(pending_prompt_text)
                            conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                   pending_prompt_text, fallback)
                            if fallback:
                                record_visible_chunk(fallback)
                                yield fallback
                                text_yielded = True
                            pending_prompt_text = ""

                    if pending_media_text:
                        # The run ended with a MEDIA: directive still buffered --
                        # either its filename never got a trailing whitespace
                        # before the stream closed, or "MEDIA:" itself was still
                        # incomplete. Nothing more is coming, so it's safe to
                        # resolve now; `_resolve_media_text` still falls back to
                        # showing it as plain text if resolution fails, so
                        # nothing is silently dropped.
                        resolved, handled = await _resolve_media_text(
                            pending_media_text,
                            valves=self.valves,
                            __request__=__request__,
                            __event_emitter__=__event_emitter__,
                        )
                        if handled:
                            conn.note_turn_rewrite(owui_origin_chat_id, owui_message_id,
                                                   pending_media_text, resolved)
                        record_visible_chunk(resolved)
                        yield resolved
                        text_yielded = True
                        pending_media_text = ""

                    # For pure-text turns, do NOT force a snapshot here: OWUI's own
                    # accumulation of the streamed yields already lands the full
                    # text in `content`, and an extra forced `replace` at this
                    # point double-writes it (P23/P25 -- exact duplicate, no
                    # separator).
                    #
                    # Turns that included a tool-call block are different (P27,
                    # 2026-07-08): once a `<details type="tool_calls">` block has
                    # been yielded, OWUI's own end-of-stream save no longer reliably
                    # lands the plain-text tail in `content` at all -- it only shows
                    # up in `output` instead. So for tool-block turns only, force
                    # one last `content` snapshot here.
                    #
                    # This was briefly reverted the same day after what looked like
                    # a live duplicate regression, but that turned out to be a false
                    # alarm caused by redeploying the pipe mid-message in the same
                    # live chat used to test it (a self-inflicted artifact of the
                    # testing method, not this code) -- confirmed by reproducing the
                    # duplicate-free "output has it once, content misses it"
                    # signature again on an unrelated turn where nothing was
                    # redeployed mid-stream. Restored. Lesson for future sessions:
                    # never redeploy this pipe function while a message in the same
                    # live chat being used to verify it is still streaming.
                    #
                    # Skip while re-entering for a modal follow-up: the snapshot must
                    # only land once the run is truly finished, not between turns.
                    # Not for an adopted run either: this reply keeps streaming
                    # the queued message's answer, and a `replace` now would
                    # freeze those deltas (P23/P25).
                    if (not adopt_new_run and had_tool_block and not adopted_run_id
                            and not handed_over):
                        await maybe_emit_snapshot(force=True)

                    # Resolve any tool call that was announced but never got a
                    # result (run cancelled, gateway dropped it, tool crashed).
                    # Its card is a spinner until something completes it, and
                    # OWUI's own "mark leftover in_progress items completed"
                    # sweep does NOT reliably reach this path -- observed
                    # 2026-07-25, where a delivered call stayed `in_progress`
                    # in the persisted item and only rendered as done because
                    # its result item happened to exist. So close them here
                    # rather than relying on that.
                    #
                    # A handed-over run is not over (its writer completes the
                    # cards from the renderer it was handed), but this
                    # request's output must still close them: Open WebUI's
                    # post-stream sweep executes every `function_call` of the
                    # stream that has no `function_call_output`, gets `Error:
                    # Tool "Bash" not found.` and sends that back as a new
                    # turn, whose stream then overwrites the writer's reply
                    # (M3 crash window, 2026-10-13). Only the yielded items are
                    # closed; the handed renderer keeps the call open.
                    if not adopt_new_run and pending_tool_calls:
                        note = ("(interrupted -- the reply continues when the run resumes)"
                                if handed_over else "(no result -- the run ended first)")
                        for orphan_id in list(pending_tool_calls):
                            pipe_log(f"  closing orphaned tool call {orphan_id}")
                            yield _tool_call_result_event(orphan_id, note)
                        pending_tool_calls.clear()

        finally:
            if awaiting_owner:
                conn.stop_awaiting_owner(session_key, owner_run)
            # A parked queue now belongs to whoever claims the run; releasing
            # it here would drop the events it is buffering.
            if not turn.parked:
                if done and not aborted and our_run_id and not handed_over:
                    # The run ended in this reply. Its trailing `chat` final
                    # lands after this consumer is gone and must not read as
                    # "the reply ended before its run" (a handover would
                    # rewrite the message OWUI is about to save) or as a run
                    # nobody showed.
                    conn.mark_delivered_live(session_key, our_run_id)
                    conn.unregister_run_target(session_key, our_run_id)
                conn.unregister_consumer(session_key, our_run_id, queue=queue)
                turn.run_id = None
                turn.queue = None
            status_lines = []
            if not aborted and text_yielded and not adopted_run_id and not handed_over:
                status_lines = await _build_usage_status_lines(conn, session_key)
            if adopted_run_id and not aborted:
                await _emit_status(
                    __event_emitter__, "Sending your message…", done=False)
            elif status_lines:
                # One `status` event per fact (context / rate-limit / goal) so
                # each row stays inside OWUI's per-line clamp instead of one
                # long combined line getting cut off. All of them already
                # reflect final data by the time we get here (both RPCs in
                # `_build_usage_status_lines` already completed) -- none of
                # this is genuinely still "in progress", so every line is
                # `done=True`. Marking earlier ones `done=False` made them
                # shimmer for an instant before getting replaced by the last
                # line, a visible flash for no reason.
                for line in status_lines:
                    await _emit_status(__event_emitter__, line, done=True)
            else:
                await _emit_status(__event_emitter__, "", done=True)
            self._current_session_key = None
            self._current_run_id = None

        pipe_log(f"DONE -- {event_count} events processed, "
                 f"text yielded: {text_yielded}")
        if adopted_run_id and not aborted:
            # The adopted run is over; now send the messages this reply owes
            # (its own, plus any carried over from cancelled replies), in the
            # same reply. The recursive call does the normal queue + send (it
            # also waits out a subagent-yield gap if the run resumes), and
            # owns the terminal snapshot, usage lines and auto-title. Seeding
            # it with what streamed so far keeps that snapshot complete.
            send_texts = list(turn.unsent)
            pipe_log(
                f"  adopted run {adopted_run_id[:20]}... finished; sending "
                f"{len(send_texts)} queued message(s)"
            )
            separator = "\n\n---\n\n" if visible_message_text.strip() else ""
            if separator:
                record_visible_chunk(separator)
                yield separator
            # From here the recursive reply owns them, and parks them itself
            # if it is cancelled.
            turn.unsent = []
            async with contextlib.aclosing(self._pipe_impl(
                body, __event_emitter__,
                __event_call__=__event_call__, __user__=__user__,
                __metadata__=__metadata__, __request__=__request__,
                __task__=__task__, __task_body__=__task_body__,
                _initial_visible_text=visible_message_text,
                _send_texts=send_texts,
            )) as continuation:
                async for item in continuation:
                    yield item
            return
        if (enqueued_not_started and not text_yielded and not aborted
                and not adopted_run_id and session_runtime == "claude-cli"
                and our_run_id and sent_texts):
            # A run started between the idle read and the send (a sub-agent's
            # parent resuming, a wake), and the Gateway queued this message
            # behind it. claude-cli cannot run a queued turn: it fails with
            # "Reply operation has no active tool authority snapshot" once the
            # active run ends (the followup path binds no tool authority,
            # ELI-87), so the message would be lost. Take it back while it is
            # queued, wait for that run to settle, and send it again.
            try:
                await _run_request(
                    conn, RUN_ABORT, {"sessionKey": session_key, "runId": our_run_id},
                    timeout=15,
                )
                took_back = True
            except Exception as ex:
                took_back = False
                pipe_log(f"  could not take back queued message: {ex}")
            if took_back:
                pipe_log(
                    f"  message was queued behind a run that started first "
                    f"(run {str(our_run_id)[:20]}...); took it back, resending once idle"
                )
                conn.unregister_run_target(session_key, our_run_id)
                async with contextlib.aclosing(self._pipe_impl(
                    body, __event_emitter__,
                    __event_call__=__event_call__, __user__=__user__,
                    __metadata__=__metadata__, __request__=__request__,
                    __task__=__task__, __task_body__=__task_body__,
                    _initial_visible_text=visible_message_text,
                    _send_texts=sent_texts,
                )) as again:
                    async for item in again:
                        yield item
                return

        if not text_yielded:
            # DIAG (ELI-56): a no-text turn is the phantom. Emit the correlation
            # keys so it can be matched to a duplicate/re-fired completion above
            # (same text_sha / owui_msg_id) and to the run that actually carried
            # the answer (which then leaks out as a separate message).
            pipe_log(
                f"  [diag] PHANTOM (no text): our_run_id={str(our_run_id)[:40]} "
                f"text_sha={getattr(self, '_diag_text_sha', None)} "
                f"first_event_arrived={first_event_arrived} aborted={aborted}"
            )

        if run_gaps and not aborted and our_run_id:
            # Events were lost and no whole-text event lined up with them
            # during the run: the run's own closing message in the transcript
            # (`cli-assistant:<runId>`, see `_history_text_for_run`) is the
            # whole text. Its tail, if the lost events were the last ones,
            # belongs at the end of this reply.
            try:
                hist = await conn.session_history(session_key, limit=RUN_TEXT_HISTORY_LIMIT)
            except Exception as ex:
                hist = None
                pipe_log(f"  event gap: chat.history failed: {ex}")
            found, whole = _history_text_for_run(hist, our_run_id)
            tail = (reconcile_whole_text(whole) if found and whole else None) or ""
            if run_gaps:
                pipe_log(f"  {len(run_gaps)} event gap(s) and no whole text lines up for run "
                         f"{str(our_run_id)[:20]}...; the lost text cannot be put back")
            elif tail and not visible_message_text.endswith(tail):
                pipe_log(f"  event gap: {len(tail)} chars lost at the end of the run, appended")
                record_visible_chunk(tail)
                yield tail
                text_yielded = True

        # Terminal back-sync (ELI-57): persist the completed turn's visible text
        # to the OWUI DB with one final `replace` snapshot. OWUI only saves
        # yielded content when the BROWSER writes it back after completion -- if
        # the tab/socket died mid-stream, the SSE yields land nowhere, raise
        # nothing, and the message stays empty in the DB forever (reload shows
        # nothing). Tool turns already snapshot along the way; pure-text turns
        # snapshot nowhere since the per-delta back-sync was reverted (ffd2fdd --
        # a mid-stream `replace` makes the frontend suppress the CONTINUING
        # delta stream, P23/P25). At terminal there are no continuing deltas,
        # so a single force snapshot is freeze-safe, and OWUI's `replace`
        # handler writes the DB unconditionally (sio.emit to an empty room is a
        # no-op, not an error), so it persists even with everything dead.
        # ELI-82 instrumentation: record the terminal decision inputs, not just
        # its effect. `text_yielded` gating this call means a turn can end with
        # a populated visible_message_text and still never snapshot, which is
        # indistinguishable from "snapshotted but OWUI dropped it" unless the
        # inputs are on the record.
        pipe_log(
            f"  terminal: aborted={aborted} text_yielded={text_yielded} "
            f"visible={len(visible_message_text)} snapshotted={len(last_snapshot_text)}"
        )
        if not aborted and text_yielded:
            await maybe_emit_snapshot(force=True)

        # Auto-title: generate title after first exchange (best-effort, non-blocking)
        if not aborted and text_yielded:
            spawn_background(
                self._auto_title(
                    body, conn, visible_message_text,
                    owui_origin_chat_id, bearer_token, session_key=session_key,
                )
            )

        if not aborted and not text_yielded:
            recovered = await recover_from_transcript()
            retry_body = _thinking_rejection_retry_body(
                body, recovered, resolved_thinking)
            if retry_body is not None:
                # Learn from the rejection before retrying. The Gateway just
                # named this model's real ladder, and it is the only place that
                # truth is stated -- describe cannot supply it. Recording it
                # here is what stops the next turn repeating this round trip.
                rejection = parse_thinking_rejection(recovered)
                learned = None
                if rejection:
                    learned = rejection["levels"]
                    _record_thinking_ladder(
                        learned,
                        model_key=rejection["model"] or session_model_key,
                        authoritative=True,
                        state_dir=getattr(self.valves, "STATE_DIR", ""),
                    )
                pipe_log(
                    f"thinking: Gateway rejected level {resolved_thinking!r} "
                    f"({recovered!r}); retrying once without an explicit level"
                )
                # Say only what was actually observed. The previous wording
                # asserted a cause it never checked ("this chat hadn't talked
                # to it before"), which was false on every turn after the
                # first and sent anyone reading it hunting the wrong bug.
                if learned:
                    supported = ", ".join(repr(lv) for lv in learned)
                    retry_note = (
                        f"_This model only supports thinking level "
                        f"{supported}, so {resolved_thinking!r} was dropped "
                        f"for this message. Remembered for next time._\n\n"
                    )
                else:
                    retry_note = (
                        f"_This model does not support thinking level "
                        f"{resolved_thinking!r}; sending without it instead._"
                        f"\n\n"
                    )
                record_visible_chunk(retry_note)
                yield retry_note
                async with contextlib.aclosing(self._pipe_impl(
                    retry_body, __event_emitter__,
                    __event_call__=__event_call__, __user__=__user__,
                    __metadata__=__metadata__, __request__=__request__,
                    __task__=__task__, __task_body__=__task_body__,
                    _initial_visible_text=visible_message_text,
                    _send_texts=sent_texts,
                )) as retry:
                    async for item in retry:
                        yield item
                return
            if recovered:
                pipe_log("  recovered assistant text at final fallback")
                record_visible_chunk(recovered)
                yield recovered
                await maybe_emit_snapshot(force=True)
            else:
                # No assistant text and preview recovery came up empty. Surface
                # the run's REAL terminal state (from the gateway) instead of a
                # scary generic "missing output event" placeholder.
                reason = None
                try:
                    desc = await conn.send_request(
                        "sessions.describe", dict(key=session_key), timeout=8)
                    row = desc.get("session") or {}
                    status = row.get("status")
                    if status == "failed":
                        reason = "**The response failed.** Please try again."
                    elif status == "cancelled":
                        reason = "**Stopped.**"
                except Exception as ex:
                    pipe_log(f"  terminal-reason describe failed: {ex}")
                no_response_text = "\n\n" + (
                    reason or "_(This turn produced no reply text.)_"
                )
                record_visible_chunk(no_response_text)
                yield no_response_text
                await maybe_emit_snapshot(force=True)
